    /// The active workspace's window tree. Every call site outside this
    /// pair of accessors goes through here (or `windows_mut`) rather than
    /// touching `self.workspaces` directly, mirroring the `open`/
    /// `open_mut` discipline already used for buffers.
    /// `frame`'s winit window, whether that frame is the active one
    /// (its state is live on `App`) or parked. `None` before the frame
    /// has been through `resumed`, and for an out-of-range index.
    fn frame_window(&self, frame: usize) -> Option<&Arc<Window>> {
        match self.frames.get(frame)? {
            Some(parked) => parked.window.as_ref(),
            None => self.window.as_ref(),
        }
    }

    /// `frame`'s split layout and workspaces, parked or live -- the
    /// read-only counterpart to `activate_frame` for the handful of
    /// places (`about_to_wait`'s animation check, cross-frame
    /// navigation) that need to look at a frame without making it the
    /// active one.
    fn frame_workspaces(&self, frame: usize) -> Option<&WorkspaceList> {
        match self.frames.get(frame)? {
            Some(parked) => Some(&parked.workspaces),
            None => Some(&self.workspaces),
        }
    }

    /// Which frame owns the winit window `id` belongs to.
    fn frame_index_of(&self, id: WindowId) -> Option<usize> {
        (0..self.frames.len()).find(|&frame| self.frame_window(frame).map(|w| w.id()) == Some(id))
    }

    /// Makes `frame` the active one: its parked state moves into the
    /// live fields on `App`, and the outgoing frame's live state is
    /// parked in its place. A no-op when `frame` is already active or
    /// out of range.
    ///
    /// Every field is swapped through `mem::replace` against the
    /// incoming frame's own value, so nothing ever needs a placeholder
    /// to stand in for a moved-out `WorkspaceList` -- and the "exactly
    /// one `None` in `frames`, at `active_frame`" invariant holds at
    /// every point this function returns.
    fn activate_frame(&mut self, frame: usize) {
        if frame == self.active_frame {
            return;
        }
        let Some(Some(incoming)) = self.frames.get_mut(frame).map(Option::take) else { return };
        let outgoing = FrameState {
            window: std::mem::replace(&mut self.window, incoming.window),
            gpu: std::mem::replace(&mut self.gpu, incoming.gpu),
            text: std::mem::replace(&mut self.text, incoming.text),
            bg_rect: std::mem::replace(&mut self.bg_rect, incoming.bg_rect),
            popup_rect: std::mem::replace(&mut self.popup_rect, incoming.popup_rect),
            caret_rect: std::mem::replace(&mut self.caret_rect, incoming.caret_rect),
            workspaces: std::mem::replace(&mut self.workspaces, incoming.workspaces),
            cursor_pos: std::mem::replace(&mut self.cursor_pos, incoming.cursor_pos),
            origin: std::mem::replace(&mut self.frame_origin, incoming.origin),
            sidebar: std::mem::replace(&mut self.sidebar, incoming.sidebar),
            sidebar_open: std::mem::replace(&mut self.sidebar_open, incoming.sidebar_open),
            sidebar_focused: std::mem::replace(&mut self.sidebar_focused, incoming.sidebar_focused),
            sidebar_scroll: std::mem::replace(&mut self.sidebar_scroll, incoming.sidebar_scroll),
            terminal_open: std::mem::replace(&mut self.terminal_open, incoming.terminal_open),
            terminal_focused: std::mem::replace(&mut self.terminal_focused, incoming.terminal_focused),
        };
        self.frames[self.active_frame] = Some(outgoing);
        self.active_frame = frame;
    }

    /// Moves editor focus to `frame` for good, as opposed to
    /// `activate_frame`'s temporary switch: this is what a keystroke, a
    /// click, or a frame command does, and the only thing that moves
    /// `focused_frame`. See that field's doc comment for what turns on
    /// the distinction.
    fn focus_frame(&mut self, frame: usize) {
        self.activate_frame(frame);
        self.focused_frame = self.active_frame;
    }

    /// Re-reads the active frame's position from the OS. Called
    /// whenever it could have changed -- the window moved, was resized,
    /// or was just created -- because directional navigation across
    /// frames is decided from these coordinates.
    ///
    /// Reads `inner_position` rather than the outer one a `Moved` event
    /// carries: pane rectangles are relative to the client area, so the
    /// client area's corner is what they have to be offset by.
    fn refresh_frame_origin(&mut self) {
        if let Some(at) = self.window.as_ref().and_then(|window| window.inner_position().ok()) {
            self.frame_origin = (at.x, at.y);
        }
    }

    /// The configured body text size *before* any DPI scaling -- what
    /// `config.ini` holds and what `SPC t =`/`SPC t -` step. Each
    /// frame's pipeline gets this multiplied by its own monitor's
    /// scale factor.
    fn logical_font_size(&self) -> f32 {
        self.config.font_size.unwrap_or(text::FONT_SIZE)
    }

    /// The active frame's DPI scale factor -- 1.0 before its window
    /// exists, which is also the right answer for a headless test.
    fn frame_scale(&self) -> f32 {
        self.window.as_ref().map(|window| window.scale_factor() as f32).unwrap_or(1.0)
    }

    /// Re-applies the configured font size to every frame, each at its
    /// own monitor's scale factor. Every frame, not just the active
    /// one, because `SPC t =` is an editor-wide preference: two windows
    /// on differently-scaled monitors should end up the same apparent
    /// size as each other, not the same pixel size.
    fn apply_font_size(&mut self) {
        let logical = self.logical_font_size();
        let previous = self.active_frame;
        for frame in 0..self.frames.len() {
            self.activate_frame(frame);
            let scale = self.frame_scale();
            if let Some(text) = &mut self.text {
                text.set_font_size(logical, scale);
            }
        }
        self.activate_frame(previous);
    }

    /// Raises the active frame's OS window and asks it to repaint --
    /// what every command that moves editor focus between frames has to
    /// end with, or the keystrokes would keep going to whichever window
    /// the OS still considers foreground.
    fn focus_active_frame_window(&self) {
        if let Some(window) = &self.window {
            window.focus_window();
            window.request_redraw();
        }
    }

    /// `SPC w n`: opens another OS window, showing the focused buffer in
    /// a single pane, and moves focus to it. The two windows share
    /// everything but layout -- one buffer list, one undo history, one
    /// PDF worker -- so the same file can be open in both and edits show
    /// up in each.
    ///
    /// A silent no-op before `resumed` has built the shared
    /// `GpuContext`: there'd be no device to hang a second swapchain
    /// off. That can't happen from a real keystroke (the window has to
    /// exist for one to arrive) and headless tests use `test_add_frame`.
    pub(crate) fn new_frame(&mut self, event_loop: &ActiveEventLoop) {
        let placement = self.next_frame_placement(event_loop);
        self.open_frame(event_loop, placement);
    }

    /// The half of `new_frame` that takes where to put the window as an
    /// argument, so restoring a saved layout can reuse it (see
    /// `restore_saved_windows`) instead of asking for a free monitor.
    fn open_frame(&mut self, event_loop: &ActiveEventLoop, placement: FramePlacement) {
        let (Some(context), Some(fonts)) = (&self.gpu_context, &self.fonts) else { return };

        let mut attrs = Window::default_attributes().with_title("Fenix").with_window_icon(fenix_icon());
        if let Some(position) = placement.position {
            attrs = attrs.with_position(position);
        }
        if let Some(size) = placement.size {
            attrs = attrs.with_inner_size(size);
        }
        let window = match event_loop.create_window(attrs) {
            Ok(window) => Arc::new(window),
            Err(err) => {
                self.set_error(format!("couldn't open a new window ({err})"));
                return;
            }
        };

        let gpu = context.attach(Arc::clone(&window));
        let mut text = TextPipeline::new(&gpu, Rc::clone(fonts));
        text.set_font_size(self.logical_font_size(), window.scale_factor() as f32);
        let bg_rect = RectRenderer::new(&gpu);
        let popup_rect = RectRenderer::new(&gpu);
        let caret_rect = RectRenderer::new(&gpu);

        let buffer = self.focused_buffer_id();
        let cursor = self.buffers.get(buffer).map(|ob| ob.cursor).unwrap_or(Cursor::at_start());
        self.frames.push(Some(FrameState {
            window: Some(Arc::clone(&window)),
            gpu: Some(gpu),
            text: Some(text),
            bg_rect: Some(bg_rect),
            popup_rect: Some(popup_rect),
            caret_rect: Some(caret_rect),
            workspaces: WorkspaceList::new(WindowTree::new(buffer), cursor),
            cursor_pos: None,
            origin: (0, 0),
            sidebar: None,
            sidebar_open: false,
            sidebar_focused: false,
            sidebar_scroll: 0,
            terminal_open: false,
            terminal_focused: false,
        }));
        let opened = self.frames.len() - 1;

        // Maximizing *after* creation, with the window already
        // positioned on the target monitor, is what makes it fill that
        // monitor rather than whichever one the OS considers primary --
        // and it respects the taskbar, which sizing to the raw monitor
        // rectangle wouldn't.
        if placement.maximized {
            window.set_maximized(true);
        }
        self.focus_frame(opened);
        self.refresh_frame_origin();
        self.focus_active_frame_window();
        self.wake_caret();
    }

    /// Where a new frame should open: the first monitor, left to right,
    /// that hasn't got a Fenix frame on it already -- so on a multi-
    /// monitor desk `SPC w n` lands on the empty screen instead of on
    /// top of the window you're already looking at.
    ///
    /// Falls back to a cascade offset from the active frame when every
    /// monitor is occupied (or when the platform reports no monitors at
    /// all), so a second frame on a single screen is still reachable and
    /// doesn't land exactly on top of the first.
    fn next_frame_placement(&self, event_loop: &ActiveEventLoop) -> FramePlacement {
        let occupied: Vec<(i32, i32)> = (0..self.frames.len()).filter_map(|frame| self.frame_center(frame)).collect();
        let mut monitors: Vec<MonitorHandle> = event_loop.available_monitors().collect();
        monitors.sort_by_key(|monitor| monitor.position().x);

        if let Some(free) = monitors.iter().find(|monitor| !occupied.iter().any(|&at| monitor_contains(monitor, at))) {
            let size = free.size();
            return FramePlacement {
                position: Some(free.position()),
                // A sensible restored-down size for a window that's
                // about to be maximized onto this monitor.
                size: Some(PhysicalSize::new(size.width / 2, size.height / 2)),
                maximized: true,
            };
        }

        const CASCADE: i32 = 48;
        let position = self
            .window
            .as_ref()
            .and_then(|window| window.inner_position().ok())
            .map(|at| PhysicalPosition::new(at.x + CASCADE, at.y + CASCADE));
        FramePlacement { position, size: self.window.as_ref().map(|window| window.inner_size()), maximized: false }
    }

    /// Reopens the windows recorded in `config.windows`, called once
    /// from `resumed` after the first window exists. The first saved
    /// entry is applied to that window; each remaining one opens a
    /// frame of its own. Focus ends on the first, wherever it sits.
    ///
    /// A saved rectangle is handed to the OS as-is. If a monitor has
    /// been unplugged since, Windows clamps the window back onto a
    /// visible screen rather than leaving it stranded off the edge --
    /// which is the whole reason this records rectangles instead of
    /// monitor names (see `fenix_config::WindowLayout`).
    fn restore_saved_windows(&mut self, event_loop: &ActiveEventLoop) {
        if self.config.restore_windows == Some(false) {
            return;
        }
        let layouts = self.config.windows.clone();
        let Some((first, rest)) = layouts.split_first() else { return };

        if let Some(window) = &self.window {
            window.set_outer_position(PhysicalPosition::new(first.x, first.y));
            let _ = window.request_inner_size(PhysicalSize::new(first.width, first.height));
            window.set_maximized(first.maximized);
        }
        self.refresh_frame_origin();

        for layout in rest {
            self.open_frame(event_loop, FramePlacement::from(*layout));
        }
        self.focus_frame(0);
        self.focus_active_frame_window();
    }

    /// Records every open window's geometry into `config`, then writes
    /// it -- called from `exiting`, the one place every quit path
    /// (`SPC q q`, `:q`, the last window's X button, `SPC q Q`) is
    /// guaranteed to pass through.
    ///
    /// A failure to write is reported to stderr and otherwise ignored,
    /// the same posture `save` already has everywhere else it's called:
    /// losing a window arrangement is not worth refusing to exit over.
    fn save_window_layout(&mut self) {
        let layouts: Vec<fenix_config::WindowLayout> = (0..self.frames.len())
            .filter_map(|frame| {
                let window = self.frame_window(frame)?;
                let at = window.outer_position().ok()?;
                let size = window.inner_size();
                Some(fenix_config::WindowLayout {
                    x: at.x,
                    y: at.y,
                    width: size.width,
                    height: size.height,
                    maximized: window.is_maximized(),
                })
            })
            .collect();
        if !layout_worth_saving(&layouts, &self.config.windows) {
            return;
        }
        self.config.windows = layouts;
        if let Err(err) = self.config.save() {
            eprintln!("fenix: couldn't save the window layout ({err})");
        }
    }

    /// The centre of `frame`'s window in desktop coordinates -- how
    /// "which monitor is this frame on" is decided. `None` for a frame
    /// with no window yet, or on a platform that won't report window
    /// positions.
    fn frame_center(&self, frame: usize) -> Option<(i32, i32)> {
        let window = self.frame_window(frame)?;
        let at = window.inner_position().ok()?;
        let size = window.inner_size();
        Some((at.x + size.width as i32 / 2, at.y + size.height as i32 / 2))
    }

    /// `SPC w Q`: closes the focused frame. Closing the *last* frame is
    /// quitting, so it goes through the ordinary unsaved-changes gate
    /// rather than silently dropping your only window -- the same
    /// posture `close_window` takes for the last pane.
    pub(crate) fn close_frame(&mut self, event_loop: &ActiveEventLoop) {
        if self.frames.len() <= 1 {
            self.request_quit(event_loop);
            return;
        }
        self.drop_frame(self.active_frame);
        self.focus_active_frame_window();
        self.wake_caret();
    }

    /// `SPC w O`: closes every frame except the focused one. The
    /// frame-level counterpart of `SPC w o`, and equally permanent.
    pub(crate) fn only_frame(&mut self) {
        while self.frames.len() > 1 {
            // Always a frame other than the active one: with more than
            // one frame open, index 0 and the last index can't both be
            // the active one.
            let victim = if self.active_frame == 0 { self.frames.len() - 1 } else { 0 };
            self.drop_frame(victim);
        }
        self.focus_active_frame_window();
        self.wake_caret();
    }

    /// `SPC w W`: moves focus to the next frame, wrapping -- the
    /// frame-level counterpart of `SPC w w`.
    pub(crate) fn cycle_frame(&mut self) {
        if self.frames.len() <= 1 {
            return;
        }
        let next = (self.active_frame + 1) % self.frames.len();
        self.focus_frame(next);
        self.focus_active_frame_window();
        self.wake_caret();
    }

    /// Removes `frame` for good: tears down the sessions living in it,
    /// then drops its `FrameState`, which drops its `Window` (closing
    /// the OS window) and its swapchain. Refuses on the last frame --
    /// callers that mean "quit" say so explicitly.
    ///
    /// Whichever frame was active stays active, unless it's the one
    /// being dropped; then focus lands on its neighbour. The live
    /// fields are always handed to a frame that will still exist
    /// *before* the removal, because `activate_frame` swaps against a
    /// parked frame and the dying one is about to stop being one.
    fn drop_frame(&mut self, frame: usize) {
        if self.frames.len() <= 1 || frame >= self.frames.len() {
            return;
        }
        let keep = self.active_frame;
        self.activate_frame(frame);
        self.close_sessions_in_active_frame();

        let survivor = if keep == frame {
            if frame == 0 {
                1
            } else {
                frame - 1
            }
        } else {
            keep
        };
        self.focus_frame(survivor);
        self.frames.remove(frame);
        if self.active_frame > frame {
            self.active_frame -= 1;
        }
        self.focused_frame = self.active_frame;
    }

    /// Tears down every session whose panes live in the active frame --
    /// called by `drop_frame` while the frame being dropped is still the
    /// live one, because each session's own close path touches
    /// `workspaces` and `buffers` and has to act on the layout it
    /// actually belongs to.
    ///
    /// Without this, closing a frame would strand whatever it was
    /// holding open: a pdfium worker still keeping a document loaded, a
    /// live VNC socket, a Docker or Git session still polling in the
    /// background -- each pointing at panes that no longer exist.
    fn close_sessions_in_active_frame(&mut self) {
        let panes = self.workspaces.all_panes();

        let pdf_keys: Vec<PathBuf> = panes.iter().filter_map(|&pane| self.pdf_session_key_for_pane(pane)).collect();
        for key in pdf_keys {
            self.pdf_session_forget(&key);
        }
        let vnc_keys: Vec<String> = panes.iter().filter_map(|&pane| self.vnc_session_key_for_pane(pane)).collect();
        for key in vnc_keys {
            self.vnc_session_close(&key);
        }
        // One pane apiece is enough to identify these: a panel session
        // builds all of its panes in one workspace, so they're either
        // all in this frame or none of them are.
        if self.docker_session.as_ref().is_some_and(|session| panes.contains(&session.containers_pane)) {
            self.docker_session_close();
        }
        if self.git_session.as_ref().is_some_and(|session| panes.contains(&session.status_pane)) {
            self.git_session_close();
        }
        if self.jira_session.as_ref().is_some_and(|session| panes.contains(&session.issues_pane)) {
            self.jira_session_close();
        }
    }

    fn windows(&self) -> &WindowTree<BufferId> {
        self.workspaces.active()
    }

    fn windows_mut(&mut self) -> &mut WindowTree<BufferId> {
        self.workspaces.active_mut()
    }

    fn focused_buffer_id(&self) -> BufferId {
        *self.windows().focused_content()
    }

    /// The currently-focused pane's open buffer. Free to use anywhere
    /// that doesn't *also* need another `App` field (like `self.vim`) in
    /// the same expression -- being a method call on `self`, it borrows
    /// opaquely, so those few spots inline `self.buffers.get_mut(id)`
    /// directly instead (see e.g. `handle_key`'s Vim dispatch).
    fn open(&self) -> &OpenBuffer {
        self.buffers.get(self.focused_buffer_id()).expect("focused window always has an open buffer")
    }

    fn open_mut(&mut self) -> &mut OpenBuffer {
        let id = self.focused_buffer_id();
        self.buffers.get_mut(id).expect("focused window always has an open buffer")
    }

    fn focused_pane_id(&self) -> fenix_window::WindowId {
        self.windows().focused_id()
    }

    /// `pane`'s own live cursor/scroll -- every existing pane has one,
    /// seeded when the pane was created (`Workspace::new`/`split_window`/
    /// `set_pane_content`), so this can safely `.expect()` rather than
    /// return `Option`, the same invariant-backed shape `open`/`open_mut`
    /// already use for `focused_buffer_id`.
    fn pane_state(&self, pane: fenix_window::WindowId) -> &PaneState {
        self.workspaces.active_pane_states().get(&pane).expect("every existing pane has a PaneState")
    }

    fn pane_state_mut(&mut self, pane: fenix_window::WindowId) -> &mut PaneState {
        self.workspaces.active_pane_states_mut().get_mut(&pane).expect("every existing pane has a PaneState")
    }

    /// The focused pane's live cursor -- read-only convenience mirroring
    /// `open()`'s role but for pane-owned (not buffer-owned) state. Same
    /// "don't use where another `self` field is also needed in the same
    /// expression" caveat as `open()`'s own doc comment.
    fn cursor(&self) -> Cursor {
        self.pane_state(self.focused_pane_id()).cursor
    }

    /// The focused buffer plus the focused pane's live cursor, as the two
    /// separate mutable borrows most buffer-editing call sites need
    /// simultaneously (`Buffer` methods take `&mut Cursor` as a sibling
    /// argument, not something bundled into one struct anymore now that
    /// cursor is pane-owned rather than buffer-owned). Not usable from a
    /// spot that *also* needs another `self` field (like `self.vim`) in
    /// the same expression -- those inline `self.buffers.get_mut(id)` /
    /// `self.workspaces.active_pane_states_mut().get_mut(&pane)` directly
    /// instead (see `handle_key`'s Vim dispatch), the same reasoning
    /// `open`/`open_mut`'s own doc comment already gives.
    fn focused_buffer_and_cursor_mut(&mut self) -> (&mut Buffer, &mut Cursor) {
        let buffer_id = self.focused_buffer_id();
        let pane = self.focused_pane_id();
        let buffer = &mut self.buffers.get_mut(buffer_id).expect("focused window always has an open buffer").buffer;
        let cursor = &mut self.workspaces.active_pane_states_mut().get_mut(&pane).expect("every existing pane has a PaneState").cursor;
        (buffer, cursor)
    }

    /// Points `pane` at `buffer_id` and resets that pane's live cursor/
    /// scroll to the newly-shown buffer's own remembered position --
    /// every `WindowTree::set_content` call site goes through this
    /// instead of calling it directly, so a pane switching to a
    /// different buffer never keeps stale cursor/scroll state left over
    /// from whatever it was showing before (which could easily be out of
    /// bounds for the new buffer's own length).
    fn set_pane_content(&mut self, pane: fenix_window::WindowId, buffer_id: BufferId) {
        self.windows_mut().set_content(pane, buffer_id);
        let cursor = self.buffers.get(buffer_id).map(|ob| ob.cursor).unwrap_or(Cursor::at_start());
        self.workspaces.active_pane_states_mut().insert(pane, PaneState::seeded_at(cursor));
    }

    /// Whether the *focused* pane currently belongs to one of the app's
    /// long-lived side sessions (VNC/PDF/Docker/Git/Jira/Task) rather
    /// than just showing an ordinary file/scratch buffer -- checked the
    /// same way each session already answers "is this my pane" for its
    /// own purposes (`vnc_session_key_for_pane`/`pdf_session_key_for_
    /// pane`/`docker_focused_role`/`git_focused_role`/`jira_focused_
    /// role`/`task_session`'s own single `pane` field), so this adds no
    /// new bookkeeping, just combines what already exists. See `open_
    /// buffer_in_focused_pane`'s doc comment for why this matters --
    /// `TaskSession` hit the exact same class of bug this guard was
    /// built for (`SPC p n` jumping to a diagnostic while the Task
    /// Output pane was focused silently replaced it with the jumped-to
    /// file, so a later `SPC p r`/`SPC p T` rerun kept running -- just
    /// into a buffer no pane displayed anymore).
    fn focused_pane_holds_a_tracked_session(&self) -> bool {
        let focused = self.focused_pane_id();
        // VNC is deliberately *not* in this list. The bug this guard
        // exists for -- a session left running with no pane showing it,
        // and no way back -- doesn't apply to VNC any more: a session is
        // identified by its buffer (`VncSession::buffer`), not by a pane,
        // so pointing a pane at something else just hides it, exactly
        // like navigating away from any other buffer, and `SPC v v` finds
        // it again (`open_vnc_session` re-opens the buffer if no pane is
        // currently showing it). Keeping it here instead meant a file
        // opened while a VNC pane was focused got flung into a whole new
        // workspace rather than opening where you were looking.
        self.pdf_session_key_for_pane(focused).is_some()
            || self.docker_focused_role().is_some()
            || self.git_focused_role().is_some()
            || self.jira_focused_role().is_some()
            || self.task_session.as_ref().is_some_and(|s| s.pane == focused)
            || self.debug_session.as_ref().is_some_and(|s| {
                focused == s.call_stack_pane || focused == s.variables_pane || focused == s.watches_pane || focused == s.breakpoints_pane
            })
            || self.tool_status_session.as_ref().is_some_and(|s| s.pane == focused)
            || self
                .history_session
                .as_ref()
                .is_some_and(|s| focused == s.graph_pane || focused == s.refs_pane || focused == s.detail_pane)
            || self.compare_session.as_ref().is_some_and(|s| focused == s.commits_pane || focused == s.diff_pane)
            || self.merge_session.as_ref().is_some_and(|s| focused == s.files_pane || focused == s.merge_pane)
            || self.forge_session.as_ref().is_some_and(|s| focused == s.list_pane || focused == s.detail_pane || focused == s.review_pane)
            || self.compose.as_ref().is_some_and(|c| focused == c.pane)
    }

    /// Points the focused pane at `id` -- unless the focused pane
    /// currently belongs to a tracked session (VNC/PDF/Docker/Git/
    /// Jira), in which case `id` opens in a brand-new workspace instead
    /// (mirroring `App::new_workspace`'s own "seed a new workspace with
    /// this buffer" logic) and the session's own pane is left completely
    /// untouched.
    ///
    /// Every "open this wherever I'm looking" action (`SPC SPC`, `SPC b
    /// b`, `SPC b X`, opening a document/dashboard/dired listing, ...)
    /// goes through this instead of calling `set_pane_content` on
    /// `focused_pane_id()` directly. Before this existed, none of them
    /// checked what the focused pane already held: reported bug was
    /// "focus a VNC pane, open a file with `SPC SPC`, and the VNC pane
    /// silently starts showing that file instead." The session itself
    /// (socket, reader thread, framebuffer) kept running with no pane
    /// left displaying it, so `SPC v v` on the same host found its own
    /// `session.pane` unchanged and landed right back on that same pane
    /// -- which was still showing the hijacked file, not VNC, making it
    /// look like reopening the session had silently done nothing.
    fn open_buffer_in_focused_pane(&mut self, id: BufferId) {
        if self.focused_pane_holds_a_tracked_session() {
            let cursor = self.buffers.get(id).map(|ob| ob.cursor).unwrap_or(Cursor::at_start());
            self.workspaces.new_workspace(id, cursor);
        } else {
            let focused = self.focused_pane_id();
            self.set_pane_content(focused, id);
        }
    }

    /// Re-derives `project_root` for the focused buffer -- called every
    /// time a pane's buffer changes, not just at startup (`with_file`
    /// does the equivalent inline before `self` exists to call this on).
    /// Deliberately does *not* register the result in `known_projects`:
    /// that list is explicitly curated via `SPC p a`/`SPC p d` now, not
    /// auto-populated from wherever you happen to open a file -- see
    /// `picker_add_project_prompt`'s own doc comment for why.
    fn refresh_project_root(&mut self) {
        self.project_root = self.open().buffer.path().and_then(fenix_project::find_project_root);
        self.sync_lsp_for_focused_buffer();
    }

    /// Makes sure the focused buffer's language server (if any is
    /// configured/available for its language) has an up to date picture
    /// of it: spawns that language's server if it isn't already running
    /// (`ensure_lsp_session`), sends `textDocument/didOpen` the first
    /// time (once the session is actually initialized), and after that
    /// compares `Buffer::edit_count()` against what was last synced --
    /// a mismatch means real edits landed since, answered with a full-
    /// text `textDocument/didChange` (whole-document sync for v1, not
    /// incremental range edits -- `Buffer::drain_edits`/`EditDelta`
    /// would let this send just the changed range later, but full-text
    /// is correct today, just not maximally efficient on a large file).
    ///
    /// Called from `refresh_project_root` (every focus change) *and*
    /// every `redraw` (every rendered frame) -- focus change alone
    /// would send `didOpen` but then never notice an edit made while
    /// staying on the same buffer, since nothing else marks "this
    /// buffer changed" the way switching away/back does.
    fn sync_lsp_for_focused_buffer(&mut self) {
        let Some(path) = self.open().buffer.path().map(Path::to_path_buf) else { return };
        let Some(language) = fenix_syntax::detect_language_from_path(&path) else { return };
        let cwd = self.project_root.clone().unwrap_or_else(|| path.parent().map(Path::to_path_buf).unwrap_or_else(|| PathBuf::from(".")));
        self.ensure_lsp_session(language, &cwd);

        // `fenix_lsp::normalize` strips Windows' `\\?\` verbatim prefix
        // (which `canonicalize` always adds there) -- everywhere else
        // a canonicalized path is compared against one that came back
        // from a server's URI (`open_documents`, `App::diagnostics`'
        // own keys) needs the same normalized form, or two spellings of
        // the same file stop matching each other.
        let canonical = fenix_lsp::normalize(std::fs::canonicalize(&path).unwrap_or(path));
        let edit_count = self.open().buffer.edit_count();
        // Fetched unconditionally, before `session` below takes a
        // mutable borrow of `self.lsp_sessions` -- both branches that
        // might actually use it need the buffer's *current* text, and
        // `self.open()` (an immutable borrow of a different `self`
        // field) can't coexist with that mutable borrow.
        let text = self.open().buffer.text();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        if session.capabilities.is_none() {
            return;
        }
        let Some(uri) = fenix_lsp::path_to_uri(&canonical) else { return };

        match session.open_documents.get(&canonical).copied() {
            None => {
                let params = lsp_types::DidOpenTextDocumentParams {
                    text_document: lsp_types::TextDocumentItem { uri, language_id: crate::lsp::language_config_name(language), version: 0, text },
                };
                if session.client.notify::<lsp_types::notification::DidOpenTextDocument>(params).is_ok() {
                    session.open_documents.insert(canonical, (edit_count, 1));
                }
            }
            Some((last_synced_edit_count, next_version)) if last_synced_edit_count != edit_count => {
                let params = lsp_types::DidChangeTextDocumentParams {
                    text_document: lsp_types::VersionedTextDocumentIdentifier { uri, version: next_version },
                    content_changes: vec![lsp_types::TextDocumentContentChangeEvent { range: None, range_length: None, text }],
                };
                if session.client.notify::<lsp_types::notification::DidChangeTextDocument>(params).is_ok() {
                    session.open_documents.insert(canonical, (edit_count, next_version + 1));
                }
            }
            Some(_) => {} // already open and already in sync -- the common case, most frames
        }
    }

    /// Spawns a language server for `language` if one isn't already
    /// running (a no-op otherwise, regardless of whether the existing
    /// session is healthy -- a dead one is replaced by `apply_lsp_event`'s
    /// own `Disconnected` handling removing it first, not respawned here
    /// on every focus change), resolving its command via `lsp::resolve_
    /// server_command` (a `[lsp]` override, or `fenix-lsp`'s built-in
    /// per-language default) and using `cwd` as both its working
    /// directory and its advertised project root -- a server has no
    /// other way to know what "the project" even is. Silently does
    /// nothing if no command is configured or known for `language` (same
    /// posture as completion quietly having nothing to offer for a
    /// language with no ctags support).
    fn ensure_lsp_session(&mut self, language: fenix_syntax::LanguageId, cwd: &Path) {
        if self.lsp_sessions.contains_key(&language) {
            return;
        }
        let Some((program, args)) = crate::lsp::resolve_server_command(language, &self.config.lsp_servers) else { return };
        match fenix_lsp::LspClient::spawn(&program, &args, cwd) {
            Ok((client, receiver)) => {
                let reader = self.event_proxy.clone().map(|proxy| LspReader::spawn(receiver, language, move |event| proxy.send_event(event).is_ok()));
                self.lsp_sessions.insert(language, LspSession { client, root: cwd.to_path_buf(), reader, capabilities: None, open_documents: HashMap::new(), pending: HashMap::new() });
                self.send_lsp_initialize(language, cwd);
            }
            Err(err) => {
                self.set_error(format!("couldn't start {program} for {language:?}: {err}"));
            }
        }
    }

    /// Sends the `initialize` request for a freshly-spawned session --
    /// deliberately not folded into `ensure_lsp_session` itself, so a
    /// later reconnect (once one exists) can re-send just this without
    /// re-spawning the process. `initialize` is always the very first
    /// request sent on a fresh connection (see `fenix_lsp::LspClient::
    /// next_id`'s own doc comment: it starts at 1 and only ever
    /// increments), so its response is always id 1 -- relied on by
    /// `apply_lsp_event` instead of a general pending-request map, which
    /// nothing else needs yet.
    fn send_lsp_initialize(&mut self, language: fenix_syntax::LanguageId, cwd: &Path) {
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        let root_uri = fenix_lsp::path_to_uri(cwd);
        let params = lsp_types::InitializeParams {
            process_id: Some(std::process::id()),
            #[allow(deprecated)] // still set alongside workspace_folders for servers that only look at this
            root_uri: root_uri.clone(),
            capabilities: crate::lsp::client_capabilities(),
            workspace_folders: root_uri.map(|uri| vec![lsp_types::WorkspaceFolder { uri, name: "root".to_string() }]),
            ..Default::default()
        };
        if let Ok(id) = session.client.request::<lsp_types::request::Initialize>(params) {
            session.pending.insert(id, PendingLspRequest::Initialize);
        }
    }

    /// Dispatches one decoded event from a language server's connection.
    fn apply_lsp_event(&mut self, language: fenix_syntax::LanguageId, event: fenix_lsp::LspEvent) {
        match event {
            fenix_lsp::LspEvent::Response { id, result } => {
                let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
                let Some(pending) = session.pending.remove(&id) else { return };
                self.apply_lsp_response(language, pending, result);
            }
            fenix_lsp::LspEvent::Notification { method, params } => {
                if method == <lsp_types::notification::PublishDiagnostics as lsp_types::notification::Notification>::METHOD {
                    if let Ok(diagnostics) = serde_json::from_value::<lsp_types::PublishDiagnosticsParams>(params) {
                        self.apply_lsp_diagnostics(diagnostics);
                    }
                }
            }
            fenix_lsp::LspEvent::ServerRequest { id, method, .. } => {
                // Not yet answering any server-initiated request (e.g.
                // `workspace/configuration`) -- replying with a generic
                // "method not found" error at least resolves it, rather
                // than leaving a spec-compliant server waiting forever
                // for a response it's entitled to.
                if let Some(session) = self.lsp_sessions.get(&language) {
                    let _ = session.client.respond(id, Err(fenix_lsp::ResponseError { code: -32601, message: format!("not implemented: {method}"), data: None }));
                }
            }
            fenix_lsp::LspEvent::Disconnected(reason) => {
                self.lsp_sessions.remove(&language);
                self.set_error(format!("{language:?} language server disconnected: {reason}"));
            }
        }
    }

    /// Routes one arrived response to whatever `pending` says the
    /// original request was for -- the single dispatch point every
    /// request-sending method's eventual answer passes through.
    fn apply_lsp_response(&mut self, language: fenix_syntax::LanguageId, pending: PendingLspRequest, result: Result<serde_json::Value, fenix_lsp::ResponseError>) {
        match pending {
            PendingLspRequest::Initialize => match result {
                Ok(value) => {
                    let capabilities = serde_json::from_value::<lsp_types::InitializeResult>(value).ok().map(|r| r.capabilities);
                    if let Some(session) = self.lsp_sessions.get_mut(&language) {
                        session.capabilities = capabilities;
                        let _ = session.client.notify::<lsp_types::notification::Initialized>(lsp_types::InitializedParams {});
                        // pyright doesn't infer which interpreter/venv a
                        // project uses on its own -- without this, "go to
                        // definition"/hover on a third-party import
                        // resolves nowhere, since pyright never looked in
                        // that venv's site-packages at all. Pushed as a
                        // `workspace/didChangeConfiguration`, the shape
                        // every pyright integration (VS Code's own
                        // extension included) actually feeds it; this
                        // client never declared `workspace/configuration`
                        // pull support, so a push right after `initialized`
                        // is the one required step, not just an optimization.
                        if language == fenix_syntax::LanguageId::Python {
                            let env = fenix_lsp::per_language::python::resolve(&session.root);
                            let settings = serde_json::json!({ "python": { "pythonPath": env.interpreter.to_string_lossy() } });
                            let _ = session.client.notify::<lsp_types::notification::DidChangeConfiguration>(lsp_types::DidChangeConfigurationParams { settings });
                        }
                    }
                    // Now that the session is actually initialized,
                    // send `didOpen` for the focused buffer if it's this
                    // language (the request that triggered spawning
                    // this session in the first place couldn't send it
                    // yet -- capabilities weren't known).
                    self.sync_lsp_for_focused_buffer();
                }
                Err(err) => self.set_error(format!("{language:?} language server failed to initialize: {}", err.message)),
            },
            PendingLspRequest::Hover { buffer } => {
                self.lsp_hover = None;
                if let Ok(Some(hover)) = result.map(|v| serde_json::from_value::<Option<lsp_types::Hover>>(v).ok().flatten()) {
                    if buffer == self.focused_buffer_id() {
                        self.lsp_hover = Some(crate::lsp::hover_contents_text(hover.contents));
                        self.wake_caret();
                    }
                }
            }
            PendingLspRequest::Definition { buffer } => {
                if let Ok(Some(response)) = result.map(|v| serde_json::from_value::<Option<lsp_types::GotoDefinitionResponse>>(v).ok().flatten()) {
                    if buffer == self.focused_buffer_id() {
                        self.goto_lsp_location_response(response);
                    }
                }
            }
            PendingLspRequest::References { buffer } => {
                if let Ok(Some(locations)) = result.map(|v| serde_json::from_value::<Option<Vec<lsp_types::Location>>>(v).ok().flatten()) {
                    if buffer == self.focused_buffer_id() {
                        self.apply_lsp_references(locations);
                    }
                }
            }
            PendingLspRequest::Rename { buffer } => match result {
                Ok(value) => {
                    if let Some(edit) = serde_json::from_value::<Option<lsp_types::WorkspaceEdit>>(value).ok().flatten() {
                        if buffer == self.focused_buffer_id() {
                            self.apply_lsp_workspace_edit(edit);
                        }
                    }
                }
                Err(err) => self.set_error(format!("rename failed: {}", err.message)),
            },
            PendingLspRequest::CodeAction { buffer } => {
                if let Ok(Some(actions)) = result.map(|v| serde_json::from_value::<Option<Vec<lsp_types::CodeActionOrCommand>>>(v).ok().flatten()) {
                    if buffer == self.focused_buffer_id() {
                        self.apply_lsp_code_actions(language, actions);
                    }
                }
            }
            PendingLspRequest::Format { buffer } => {
                if let Ok(Some(edits)) = result.map(|v| serde_json::from_value::<Option<Vec<lsp_types::TextEdit>>>(v).ok().flatten()) {
                    if buffer == self.focused_buffer_id() {
                        self.apply_lsp_text_edits(buffer, edits);
                    }
                }
            }
            PendingLspRequest::Completion { buffer, prefix_start } => {
                if let Ok(value) = result {
                    self.apply_lsp_completion(buffer, prefix_start, value);
                }
            }
        }
    }

    /// Records (or clears) one file's diagnostics -- `textDocument/
    /// publishDiagnostics` is keyed by URI regardless of whether a
    /// buffer for it is currently open, and an *empty* list is the
    /// server's way of saying "no more diagnostics here," not "nothing
    /// changed," so it's stored as an actual removal rather than an
    /// empty `Vec` left behind.
    fn apply_lsp_diagnostics(&mut self, params: lsp_types::PublishDiagnosticsParams) {
        let Some(path) = fenix_lsp::uri_to_path(&params.uri) else { return };
        if params.diagnostics.is_empty() {
            self.diagnostics.remove(&path);
        } else {
            self.diagnostics.insert(path, params.diagnostics);
        }
    }

    /// The language, session, and current-cursor-as-LSP-`Position` for
    /// the focused buffer -- `None` unless a fully initialized language
    /// server is actually attached to it (checked via `open_documents`,
    /// not just `capabilities.is_some()`: a session can be initialized
    /// for a *different* buffer's `didOpen` before this one's has landed).
    /// The shared precondition every LSP request this app sends starts
    /// from (`gd`/`gr`/`K`/rename/code actions/format all begin here).
    fn focused_lsp_context(&self) -> Option<(fenix_syntax::LanguageId, lsp_types::TextDocumentIdentifier, lsp_types::Position)> {
        let ob = self.open();
        let path = ob.buffer.path()?;
        let language = fenix_syntax::detect_language_from_path(path)?;
        let canonical = fenix_lsp::normalize(std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf()));
        let session = self.lsp_sessions.get(&language)?;
        session.capabilities.as_ref()?;
        if !session.open_documents.contains_key(&canonical) {
            return None;
        }
        let uri = fenix_lsp::path_to_uri(&canonical)?;
        let position = fenix_lsp::char_offset_to_position(ob.buffer.rope(), self.cursor().char_idx);
        Some((language, lsp_types::TextDocumentIdentifier { uri }, position))
    }

    /// Finds the already-open buffer (if any) for a path that came from
    /// an LSP URI -- tries an exact `BufferList::id_for_path` match
    /// first (works whenever the buffer's own stored path is already
    /// exactly this), then falls back to comparing the *focused*
    /// buffer's own canonicalized path (the common case this exists
    /// for: a rename/code action/format response for whatever's
    /// currently being edited, where the stored path may be a
    /// differently-spelled-but-equivalent representation of the same
    /// file -- see `fenix_lsp::normalize`'s own doc comment). Doesn't
    /// open anything -- see `apply_lsp_workspace_edit`'s own doc comment
    /// for why a path with no open buffer is simply skipped rather than
    /// opened invisibly.
    fn buffer_id_for_lsp_path(&self, path: &Path) -> Option<BufferId> {
        if let Some(id) = self.buffers.id_for_path(path) {
            return Some(id);
        }
        let focused = self.focused_buffer_id();
        let focused_path = self.buffers.get(focused)?.buffer.path()?;
        let focused_canonical = fenix_lsp::normalize(std::fs::canonicalize(focused_path).unwrap_or_else(|_| focused_path.to_path_buf()));
        (focused_canonical == path).then_some(focused)
    }

    /// Moves the focused pane's cursor to an LSP `Position` within
    /// whatever buffer is focused *right now* -- callers that need to
    /// land in a *different* file open it first (`open_file_from_
    /// picker`, which this deliberately doesn't do itself, so it stays
    /// usable both for "jump to a different file" and "jump within the
    /// one already focused," e.g. a same-file `gd`).
    fn goto_lsp_position(&mut self, position: lsp_types::Position) {
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        cursor.char_idx = fenix_lsp::position_to_char_offset(buffer.rope(), position).min(buffer.len_chars());
        let (_, sticky) = buffer.line_col(cursor);
        cursor.sticky_col = sticky;
    }

    /// Opens (or switches to) `location`'s file via `open_file_from_
    /// picker` -- reusing it rather than a bespoke "just point the
    /// focused pane at this path" means a `gd` into a live VNC/Docker/
    /// Git/Jira/PDF session's pane gets the same hijack protection any
    /// other "open this wherever I'm looking" action already has (see
    /// `open_buffer_in_focused_pane`) -- then moves the cursor to its
    /// range's start.
    fn goto_lsp_location(&mut self, location: &lsp_types::Location) {
        let Some(path) = fenix_lsp::uri_to_path(&location.uri) else { return };
        self.open_file_from_picker(&path);
        self.goto_lsp_position(location.range.start);
    }

    /// `textDocument/definition`'s response: a single location jumps
    /// straight there (recorded on the jumplist first, so `Ctrl-O` gets
    /// back); a list (rare -- an overloaded/ambiguous declaration) or a
    /// `LocationLink` list (newer servers' richer shape) instead
    /// populates the same generalized `quickfix` list `gr` uses, so
    /// `SPC p n`/`SPC p N` step through them exactly the same way
    /// regardless of which populated it.
    fn goto_lsp_location_response(&mut self, response: lsp_types::GotoDefinitionResponse) {
        let locations: Vec<lsp_types::Location> = match response {
            lsp_types::GotoDefinitionResponse::Scalar(loc) => vec![loc],
            lsp_types::GotoDefinitionResponse::Array(locs) => locs,
            lsp_types::GotoDefinitionResponse::Link(links) => {
                links.into_iter().map(|link| lsp_types::Location { uri: link.target_uri, range: link.target_selection_range }).collect()
            }
        };
        match locations.len() {
            0 => self.set_error("no definition found".to_string()),
            1 => {
                let from = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
                self.goto_lsp_location(&locations[0]);
                self.record_jump(from);
            }
            _ => self.apply_lsp_references(locations),
        }
    }

    /// Turns `textDocument/references`' response (or `goto_lsp_location_
    /// response`'s multi-location fallback) into the generalized
    /// `quickfix` list, then jumps to the first entry immediately --
    /// matching real Vim's own `:grep`/tag-list auto-jump-to-first
    /// convention, and `run_grep`'s own precedent in this codebase.
    fn apply_lsp_references(&mut self, locations: Vec<lsp_types::Location>) {
        self.quickfix = locations
            .into_iter()
            .filter_map(|loc| fenix_lsp::uri_to_path(&loc.uri).map(|path| QuickfixEntry::Lsp { path, position: loc.range.start }))
            .collect();
        self.quickfix_index = None;
        if self.quickfix.is_empty() {
            self.set_error("no references found".to_string());
        } else {
            self.quickfix_step(1);
        }
    }

    /// Applies a server's `TextEdit`s to `buffer_id`'s content -- each
    /// edit's range refers to the document as it stood *before any of
    /// this batch was applied* (not progressively renumbered edit by
    /// edit, per spec), which is why this applies them back-to-front by
    /// position: an edit earlier in the document never shifts the
    /// position of one later in it as long as the later one is applied
    /// first.
    fn apply_lsp_text_edits(&mut self, buffer_id: BufferId, mut edits: Vec<lsp_types::TextEdit>) {
        edits.sort_by(|a, b| b.range.start.cmp(&a.range.start));
        let Some(ob) = self.buffers.get_mut(buffer_id) else { return };
        for edit in edits {
            let start = fenix_lsp::position_to_char_offset(ob.buffer.rope(), edit.range.start);
            let end = fenix_lsp::position_to_char_offset(ob.buffer.rope(), edit.range.end);
            ob.buffer.replace_range(&mut ob.cursor, start, end, &edit.new_text);
        }
    }

    /// Applies a server's `WorkspaceEdit` (rename's result, or a code
    /// action's) -- limited to buffers *already open*
    /// (`buffer_id_for_lsp_path`): opening every file a multi-file edit
    /// touches, applying it, and saving automatically is real scope
    /// beyond what this needs yet (most renames pyright/rust-analyzer
    /// produce for a local symbol stay within one file anyway). A path
    /// with no open buffer is silently skipped rather than edited
    /// invisibly on disk behind a file the user never asked to have
    /// touched without seeing it happen.
    ///
    /// Reads both shapes a `WorkspaceEdit` can arrive in: the plain
    /// `changes` map this client's own capabilities ask for (`lsp::
    /// client_capabilities` declares no `workspace.workspaceEdit`
    /// block at all, which per spec should keep a server on this
    /// simpler shape), and `document_changes`' `TextDocumentEdit` list,
    /// which pyright sends regardless in practice -- confirmed live
    /// against a real pyright rename, which came back empty-handed
    /// (`changes: None`) until this fallback was added. A resource
    /// operation entry (`document_changes`' `Operations` variant --
    /// create/rename/delete a whole file) is skipped for the same
    /// reason cross-file edits already are: nothing here opens or
    /// creates files on a server's say-so.
    fn apply_lsp_workspace_edit(&mut self, edit: lsp_types::WorkspaceEdit) {
        let per_file: Vec<(lsp_types::Uri, Vec<lsp_types::TextEdit>)> = if let Some(changes) = edit.changes {
            changes.into_iter().collect()
        } else {
            match edit.document_changes {
                Some(lsp_types::DocumentChanges::Edits(edits)) => edits
                    .into_iter()
                    .map(|e| {
                        let edits = e.edits.into_iter().map(|oe| match oe {
                            lsp_types::OneOf::Left(edit) => edit,
                            lsp_types::OneOf::Right(annotated) => annotated.text_edit,
                        });
                        (e.text_document.uri, edits.collect())
                    })
                    .collect(),
                _ => Vec::new(),
            }
        };
        for (uri, edits) in per_file {
            let Some(path) = fenix_lsp::uri_to_path(&uri) else { continue };
            let Some(buffer_id) = self.buffer_id_for_lsp_path(&path) else { continue };
            self.apply_lsp_text_edits(buffer_id, edits);
        }
    }

    /// `textDocument/codeAction`'s response: a `Command` entry (a
    /// server-side action with no client-applicable edit of its own,
    /// e.g. "organize imports" some servers implement as a command
    /// rather than a `WorkspaceEdit`) is skipped -- executing an
    /// arbitrary server-defined command is real scope beyond applying
    /// an edit this app already knows how to interpret. Only one action
    /// exists today: whichever's `WorkspaceEdit` is present is applied
    /// immediately, no picker -- `SPC c a` becomes a real chooser once
    /// more than one meaningfully-different action is common enough to
    /// justify it.
    fn apply_lsp_code_actions(&mut self, _language: fenix_syntax::LanguageId, actions: Vec<lsp_types::CodeActionOrCommand>) {
        let edit = actions.into_iter().find_map(|action| match action {
            lsp_types::CodeActionOrCommand::CodeAction(action) => action.edit,
            lsp_types::CodeActionOrCommand::Command(_) => None,
        });
        match edit {
            Some(edit) => self.apply_lsp_workspace_edit(edit),
            None => self.set_error("no applicable code action".to_string()),
        }
    }

    /// `textDocument/completion`'s response merged into whatever
    /// completion popup is already open -- see `sync_completion`'s own
    /// call site for how `CompletionKind::Lsp` items reach the same
    /// picker buffer-word/ctags candidates already do. A no-op if the
    /// popup closed (moved on to something else) before this arrived,
    /// or if `buffer` isn't focused any more.
    fn apply_lsp_completion(&mut self, buffer: BufferId, prefix_start: usize, value: serde_json::Value) {
        if buffer != self.focused_buffer_id() {
            return;
        }
        // `PickerState` has no "add candidates to what's already there"
        // method (every other picker in this app is built once, up
        // front, from a source that's already fully known -- this is
        // the first one whose candidate pool can grow *after* it opens,
        // since an LSP response is inherently async relative to the
        // keystroke that triggered it). Rebuilt from scratch instead,
        // combining the always-available local candidates
        // (`completion_candidates`) with these LSP ones, then
        // re-applying whatever query was already typed -- cheap enough
        // (a handful of candidates, not thousands) that rebuilding isn't
        // worth avoiding.
        let Some((query, current_prefix_start)) = self.completion.as_ref().map(|s| (s.picker.query().to_string(), s.prefix_start)) else {
            return;
        };
        if current_prefix_start != prefix_start {
            return; // superseded by a newer prefix since this request was sent
        }
        let items: Vec<lsp_types::CompletionItem> = serde_json::from_value::<lsp_types::CompletionResponse>(value)
            .map(|r| match r {
                lsp_types::CompletionResponse::Array(items) => items,
                lsp_types::CompletionResponse::List(list) => list.items,
            })
            .unwrap_or_default();
        if items.is_empty() {
            return;
        }
        let mut candidates = self.completion_candidates();
        candidates.extend(items.into_iter().map(|item| {
            let label = item.label;
            fenix_picker::Candidate::new(label.clone(), fenix_completion::CompletionItem { label, kind: fenix_completion::CompletionKind::Lsp })
        }));
        let mut picker = fenix_picker::PickerState::new(candidates);
        picker.set_query(&query);
        if let Some(state) = &mut self.completion {
            state.picker = picker;
        }
    }

    /// `K` -- requests `textDocument/hover` for the cursor's current
    /// position. A no-op (no error message; this fires on every `K`
    /// press, including ones with genuinely nothing to say) if no
    /// server is attached to the focused buffer.
    pub(crate) fn request_hover(&mut self) {
        let Some((language, text_document, position)) = self.focused_lsp_context() else { return };
        let buffer = self.focused_buffer_id();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        let params = lsp_types::HoverParams { text_document_position_params: lsp_types::TextDocumentPositionParams { text_document, position }, work_done_progress_params: Default::default() };
        if let Ok(id) = session.client.request::<lsp_types::request::HoverRequest>(params) {
            session.pending.insert(id, PendingLspRequest::Hover { buffer });
        }
    }

    /// `gd` -- requests `textDocument/definition`.
    pub(crate) fn request_goto_definition(&mut self) {
        let Some((language, text_document, position)) = self.focused_lsp_context() else { return };
        let buffer = self.focused_buffer_id();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        let params = lsp_types::GotoDefinitionParams {
            text_document_position_params: lsp_types::TextDocumentPositionParams { text_document, position },
            work_done_progress_params: Default::default(),
            partial_result_params: Default::default(),
        };
        if let Ok(id) = session.client.request::<lsp_types::request::GotoDefinition>(params) {
            session.pending.insert(id, PendingLspRequest::Definition { buffer });
        }
    }

    /// `gr` -- requests `textDocument/references` (including the
    /// declaration itself in the results, matching what most editors'
    /// own "find references" shows by default).
    pub(crate) fn request_references(&mut self) {
        let Some((language, text_document, position)) = self.focused_lsp_context() else { return };
        let buffer = self.focused_buffer_id();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        let params = lsp_types::ReferenceParams {
            text_document_position: lsp_types::TextDocumentPositionParams { text_document, position },
            work_done_progress_params: Default::default(),
            partial_result_params: Default::default(),
            context: lsp_types::ReferenceContext { include_declaration: true },
        };
        if let Ok(id) = session.client.request::<lsp_types::request::References>(params) {
            session.pending.insert(id, PendingLspRequest::References { buffer });
        }
    }

    /// `SPC c a` -- requests `textDocument/codeAction` for the focused
    /// buffer's current line (a single-line range, matching what most
    /// editors send when the caller isn't a Visual selection -- Fenix
    /// has no separate "code action for this selection" entry point yet).
    pub(crate) fn request_code_action(&mut self) {
        let Some((language, text_document, position)) = self.focused_lsp_context() else { return };
        let buffer = self.focused_buffer_id();
        let diagnostics = self.open().buffer.path().and_then(|p| std::fs::canonicalize(p).ok()).and_then(|p| self.diagnostics.get(&fenix_lsp::normalize(p)).cloned()).unwrap_or_default();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        let line_range = lsp_types::Range { start: lsp_types::Position { line: position.line, character: 0 }, end: lsp_types::Position { line: position.line, character: u32::MAX } };
        let params = lsp_types::CodeActionParams {
            text_document,
            range: line_range,
            context: lsp_types::CodeActionContext { diagnostics, only: None, trigger_kind: None },
            work_done_progress_params: Default::default(),
            partial_result_params: Default::default(),
        };
        if let Ok(id) = session.client.request::<lsp_types::request::CodeActionRequest>(params) {
            session.pending.insert(id, PendingLspRequest::CodeAction { buffer });
        }
    }

    /// `SPC c f`/`SPC c F` -- requests `textDocument/formatting` when a
    /// server capable of it is attached; the caller (`format_selection`/
    /// `format_buffer`) falls back to `fenix-format`'s generic bracket-
    /// depth reindenter when this returns `false` (no server, or the
    /// attached one never advertised formatting support), same
    /// graceful-degradation posture as VNC's remote-resize falling back
    /// to client-side scaling. Always requests the *whole document* --
    /// LSP's `rangeFormatting` is a separate, optional capability this
    /// doesn't use yet, so a selection-scoped format still asks for and
    /// gets the whole file reformatted.
    pub(crate) fn request_lsp_format(&mut self) -> bool {
        let Some((language, text_document, _)) = self.focused_lsp_context() else { return false };
        let buffer = self.focused_buffer_id();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return false };
        if !session.capabilities.as_ref().is_some_and(|c| matches!(c.document_formatting_provider, Some(lsp_types::OneOf::Left(true)) | Some(lsp_types::OneOf::Right(_)))) {
            return false;
        }
        let params = lsp_types::DocumentFormattingParams {
            text_document,
            options: lsp_types::FormattingOptions { tab_size: 4, insert_spaces: true, ..Default::default() },
            work_done_progress_params: Default::default(),
        };
        match session.client.request::<lsp_types::request::Formatting>(params) {
            Ok(id) => {
                session.pending.insert(id, PendingLspRequest::Format { buffer });
                true
            }
            Err(_) => false,
        }
    }

    /// Sends `textDocument/completion` for the popup's current prefix --
    /// called from `sync_completion`/`force_open_completion` right after
    /// they open/update the popup with local candidates, so the LSP
    /// items (once the response arrives, `apply_lsp_completion`) merge
    /// into whatever's already showing instead of racing to replace it.
    /// A no-op if no server is attached -- the popup still works from
    /// local candidates alone, same as it always has for a language
    /// with none configured.
    fn request_lsp_completion(&mut self, prefix_start: usize) {
        let Some((language, text_document, position)) = self.focused_lsp_context() else { return };
        let buffer = self.focused_buffer_id();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        let params = lsp_types::CompletionParams {
            text_document_position: lsp_types::TextDocumentPositionParams { text_document, position },
            work_done_progress_params: Default::default(),
            partial_result_params: Default::default(),
            context: None,
        };
        if let Ok(id) = session.client.request::<lsp_types::request::Completion>(params) {
            session.pending.insert(id, PendingLspRequest::Completion { buffer, prefix_start });
        }
    }

    /// `SPC c r` -- opens the rename prompt, pre-filled with whatever
    /// identifier-prefix precedes the cursor (real editors' own
    /// convention: rename almost always starts from "call this
    /// something else," not a blank field), same capturing-prompt shape
    /// as `start_rename_file_prompt`. A no-op (with a message) if no
    /// server is attached to the focused buffer -- there's nothing to
    /// send a rename request to.
    pub(crate) fn open_lsp_rename_prompt(&mut self) {
        if self.focused_lsp_context().is_none() {
            self.set_error("no language server attached to this buffer".to_string());
            return;
        }
        let cursor = self.cursor();
        let ob = self.open();
        let current = completion::prefix_at_cursor(&ob.buffer, &cursor).map(|(_, prefix)| prefix).unwrap_or_default();
        self.lsp_rename_prompt = Some(current);
    }

    /// Routes one keypress to the in-progress `lsp_rename_prompt` --
    /// same shape as `rename_file_prompt_key`, except `Enter` sends the
    /// `textDocument/rename` request rather than applying anything
    /// synchronously (the edit only lands once the server answers).
    fn lsp_rename_prompt_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(input), Some(text)) = (&mut self.lsp_rename_prompt, pasted) {
                input.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some(input) = &mut self.lsp_rename_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.lsp_rename_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let new_name = self.lsp_rename_prompt.take().unwrap_or_default();
                self.send_lsp_rename(&new_name);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                input.pop();
            }
            KeyCode::Char(c) if key.mods == Mods::default() => input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    fn send_lsp_rename(&mut self, new_name: &str) {
        let new_name = new_name.trim();
        if new_name.is_empty() {
            return;
        }
        let Some((language, text_document, position)) = self.focused_lsp_context() else { return };
        let buffer = self.focused_buffer_id();
        let Some(session) = self.lsp_sessions.get_mut(&language) else { return };
        let params = lsp_types::RenameParams { text_document_position: lsp_types::TextDocumentPositionParams { text_document, position }, new_name: new_name.to_string(), work_done_progress_params: Default::default() };
        if let Ok(id) = session.client.request::<lsp_types::request::Rename>(params) {
            session.pending.insert(id, PendingLspRequest::Rename { buffer });
        }
    }

    /// What to show in place of the modeline while `lsp_rename_prompt`
    /// is capturing keys -- same shape as `rename_file_prompt_text`.
    fn lsp_rename_prompt_text(&self) -> Option<String> {
        self.lsp_rename_prompt.as_ref().map(|input| format!("rename to: {input}"))
    }

    /// Records `path` as recently-opened for the dashboard's "Recent
    /// Files" list -- called from every real "read this path off disk"
    /// call site (the picker, the explorer; `with_file`'s own CLI-arg
    /// branch does the equivalent inline before `self` exists). Unlike
    /// `known_projects`, this is automatic, not explicitly curated --
    /// see `RecentFiles`'s own doc comment.
    fn record_recent_file(&mut self, path: &Path) {
        let canonical = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
        self.recent_files.add(canonical);
        if let Err(err) = self.recent_files.save() {
            eprintln!("fenix: couldn't save recent files: {err}");
        }
    }

    /// The Tcl completion candidate pool (keywords + `ctags`-sourced
    /// definitions + any entries from `self.config.completion_symbols_
    /// file`, deduped against each other), rebuilding only when `root`
    /// differs from what's cached -- `ctags::run` shells a real
    /// subprocess, so this is worth avoiding on every keystroke (matches
    /// the "expensive work only on real state changes" discipline
    /// already used for git-status-on-explorer-open). The symbols file
    /// is re-read on the same cadence, not independently -- both sources
    /// share one manual refresh (`refresh_completion_tags`/`SPC c r`).
    /// Cloning the cached `Vec` on a cache hit is cheap: dozens to low
    /// hundreds of small entries.
    fn tcl_candidates(&mut self, root: Option<&Path>) -> Vec<fenix_picker::Candidate<fenix_completion::CompletionItem>> {
        let stale = match &self.tcl_candidates_cache {
            Some((cached_root, _)) => cached_root.as_deref() != root,
            None => true,
        };
        if stale {
            let mut seen = std::collections::HashSet::new();
            let mut candidates = Vec::new();
            for &keyword in fenix_completion::tcl::KEYWORDS {
                if seen.insert(keyword.to_string()) {
                    let item = fenix_completion::CompletionItem {
                        label: keyword.to_string(),
                        kind: fenix_completion::CompletionKind::Keyword,
                    };
                    candidates.push(fenix_picker::Candidate::new(item.label.clone(), item));
                }
            }
            for tag in self.tcl_tags(root) {
                if seen.insert(tag.name.clone()) {
                    let item = fenix_completion::CompletionItem { label: tag.name, kind: fenix_completion::CompletionKind::Tag };
                    candidates.push(fenix_picker::Candidate::new(item.label.clone(), item));
                }
            }
            if let Some(symbols_file) = &self.config.completion_symbols_file {
                for item in fenix_completion::custom::load(symbols_file) {
                    if seen.insert(item.label.clone()) {
                        candidates.push(fenix_picker::Candidate::new(item.label.clone(), item));
                    }
                }
            }
            self.tcl_candidates_cache = Some((root.map(PathBuf::from), candidates));
        }
        self.tcl_candidates_cache.as_ref().expect("just populated above if it was missing").1.clone()
    }

    /// The raw `ctags`-shelled Tcl tag list (name/file/line preserved),
    /// rebuilding only when `root` differs from what's cached -- same
    /// cost tradeoff and cache shape as `tcl_candidates`, which this now
    /// backs (see its own doc comment) alongside the `SPC c s` symbol
    /// picker (`picker_symbols`), which needs the location `tcl_
    /// candidates`'s `CompletionItem` conversion throws away. `None`
    /// root (no known project) always yields an empty list without
    /// shelling anything, same as `tcl_candidates` did inline before.
    fn tcl_tags(&mut self, root: Option<&Path>) -> Vec<fenix_completion::ctags::TagEntry> {
        let stale = match &self.tcl_tags_cache {
            Some((cached_root, _)) => cached_root.as_deref() != root,
            None => true,
        };
        if stale {
            let tags = root.map(|r| fenix_completion::ctags::run(r, "Tcl")).unwrap_or_default();
            self.tcl_tags_cache = Some((root.map(PathBuf::from), tags));
        }
        self.tcl_tags_cache.as_ref().expect("just populated above if it was missing").1.clone()
    }

    /// `SPC c s` -- fuzzy-find any known Tcl definition (proc/namespace)
    /// by its fully-qualified name and jump straight to where it's
    /// defined. Sourced from `tcl_tags`, so it shares that cache (and
    /// `SPC c r`'s manual refresh) with the Insert-mode completion
    /// popup's own `Tag`-kind entries -- opening this picker never
    /// re-shells `ctags` on its own.
    pub(crate) fn picker_symbols(&mut self) {
        let root = self.project_root.clone();
        let candidates =
            self.tcl_tags(root.as_deref()).into_iter().map(|tag| fenix_picker::Candidate::new(tag.name.clone(), tag)).collect();
        self.enter_picker(ActivePicker::Symbol(fenix_picker::PickerState::new(candidates)));
    }

    /// Whether the char immediately before the cursor sits inside a
    /// comment or string literal -- `sync_completion`'s auto-trigger
    /// gate, so typing an ordinary word inside a comment or a string
    /// literal doesn't pop the completion popup (real code identifiers
    /// aren't what's being typed there). Two checks, since neither
    /// alone covers both: `completion::cursor_in_unterminated_string`'s
    /// textual heuristic catches a string still being typed (open
    /// quote, cursor right after it); the focused buffer's own syntax
    /// tree catches a comment (always parses cleanly) and a string
    /// that's already been *closed* elsewhere on the line (a real
    /// capture by then). Deliberately only gates *auto*-trigger: `Ctrl-
    /// Space`'s `force_open_completion` bypasses this, the same "auto-
    /// trigger is context-gated, manual invoke always works" split
    /// most editors make. `false` (never suppress) for any buffer with
    /// no syntax tree at all -- an unrecognized language, or a non-
    /// editor buffer kind -- since there's no way to know the context
    /// without one; that's just today's pre-existing behavior.
    ///
    /// `spell` counts as a comment marker too: Tcl's own `highlights.
    /// scm` captures a comment node as both `@spell @comment` on the
    /// exact same span, and `resolve_overlaps` only ever keeps one
    /// capture of an exact tie (see its own doc comment) -- so either
    /// name showing up here means the same thing, and checking only
    /// `"comment"` would silently miss the tie going the other way.
    fn cursor_in_comment_or_string(&mut self) -> bool {
        let cursor = self.cursor();
        let id = self.focused_buffer_id();
        let Some(ob) = self.buffers.get_mut(id) else { return false };
        // Catches a freshly-typed, still-open string before the syntax
        // tree can (see `cursor_in_unterminated_string`'s own doc
        // comment for why the tree alone can't) -- checked first since
        // it needs no syntax-tree work at all.
        if completion::cursor_in_unterminated_string(&ob.buffer, &cursor) {
            return true;
        }
        // Same "drain this buffer's pending edits, apply them to its
        // syntax tree, then query" shape `content_highlights_for_
        // visible_range` already uses -- draining here and again
        // (with an empty leftover list) at the next redraw is harmless,
        // per `SyntaxState::apply_edits`'s own doc comment.
        let edits: Vec<fenix_syntax::RawEdit> = ob
            .buffer
            .drain_edits()
            .into_iter()
            .map(|d| fenix_syntax::RawEdit { start_char: d.start_char, new_end_char: d.new_end_char, removed: d.removed })
            .collect();
        let Some(syntax) = &mut ob.syntax else { return false };
        let source = ob.buffer.text();
        syntax.apply_edits(&source, &edits);

        let byte_idx = ob.buffer.char_to_byte(cursor.char_idx.min(ob.buffer.len_chars()));
        let Some(check_at) = byte_idx.checked_sub(1) else { return false };
        syntax
            .highlights_in_range(&source, check_at..byte_idx)
            .into_iter()
            .any(|(_, name)| name.starts_with("comment") || name.starts_with("string") || name == "spell")
    }

    /// Re-derives the completion popup's state from whatever's current --
    /// called once right after every keystroke that reaches Vim while
    /// Insert-relevant (`handle_key`'s Vim-fallthrough tier). Closes the
    /// popup (via `None`) the instant any of its preconditions stop
    /// holding: not in Insert mode, the cursor's inside a comment or
    /// string (`cursor_in_comment_or_string`), not a Tcl buffer, no
    /// identifier prefix at the cursor, or the prefix no longer matches
    /// anything.
    fn sync_completion(&mut self) {
        if self.vim.mode() != Mode::Insert {
            self.completion = None;
            return;
        }
        if self.cursor_in_comment_or_string() {
            self.completion = None;
            return;
        }
        let cursor = self.cursor();
        let ob = self.open();
        let Some((start, prefix)) = completion::prefix_at_cursor(&ob.buffer, &cursor) else {
            self.completion = None;
            return;
        };

        match &mut self.completion {
            Some(state) => {
                state.prefix_start = start;
                state.picker.set_query(&prefix);
            }
            None => {
                let candidates = self.completion_candidates();
                let mut picker = fenix_picker::PickerState::new(candidates);
                picker.set_query(&prefix);
                self.completion = Some(CompletionState { prefix_start: start, picker });
            }
        }
        // A server attached to this buffer may still fill the popup
        // once its (async) response lands (`apply_lsp_completion`),
        // even if the locally-known candidates are empty right now --
        // so an empty popup isn't closed out from under that pending
        // request the way it is when there's no server to wait on.
        let lsp_attached = self.focused_lsp_context().is_some();
        if lsp_attached {
            self.request_lsp_completion(start);
        }
        if !lsp_attached && self.completion.as_ref().is_some_and(|state| state.picker.is_empty()) {
            self.completion = None;
        }
        self.completion_scroll = 0;
    }

    /// The completion popup's own keys, claimed before Vim ever sees
    /// them. Returns whether `keypress` was claimed.
    ///
    /// The popup only ever exists in Insert mode. `Ctrl-Space`
    /// force-opens it whether or not it is already open (unclaimed
    /// otherwise -- not a global Ctrl chord, not handled by
    /// `handle_insert_key`). While it is open, its navigation/accept/
    /// dismiss keys are claimed here; every other key (plain typing,
    /// Backspace, arrows, Escape) falls through to the ordinary Vim
    /// dispatch, after which `sync_completion` re-derives the popup's
    /// state fresh -- there is no `VimEvent` for "a character was
    /// typed", so this recomputes rather than tracking incrementally.
    fn completion_key(&mut self, keypress: KeyPress) -> bool {
        if self.vim.mode() != Mode::Insert {
            return false;
        }
        if keypress == KeyPress::char(' ').with_ctrl() {
            self.force_open_completion();
            return true;
        }
        if self.completion.is_none() {
            return false;
        }
        match keypress.code {
            KeyCode::Named(FenixNamedKey::Down) => self.completion.as_mut().unwrap().picker.move_selection(1),
            KeyCode::Named(FenixNamedKey::Up) => self.completion.as_mut().unwrap().picker.move_selection(-1),
            KeyCode::Char('n') if keypress.mods.ctrl => self.completion.as_mut().unwrap().picker.move_selection(1),
            KeyCode::Char('p') if keypress.mods.ctrl => self.completion.as_mut().unwrap().picker.move_selection(-1),
            KeyCode::Named(FenixNamedKey::Tab) | KeyCode::Named(FenixNamedKey::Enter) => self.accept_completion(),
            // Vim's own accept key, beside the Tab/Enter every other
            // editor uses.
            KeyCode::Char('y') if keypress.mods.ctrl => self.accept_completion(),
            // Vim's own dismiss key: closes the popup and leaves you
            // typing. This is the behaviour Escape used to have, and
            // moving it here is the whole point -- see below.
            KeyCode::Char('e') if keypress.mods.ctrl => self.completion = None,
            // Escape is deliberately not claimed. It used to be, closing
            // the popup and leaving you in Insert -- so getting back to
            // Normal took two presses, and which one you needed depended
            // on whether a popup you may not even have been looking at
            // happened to be open. That is the VS Code reflex, and it
            // does not transfer: there, Escape has nothing to do *but*
            // dismiss things, so spending it on the popup costs nothing.
            // In a modal editor it costs the one key the whole grammar
            // rests on.
            //
            // Real Vim agrees, and `:h popupmenu-keys` is explicit: it
            // lists every key with a special meaning while the menu is
            // up -- CTRL-Y, CTRL-E, the arrows, Tab, Space -- and Escape
            // is not among them. It keeps its ordinary Insert-mode
            // meaning, and the popup closing is a consequence of leaving
            // Insert rather than something Escape was spent on. Falling
            // through is all that takes here too: `sync_completion` runs
            // after every key that reaches Vim and drops the popup the
            // moment the mode stops being Insert.
            _ => return false, // plain typing/Backspace/arrows/Escape
        }
        true
    }

    /// Force-opens the completion popup at the current (possibly empty)
    /// prefix, bypassing the normal ">=1 char" auto-trigger threshold --
    /// `Ctrl-Space`'s effect, the near-universal manual-trigger
    /// convention.
    fn force_open_completion(&mut self) {
        let cursor = self.cursor();
        let ob = self.open();
        let (prefix_start, prefix) =
            completion::prefix_at_cursor(&ob.buffer, &cursor).unwrap_or((cursor.char_idx, String::new()));
        let candidates = self.completion_candidates();
        let mut picker = fenix_picker::PickerState::new(candidates);
        picker.set_query(&prefix);
        let lsp_attached = self.focused_lsp_context().is_some();
        self.completion =
            if picker.is_empty() && !lsp_attached { None } else { Some(CompletionState { prefix_start, picker }) };
        if lsp_attached {
            self.request_lsp_completion(prefix_start);
        }
        self.completion_scroll = 0;
    }

    /// The completion candidate pool for whatever buffer is focused right
    /// now -- the Tcl-specific keyword/ctags/symbols-file pool (`tcl_
    /// candidates`) for a Tcl buffer, plus buffer-word candidates
    /// (`completion::buffer_words`) layered on top regardless of
    /// language -- the one source that isn't Tcl-specific, so a buffer
    /// in any other (or no recognized) language still gets a useful
    /// popup once there's something in it to complete from. Shared by
    /// `sync_completion`/`force_open_completion` so the two ways of
    /// opening the popup never drift out of sync with each other.
    /// Buffer-word candidates tagged `CompletionKind::Tag`, the same
    /// "not a built-in keyword" bucket ctags/symbols-file entries
    /// already share -- see that variant's own doc comment for why a
    /// third kind isn't worth a new calibrated popup color.
    fn completion_candidates(&mut self) -> Vec<fenix_picker::Candidate<fenix_completion::CompletionItem>> {
        let mut candidates = if self.focused_language() == Some(fenix_syntax::LanguageId::Tcl) {
            let root = self.project_root.clone();
            self.tcl_candidates(root.as_deref())
        } else {
            Vec::new()
        };
        let mut seen: std::collections::HashSet<String> = candidates.iter().map(|c| c.label.clone()).collect();
        for word in completion::buffer_words(&self.open().buffer) {
            if seen.insert(word.clone()) {
                let item = fenix_completion::CompletionItem { label: word.clone(), kind: fenix_completion::CompletionKind::Tag };
                candidates.push(fenix_picker::Candidate::new(word, item));
            }
        }
        candidates
    }

    /// `SPC c r` -- clears the cached Tcl completion candidates *and*
    /// eagerly re-shells `ctags` right away (rather than leaving it to
    /// the next `sync_completion`/`force_open_completion` call to
    /// trigger lazily), so pressing this key has an immediate, visible
    /// result: an `eprintln!` reporting either how many definitions were
    /// found or, if there's no known project root at all, that there
    /// was nothing to scan. `ctags::run` itself already reports *why* a
    /// scan came back empty (missing binary, non-zero exit, its stderr,
    /// ...) -- this is the "did the refresh actually do anything"
    /// summary on top of that, since a manually-triggered action with no
    /// feedback at all is indistinguishable from one that silently
    /// failed. Manual only (no save-hook/file-watcher refresh) -- see
    /// the plan's Scope.
    pub(crate) fn refresh_completion_tags(&mut self) {
        self.tcl_candidates_cache = None;
        self.tcl_tags_cache = None;
        match self.project_root.clone() {
            Some(root) => {
                let count = self.tcl_tags(Some(&root)).len();
                self.set_message(format!("refreshed Tcl completion tags for {} -- {count} definition(s) found", root.display()));
            }
            None => {
                self.set_error(
                    "no project root detected for the focused buffer -- open a file inside a recognized project \
                     (a `.git`/`Cargo.toml`/etc. marker somewhere above it) first",
                );
            }
        }
    }

    /// The focused buffer's detected language -- a path-extension check
    /// used by the Tcl-specific slice of `completion_candidates`,
    /// `toggle_comment_lines`'s own comment-token lookup, and (to
    /// exclude string/comment spans from the bracket scan, not to gate
    /// whether it runs at all -- `format_buffer`/`format_selection`
    /// work on any buffer regardless) `reindent_skip_ranges`.
    fn focused_language(&self) -> Option<fenix_syntax::LanguageId> {
        self.open().buffer.path().and_then(|p| p.extension()).and_then(|e| e.to_str()).and_then(fenix_syntax::detect_language)
    }

    /// `SPC c x`: flips the GFM task checkbox (`- [ ]`/`- [x]`/`- [X]`)
    /// on the focused pane's current line, in place. No per-language
    /// gate -- same "the text shape alone is the signal" posture list
    /// continuation (`fenix_vim::indent::parse_list_item`) already has,
    /// and this is an explicit, deliberate keypress rather than
    /// something that fires on every Enter, so there's even less risk
    /// in leaving it available everywhere. A no-op (with a message) if
    /// the current line has no checkbox to toggle.
    pub(crate) fn toggle_checkbox(&mut self) {
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        if !fenix_vim::toggle_checkbox(buffer, cursor, line) {
            self.set_error("no checkbox on this line to toggle");
        }
    }

    /// `gcc`/`gc{motion}` (`VimEvent::ToggleComment`) -- toggles a
    /// line-comment prefix across `start_line..=end_line`. Blank lines
    /// (after trimming leading whitespace) are never touched either
    /// direction, matching Comment.nvim/vim-commentary. If every non-
    /// blank line in range is already commented, uncomments all of
    /// them; otherwise comments every one that *isn't* already
    /// commented (leaving already-commented lines alone -- the standard
    /// "mixed selection comments the rest" convention those plugins
    /// share). A no-op (with a message, same posture `format_buffer`
    /// already has for "no formatter configured") if the language has
    /// no single-token line comment (`line_comment_token`), or the
    /// range is entirely blank.
    pub(crate) fn toggle_comment_lines(&mut self, start_line: usize, end_line: usize) {
        let Some(token) = self.focused_language().and_then(line_comment_token) else {
            self.set_error("no comment syntax known for this buffer's language");
            return;
        };
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let end_line = end_line.min(buffer.line_count().saturating_sub(1));

        // One pass over the *original* text: `first` (a char offset, not
        // byte -- indentation is assumed ASCII, same assumption this
        // codebase's other leading-whitespace helpers already make) and
        // whether this line is already commented. Bottom-to-top
        // processing below never invalidates a not-yet-processed
        // (lower) line's own `line_start_char`, so none of this needs
        // re-reading after an edit.
        let mut lines: Vec<(usize, usize, bool)> = Vec::new();
        let mut all_commented = true;
        for line in start_line..=end_line {
            let start = buffer.line_start_char(line);
            let text = buffer.text_range(start, start + buffer.line_len(line));
            let chars: Vec<char> = text.chars().collect();
            let Some(first) = chars.iter().position(|&c| c != ' ' && c != '\t') else { continue };
            let rest: String = chars[first..].iter().collect();
            let commented = rest.starts_with(token);
            if !commented {
                all_commented = false;
            }
            lines.push((line, first, commented));
        }
        if lines.is_empty() {
            return;
        }

        for &(line, first, commented) in lines.iter().rev() {
            let start = buffer.line_start_char(line);
            if all_commented {
                let mut remove_len = token.chars().count();
                if buffer.char_at(start + first + remove_len) == Some(' ') {
                    remove_len += 1;
                }
                buffer.delete_range(cursor, start + first, start + first + remove_len);
            } else if !commented {
                // Uses the *real* pane cursor here (not a throwaway
                // local `Cursor`) -- a throwaway one would leave the
                // real cursor's `char_idx` stale relative to the just-
                // inserted text, silently pointing at the wrong
                // character for whatever runs next (a follow-up motion,
                // or `.` replaying this same command from a different
                // line).
                cursor.char_idx = start + first;
                buffer.insert_str(cursor, &format!("{token} "));
            }
        }
        // Lands on the first affected line's own start, a stable and
        // predictable spot regardless of which lines above got
        // commented/uncommented (rather than wherever the loop's last
        // per-line edit happened to leave the cursor).
        cursor.char_idx = buffer.line_start_char(start_line).min(buffer.len_chars());
        let (_, col) = buffer.line_col(cursor);
        cursor.sticky_col = col;
        // The mutation happens here, *after* `vim.handle_key` already
        // returned (outside `route_keypress`'s own edit_count comparison
        // window) -- without this, `.` would silently fail to capture
        // `gcc`/`gc{motion}` as a repeatable change. Same guard as the
        // automatic `` `. `` mark write for the same reason.
        if !self.replaying_change {
            self.change_capture_dirty = true;
        }
    }

    /// `SPC c F` -- reindents the whole focused buffer in place,
    /// structurally (`fenix_format::reindent`) rather than via a
    /// per-language external tool -- Emacs' `indent-region`, real
    /// Vim's `=` operator. Works on any buffer, not just ones with a
    /// detected language (see `reindent_skip_ranges`'s own doc
    /// comment for what a detected one buys in accuracy). A no-op if
    /// the result is identical to what's already there.
    pub(crate) fn format_buffer(&mut self) {
        let indent_width = self.vim.indent_width();
        let language = self.focused_language();
        let source = self.open().buffer.text();
        let skip = reindent_skip_ranges(language, &source);
        let last_line = self.open().buffer.line_count().saturating_sub(1);
        let formatted = fenix_format::reindent(&source, 0, last_line, indent_width, &skip);
        if formatted == source {
            return;
        }
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let end = buffer.len_chars();
        buffer.replace_range(cursor, 0, end, &formatted);
    }

    /// `SPC c f` -- reindents the active Visual selection's lines in
    /// place, then returns to Normal mode (mirroring what an ordinary
    /// Visual operator does on completion). The whole buffer is still
    /// walked for nesting context (`fenix_format::reindent_lines`'s own
    /// doc comment on why), but only the selection's own lines become
    /// part of the edit. Only meaningful for Char/Line selections -- a
    /// line-based reindent has no sensible reading of a column
    /// rectangle -- so this is a no-op outside Visual mode or on a
    /// Visual-Block selection.
    pub(crate) fn format_selection(&mut self) {
        // See `request_lsp_format`'s own doc comment: a server-backed
        // format is always whole-document, so this deliberately
        // reformats more than just the selection when one's attached --
        // accepted rather than building a separate `rangeFormatting`
        // path for what's otherwise a rare, capability-gated case.
        if self.request_lsp_format() {
            let pane = self.focused_pane_id();
            if let Some(pane_state) = self.workspaces.active_pane_states_mut().get_mut(&pane) {
                self.vim.exit_visual_mode(&pane_state.cursor);
            }
            return;
        }
        let id = self.focused_buffer_id();
        let pane = self.focused_pane_id();
        let indent_width = self.vim.indent_width();
        let Some(ob) = self.buffers.get_mut(id) else { return };
        let Some(pane_state) = self.workspaces.active_pane_states_mut().get_mut(&pane) else { return };
        let Some((range, _linewise)) = self.vim.visual_selection_range(&ob.buffer, &pane_state.cursor) else {
            // Can't call `self.set_error` here -- `ob`/`pane_state` still
            // hold disjoint mutable borrows of `self.buffers`/`self.
            // workspaces` at this point. Set directly instead; equivalent
            // to `set_error`, just without the (unavailable) method call.
            self.status_message = Some(StatusMessage {
                text: "SPC c f needs an active (non-block) Visual selection".to_string(),
                is_error: true,
                set_at: Instant::now(),
            });
            return;
        };

        // The selection's own char range doesn't need to survive past
        // this point -- only the line numbers it touches do (a
        // structural reindent, like real Vim's `=`, always acts on
        // whole lines regardless of exactly where within them the
        // selection's own endpoints fall). `range.end` is an exclusive
        // upper bound, so the line it names isn't necessarily one the
        // selection actually reaches -- querying at `range.end - 1`
        // (clamped so an empty selection can't underflow) is what
        // avoids pulling in one extra line past a selection that
        // happens to end exactly on a line boundary.
        let start_line_cursor = Cursor { char_idx: range.start, sticky_col: 0 };
        let end_line_cursor = Cursor { char_idx: range.end.saturating_sub(1).max(range.start), sticky_col: 0 };
        let (first_line, _) = ob.buffer.line_col(&start_line_cursor);
        let (last_line, _) = ob.buffer.line_col(&end_line_cursor);

        let source = ob.buffer.text();
        let language = ob.buffer.path().and_then(|p| p.extension()).and_then(|e| e.to_str()).and_then(fenix_syntax::detect_language);
        let skip = reindent_skip_ranges(language, &source);
        let replacement = fenix_format::reindent_lines(&source, first_line, last_line, indent_width, &skip);

        let start = ob.buffer.line_start_char(first_line);
        let end = ob.buffer.line_start_char(last_line) + ob.buffer.line_len(last_line);
        if ob.buffer.text_range(start, end) != replacement {
            ob.buffer.replace_range(&mut pane_state.cursor, start, end, &replacement);
        }
        self.vim.exit_visual_mode(&pane_state.cursor);
    }

    /// Replaces the typed prefix with the selected candidate's full
    /// label -- one atomic undo step via `Buffer::replace_range`.
    fn accept_completion(&mut self) {
        let Some(state) = self.completion.take() else { return };
        let Some(label) = state.picker.selected().map(|c| c.payload.label.clone()) else { return };
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let end = cursor.char_idx;
        buffer.replace_range(cursor, state.prefix_start, end, &label);
    }

    pub(crate) fn save(&mut self) {
        self.save_inner(false);
    }

    /// `:w!` -- write even though the file changed underneath us.
    pub(crate) fn save_force(&mut self) {
        self.save_inner(true);
    }

    /// Writes the focused buffer, refusing by default if the file has
    /// changed on disk since Fenix last read or wrote it.
    ///
    /// The refusal is the point of the whole file-watching feature. A
    /// plain write is a whole-file overwrite: whatever the other side
    /// did between the buffer being read and this keystroke is gone,
    /// with nothing to recover it from. Both ways out are offered by
    /// name, because "your file changed" is useless without them.
    fn save_inner(&mut self, force: bool) {
        let id = self.focused_buffer_id();
        if self.open().buffer.path().is_none() {
            self.set_error("no file path to save to yet; pass a file path as the first argument");
            return;
        }
        if !force {
            // Re-checked here rather than trusting the last sweep: the
            // sweep runs every couple of seconds, and the write is
            // happening now.
            let mut sweep = DiskSweep::default();
            self.check_one_file(id, &mut sweep, false);
            if self.externally_changed.contains(&id) {
                let name = self.buffer_display_name(id);
                self.set_error(format!("{name} changed on disk since you opened it -- :w! keeps yours, :e! takes theirs"));
                self.wake_caret();
                return;
            }
            // The check may have reloaded a clean buffer out from under
            // this save, in which case there is nothing left to write
            // and saying so beats silently writing the file back to
            // itself.
            if !sweep.reloaded.is_empty() {
                self.set_message(format!("{} changed on disk and was reloaded -- nothing of yours to save", join_names(&sweep.reloaded)));
                self.wake_caret();
                return;
            }
        }
        let ob = self.open_mut();
        match ob.buffer.save() {
            Ok(()) => {
                let path = ob.buffer.path().unwrap().to_path_buf();
                // Recorded before the message: this is what stops the
                // next sweep reporting Fenix's own write as somebody
                // else's change.
                self.note_disk_state(id);
                // The work is on disk now, so the snapshot describes
                // nothing that's lost -- and leaving it would offer to
                // "recover" it on the next start.
                self.discard_recovery_for(id);
                self.set_message(format!("saved {}", path.display()));
            }
            Err(err) => self.set_error(format!("save failed: {err}")),
        }
        self.wake_caret();
    }

    /// Every open buffer whose kind can actually hold savable content
    /// (`BufferKind::tracks_unsaved_changes`) and is currently dirty,
    /// in `ids_sorted_by_path()` order. Single source of truth for
    /// "what would `:qa` warn about" -- generated, pathless views like
    /// the Jira/Docker/Git panels or the startup dashboard are never
    /// savable in the first place (`App::save` refuses them outright),
    /// so their `is_dirty()` -- which the host itself sets every time
    /// it re-renders them -- would otherwise falsely and permanently
    /// count as "unsaved work."
    fn dirty_tracked_buffer_ids(&self) -> Vec<BufferId> {
        self.buffers
            .ids_sorted_by_path()
            .into_iter()
            .filter(|&id| self.buffers.get(id).is_some_and(|ob| ob.kind.tracks_unsaved_changes() && ob.buffer.is_dirty()))
            .collect()
    }

    /// Whether any buffer has unsaved changes worth warning about --
    /// extends the modeline's existing single-buffer `[+]` marker
    /// across every open buffer.
    ///
    /// Test-only now: `request_quit` grew past a boolean and works
    /// from `dirty_tracked_buffer_ids` directly, so it can name the
    /// buffers it is blocking on. Kept because it is the readable way
    /// to assert "nothing is unsaved", which several tests want.
    #[cfg(test)]
    fn any_buffer_dirty(&self) -> bool {
        !self.dirty_tracked_buffer_ids().is_empty()
    }

    /// Up to this many dirty buffer names are listed by name in the
    /// quit-confirm message before falling back to "(+N more)".
    const QUIT_CONFIRM_NAME_CAP: usize = 4;

    /// Builds the "N unsaved buffers: a, b, c -- quit anyway?" message
    /// for `dirty`, naming buffers via `buffer_display_name` (the same
    /// path/`*dashboard*`/`*docker*`/etc. fallback the modeline already
    /// uses) so the user knows exactly what `:qa`/`SPC q q` is
    /// blocking on, not just how many.
    fn format_quit_confirm_message(&self, dirty: &[BufferId]) -> String {
        let count = dirty.len();
        let plural = if count == 1 { "" } else { "s" };
        let names: Vec<String> = dirty.iter().take(Self::QUIT_CONFIRM_NAME_CAP).map(|&id| self.buffer_display_name(id)).collect();
        let more = count.saturating_sub(Self::QUIT_CONFIRM_NAME_CAP);
        let suffix = if more > 0 { format!(" (+{more} more)") } else { String::new() };
        format!("{count} unsaved buffer{plural}: {}{suffix} -- quit anyway? (y=yes / n=no / l=list)", names.join(", "))
    }

    /// The event-loop-independent half of `request_quit`: arms `quit_
    /// confirm` and the modeline message when there's unsaved work
    /// (returning `true`), or leaves everything untouched when there
    /// isn't (returning `false`, meaning the caller should exit
    /// immediately). Split out purely so it's directly testable --
    /// `&ActiveEventLoop` can't be constructed in this test harness (see
    /// `test_dispatch_key`'s own doc comment for the same limitation
    /// elsewhere in this file).
    fn arm_quit_confirm_if_dirty(&mut self) -> bool {
        let dirty = self.dirty_tracked_buffer_ids();
        if dirty.is_empty() {
            return false;
        }
        self.quit_confirm = true;
        self.set_error(self.format_quit_confirm_message(&dirty));
        true
    }

    /// `:qa`/`:quitall`/`SPC q q`/the window's close button
    /// (`app.quit`) -- exits immediately if every buffer is saved,
    /// otherwise arms `quit_confirm` and shows a message instead of
    /// exiting, so an accidental (or just habitual, forgetting there's
    /// unsaved work) quit can't silently discard it. `:qa!`/`app.
    /// quit_force` bypasses this entirely (`commands::cmd_quit_force`)
    /// -- real Vim's own `!` convention for "yes, I know, do it
    /// anyway." Note this is no longer reachable from a bare `:q`/
    /// `SPC b k` -- those only close the focused buffer now, see
    /// `App::kill_buffer`.
    pub(crate) fn request_quit(&mut self, event_loop: &ActiveEventLoop) {
        if !self.arm_quit_confirm_if_dirty() {
            event_loop.exit();
        }
    }

    /// Saves every dirty, tracked (`BufferKind::tracks_unsaved_
    /// changes`) buffer that has a path. Refuses the whole operation
    /// up front -- no partial saves -- if any such buffer has no path
    /// (nothing to `:w` to yet), naming which one(s) need `:w <path>`
    /// first. Returns whether it's now safe to quit; callers must not
    /// quit on `false`, an error has already been set.
    fn save_all(&mut self) -> bool {
        let dirty = self.dirty_tracked_buffer_ids();
        let unnamed: Vec<BufferId> = dirty.iter().copied().filter(|&id| self.buffers.get(id).is_some_and(|ob| ob.buffer.path().is_none())).collect();
        if !unnamed.is_empty() {
            let names: Vec<String> = unnamed.iter().map(|&id| self.buffer_display_name(id)).collect();
            self.set_error(format!("no file name for {} -- use :w <path> first", names.join(", ")));
            return false;
        }
        for id in dirty {
            let name = self.buffer_display_name(id);
            let Some(ob) = self.buffers.get_mut(id) else { continue };
            if let Err(err) = ob.buffer.save() {
                self.set_error(format!("save failed for {name}: {err}"));
                return false;
            }
        }
        true
    }

    /// `:wqa`/`:xa` -- saves every unsaved, savable buffer, then quits
    /// unconditionally. Deliberately bypasses the `quit_confirm` y/n
    /// prompt entirely: once `save_all` returns `true` there is by
    /// definition nothing left dirty to warn about, mirroring real
    /// Vim's own `:wqa`, which either succeeds outright or errors, but
    /// never prompts.
    pub(crate) fn request_save_all_and_quit(&mut self, event_loop: &ActiveEventLoop) {
        if self.save_all() {
            event_loop.exit();
        }
    }

    /// The event-loop-independent half of `quit_confirm_key`: clears
    /// `quit_confirm` and reports what the pressed key resolved to --
    /// `y` confirms, `l` asks to see the offending buffers (chosen to
    /// not collide with `y`/`n`), anything else cancels. Split out for
    /// the same testability reason as `arm_quit_confirm_if_dirty`.
    fn resolve_quit_confirm_action(&mut self, keypress: KeyPress) -> QuitConfirmAction {
        self.quit_confirm = false;
        match keypress.code {
            KeyCode::Char('y') => QuitConfirmAction::Quit,
            KeyCode::Char('l') => QuitConfirmAction::ShowDirtyBuffers,
            _ => QuitConfirmAction::Cancel,
        }
    }

    /// Resolves an armed `quit_confirm` -- `y` quits unconditionally
    /// (same as `:qa!`), `l` opens the buffer picker filtered to just
    /// the dirty buffers so the user can jump to and save them instead
    /// of guessing, anything else cancels. Same "captures the very
    /// next key" shape as `docker_confirm_key`/`git_confirm_key`.
    fn quit_confirm_key(&mut self, keypress: KeyPress, event_loop: &ActiveEventLoop) {
        match self.resolve_quit_confirm_action(keypress) {
            QuitConfirmAction::Quit => event_loop.exit(),
            QuitConfirmAction::ShowDirtyBuffers => self.picker_switch_dirty_buffers(),
            QuitConfirmAction::Cancel => {}
        }
        self.wake_caret();
    }

    /// `l` at the `quit_confirm` prompt -- the same `SPC b b` picker
    /// machinery as `picker_switch_buffer`, restricted to just the
    /// buffers blocking `:qa`/`SPC q q`.
    fn picker_switch_dirty_buffers(&mut self) {
        let candidates = self
            .dirty_tracked_buffer_ids()
            .into_iter()
            .map(|id| fenix_picker::Candidate::new(format!("+ {}", self.buffer_display_name(id)), id))
            .collect();
        self.enter_picker(ActivePicker::SwitchBuffer(fenix_picker::PickerState::new(candidates)));
    }

    /// Directory the explorer opens in when asked to "start somewhere
    /// sensible": the focused buffer's own directory if it has a path,
    /// else the process's cwd.
    fn explorer_start_dir(&self) -> PathBuf {
        self.open()
            .buffer
            .path()
            .and_then(|p| p.parent())
            .filter(|p| !p.as_os_str().is_empty())
            .map(Path::to_path_buf)
            .unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")))
    }

    /// `SPC f j` (dired-jump): opens a real, closable (`SPC b k`),
    /// splittable (`SPC w v`/`SPC w s`), buffer-switcher-listed (`SPC b
    /// b`) dired buffer (`BufferKind::Explorer`) at the current file's
    /// directory, in the focused pane -- unlike the older full-buffer/
    /// sidebar overlay (`self.explorer`/`self.sidebar`, still used
    /// unchanged for `SPC p a`'s directory-picking flow and the
    /// persistent sidebar respectively; see `MainView::Explorer`'s own
    /// doc comment), this is a genuine `BufferId` other panes/workspaces
    /// can reference, and ordinary Vim motions navigate it for free
    /// since its content is real rope text (see `handle_key`'s own
    /// `BufferKind::Explorer` interception for the small set of action
    /// keys layered on top).
    pub(crate) fn explorer_jump(&mut self) {
        let dir = self.explorer_start_dir();
        self.open_dired_at(&dir);
    }

    /// Shared by `explorer_jump` (which derives `dir` from the current
    /// file) and tests (which just want a specific directory) -- opens a
    /// fresh dired buffer at `dir` in the focused pane.
    fn open_dired_at(&mut self, dir: &Path) {
        // Opens empty and fills in when the read lands. A fresh buffer
        // has nothing to keep showing in the meantime, unlike a pane
        // that is navigating from somewhere -- so this is the one case
        // where a pending listing really is blank.
        let state = ExplorerState::pending_at(dir);
        let (text, lines) = explorer_dired_text(&state, Some(dir), crate::wrap::DEFAULT_WRAP_WIDTH);
        let id = self.buffers.open_explorer(&text);
        self.dired_states.insert(id, state);
        self.dired_lines.insert(id, lines);
        self.open_buffer_in_focused_pane(id);
        self.explorer_navigate(id, dir);
        self.wake_caret();
    }

    // -- Reading a directory without freezing the editor -----------------

    /// Points `buffer`'s listing at `path`, reading it off the main
    /// thread.
    ///
    /// The pane keeps showing where it already is until the new listing
    /// arrives. That is deliberate on two counts: it is what a file
    /// manager should do anyway (you can still read the directory you
    /// are leaving), and it means a path that never answers costs you
    /// nothing at all -- Escape abandons the wait and you are still
    /// where you were, rather than sitting in an empty pane.
    ///
    /// Git status follows as a separate event on the same thread, so
    /// badges never delay the listing. It is skipped outright for UNC
    /// paths: running a `git status` subprocess across a share is slow
    /// and almost never what anyone wants. (A network drive mapped to a
    /// letter is not detected here -- telling those apart needs the
    /// drive-type lookup that comes with the Places work.)
    fn explorer_navigate(&mut self, buffer: BufferId, path: &Path) {
        let show_hidden = self.dired_states.get(&buffer).is_some_and(|s| s.show_hidden);
        self.next_explorer_request += 1;
        let request = self.next_explorer_request;
        let path = path.to_path_buf();
        self.explorer_requests.insert(buffer, ExplorerRequest { id: request, path: path.clone(), started: Instant::now(), done: false });

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let result = fenix_explorer::read_listing(&path, show_hidden).map_err(|err| err.to_string());
                    let worth_annotating = result.is_ok() && !is_unc(&path);
                    if proxy.send_event(FenixUserEvent::ExplorerListed { buffer, request, result }).is_err() {
                        return;
                    }
                    if worth_annotating {
                        let statuses = fenix_explorer::status_for_dir(&path);
                        let _ = proxy.send_event(FenixUserEvent::ExplorerGitStatus { buffer, request, statuses });
                    }
                });
            }
            None => {
                // No event loop to report back through (every test) --
                // read and apply inline, same posture as every other
                // background call in this file.
                let result = fenix_explorer::read_listing(&path, show_hidden).map_err(|err| err.to_string());
                let worth_annotating = result.is_ok() && !is_unc(&path);
                self.apply_explorer_listed(buffer, request, result);
                if worth_annotating {
                    let statuses = fenix_explorer::status_for_dir(&path);
                    self.apply_explorer_git_status(buffer, request, statuses);
                }
            }
        }
        self.render_dired(buffer, false);
    }

    /// `FenixUserEvent::ExplorerListed`: swaps in a listing, unless it
    /// has been superseded by a newer request or abandoned outright, or
    /// its buffer has since been closed.
    fn apply_explorer_listed(&mut self, buffer: BufferId, request: u64, result: Result<fenix_explorer::Listing, String>) {
        if !self.explorer_request_is_current(buffer, request) {
            return;
        }
        match result {
            Ok(listing) => {
                let path = listing.cwd.clone();
                if let Some(state) = self.dired_states.get_mut(&buffer) {
                    state.apply_listing(listing);
                }
                self.mark_explorer_request_done(buffer, request);
                self.render_dired(buffer, true);
                self.remember_visited_directory(&path);
            }
            Err(err) => {
                // The pane stays where it was, which is the useful place
                // to be left after a directory refuses to open.
                self.mark_explorer_request_done(buffer, request);
                self.set_error(err);
                self.render_dired(buffer, false);
            }
        }
        self.wake_caret();
    }

    /// `FenixUserEvent::ExplorerGitStatus`: the second pass, applied on
    /// top of a listing that is already on screen.
    fn apply_explorer_git_status(&mut self, buffer: BufferId, request: u64, statuses: HashMap<PathBuf, fenix_explorer::GitStatus>) {
        // Checked against the request the *listing* came from: badges
        // computed for one directory must never decorate another.
        if self.explorer_requests.get(&buffer).map(|r| r.id) != Some(request) {
            return;
        }
        if let Some(state) = self.dired_states.get_mut(&buffer) {
            state.apply_git_statuses(statuses);
        }
        self.render_dired(buffer, false);
        self.wake_caret();
    }

    /// Whether `request` is still the read `buffer` is waiting for.
    fn explorer_request_is_current(&self, buffer: BufferId, request: u64) -> bool {
        self.buffers.get(buffer).is_some() && self.explorer_requests.get(&buffer).is_some_and(|r| r.id == request && !r.done)
    }

    fn mark_explorer_request_done(&mut self, buffer: BufferId, request: u64) {
        if let Some(r) = self.explorer_requests.get_mut(&buffer) {
            if r.id == request {
                r.done = true;
            }
        }
    }

    /// Which directory `buffer` is currently waiting on, if the wait has
    /// gone on long enough to be worth mentioning. Below
    /// `SLOW_LISTING_AFTER` this stays `None`, so an ordinary local
    /// directory never flashes a "reading..." line on its way in.
    fn explorer_waiting_on(&self, buffer: BufferId) -> Option<&Path> {
        let request = self.explorer_requests.get(&buffer)?;
        (!request.done && request.started.elapsed() >= SLOW_LISTING_AFTER).then_some(request.path.as_path())
    }

    /// Escape on an explorer buffer with a read outstanding: stop
    /// waiting for it.
    ///
    /// Bumping the id is the whole mechanism -- the thread cannot be
    /// killed and is not asked to be (see `ExplorerRequest`); its result
    /// simply arrives stale and is dropped. Returns whether there was
    /// anything to abandon, so the key falls through when there was not.
    fn explorer_abandon_listing(&mut self, buffer: BufferId) -> bool {
        let Some(request) = self.explorer_requests.get(&buffer) else { return false };
        if request.done {
            return false;
        }
        let path = request.path.clone();
        self.explorer_requests.remove(&buffer);
        self.set_message(format!("stopped waiting for {}", path.display()));
        self.render_dired(buffer, false);
        self.wake_caret();
        true
    }

    /// Regenerates `buffer`'s text from its state in one atomic step
    /// (`Buffer::replace_range` over the whole content -- the same
    /// "rewrite the affected span as one step" tool `:s` already uses).
    ///
    /// `reset_cursor` is for arriving in a *different* directory, where
    /// the old cursor position means nothing against entirely different
    /// content. A re-render of the same listing (a git badge landing, a
    /// pending note appearing) leaves the cursor where the user put it.
    fn render_dired(&mut self, buffer: BufferId, reset_cursor: bool) {
        let waiting = self.explorer_waiting_on(buffer).map(Path::to_path_buf);
        // Laid out against whichever pane is showing this listing, so
        // the columns line up with the space they actually have.
        let width = self
            .windows()
            .windows()
            .into_iter()
            .find(|&p| self.windows().content(p) == Some(&buffer))
            .map(|pane| self.pane_cols_or(pane, crate::wrap::DEFAULT_WRAP_WIDTH))
            .unwrap_or(crate::wrap::DEFAULT_WRAP_WIDTH);
        let Some(state) = self.dired_states.get(&buffer) else { return };
        let (text, lines) = explorer_dired_text(state, waiting.as_deref(), width);
        self.dired_lines.insert(buffer, lines);

        // Which *line* each pane is on, remembered across the rewrite.
        // A character index would not survive it: the header changes
        // length whenever the counts in it change, so marking a file
        // would silently slide every cursor showing this listing
        // backwards -- and the next operation would act on a different
        // row than the one being looked at.
        let panes: Vec<fenix_window::WindowId> =
            self.windows().windows().into_iter().filter(|&p| self.windows().content(p) == Some(&buffer)).collect();
        let lines_before: Vec<usize> = panes
            .iter()
            .map(|&pane| {
                let cursor = self.pane_state(pane).cursor;
                self.buffers.get(buffer).map(|ob| ob.buffer.line_col(&cursor).0).unwrap_or(0)
            })
            .collect();

        if let Some(ob) = self.buffers.get_mut(buffer) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &text);
        }

        if !reset_cursor {
            let last_line = self.buffers.get(buffer).map(|ob| ob.buffer.line_count().saturating_sub(1)).unwrap_or(0);
            for (&pane, &line) in panes.iter().zip(&lines_before) {
                // Clamped, because a listing can get shorter -- deleting
                // the last row has to leave the cursor somewhere real.
                let line = line.min(last_line);
                let char_idx = self.buffers.get(buffer).map(|ob| ob.buffer.line_start_char(line)).unwrap_or(0);
                self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
            }
        }

        if reset_cursor {
            // Line 0 is the header, which is not an entry -- starting
            // there would mean the first `Enter` of every directory does
            // nothing. Land on the first real row instead.
            let first_entry = self.buffers.get(buffer).map(|ob| ob.buffer.line_start_char(1)).unwrap_or(0);
            for pane in self.windows().windows() {
                if self.windows().content(pane) == Some(&buffer) {
                    let ps = self.pane_state_mut(pane);
                    *ps = PaneState::seeded_at(Cursor { char_idx: first_entry, sticky_col: 0 });
                }
            }
        }
    }

    /// Hook for the recent-directories list the Places work will read.
    /// Deliberately a no-op for now rather than a `TODO` comment: the
    /// one call site that should record a visit is here, and finding it
    /// later is the part that goes wrong.
    fn remember_visited_directory(&mut self, _path: &Path) {}

    /// `Enter` on a dired buffer: opens the file at the cursor's line
    /// into the focused pane, or navigates into the directory at that
    /// line in place (same `BufferId`, freshly regenerated) -- matches
    /// real dired's own "navigating a subdirectory reuses the buffer"
    /// convention, not a new buffer per level.
    fn dired_activate_selected(&mut self) {
        let id = self.focused_buffer_id();
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let Some(Some(row)) = self.dired_lines.get(&id).and_then(|lines| lines.get(line)).copied() else {
            return;
        };
        let entry_idx = row.entry;
        let Some(entry) = self.dired_states.get(&id).and_then(|s| s.entries.get(entry_idx)) else { return };
        let path = entry.path.clone();
        let is_dir = entry.is_dir();
        if is_dir {
            self.explorer_navigate(id, &path);
        } else {
            self.open_file_from_picker(&path);
        }
    }

    /// Runs one `ExplorerAction` against the focused explorer buffer.
    ///
    /// Reconciles the cursor with the listing's own selection first, so
    /// every operation acts on the row the user is actually looking at,
    /// then re-renders, because almost all of them change what the text
    /// should say (a mark appearing, a count in the header moving).
    fn dired_handle_action(&mut self, action: ExplorerAction) {
        let Some(buffer) = self.focused_dired_buffer() else { return };
        self.sync_dired_selection_from_cursor();
        match action {
            // `Enter`/`l` on a file opens it into the pane, which is not
            // what the overlay's `Open` does (it has its own
            // return-to-editor dance), so this one stays local.
            ExplorerAction::Open => self.dired_activate_selected(),
            other => self.explorer_handle_action(other),
        }
        // A navigation action has already re-rendered through
        // `explorer_navigate`; re-rendering again here would be
        // harmless but would also undo a cursor reset it just made.
        if self.dired_states.contains_key(&buffer) && !matches!(action, ExplorerAction::Open | ExplorerAction::ParentDir | ExplorerAction::Refresh | ExplorerAction::ToggleHidden) {
            self.render_dired(buffer, false);
        }
    }

    /// `SPC e t`: toggles the sidebar open/closed. Opening focuses it
    /// immediately (you just asked to browse); closing always returns
    /// focus to the editor.
    pub(crate) fn toggle_sidebar(&mut self) {
        if self.sidebar_open {
            self.sidebar_open = false;
            self.sidebar_focused = false;
            self.sidebar = None;
        } else {
            let dir = self.explorer_start_dir();
            match ExplorerState::opened(&dir) {
                Ok(explorer) => {
                    self.sidebar = Some(explorer);
                    self.sidebar_open = true;
                    self.sidebar_focused = true;
                }
                Err(err) => eprintln!("fenix: couldn't list {} ({err})", dir.display()),
            }
        }
        self.wake_caret();
    }

    /// `SPC o t`: toggles the terminal panel's visibility. Hiding it is
    /// purely a layout/rendering concern (`terminal_open = false`,
    /// unfocus) -- deliberately does *not* touch `self.terminal` itself,
    /// unlike `toggle_sidebar`'s own `self.sidebar = None`, since the
    /// whole point is that the shell (and anything running in it) keeps
    /// going while hidden.
    ///
    /// Opening (for the first time, or after the previous shell exited
    /// -- `Terminal::is_alive` catches both) spawns a fresh shell on a
    /// **background thread**, reported back via `FenixUserEvent::
    /// TerminalSpawned` (`apply_terminal_spawned`) -- deliberately *not*
    /// a direct, synchronous `fenix_terminal::Terminal::spawn` call on
    /// this (the main UI) thread the way an earlier version of this
    /// function did. `Terminal::spawn` itself (the PTY/process-creation
    /// call) tends to return quickly even here; the actual reported bug
    /// ("nothing shows up in the panel, and SPC is stuck until I click
    /// something") traces to what happens *after*: the previous version
    /// focused the terminal immediately, right when the (fast) spawn
    /// call returned, before the shell had produced a single byte of
    /// output -- and a freshly spawned interactive shell can take a genuinely
    /// long time to print its first prompt on this class of environment
    /// (60-90+ seconds under antivirus/EDR-style scanning of the child
    /// process, confirmed via `fenix-terminal`'s own `spawn_write_and_
    /// read_a_real_shell_round_trip` test). With nothing rendered and no
    /// indication a terminal now owns every keystroke, `SPC` (and
    /// everything else) silently vanishes into that empty shell for as
    /// long as it stays silent -- indistinguishable from the app being
    /// broken. Backgrounding the spawn is cheap insurance against a
    /// slow `Terminal::spawn` call too, but the real fix is pairing the
    /// focus-grab with immediate, honest feedback: the panel opens (and
    /// shows a "Starting shell..." placeholder -- `terminal_panel_
    /// render`) right away, and only *focuses* once `apply_terminal_
    /// spawned` confirms the shell process actually exists -- so `SPC`
    /// still worked as the leader key for the (usually brief) gap
    /// before that, and once focus does land, the placeholder makes it
    /// obvious a terminal now owns the keyboard, however long it stays
    /// quiet after that (real Vim/Neovim's own `:terminal` convention --
    /// `Ctrl-\` -- gets the user back out).
    pub(crate) fn toggle_terminal(&mut self) {
        if self.terminal_open {
            self.terminal_open = false;
            self.terminal_focused = false;
            self.wake_caret();
            return;
        }
        self.terminal_open = true;
        let needs_spawn = self.terminal.as_mut().is_none_or(|t| !t.session.is_alive());
        if needs_spawn {
            self.terminal_focused = false;
            self.terminal_spawning = true;
            let rows = text::TERMINAL_ROWS as u16;
            let cols = self.terminal_cols();
            match self.event_proxy.clone() {
                Some(proxy) => {
                    std::thread::spawn(move || {
                        let result = fenix_terminal::Terminal::spawn(rows, cols);
                        let _ = proxy.send_event(FenixUserEvent::TerminalSpawned(TerminalTarget::Panel, TerminalSpawnResult(result)));
                    });
                }
                None => {
                    // No event loop to report back through (every test)
                    // -- run synchronously and apply the result directly,
                    // same "no fake event loop needed" posture `git_
                    // refresh_session`'s own `None` branch already has.
                    let result = fenix_terminal::Terminal::spawn(rows, cols);
                    self.apply_terminal_spawned(result);
                }
            }
        } else {
            self.terminal_focused = true;
        }
        self.wake_caret();
    }

    /// `FenixUserEvent::TerminalSpawned` handling: wires the freshly
    /// spawned shell's reader thread and, if the panel's still open
    /// (the user could have closed it again while the spawn was in
    /// flight -- the shell keeps running regardless, same "runs on
    /// while hidden" posture `toggle_terminal`'s own doc comment
    /// already describes), focuses it now that it's actually ready. A
    /// spawn failure closes the panel back up and surfaces the error
    /// via the status-message system rather than leaving an inert,
    /// permanently-empty panel open.
    fn apply_terminal_spawned(&mut self, result: std::io::Result<(fenix_terminal::Terminal, Box<dyn std::io::Read + Send>)>) {
        self.terminal_spawning = false;
        match result {
            Ok((session, reader)) => {
                let terminal_reader = self.event_proxy.clone().map(|proxy| {
                    TerminalReader::spawn(TerminalTarget::Panel, reader, move |event| proxy.send_event(event).is_ok())
                });
                self.terminal = Some(TerminalState { session, reader: terminal_reader });
                if self.terminal_open {
                    self.terminal_focused = true;
                }
            }
            Err(err) => {
                self.terminal_open = false;
                self.set_error(format!("couldn't start a terminal: {err}"));
            }
        }
        self.wake_caret();
    }

    /// Terminal columns that fit the current window width -- rows are
    /// always the fixed `text::TERMINAL_ROWS`, so only this needs
    /// recomputing on resize/font-size change. Falls back to a plain
    /// default when there's no real GPU/text pipeline yet (every test,
    /// and a `redraw()` before the GPU is ready) -- exact column count
    /// doesn't matter there, nothing asserts on real terminal line-
    /// wrapping in a headless test.
    fn terminal_cols(&self) -> u16 {
        let (width, char_width) = match (&self.gpu, &self.text) {
            (Some(gpu), Some(text)) => (gpu.size.width as f32, text.char_width()),
            _ => (800.0, text::CHAR_WIDTH),
        };
        (((width - text::PAD_LEFT * 2.0) / char_width).floor().max(1.0)) as u16
    }

    /// How many characters wide `pane`'s content area is, for wrapping
    /// generated text to the pane it's actually going into rather than
    /// to a fixed guess.
    ///
    /// Same shape as `terminal_cols`, including its headless fallback:
    /// with no GPU or text pipeline there's no real geometry to measure
    /// (every test, and any `redraw` before the pipeline is up), so it
    /// answers with `wrap::DEFAULT_WRAP_WIDTH` -- the fixed width every
    /// other panel wraps to, which keeps rendering tests asserting on
    /// one predictable layout.
    fn pane_cols(&self, pane: fenix_window::WindowId) -> usize {
        self.pane_cols_or(pane, crate::wrap::DEFAULT_WRAP_WIDTH)
    }

    /// `pane_cols` with the caller's own headless fallback -- the merge
    /// view's columns want a different one from the panels' wrap width,
    /// and a view that renders differently under test than in use is
    /// worse than one that renders wide.
    fn pane_cols_or(&self, pane: fenix_window::WindowId, fallback: usize) -> usize {
        let (Some(gpu), Some(text)) = (&self.gpu, &self.text) else {
            return fallback;
        };
        let (window_width, window_height) = (gpu.size.width as f32, gpu.size.height as f32);
        let (sidebar_px, terminal_h, modeline_top) = self.frame_metrics(window_height);
        let geometry = self.frame_geometry(window_width, sidebar_px, terminal_h, modeline_top);
        let Some((_, rect)) = geometry.panes.iter().find(|(id, _)| *id == pane) else {
            return fallback;
        };
        // Two characters of slack: a pane's own padding, and the
        // rightmost column being flush against the divider reads as
        // text running into the next pane even when it technically
        // fits.
        let cols = ((rect.w - text::PAD_LEFT * 2.0) / text.char_width()).floor() as isize - 2;
        cols.clamp(20, 400) as usize
    }

    /// `FenixUserEvent::TerminalOutput` handling: feeds the chunk into
    /// the live session's `vt100` parser and requests a redraw. A no-op
    /// if the session's since been replaced/closed (a stray chunk from
    /// an old, already-superseded shell -- there's no request-id here
    /// the way `GitMainReady`/`GitRefreshReady` need one, since output
    /// only ever comes from whichever session is *currently* `self.
    /// terminal`, never a concurrently-in-flight alternate request).
    fn apply_terminal_output(&mut self, target: TerminalTarget, bytes: Vec<u8>) {
        let state = match target {
            TerminalTarget::Panel => self.terminal.as_mut(),
            TerminalTarget::Buffer(id) => self.terminal_buffers.get_mut(&id),
        };
        let Some(state) = state else { return };
        state.session.process(&bytes);
        self.wake_caret();
    }

    // -- Pane-resident terminals ---------------------------------------

    /// `SPC o T`: a shell in the focused pane, staying in this
    /// workspace -- see `TerminalTarget` for how this differs from the
    /// popup panel, and why both exist.
    ///
    /// Pressing it while looking at a terminal you already opened takes
    /// the keyboard back rather than making a second one. That is the
    /// common case by far: `SPC o T` is both "give me a shell" and "let
    /// me type in it again after `Ctrl-\`", and a key that quietly
    /// accumulated shells every time you meant the second thing would
    /// leave processes running behind panes you never look at.
    pub(crate) fn open_terminal_buffer(&mut self) {
        let focused_buffer = self.focused_buffer_id();
        if self.terminal_buffers_spawning.contains(&focused_buffer) {
            self.focus_terminal_buffer(focused_buffer);
            self.wake_caret();
            return;
        }
        if let Some(state) = self.terminal_buffers.get_mut(&focused_buffer) {
            if state.session.is_alive() {
                self.focus_terminal_buffer(focused_buffer);
                self.wake_caret();
                return;
            }
            // The shell exited (`exit`, or something killed it) and its
            // last screen is still sitting there. Start a fresh one in
            // the same buffer rather than making a new one: the pane,
            // the workspace and the name are all still the ones the user
            // arranged, and only the process behind them is gone.
            self.terminal_buffers.remove(&focused_buffer);
            self.spawn_terminal_for(focused_buffer);
            self.wake_caret();
            return;
        }
        let id = self.buffers.open_terminal();
        self.terminal_buffers_opened += 1;
        self.terminal_buffer_labels.insert(id, format!("*terminal {}*", self.terminal_buffers_opened));
        self.open_buffer_in_focused_pane(id);
        self.spawn_terminal_for(id);
        self.wake_caret();
    }

    /// Starts a shell for one terminal buffer, sized to the pane
    /// currently showing it. Backgrounded for the same reason the
    /// panel's spawn is (see `toggle_terminal`): process creation is not
    /// something to block a redraw on.
    fn spawn_terminal_for(&mut self, id: BufferId) {
        let pane = self.windows().windows().into_iter().find(|&p| self.windows().content(p) == Some(&id)).unwrap_or(self.focused_pane_id());
        let (rows, cols) = self.terminal_pane_size(pane);
        self.terminal_buffers_spawning.insert(id);
        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let result = fenix_terminal::Terminal::spawn(rows, cols);
                    let _ = proxy.send_event(FenixUserEvent::TerminalSpawned(TerminalTarget::Buffer(id), TerminalSpawnResult(result)));
                });
            }
            None => {
                // No event loop to report back through (every test) --
                // run synchronously, same posture as `toggle_terminal`.
                let result = fenix_terminal::Terminal::spawn(rows, cols);
                self.apply_terminal_buffer_spawned(id, result);
            }
        }
    }

    /// `FenixUserEvent::TerminalSpawned` for a pane-resident shell.
    /// Grabs the keyboard only if the buffer is still open -- the user
    /// can close a pane while its shell is still starting, and a
    /// terminal that captured keys on the way out would swallow
    /// everything typed next with nothing on screen to explain it.
    fn apply_terminal_buffer_spawned(
        &mut self,
        id: BufferId,
        result: std::io::Result<(fenix_terminal::Terminal, Box<dyn std::io::Read + Send>)>,
    ) {
        self.terminal_buffers_spawning.remove(&id);
        if self.buffers.get(id).is_none() {
            // Closed while the spawn was in flight. `session`/`reader`
            // drop here, which kills the shell -- there is nothing left
            // that could ever show it.
            return;
        }
        match result {
            Ok((session, reader)) => {
                let terminal_reader = self.event_proxy.clone().map(|proxy| {
                    TerminalReader::spawn(TerminalTarget::Buffer(id), reader, move |event| proxy.send_event(event).is_ok())
                });
                self.terminal_buffers.insert(id, TerminalState { session, reader: terminal_reader });
                self.focus_terminal_buffer(id);
            }
            Err(err) => {
                self.terminal_buffer_labels.remove(&id);
                self.set_error(format!("couldn't start a terminal: {err}"));
            }
        }
        self.wake_caret();
    }

    /// Hands the keyboard to one pane-resident terminal, and says so --
    /// `Ctrl-\` is the only way back out, and nothing else on screen
    /// would tell you that.
    fn focus_terminal_buffer(&mut self, id: BufferId) {
        self.terminal_buffer_focused = Some(id);
        // A terminal owns every key while it has them, so no other
        // capturing surface may hold them at the same time.
        self.terminal_focused = false;
        self.sidebar_focused = false;
        let name = self.buffer_display_name(id);
        self.set_message(format!("{name} -- Ctrl-\\ to leave the terminal"));
    }

    /// Releases keyboard capture without closing anything -- the pane
    /// stays where it is and the shell keeps running, exactly as
    /// `Ctrl-\` does for the popup panel and for a VNC pane.
    fn unfocus_terminal_buffer(&mut self) {
        self.terminal_buffer_focused = None;
    }

    /// The pane-resident terminal that should receive a keystroke right
    /// now -- `Some` only when one has capture, the focused pane is
    /// still showing it, and its shell is still running.
    ///
    /// The pane check matters because capture survives a pane switch
    /// (see `terminal_buffer_focused`): without it, moving to another
    /// pane and typing would go on feeding the shell you walked away
    /// from. The liveness check is what gets you *out* of a terminal
    /// whose shell you just exited -- capture is released here, on the
    /// next keystroke, so the keyboard goes back to Vim on its own
    /// rather than disappearing into a dead process until you remember
    /// the release chord.
    fn active_terminal_buffer(&mut self) -> Option<BufferId> {
        let id = self.terminal_buffer_focused?;
        if self.windows().content(self.focused_pane_id()) != Some(&id) {
            return None;
        }
        if self.terminal_buffers.get_mut(&id).is_none_or(|state| !state.session.is_alive()) {
            self.unfocus_terminal_buffer();
            self.set_message("the shell exited -- SPC o T starts a new one");
            return None;
        }
        Some(id)
    }

    /// Writes one keypress to a pane-resident terminal, encoded exactly
    /// as the panel encodes its own (`encode_terminal_key`) -- a key
    /// with no terminal meaning is dropped rather than guessed at.
    fn write_terminal_buffer_input(&mut self, id: BufferId, keypress: KeyPress) {
        let Some(bytes) = encode_terminal_key(keypress) else { return };
        let Some(state) = self.terminal_buffers.get_mut(&id) else { return };
        let _ = state.session.write_input(&bytes);
    }

    /// How many rows and columns of shell fit in `pane`, from the same
    /// geometry the render loop lays that pane out with. Falls back to a
    /// plain default with no GPU/text pipeline (every headless test),
    /// same posture as `terminal_cols`.
    fn terminal_pane_size(&self, pane: fenix_window::WindowId) -> (u16, u16) {
        let cols = (self.pane_cols_or(pane, 80) as u16).max(1);
        let (Some(gpu), Some(text)) = (&self.gpu, &self.text) else {
            return (text::TERMINAL_ROWS as u16, cols);
        };
        let (window_width, window_height) = (gpu.size.width as f32, gpu.size.height as f32);
        let line_height = text.line_height();
        let (sidebar_px, terminal_h, modeline_top) = self.frame_metrics(window_height);
        let geometry = self.frame_geometry(window_width, sidebar_px, terminal_h, modeline_top);
        let Some((_, rect)) = geometry.panes.iter().find(|(id, _)| *id == pane) else {
            return (text::TERMINAL_ROWS as u16, cols);
        };
        // Every pane reserves its top line for a title bar, so the shell
        // gets what is left -- measured the same way `redraw` does, or
        // the last row would render underneath the pane below it.
        let content = pane_content_rect(*rect, line_height, true);
        let rows = (text::lines_that_fit(content.h, line_height).max(1)) as u16;
        (rows, cols)
    }

    /// Drops one pane-resident terminal and kills its shell. Called
    /// when its buffer is closed -- the one gesture that says the shell
    /// has no owner left, since pointing a pane elsewhere deliberately
    /// leaves it running (see `TerminalState`).
    fn close_terminal_buffer(&mut self, id: BufferId) {
        // `TerminalState::drop` kills the shell, which is also what
        // unblocks its reader thread's blocking read.
        self.terminal_buffers.remove(&id);
        self.terminal_buffers_spawning.remove(&id);
        self.terminal_buffer_labels.remove(&id);
        if self.terminal_buffer_focused == Some(id) {
            self.terminal_buffer_focused = None;
        }
    }

    /// `SPC v v`: opens (or, if already open, switches straight to) the
    /// named VM's VNC console. Connects lazily -- the first selection of
    /// a given name is what actually dials it; every later selection
    /// just switches workspace/focus, since the session stays live in
    /// the background once opened (this feature's own "each VM stays
    /// connected" decision). Backgrounds the connect itself (mirrors
    /// `toggle_terminal`'s own reasoning: a slow/unreachable host would
    /// otherwise freeze the whole editor for as long as the handshake
    /// takes).
    pub(crate) fn open_vnc_session(&mut self, name: &str) {
        if let Some(session) = self.vnc_sessions.get(name) {
            let (workspace_index, buffer) = (session.workspace_index, session.buffer);
            self.workspaces.switch_to_index(workspace_index);
            // Focus whichever pane is already showing this session, if
            // any -- there can be several (splits), and after the switch
            // above there may be none at all, if the pane that used to
            // show it has since been pointed at something else. Falling
            // back to opening it in the focused pane is what makes a
            // second `SPC v v` on the same host reliably get you back to
            // it rather than landing on a pane showing whatever replaced
            // it.
            match self.windows().windows().into_iter().find(|&p| self.windows().content(p) == Some(&buffer)) {
                Some(pane) => {
                    self.windows_mut().focus(pane);
                }
                None => self.open_buffer_in_focused_pane(buffer),
            }
            self.sync_vnc_focus();
            self.wake_caret();
            return;
        }
        if self.vnc_connecting.contains(name) {
            return; // already dialing this one -- SPC v v pressed twice in a row
        }
        let Some((_, host, port)) = self.config.vnc_hosts.iter().find(|(n, _, _)| n == name).cloned() else {
            self.set_error(format!("no VNC host configured named {name}"));
            return;
        };
        self.vnc_connecting.insert(name.to_string());
        self.start_vnc_connect(name.to_string(), host, port);
        self.set_message(format!("Connecting to {name}..."));
        self.wake_caret();
    }

    /// `SPC r f`: a fuzzy picker over `config.ini`'s `[documents]`
    /// index -- the shelf of references the user reads often enough to
    /// want by name rather than by hunting for a path. Same "one
    /// candidate list, one picker variant" shape as `start_vnc_picker`,
    /// which the `[vnc]` section already established for a
    /// hand-configured list.
    ///
    /// An empty index says so rather than opening a picker over nothing:
    /// this is the one list in the app that can only be populated by
    /// hand-editing `config.ini`, so "no matches" would be indis-
    /// tinguishable from "you haven't set this up yet".
    pub(crate) fn start_document_picker(&mut self) {
        if self.config.documents.is_empty() {
            self.set_error("no documents configured -- add a [documents] section to config.ini (doc1 = Name|path)".to_string());
            return;
        }
        let candidates = self
            .config
            .documents
            .iter()
            .map(|(name, path)| fenix_picker::Candidate::new(name.clone(), path.clone()))
            .collect();
        self.enter_picker(ActivePicker::Document(fenix_picker::PickerState::new(candidates)));
    }

    /// Opens one `[documents]` entry in the focused pane. A PDF goes
    /// through the reader (`PdfPlacement::FocusedPane`); anything else
    /// opens as ordinary text, exactly the way `open_file_from_picker`
    /// already does -- the index is a shelf of *documents*, and there's
    /// no reason a plain-text or Markdown reference can't live on it.
    ///
    /// A configured path that no longer exists reports that by name
    /// rather than opening an empty buffer titled after a file that
    /// isn't there: this list is hand-maintained and long-lived, so a
    /// moved or renamed file is the expected failure, and silently
    /// creating a blank buffer for it would look like the document was
    /// empty.
    fn open_document(&mut self, path: &Path) {
        if !path.exists() {
            self.set_error(format!("{} no longer exists -- check its [documents] entry in config.ini", path.display()));
            return;
        }
        if Self::looks_like_pdf(path) {
            self.open_pdf_path_with(path, PdfPlacement::FocusedPane);
            return;
        }
        let id = self.buffers.open_path(path);
        self.note_disk_state(id);
        self.open_buffer_in_focused_pane(id);
        self.refresh_project_root();
        self.record_recent_file(path);
        self.main_view = MainView::Editor;
        self.wake_caret();
    }

    /// `SPC v v`: a fuzzy picker over every configured VNC host name --
    /// confirming calls `open_vnc_session`, same "one candidate list,
    /// one picker variant" shape as `picker_pick_theme`.
    pub(crate) fn start_vnc_picker(&mut self) {
        let candidates = self.config.vnc_hosts.iter().map(|(name, _, _)| fenix_picker::Candidate::new(name.clone(), name.clone())).collect();
        self.enter_picker(ActivePicker::VncHost(fenix_picker::PickerState::new(candidates)));
    }

    /// The actual background-thread connect, shared by the first connect
    /// (`open_vnc_session`) and every later reconnect attempt
    /// (`schedule_vnc_reconnect`) -- both just need "dial this host:port,
    /// report back via the same `FenixUserEvent::VncConnected`."
    fn start_vnc_connect(&mut self, name: String, host: String, port: u16) {
        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let result = fenix_vnc::VncClient::connect(&host, port);
                    let _ = proxy.send_event(FenixUserEvent::VncConnected { name, host, port, result: VncConnectResult(result) });
                });
            }
            None => {
                // No event loop to report back through (every test) --
                // run synchronously, same posture as `toggle_terminal`'s
                // own `None` branch.
                let result = fenix_vnc::VncClient::connect(&host, port);
                self.apply_vnc_connected(name, host, port, result);
            }
        }
    }

    /// `FenixUserEvent::VncConnected` handling -- covers both a brand
    /// new session (nothing in `vnc_sessions` for `name` yet) and a
    /// reconnect attempt after a `Disconnected` frame (the session, and
    /// its pane/buffer/workspace, are kept alive across the gap -- see
    /// `VncSession`'s own doc comment on field drop order). A failed
    /// *first* connect just reports the error, no auto-retry -- retrying
    /// forever against e.g. a typo'd hostname would be pure noise. A
    /// failed *reconnect* backs off and tries again up to `MAX_VNC_
    /// RECONNECT_ATTEMPTS` times before giving up and leaving the pane
    /// showing its last-known frame, reopenable manually.
    fn apply_vnc_connected(&mut self, name: String, host: String, port: u16, result: std::io::Result<(fenix_vnc::VncClient, std::sync::mpsc::Receiver<fenix_vnc::VncFrame>)>) {
        self.vnc_connecting.remove(&name);
        if self.vnc_sessions.contains_key(&name) {
            match result {
                Ok((client, receiver)) => {
                    // Reuses the *existing* shared framebuffer (a cheap
                    // `Arc::clone`, not a fresh one) so the last-good
                    // picture stays visible across the reconnect gap,
                    // same posture as never resetting it here before
                    // this rewrite.
                    let Some(framebuffer) = self.vnc_sessions.get(&name).map(|s| s.framebuffer.clone()) else { return };
                    let reader = self.event_proxy.clone().map(|proxy| {
                        VncReader::spawn(receiver, name.clone(), framebuffer, move |event| proxy.send_event(event).is_ok())
                    });
                    if let Some(session) = self.vnc_sessions.get_mut(&name) {
                        session.client = client;
                        session.reader = reader;
                        session.reconnect_attempts = 0;
                        // The fresh connection starts back at the
                        // server's own default resolution -- it has no
                        // memory of any resize this client previously
                        // requested on the dropped connection. Forget
                        // ours too, so the next stable frame in `redraw`
                        // re-sends the request even if the pane's own
                        // size never changed across the reconnect gap.
                        session.resize_requested_for = (0, 0);
                    }
                    self.set_message(format!("VNC {name} reconnected"));
                }
                Err(err) => {
                    let attempts = self.vnc_sessions.get(&name).map_or(0, |s| s.reconnect_attempts) + 1;
                    if let Some(session) = self.vnc_sessions.get_mut(&name) {
                        session.reconnect_attempts = attempts;
                    }
                    if attempts >= MAX_VNC_RECONNECT_ATTEMPTS {
                        self.set_error(format!("VNC {name}: reconnect failed after {attempts} attempts ({err}) -- giving up; reopen manually with SPC v v"));
                    } else {
                        self.set_error(format!("VNC {name}: reconnect failed ({err}); retrying..."));
                        self.schedule_vnc_reconnect(name, host, port, attempts);
                    }
                }
            }
            self.wake_caret();
            return;
        }

        match result {
            Ok((client, receiver)) => {
                let buffer = self.buffers.open_vnc();
                // Opened where you are, like any other buffer, rather
                // than always seizing a brand-new workspace -- that's
                // what made a second session impossible to place beside
                // the first, so "two VMs side by side" (or a VM beside a
                // file) couldn't be built at all. `open_buffer_in_
                // focused_pane` still falls back to a new workspace when
                // the focused pane is already some *other* tracked
                // session's, so this can't hijack one.
                self.open_buffer_in_focused_pane(buffer);
                let workspace_index = self.workspaces.active_index();
                let framebuffer = Arc::new(Mutex::new(fenix_vnc::framebuffer::VncFramebuffer::new()));
                let reader = self.event_proxy.clone().map(|proxy| {
                    VncReader::spawn(receiver, name.clone(), framebuffer.clone(), move |event| proxy.send_event(event).is_ok())
                });
                self.vnc_sessions.insert(
                    name,
                    VncSession {
                        client,
                        reader,
                        workspace_index,
                        buffer,
                        host,
                        port,
                        framebuffer,
                        texture: None,
                        texture_dims: (0, 0),
                        cursor: None,
                        pointer_pos: None,
                        pointer_buttons: 0,
                        reconnect_attempts: 0,
                        last_pane_size: (0, 0),
                        pane_size_stable_since: Instant::now(),
                        resize_requested_for: (0, 0),
                    },
                );
                self.sync_vnc_focus();
            }
            Err(err) => {
                self.set_error(format!("couldn't connect to {name}: {err}"));
            }
        }
        self.wake_caret();
    }

    /// Backs off, then retries a dropped VNC connection -- spawned on its
    /// own one-shot thread (a plain `std::thread::sleep` there costs
    /// nothing real, unlike blocking the main thread would) that sleeps
    /// for `vnc_reconnect_delay(attempts)` and then runs the exact same
    /// connect `start_vnc_connect` does. A no-op without a real
    /// `event_proxy` (every test) -- there's nothing to retry against in
    /// a headless test anyway.
    fn schedule_vnc_reconnect(&mut self, name: String, host: String, port: u16, attempts: u32) {
        let Some(proxy) = self.event_proxy.clone() else { return };
        let delay = vnc_reconnect_delay(attempts);
        std::thread::spawn(move || {
            std::thread::sleep(delay);
            let result = fenix_vnc::VncClient::connect(&host, port);
            let _ = proxy.send_event(FenixUserEvent::VncConnected { name, host, port, result: VncConnectResult(result) });
        });
    }

    /// `SPC v q`: closes whichever VNC session owns the currently focused
    /// pane/buffer, if any -- unlike `docker.close`/`git.close`/`jira.
    /// close` (which always mean "the one session," since only one of
    /// each ever exists at a time), this needs its own "which one" scan
    /// since several VNC sessions can be open at once.
    pub(crate) fn vnc_close_focused_session(&mut self) {
        let Some(key) = self.vnc_session_key_for_buffer(self.focused_buffer_id()) else {
            self.set_error("no VNC session focused");
            return;
        };
        self.vnc_session_close(&key);
    }

    /// Tears down one VNC session: drops the connection (closing the
    /// socket, per `fenix_vnc::VncClient`'s own `Drop`), closes its
    /// buffer, clears its pane title, and removes its workspace --
    /// mirrors `docker_session_close`/`jira_session_close` exactly,
    /// generalized to look the session up by name instead of assuming
    /// there's only one.
    pub(crate) fn vnc_session_close(&mut self, name: &str) {
        let Some(session) = self.vnc_sessions.remove(name) else { return };
        if self.vnc_focused.as_deref() == Some(name) {
            self.set_vnc_focused(None);
        }
        self.buffers.close(session.buffer);
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    /// Finds whichever VNC session (if any) owns `id` as its pane's
    /// buffer -- a linear scan over at most a handful of sessions, not a
    /// real cost; needed because sessions are keyed by name, not by
    /// buffer, unlike Docker/Git/Jira's flat per-session buffer-id lists.
    fn vnc_session_key_for_buffer(&self, id: BufferId) -> Option<String> {
        self.vnc_sessions.iter().find(|(_, session)| session.buffer == id).map(|(key, _)| key.clone())
    }

    /// Same as `vnc_session_key_for_buffer`, for callers that start from
    /// a pane (mouse hit-testing, the per-pane render loop) -- resolved
    /// *through* that pane's buffer rather than by remembering which
    /// pane a session lives in.
    ///
    /// That indirection is the whole point: a buffer can be shown by any
    /// number of panes (that's what a split is), so a session pinned to
    /// one pane id silently stops existing for every other pane showing
    /// the same buffer. It used to be pinned, and a `SPC w v` split of a
    /// VNC pane drew the new pane completely blank -- the session was
    /// still running and still had a texture, its `pane` just didn't
    /// match.
    fn vnc_session_key_for_pane(&self, pane: fenix_window::WindowId) -> Option<String> {
        let buffer = *self.windows().content(pane)?;
        self.vnc_session_key_for_buffer(buffer)
    }

    /// Recomputes `vnc_focused` from whichever pane is actually focused
    /// right now -- called after every focus-changing action (opening a
    /// session, pane navigation, a click) instead of trying to intercept
    /// every such call site individually. Also throttles every *other*
    /// open session down to `IDLE_REFRESH_MILLIS` and the newly-focused
    /// one (if any) back up to full rate -- see `fenix_vnc::VncClient::
    /// set_active`'s own doc comment for why this is safe to do on every
    /// focus change rather than only on a real visibility transition.
    fn sync_vnc_focus(&mut self) {
        let focused_key = self.vnc_session_key_for_buffer(self.focused_buffer_id());
        let newly_focused = focused_key.is_some() && focused_key != self.vnc_focused;
        self.set_vnc_focused(focused_key.clone());
        for (key, session) in self.vnc_sessions.iter() {
            session.client.set_active(Some(key) == focused_key.as_ref());
        }
        // Mirror the local clipboard to the VM on genuinely *becoming*
        // focused (not on every call -- most calls here are just
        // reconfirming the same pane) -- simpler than intercepting `p`/
        // `P` inside a focused VNC pane to inject a paste keystroke
        // sequence, which would invent a keybinding meaning that only
        // exists inside a VNC pane. The guest's own paste keystroke
        // (typed normally) then just forwards as an ordinary keysym.
        if newly_focused {
            if let Some((key, text)) = focused_key.clone().zip(self.clipboard.as_mut().and_then(|c| c.get_text().ok())) {
                if let Some(session) = self.vnc_sessions.get(&key) {
                    session.client.send_clipboard(text);
                }
            }
        }
    }

    /// The one place `vnc_focused` is actually written -- besides the
    /// field itself, keeps two OS-level pointer concerns in sync with
    /// input capture.
    ///
    /// The cursor *grab*: confined to the window while some VNC session
    /// has capture, released the moment it doesn't. Keyboard capture
    /// (`vnc_focused`) already means every keystroke goes straight to the
    /// guest instead of vim's own dispatch; without also confining the
    /// pointer, a drag started inside a VNC pane can wander onto another
    /// window or monitor mid-gesture and strand a mouse button held down
    /// in the guest. `Confined`, not `Locked`: pointer forwarding
    /// (`handle_vnc_pointer_move`) maps the cursor's real *absolute*
    /// window-local position onto the framebuffer, which needs the actual
    /// cursor position, not `Locked`'s relative-motion-from-center
    /// scheme.
    ///
    /// The cursor's *visibility*: hidden while captured, so the guest's
    /// own pointer is the only one on screen. Without this there are
    /// visibly two -- the host's, and the guest's drawn either by
    /// `redraw` (from `VncFrame::Cursor`) or by the server compositing it
    /// into the framebuffer when it doesn't support `CursorPseudo` --
    /// tracking each other a few pixels apart, since the two have
    /// different shapes and hotspots. Exactly one of those guest cursors
    /// always exists, so hiding the host's can't leave a captured session
    /// with no pointer at all.
    ///
    /// Achieved by swapping in `vnc_hidden_cursor` (a transparent 1x1
    /// image), not `Window::set_cursor_visible(false)` -- a real,
    /// confirmed bug the obvious approach has on Windows: winit's own
    /// Windows backend, whenever *both* its grabbed and hidden cursor
    /// flags are set at once, clips the cursor to a single pixel at the
    /// window's exact center instead of the whole client area (see
    /// `refresh_os_cursor` in winit's `platform_impl/windows/window_
    /// state.rs` -- deliberate on winit's part, to stop a hidden,
    /// confined cursor near a window edge from activating the taskbar
    /// underneath it, but incompatible with also wanting the cursor
    /// free to move across the *whole* pane for pointer forwarding).
    /// That combination is exactly what this function used to set --
    /// `Confined` plus `set_cursor_visible(false)` -- which is why the
    /// cursor would appear to freeze in place the instant a VNC session
    /// captured it, moving again only once capture released. Swapping
    /// the cursor's *image* for a transparent one instead leaves
    /// winit's own hidden-flag unset, so the confine clips to the full
    /// window as intended, while still rendering nothing on screen.
    ///
    /// Both are best-effort: not every platform/backend supports
    /// grabbing (see `CursorGrabMode::Confined`'s own platform notes),
    /// and a failure isn't fatal to using the app, just to the
    /// convenience.
    fn set_vnc_focused(&mut self, key: Option<String>) {
        if key == self.vnc_focused {
            return;
        }
        self.vnc_focused = key;
        if let Some(window) = &self.window {
            let captured = self.vnc_focused.is_some();
            let mode = if captured { CursorGrabMode::Confined } else { CursorGrabMode::None };
            let _ = window.set_cursor_grab(mode);
            // Not `Window::set_cursor_visible(false)` -- see `vnc_
            // hidden_cursor`'s own doc comment for why that specific
            // combination (confined *and* hidden) freezes the cursor
            // in place on Windows instead of merely hiding it. Swapping
            // the cursor's own *image* for a transparent one achieves
            // the same "just the guest's own pointer is visible" result
            // without ever setting the flag that triggers it.
            if captured {
                if let Some(hidden) = &self.vnc_hidden_cursor {
                    window.set_cursor(hidden.clone());
                }
            } else {
                window.set_cursor(winit::window::CursorIcon::default());
            }
        }
    }

    /// Sends one key event (down or up) to the named VNC session, mapped
    /// through `fenix_vnc::keysym::keysym_for` -- `None` for a key with
    /// no keysym mapping (silently dropped, same posture `encode_
    /// terminal_key`'s own `None` case already has). The actual sequence
    /// of keysyms this turns into (bracketed with any held modifiers) is
    /// `vnc_key_sequence`'s own job -- split out as a plain function so
    /// that ordering is unit-testable without a live `VncClient`
    /// connection.
    fn send_vnc_key(&mut self, key: &str, keypress: KeyPress, down: bool) {
        let Some(keysym) = fenix_vnc::keysym::keysym_for(keypress) else { return };
        let Some(session) = self.vnc_sessions.get(key) else { return };
        for (sym, sym_down) in vnc_key_sequence(keysym, keypress.mods, down) {
            session.client.send_key(sym, sym_down);
        }
    }

    /// `FenixUserEvent::VncFrame` handling -- decodes/applies one update
    /// from a session's background reader thread. A no-op if the named
    /// session's since been closed (a stray frame from an already-
    /// superseded/closed connection, same "arrived after the fact"
    /// reasoning `apply_terminal_output` doesn't need but `GitMainReady`/
    /// `GitRefreshReady` do).
    ///
    /// `Rect`/`Copy` never reach this function at all -- `VncReader`
    /// applies those directly to the session's shared `framebuffer` on
    /// its own thread (see its own doc comment for why). `Resolution`
    /// only needs to reset `texture` here (the buffer itself was already
    /// resized, under the lock, by the reader thread before this event
    /// was even sent); `Disconnected` still needs the error message and
    /// reconnect scheduling. Both redraw immediately -- rare, discrete,
    /// non-bursty events, unlike the pixel traffic that used to flow
    /// through here.
    fn apply_vnc_frame(&mut self, key: String, frame: fenix_vnc::VncFrame) {
        match frame {
            fenix_vnc::VncFrame::Resolution { .. } => {
                let Some(session) = self.vnc_sessions.get_mut(&key) else { return };
                // Recreated lazily next redraw, once the new size is
                // known and (if not already) a real GPU exists.
                session.texture = None;
                if let Some(window) = &self.window {
                    window.request_redraw();
                }
            }
            fenix_vnc::VncFrame::Rect { .. } | fenix_vnc::VncFrame::Copy { .. } | fenix_vnc::VncFrame::UpdateEnd => {
                debug_assert!(false, "VncReader applies Rect/Copy/UpdateEnd directly and never forwards them");
            }
            fenix_vnc::VncFrame::Cursor { width, height, hotspot_x, hotspot_y, bgra } => {
                let Some(session) = self.vnc_sessions.get_mut(&key) else { return };
                // A zero-sized cursor is the server's way of saying "draw
                // nothing here" -- keeping an empty `VncCursor` around
                // would just mean a zero-area quad every frame.
                session.cursor = if width == 0 || height == 0 {
                    None
                } else {
                    // `texture: None` -- uploading needs `&wgpu::Device`,
                    // so the next `redraw` builds it. Cursor shapes change
                    // rarely (per hovered widget, not per pointer move),
                    // so this costs a texture creation about as often as
                    // the guest changes its pointer, not per frame.
                    Some(VncCursor { width, height, hotspot_x, hotspot_y, bgra, texture: None })
                };
                if let Some(window) = &self.window {
                    window.request_redraw();
                }
            }
            fenix_vnc::VncFrame::ClipboardText(text) => {
                if let Some(clipboard) = &mut self.clipboard {
                    let _ = clipboard.set_text(text);
                }
            }
            fenix_vnc::VncFrame::Bell => {}
            fenix_vnc::VncFrame::Disconnected(reason) => {
                let Some(session) = self.vnc_sessions.get_mut(&key) else { return };
                session.reader = None;
                let (host, port) = (session.host.clone(), session.port);
                self.set_error(format!("VNC {key} disconnected: {reason} -- reconnecting..."));
                self.schedule_vnc_reconnect(key, host, port, 0);
                if let Some(window) = &self.window {
                    window.request_redraw();
                }
            }
        }
    }

    /// `SPC v s`: writes the focused VNC session's current framebuffer to
    /// a timestamped PNG next to the project root (or the process's cwd,
    /// same fallback `explorer_start_dir` already uses) -- a cheap extra
    /// once the CPU-side `framebuffer` already exists for every session
    /// regardless (see `VncSession::framebuffer`'s own doc comment).
    pub(crate) fn vnc_screenshot(&mut self) {
        let Some(key) = self.vnc_session_key_for_buffer(self.focused_buffer_id()) else {
            self.set_error("no VNC session focused");
            return;
        };
        let Some(session) = self.vnc_sessions.get(&key) else { return };
        let (fb_width, fb_height, snapshot) = {
            let fb = session.framebuffer.lock().unwrap();
            let (w, h) = fb.dimensions();
            (w, h, fb.snapshot())
        };
        if fb_width == 0 || fb_height == 0 {
            self.set_error(format!("VNC {key}: no frame to save yet"));
            return;
        }
        let Some(image_buffer) = image::RgbaImage::from_fn(fb_width as u32, fb_height as u32, |x, y| {
            let i = (y as usize * fb_width as usize + x as usize) * 4;
            let b = snapshot[i];
            let g = snapshot[i + 1];
            let r = snapshot[i + 2];
            let a = snapshot[i + 3];
            image::Rgba([r, g, b, a])
        })
        .into()
        else {
            self.set_error(format!("VNC {key}: couldn't build the screenshot image"));
            return;
        };
        let dir = self.explorer_start_dir();
        let filename = format!("vnc-{key}-{}.png", chrono::Local::now().format("%Y%m%d-%H%M%S"));
        let path = dir.join(filename);
        match image::DynamicImage::ImageRgba8(image_buffer).save(&path) {
            Ok(()) => self.set_message(format!("saved {}", path.display())),
            Err(err) => self.set_error(format!("couldn't save screenshot: {err}")),
        }
    }

    /// Whether `path` should open as a rendered PDF pane instead of an
    /// ordinary text buffer -- checked by every real "open this path"
    /// call site (`open_file_from_picker`, `explorer_open_selected`,
    /// startup) before it ever reaches `BufferList::open_path`, which has
    /// no notion of PDFs and would otherwise load the raw bytes as
    /// (garbage) text. Same case-insensitive extension-check idiom as
    /// `fenix_syntax::detect_language_from_path`.
    fn looks_like_pdf(path: &Path) -> bool {
        path.extension().and_then(|e| e.to_str()).is_some_and(|ext| ext.eq_ignore_ascii_case("pdf"))
    }

    /// Points the focused pane at `path` as a PDF (`SPC r o` and every
    /// path-opening call site once `looks_like_pdf` says so) -- the PDF
    /// equivalent of `open_file_from_picker`. Reuses an already-open
    /// session for the same canonicalized path instead of duplicating it
    /// (mirrors `open_vnc_session`'s "already open -> switch" branch);
    /// otherwise spawns the shared worker if this is the first PDF
    /// opened this run, creates the pane/buffer, and dispatches the
    /// `Open` request -- the actual page count/render arrive later, async,
    /// via `apply_pdf_response`.
    pub(crate) fn open_pdf_path(&mut self, path: &Path) {
        self.open_pdf_path_with(path, PdfPlacement::NewWorkspace);
    }

    /// `open_pdf_path` with an explicit `PdfPlacement` -- see that enum
    /// for what each choice means and why the document index
    /// (`SPC r f`) wants the other one.
    fn open_pdf_path_with(&mut self, path: &Path, placement: PdfPlacement) {
        let canonical = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
        if let Some(session) = self.pdf_sessions.get(&canonical) {
            let (workspace_index, pane) = (session.workspace_index, session.pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(pane);
            self.main_view = MainView::Editor;
            self.wake_caret();
            return;
        }

        if self.pdf_worker.is_none() {
            let worker = match self.event_proxy.clone() {
                Some(proxy) => fenix_pdf::PdfWorker::spawn(move |response| {
                    let _ = proxy.send_event(FenixUserEvent::PdfResponse(response));
                }),
                // No event loop to report back through (every test) --
                // the worker still runs (pdfium calls stay serialized
                // through it, same as real use), its replies just have
                // nowhere to go, mirroring `start_vnc_connect`'s own
                // reasoning for why a synchronous fallback isn't used
                // here: unlike a plain `VncClient::connect` call, calling
                // pdfium directly on this thread would reintroduce the
                // exact concurrent-access hazard the shared worker exists
                // to prevent (see `fenix_pdf`'s own top-level doc comment).
                None => fenix_pdf::PdfWorker::spawn(|_| {}),
            };
            self.pdf_worker = Some(worker);
        }

        // Retired *before* the new buffer is created and pointed at, so
        // its own teardown (which clears `pane_titles` for the pane it
        // was on -- the very pane about to be reused) can't wipe the new
        // session's title back out from under it.
        if placement == PdfPlacement::FocusedPane {
            if let Some(previous) = self.pdf_session_key_for_pane(self.focused_pane_id()) {
                if previous == canonical {
                    return; // already showing exactly this document here
                }
                // Its outline/search companions belong to *that*
                // document, so they go with it -- closed via their own
                // functions (which need the session to still exist, hence
                // before `pdf_session_forget`) rather than left as panes
                // showing a stale bookmark list next to a different PDF.
                // In the `NewWorkspace` case `remove_active()` takes care
                // of these for free, which is why `pdf_session_close`
                // doesn't need this.
                self.pdf_close_outline_pane(&previous);
                self.pdf_close_search_pane(&previous);
                self.pdf_session_forget(&previous);
            }
        }

        let buffer = self.buffers.open_pdf();
        let cursor = Cursor::at_start();
        match placement {
            PdfPlacement::NewWorkspace => self.workspaces.new_workspace(buffer, cursor),
            PdfPlacement::FocusedPane => self.open_buffer_in_focused_pane(buffer),
        }
        let workspace_index = self.workspaces.active_index();
        let pane = self.focused_pane_id();
        let name = canonical.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_else(|| canonical.display().to_string());
        self.pane_titles.insert(pane, format!("PDF: {name}"));
        self.pdf_display_names.insert(buffer, name);

        let doc_key = fenix_pdf::PdfDocKey::new();
        if let Some(worker) = &self.pdf_worker {
            worker.send(fenix_pdf::PdfRequest::Open { key: doc_key, path: canonical.clone() });
        }
        self.pdf_sessions.insert(
            canonical.clone(),
            PdfSession {
                doc_key,
                workspace_index,
                pane,
                buffer,
                page_count: 0,
                current_page: 0,
                rendered_page: None,
                land_at_bottom: false,
                last_requested_size: (0, 0),
                pending_request_id: 0,
                page_point_size: (0.0, 0.0),
                zoom: PdfZoom::FitPage,
                last_pane_size: (0, 0),
                scroll_offset: (0, 0),
                full_bgra: None,
                last_uploaded: None,
                texture: None,
                outline: None,
                pending_search_request_id: 0,
                last_search_query: String::new(),
            },
        );
        self.refresh_project_root();
        self.record_recent_file(&canonical);
        self.main_view = MainView::Editor;
        self.wake_caret();
    }

    /// Finds whichever PDF session (if any) owns `pane` -- same "keyed by
    /// something other than buffer/pane, so a linear scan" shape as
    /// `vnc_session_key_for_pane`.
    fn pdf_session_key_for_pane(&self, pane: fenix_window::WindowId) -> Option<PathBuf> {
        self.pdf_sessions.iter().find(|(_, session)| session.pane == pane).map(|(key, _)| key.clone())
    }

    /// Same as `pdf_session_key_for_pane`, keyed by buffer instead -- what
    /// `kill_buffer_now` needs to recognize "the buffer about to be
    /// killed belongs to a PDF session" the same way it already does for
    /// VNC (`vnc_session_key_for_buffer`).
    fn pdf_session_key_for_buffer(&self, id: BufferId) -> Option<PathBuf> {
        self.pdf_sessions.iter().find(|(_, session)| session.buffer == id).map(|(key, _)| key.clone())
    }

    /// Tears down one PDF session: tells the shared worker to drop the
    /// document (freeing pdfium's own handle for it), closes its buffer,
    /// clears its pane title/display name, and removes its workspace --
    /// mirrors `vnc_session_close` exactly. Also cleans up an open
    /// outline companion pane's side-table entries, if it has one: the
    /// pane/buffer itself is torn down for free by `remove_active()`
    /// (the outline pane lives in the same workspace, since `pdf_toggle_
    /// outline` opens it via a plain split), but `pdf_outline_panes`/
    /// `pdf_outline_lines`/`pdf_outline_source` don't know that on their
    /// own and would otherwise keep stale entries forever -- a real leak
    /// over a long session's worth of opening/closing PDFs, and (worse)
    /// a wrong answer if this same path is ever reopened: `pdf_outline_
    /// panes` would still claim an outline pane exists for it when it
    /// doesn't.
    fn pdf_session_close(&mut self, key: &Path) {
        let Some(workspace_index) = self.pdf_sessions.get(key).map(|session| session.workspace_index) else { return };
        self.pdf_session_forget(key);
        self.workspaces.switch_to_index(workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    /// Everything `pdf_session_close` does *except* removing the
    /// session's workspace: drops the document on the worker, closes its
    /// buffer, clears its pane title/display name, and forgets its
    /// outline/search companion side-table entries. Split out because
    /// `PdfPlacement::FocusedPane` needs exactly this and nothing more --
    /// opening a document into a pane that already held a different PDF
    /// has to retire that session (otherwise two sessions claim the same
    /// pane and `redraw`'s `find(|s| s.pane == ...)` picks between them
    /// by `HashMap` iteration order) while *keeping* the workspace the
    /// new document is about to be shown in.
    fn pdf_session_forget(&mut self, key: &Path) {
        let Some(session) = self.pdf_sessions.remove(key) else { return };
        if let Some(worker) = &self.pdf_worker {
            worker.send(fenix_pdf::PdfRequest::Close { key: session.doc_key });
        }
        self.buffers.close(session.buffer);
        self.pane_titles.remove(&session.pane);
        self.pdf_display_names.remove(&session.buffer);
        if self.pdf_outline_panes.remove(key).is_some() {
            let stale_outline_buffers: Vec<BufferId> =
                self.pdf_outline_source.iter().filter(|(_, source)| source.as_path() == key).map(|(buffer, _)| *buffer).collect();
            for buffer in stale_outline_buffers {
                self.pdf_outline_lines.remove(&buffer);
                self.pdf_outline_source.remove(&buffer);
            }
        }
        // Same leak/stale-answer reasoning as the outline cleanup just
        // above, for a still-open search-results companion pane.
        if self.pdf_search_panes.remove(key).is_some() {
            let stale_search_buffers: Vec<BufferId> =
                self.pdf_search_source.iter().filter(|(_, source)| source.as_path() == key).map(|(buffer, _)| *buffer).collect();
            for buffer in stale_search_buffers {
                self.pdf_search_result_lines.remove(&buffer);
                self.pdf_search_source.remove(&buffer);
            }
        }
    }

    /// Dispatches a fresh `RenderPage` request for `key` at `target_w` x
    /// `target_h` pixels, bumping `pending_request_id` first so a reply to
    /// an earlier, now-superseded request gets dropped by `apply_pdf_
    /// response` instead of clobbering a newer one. A no-op if the
    /// session or worker doesn't exist, the document hasn't reported its
    /// page count back yet, or `target_w`/`target_h` is degenerate
    /// (nothing meaningful to render before either is known).
    fn dispatch_pdf_render(&mut self, key: &Path, target_w: u32, target_h: u32) {
        if target_w == 0 || target_h == 0 {
            return;
        }
        let Some(session) = self.pdf_sessions.get_mut(key) else { return };
        if session.page_count == 0 {
            return;
        }
        session.pending_request_id += 1;
        session.last_requested_size = (target_w, target_h);
        let (doc_key, request_id, page_index) = (session.doc_key, session.pending_request_id, session.current_page);
        if let Some(worker) = &self.pdf_worker {
            worker.send(fenix_pdf::PdfRequest::RenderPage { key: doc_key, request_id, page_index, target_w, target_h });
        }
    }

    /// Recomputes this session's render target from its current `zoom` +
    /// `page_point_size` + `last_pane_size` and dispatches it -- the
    /// shared "something changed that isn't a plain resize" path every
    /// keypress-driven mutator (`pdf_turn_page`, `pdf_goto_page`, the
    /// `pdf_zoom_*` family) uses instead of duplicating this computation.
    /// `redraw`'s own pane-classification loop does the equivalent
    /// computation for the *resize* case specifically, since it's the
    /// only place that learns about a resize in the first place -- this
    /// is what everything else reaches for once `last_pane_size` is
    /// already known from that loop's last pass.
    fn pdf_dispatch_render_for_zoom(&mut self, key: &Path) {
        let Some(session) = self.pdf_sessions.get(key) else { return };
        let (target_w, target_h) = pdf_target_size(session.zoom, session.page_point_size, session.last_pane_size);
        self.dispatch_pdf_render(key, target_w, target_h);
    }

    /// `FenixUserEvent::PdfResponse` handling. Every variant carries its
    /// own `fenix_pdf::PdfDocKey`, not the path `pdf_sessions` is keyed
    /// by, so each arm scans for the session whose `doc_key` matches
    /// first -- a no-op (like `apply_vnc_frame`'s per-name lookup) if
    /// that session's since been closed.
    fn apply_pdf_response(&mut self, response: fenix_pdf::PdfResponse) {
        match response {
            fenix_pdf::PdfResponse::Opened { key, page_count, page_width_pts, page_height_pts } => {
                let Some(path) = self.pdf_sessions.iter().find(|(_, s)| s.doc_key == key).map(|(p, _)| p.clone()) else { return };
                let Some(session) = self.pdf_sessions.get_mut(&path) else { return };
                session.page_count = page_count;
                session.page_point_size = (page_width_pts, page_height_pts);
                // No render dispatched here -- `last_requested_size`
                // stays `(0, 0)`, which `redraw`'s pane-classification
                // loop (the only place that actually knows this pane's
                // real current pixel size) treats as "never rendered
                // yet" and requests the first render itself on the very
                // next frame, the same way it reacts to any later resize.
            }
            fenix_pdf::PdfResponse::OpenFailed { key, message } => {
                let Some(path) = self.pdf_sessions.iter().find(|(_, s)| s.doc_key == key).map(|(p, _)| p.clone()) else { return };
                self.set_error(format!("couldn't open {}: {message}", path.display()));
            }
            fenix_pdf::PdfResponse::PageRendered { key, request_id, page_index, width, height, bgra, page_width_pts, page_height_pts } => {
                let Some(path) = self.pdf_sessions.iter().find(|(_, s)| s.doc_key == key).map(|(p, _)| p.clone()) else { return };
                let Some(session) = self.pdf_sessions.get_mut(&path) else { return };
                if request_id != session.pending_request_id || page_index != session.current_page {
                    return; // superseded by a later request/page turn since this one was dispatched
                }
                session.rendered_page = Some(page_index);
                session.page_point_size = (page_width_pts, page_height_pts);
                // A fresh render always starts scrolled to the top-left,
                // and always invalidates whatever's currently uploaded
                // (see `last_uploaded`'s own doc comment) -- `redraw`
                // recreates the texture from `full_bgra` as needed, same
                // "defer the actual GPU work to redraw" shape VNC's own
                // `Resolution` arm uses.
                // `u32::MAX` rather than a computed bottom offset:
                // `redraw` already clamps `scroll_offset` against the
                // render's real size and the pane's current size every
                // frame (the only place both are known together), so
                // "as far down as this page goes" needs no second copy
                // of that math here.
                session.scroll_offset = if session.land_at_bottom { (0, u32::MAX) } else { (0, 0) };
                session.land_at_bottom = false;
                session.full_bgra = Some((width, height, bgra));
                session.last_uploaded = None;
                // Self-correction for a PDF whose pages aren't all the
                // same point-size: `page_width_pts`/`page_height_pts` is
                // *this* page's real size, which may differ from whatever
                // was assumed when this request was dispatched (there was
                // no way to know ahead of a page actually being open) --
                // if the target this page's real size calls for doesn't
                // match what was actually rendered, the render just
                // applied is wrong-sized and immediately superseded by a
                // corrected one. The mutable `session` borrow must end
                // before this call (`dispatch_pdf_render` needs its own
                // `&mut self`), hence computing `corrected` here but
                // calling after the match arm's borrow is out of scope.
                //
                // Tolerated to within a pixel on each axis rather than
                // demanded exactly: real documents routinely vary their
                // page boxes in the second decimal place (this is true of
                // most standards PDFs -- a cover page at 595.22x842pt
                // followed by a body at 595.38x841.98pt is typical), which
                // rounds to a fit target one pixel off often enough that
                // an exact comparison re-renders the whole page a second
                // time on a large fraction of page turns. A pixel of
                // difference is invisible -- the render is aspect-correct
                // for its own page either way, and `redraw` centers it in
                // the pane -- so paying a full re-render for it is pure
                // waste on the one path that most needs to feel instant.
                let corrected = pdf_target_size(session.zoom, session.page_point_size, session.last_pane_size);
                let off_by = (corrected.0.abs_diff(width), corrected.1.abs_diff(height));
                if corrected != (0, 0) && (off_by.0 > 1 || off_by.1 > 1) {
                    self.dispatch_pdf_render(&path, corrected.0, corrected.1);
                }
            }
            fenix_pdf::PdfResponse::RenderFailed { key, request_id, message } => {
                let Some(path) = self.pdf_sessions.iter().find(|(_, s)| s.doc_key == key).map(|(p, _)| p.clone()) else { return };
                let Some(session) = self.pdf_sessions.get(&path) else { return };
                if request_id != session.pending_request_id {
                    return;
                }
                self.set_error(format!("couldn't render page: {message}"));
            }
            fenix_pdf::PdfResponse::Outline { key, entries } => {
                let Some(path) = self.pdf_sessions.iter().find(|(_, s)| s.doc_key == key).map(|(p, _)| p.clone()) else { return };
                if let Some(session) = self.pdf_sessions.get_mut(&path) {
                    session.outline = Some(entries.clone());
                }
                // Always opens the pane once fetched -- `FetchOutline` is
                // only ever dispatched by `pdf_toggle_outline` wanting to
                // show it, so there's no other reason a reply would be in
                // flight. `pdf_open_outline_pane` re-focuses the session's
                // own workspace/pane first, so this is correct even if the
                // user navigated elsewhere while the fetch was in flight.
                self.pdf_open_outline_pane(&path, &entries);
            }
            fenix_pdf::PdfResponse::SearchResults { key, request_id, matches } => {
                let Some(path) = self.pdf_sessions.iter().find(|(_, s)| s.doc_key == key).map(|(p, _)| p.clone()) else { return };
                let Some(session) = self.pdf_sessions.get(&path) else { return };
                if request_id != session.pending_search_request_id {
                    return; // superseded by a later search since this one was dispatched
                }
                let query = session.last_search_query.clone();
                self.set_message(format!("{} match{} for \"{query}\"", matches.len(), if matches.len() == 1 { "" } else { "es" }));
                self.pdf_open_or_update_search_pane(&path, &query, &matches);
            }
        }
        self.wake_caret();
    }

    /// `SPC r n` / `SPC r p`: turns the focused PDF session to the next/
    /// previous page (clamped to `0..page_count`), dispatching a fresh
    /// render at the pane's last-known size and this session's current
    /// zoom -- a no-op at either end of the document, and a no-op if the
    /// focused pane isn't a PDF session at all.
    fn pdf_turn_page(&mut self, delta: i32) {
        self.pdf_turn_page_landing(delta, false);
    }

    /// `pdf_turn_page` plus control over where the new page starts
    /// scrolled to -- `land_at_bottom` is what makes scrolling up past
    /// the top of a page continue onto the *bottom* of the previous one
    /// (see `PdfSession::land_at_bottom`). Returns whether a page turn
    /// actually happened, which is what `pdf_scroll` needs to know to
    /// tell "walked onto the next page" apart from "already at the last
    /// page, so this scroll did nothing".
    fn pdf_turn_page_landing(&mut self, delta: i32, land_at_bottom: bool) -> bool {
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return false };
        let Some(session) = self.pdf_sessions.get_mut(&key) else { return false };
        if session.page_count == 0 {
            return false;
        }
        let new_page = (session.current_page as i32 + delta).clamp(0, session.page_count as i32 - 1) as u32;
        if new_page == session.current_page {
            return false;
        }
        session.current_page = new_page;
        session.land_at_bottom = land_at_bottom;
        self.pdf_dispatch_render_for_zoom(&key);
        self.wake_caret();
        true
    }

    pub(crate) fn pdf_next_page(&mut self) {
        self.pdf_turn_page(1);
    }

    pub(crate) fn pdf_prev_page(&mut self) {
        self.pdf_turn_page(-1);
    }

    /// `SPC r [` / `Home` and `SPC r ]` / `End`: jumps the focused PDF
    /// session to the first/last page outright. A no-op if the focused
    /// pane isn't a PDF session, or its page count isn't known yet.
    pub(crate) fn pdf_first_page(&mut self) {
        self.pdf_goto_page(1);
    }

    pub(crate) fn pdf_last_page(&mut self) {
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };
        let Some(page_count) = self.pdf_sessions.get(&key).map(|session| session.page_count) else { return };
        self.pdf_goto_page(page_count);
    }

    /// Scrolls the focused PDF session's page vertically by `delta_px`
    /// (positive = further *down* the page), turning to the next/previous
    /// page once there's nothing left to scroll in that direction --
    /// which is what makes a wheel notch, `j`/`k`, or an arrow key walk
    /// through a whole document continuously, the way every other PDF
    /// reader does, instead of dead-ending at the bottom of a page.
    ///
    /// The "nothing left to scroll" case covers the common one too:
    /// fit-to-page renders the page to exactly the size it occupies, so
    /// there is *never* anything to scroll under the default zoom and
    /// every scroll gesture turns the page immediately.
    ///
    /// A page turn triggered by scrolling *up* lands on the bottom of the
    /// previous page rather than its top (see `PdfSession::
    /// land_at_bottom`), so scrolling back up retraces exactly the
    /// content scrolling down just covered.
    fn pdf_scroll(&mut self, delta_px: i32) {
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };
        let Some(session) = self.pdf_sessions.get_mut(&key) else { return };
        let full_h = session.full_bgra.as_ref().map(|(_, h, _)| *h).unwrap_or(0);
        // Same clamp `redraw` applies (and writes back) every frame --
        // recomputed here because a keypress can land between two frames,
        // and because `apply_pdf_response` deliberately parks a "start at
        // the bottom" offset out of range for this to resolve.
        let max_scroll_y = full_h.saturating_sub(full_h.min(session.last_pane_size.1));
        let current = session.scroll_offset.1.min(max_scroll_y);
        let next = (current as i64 + delta_px as i64).clamp(0, max_scroll_y as i64) as u32;
        if next != current {
            session.scroll_offset.1 = next;
            self.wake_caret();
            return;
        }
        // Already parked against the edge this scroll pushes toward, so
        // the gesture means "keep going" -- into the next/previous page.
        if delta_px > 0 {
            self.pdf_turn_page_landing(1, false);
        } else if delta_px < 0 {
            self.pdf_turn_page_landing(-1, true);
        }
    }

    /// `SPC r g`: starts the "type a page number" prompt -- a no-op if
    /// the focused pane isn't a PDF session (nothing to jump within).
    pub(crate) fn start_pdf_goto_page_prompt(&mut self) {
        if self.pdf_session_key_for_pane(self.focused_pane_id()).is_none() {
            return;
        }
        self.pdf_goto_page_prompt = Some(String::new());
        self.wake_caret();
    }

    /// Routes one keypress to the in-progress `pdf_goto_page_prompt` --
    /// digits only (this is a 1-indexed page number, not free text), same
    /// capturing shape as `find_file_prompt_key`.
    fn pdf_goto_page_prompt_key(&mut self, key: KeyPress) {
        let Some(input) = &mut self.pdf_goto_page_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.pdf_goto_page_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let input = self.pdf_goto_page_prompt.take().unwrap_or_default();
                if let Ok(page_number) = input.parse::<u32>() {
                    self.pdf_goto_page(page_number);
                }
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                input.pop();
            }
            KeyCode::Char(c) if key.mods == Mods::default() && c.is_ascii_digit() => input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// What to show in place of the modeline while `pdf_goto_page_prompt`
    /// is active -- mirrors `find_file_prompt_text`.
    fn pdf_goto_page_prompt_text(&self) -> Option<String> {
        self.pdf_goto_page_prompt.as_ref().map(|input| format!("go to page: {input}"))
    }

    /// Jumps the focused PDF session directly to `page_number` (1-indexed,
    /// as shown to the user -- clamped into `1..=page_count`, so an
    /// out-of-range number lands on the nearest real page rather than
    /// being rejected outright, same forgiving posture as most page-jump
    /// UIs). A no-op if the focused pane isn't a PDF session, or its page
    /// count isn't known yet.
    fn pdf_goto_page(&mut self, page_number: u32) {
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };
        let Some(session) = self.pdf_sessions.get_mut(&key) else { return };
        if session.page_count == 0 {
            return;
        }
        let new_page = page_number.saturating_sub(1).min(session.page_count - 1);
        if new_page == session.current_page {
            return;
        }
        session.current_page = new_page;
        self.pdf_dispatch_render_for_zoom(&key);
        self.wake_caret();
    }

    /// The effective zoom percentage a session's *current* render sits
    /// at, used to seed `pdf_zoom_in`/`pdf_zoom_out`'s step regardless of
    /// which zoom mode got it there (`FitPage`/`FitWidth` have no
    /// percentage of their own -- this derives one from the actual
    /// rendered size against the page's native point width). Falls back
    /// to `100` if nothing's been rendered yet or the page size isn't
    /// known (nothing to derive a ratio from).
    fn pdf_effective_percent(session: &PdfSession) -> u32 {
        let (rendered_w, _) = session.last_requested_size;
        let (page_w_pts, _) = session.page_point_size;
        if rendered_w == 0 || page_w_pts <= 0.0 {
            return 100;
        }
        ((rendered_w as f32 / page_w_pts) * 100.0).round().max(1.0) as u32
    }

    /// Shared body for `pdf_zoom_in`/`pdf_zoom_out`: steps the focused
    /// session's effective zoom percentage by `delta_percent` (positive
    /// or negative), clamped to `PDF_ZOOM_MIN_PERCENT..=PDF_ZOOM_MAX_
    /// PERCENT`, switching it into `PdfZoom::Percent` regardless of
    /// whatever mode it was in before -- a no-op if the focused pane
    /// isn't a PDF session.
    fn pdf_zoom_step(&mut self, delta_percent: i32) {
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };
        let Some(session) = self.pdf_sessions.get_mut(&key) else { return };
        let current = Self::pdf_effective_percent(session);
        let stepped = (current as i32 + delta_percent).clamp(PDF_ZOOM_MIN_PERCENT as i32, PDF_ZOOM_MAX_PERCENT as i32) as u32;
        session.zoom = PdfZoom::Percent(stepped);
        self.pdf_dispatch_render_for_zoom(&key);
        self.wake_caret();
    }

    pub(crate) fn pdf_zoom_in(&mut self) {
        self.pdf_zoom_step(PDF_ZOOM_STEP_PERCENT as i32);
    }

    pub(crate) fn pdf_zoom_out(&mut self) {
        self.pdf_zoom_step(-(PDF_ZOOM_STEP_PERCENT as i32));
    }

    /// Shared body for `pdf_zoom_fit_page`/`pdf_zoom_fit_width`: sets the
    /// focused session's zoom mode outright and dispatches a render for
    /// it -- a no-op if the focused pane isn't a PDF session.
    fn pdf_set_zoom(&mut self, zoom: PdfZoom) {
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };
        let Some(session) = self.pdf_sessions.get_mut(&key) else { return };
        session.zoom = zoom;
        self.pdf_dispatch_render_for_zoom(&key);
        self.wake_caret();
    }

    pub(crate) fn pdf_zoom_fit_page(&mut self) {
        self.pdf_set_zoom(PdfZoom::FitPage);
    }

    pub(crate) fn pdf_zoom_fit_width(&mut self) {
        self.pdf_set_zoom(PdfZoom::FitWidth);
    }

    /// `h`/`j`/`k`/`l` while a PDF pane is focused (see `route_keypress`'s
    /// own `BufferKind::Pdf` block): nudges `scroll_offset` by
    /// `PDF_PAN_STEP_PX` in the given direction. Never clamped here --
    /// `redraw`'s own crop computation clamps against `full_bgra`'s
    /// actual size and the pane's current size every frame regardless of
    /// how `scroll_offset` got to wherever it is, so an over-eager pan
    /// past either edge just settles at that edge next frame rather than
    /// needing its own bounds check here. A no-op if the focused pane
    /// isn't a PDF session.
    fn pdf_pan(&mut self, dx: i32, dy: i32) {
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };
        let Some(session) = self.pdf_sessions.get_mut(&key) else { return };
        let step = PDF_PAN_STEP_PX as i32;
        session.scroll_offset =
            ((session.scroll_offset.0 as i32 + dx * step).max(0) as u32, (session.scroll_offset.1 as i32 + dy * step).max(0) as u32);
        self.wake_caret();
    }

    /// Jumps the PDF session at `key` directly to `page_index`
    /// (0-indexed, already clamped by the caller if needed) and
    /// dispatches a fresh render for it. Unlike `pdf_goto_page`/`pdf_
    /// turn_page` (which act on whichever pane is *focused*), this takes
    /// an explicit session key -- what `pdf_outline_activate_selected`
    /// needs, since the *focused* pane when `Enter` is pressed there is
    /// the outline pane, not the PDF pane it should jump.
    fn pdf_jump_session_to_page(&mut self, key: &Path, page_index: u32) {
        let Some(session) = self.pdf_sessions.get_mut(key) else { return };
        if session.page_count == 0 {
            return;
        }
        let new_page = page_index.min(session.page_count - 1);
        if new_page != session.current_page {
            session.current_page = new_page;
            self.pdf_dispatch_render_for_zoom(key);
        }
        self.wake_caret();
    }

    /// Closes the outline pane for the PDF session at `key`, if one is
    /// currently open -- shared by `pdf_toggle_outline`'s toggle-off path
    /// and `kill_buffer_now`'s "the buffer being killed is a `PdfOutline`
    /// buffer" branch. Refocuses the companion PDF pane afterward so
    /// toggling feels like a real toggle rather than a jump elsewhere.
    fn pdf_close_outline_pane(&mut self, key: &Path) {
        let Some(pane) = self.pdf_outline_panes.remove(key) else { return };
        let Some(session_pane) = self.pdf_sessions.get(key).map(|session| session.pane) else { return };
        let buffer = self.windows().content(pane).copied();
        self.windows_mut().focus(pane);
        if self.windows_mut().close_focused() {
            self.workspaces.active_pane_states_mut().remove(&pane);
            self.workspaces.active_scroll_anims_mut().remove(&pane);
        }
        if let Some(buffer) = buffer {
            self.buffers.close(buffer);
            self.pdf_outline_lines.remove(&buffer);
            self.pdf_outline_source.remove(&buffer);
        }
        self.windows_mut().focus(session_pane);
        self.wake_caret();
    }

    /// Opens (or, if the worker's reply arrived after the user navigated
    /// elsewhere, re-opens) an outline pane for the PDF session at `key`,
    /// showing `entries` -- a plain vertical split off the session's own
    /// PDF pane, so it always ends up right next to it regardless of
    /// whatever else might currently be focused. Called both from `pdf_
    /// toggle_outline`'s "already cached" synchronous path and from
    /// `apply_pdf_response`'s `Outline` arm (the first-fetch path).
    fn pdf_open_outline_pane(&mut self, key: &Path, entries: &[fenix_pdf::outline::OutlineEntry]) {
        let Some(session_pane) = self.pdf_sessions.get(key).map(|session| session.pane) else { return };
        let Some(workspace_index) = self.pdf_sessions.get(key).map(|session| session.workspace_index) else { return };
        self.workspaces.switch_to_index(workspace_index);
        self.windows_mut().focus(session_pane);

        let (text, lines) = pdf_outline::render(entries);
        let buffer = self.buffers.open_pdf_outline(&text);
        let outline_pane = self.windows_mut().split(SplitKind::Vertical, buffer);
        self.workspaces.active_pane_states_mut().insert(outline_pane, PaneState::seeded_at(Cursor::at_start()));
        self.pane_titles.insert(outline_pane, "Outline".to_string());
        self.pdf_outline_lines.insert(buffer, lines);
        self.pdf_outline_source.insert(buffer, key.to_path_buf());
        self.pdf_outline_panes.insert(key.to_path_buf(), outline_pane);
        self.wake_caret();
    }

    /// `SPC r o`: toggles the focused PDF session's outline/bookmarks
    /// panel. Three cases: (1) the outline pane itself is focused --
    /// close it and return to the PDF pane; (2) a PDF pane is focused and
    /// its outline is already open -- close it (a real toggle, not
    /// "always open"); (3) a PDF pane is focused and its outline isn't
    /// open yet -- open it immediately from `PdfSession::outline` if
    /// already cached from an earlier toggle, or dispatch `FetchOutline`
    /// and let `apply_pdf_response`'s `Outline` arm open it once the
    /// reply lands (the bookmark tree can't change while a document's
    /// open, so this only ever happens once per session). A no-op if
    /// neither a PDF pane nor its outline pane is focused.
    pub(crate) fn pdf_toggle_outline(&mut self) {
        let focused_buffer = self.focused_buffer_id();
        if self.buffers.get(focused_buffer).is_some_and(|ob| ob.kind == BufferKind::PdfOutline) {
            if let Some(key) = self.pdf_outline_source.get(&focused_buffer).cloned() {
                self.pdf_close_outline_pane(&key);
            }
            return;
        }

        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };

        if self.pdf_outline_panes.contains_key(&key) {
            self.pdf_close_outline_pane(&key);
            return;
        }

        if let Some(entries) = self.pdf_sessions.get(&key).and_then(|session| session.outline.clone()) {
            self.pdf_open_outline_pane(&key, &entries);
            return;
        }

        let Some(session) = self.pdf_sessions.get(&key) else { return };
        if let Some(worker) = &self.pdf_worker {
            worker.send(fenix_pdf::PdfRequest::FetchOutline { key: session.doc_key });
        }
    }

    /// `Enter` on a `BufferKind::PdfOutline` line (see `route_keypress`'s
    /// own `PdfOutline` block): looks up what the cursor's current line
    /// means via `pdf_outline_lines`, a no-op for a blank/unstyled line
    /// (e.g. the "(this PDF has no bookmarks)" placeholder), and
    /// otherwise jumps the companion PDF pane straight to that entry's
    /// page -- mirrors `dashboard_activate_selected`'s own cursor-line ->
    /// side-table -> action shape.
    fn pdf_outline_activate_selected(&mut self) {
        let cursor = self.cursor();
        let line = self.open().buffer.line_col(&cursor).0;
        let buffer_id = self.focused_buffer_id();
        let page_index = self
            .pdf_outline_lines
            .get(&buffer_id)
            .and_then(|lines| lines.get(line))
            .and_then(|meta| meta.as_ref())
            .map(|meta| meta.page_index);
        let Some(page_index) = page_index else { return };
        let Some(key) = self.pdf_outline_source.get(&buffer_id).cloned() else { return };
        self.pdf_jump_session_to_page(&key, page_index);
    }

    /// `SPC r /`: starts the "type a search query" prompt -- a no-op if
    /// the focused pane isn't a PDF session (nothing to search within),
    /// same guard `start_pdf_goto_page_prompt` uses.
    pub(crate) fn start_pdf_search_prompt(&mut self) {
        if self.pdf_session_key_for_pane(self.focused_pane_id()).is_none() {
            return;
        }
        self.pdf_search_prompt = Some(String::new());
        self.wake_caret();
    }

    /// Routes one keypress to the in-progress `pdf_search_prompt` -- free
    /// text (unlike `pdf_goto_page_prompt_key`'s digits-only), same
    /// capturing shape as `find_file_prompt_key`.
    fn pdf_search_prompt_key(&mut self, key: KeyPress) {
        let Some(input) = &mut self.pdf_search_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.pdf_search_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let query = self.pdf_search_prompt.take().unwrap_or_default();
                self.pdf_dispatch_search(query);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                input.pop();
            }
            KeyCode::Char(c) if key.mods == Mods::default() => input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// What to show in place of the modeline while `pdf_search_prompt` is
    /// active -- mirrors `pdf_goto_page_prompt_text`.
    fn pdf_search_prompt_text(&self) -> Option<String> {
        self.pdf_search_prompt.as_ref().map(|input| format!("search pdf: {input}"))
    }

    /// Dispatches a `Search` request for the focused PDF session with
    /// `query`, bumping `pending_search_request_id` first so a reply to
    /// an earlier, now-superseded search gets dropped by `apply_pdf_
    /// response` instead of clobbering a newer one -- same staleness
    /// guard `pdf_dispatch_render` gives page renders. A no-op (blank
    /// query, no focused PDF session, or no worker) leaves whatever
    /// search-results pane already exists untouched.
    fn pdf_dispatch_search(&mut self, query: String) {
        if query.trim().is_empty() {
            return;
        }
        let Some(key) = self.pdf_session_key_for_pane(self.focused_pane_id()) else { return };
        let Some(session) = self.pdf_sessions.get_mut(&key) else { return };
        session.pending_search_request_id += 1;
        session.last_search_query = query.clone();
        let request_id = session.pending_search_request_id;
        let doc_key = session.doc_key;
        if let Some(worker) = &self.pdf_worker {
            worker.send(fenix_pdf::PdfRequest::Search { key: doc_key, request_id, query });
        }
        self.set_message("searching...");
    }

    /// Closes the search-results pane for the PDF session at `key`, if
    /// one is currently open -- mirrors `pdf_close_outline_pane` exactly,
    /// used by `kill_buffer_now`'s "the buffer being killed is a
    /// `PdfSearchResults` buffer" branch (there's no dedicated toggle key
    /// for search the way `SPC r o` doubles as open/close for the
    /// outline -- a fresh `SPC r /` search just replaces this pane's
    /// content in place instead, see `pdf_open_or_update_search_pane`).
    fn pdf_close_search_pane(&mut self, key: &Path) {
        let Some(pane) = self.pdf_search_panes.remove(key) else { return };
        let Some(session_pane) = self.pdf_sessions.get(key).map(|session| session.pane) else { return };
        let buffer = self.windows().content(pane).copied();
        self.windows_mut().focus(pane);
        if self.windows_mut().close_focused() {
            self.workspaces.active_pane_states_mut().remove(&pane);
            self.workspaces.active_scroll_anims_mut().remove(&pane);
        }
        if let Some(buffer) = buffer {
            self.buffers.close(buffer);
            self.pdf_search_result_lines.remove(&buffer);
            self.pdf_search_source.remove(&buffer);
        }
        self.windows_mut().focus(session_pane);
        self.wake_caret();
    }

    /// Opens a search-results pane for the PDF session at `key` showing
    /// `matches` (a plain vertical split off the session's own PDF pane,
    /// same as `pdf_open_outline_pane`), or, if one's already open from
    /// an earlier search on this same session, rewrites its buffer text
    /// in place instead of stacking a second pane -- same "rewrite the
    /// whole affected span as one step" tool (`Buffer::replace_range`)
    /// `set_docker_buffer`'s refresh already uses, and the same
    /// "a refreshed listing can reorder/add/remove rows, so an old cursor
    /// position is meaningless against it" reasoning for resetting the
    /// cursor to the top on every update.
    fn pdf_open_or_update_search_pane(&mut self, key: &Path, query: &str, matches: &[fenix_pdf::search::PdfSearchMatch]) {
        let (text, lines) = pdf_search::render(query, matches);

        if let Some(&pane) = self.pdf_search_panes.get(key) {
            if let Some(buffer) = self.windows().content(pane).copied() {
                if let Some(ob) = self.buffers.get_mut(buffer) {
                    let end = ob.buffer.len_chars();
                    let mut scratch_cursor = Cursor::at_start();
                    ob.buffer.replace_range(&mut scratch_cursor, 0, end, &text);
                }
                self.pdf_search_result_lines.insert(buffer, lines);
                for p in self.windows().windows() {
                    if self.windows().content(p) == Some(&buffer) {
                        let ps = self.pane_state_mut(p);
                        *ps = PaneState::seeded_at(Cursor::at_start());
                    }
                }
                self.wake_caret();
                return;
            }
        }

        let Some(session_pane) = self.pdf_sessions.get(key).map(|session| session.pane) else { return };
        let Some(workspace_index) = self.pdf_sessions.get(key).map(|session| session.workspace_index) else { return };
        self.workspaces.switch_to_index(workspace_index);
        self.windows_mut().focus(session_pane);

        let buffer = self.buffers.open_pdf_search_results(&text);
        let search_pane = self.windows_mut().split(SplitKind::Vertical, buffer);
        self.workspaces.active_pane_states_mut().insert(search_pane, PaneState::seeded_at(Cursor::at_start()));
        self.pane_titles.insert(search_pane, "Search results".to_string());
        self.pdf_search_result_lines.insert(buffer, lines);
        self.pdf_search_source.insert(buffer, key.to_path_buf());
        self.pdf_search_panes.insert(key.to_path_buf(), search_pane);
        self.wake_caret();
    }

    /// `Enter` on a `BufferKind::PdfSearchResults` line (see
    /// `route_keypress`'s own `PdfSearchResults` block): looks up what
    /// the cursor's current line means via `pdf_search_result_lines`, a
    /// no-op for a blank/unstyled line (e.g. the "(no matches for ...)"
    /// placeholder), and otherwise jumps the companion PDF pane straight
    /// to that match's page -- mirrors `pdf_outline_activate_selected`
    /// exactly.
    fn pdf_search_activate_selected(&mut self) {
        let cursor = self.cursor();
        let line = self.open().buffer.line_col(&cursor).0;
        let buffer_id = self.focused_buffer_id();
        let page_index = self
            .pdf_search_result_lines
            .get(&buffer_id)
            .and_then(|lines| lines.get(line))
            .and_then(|meta| meta.as_ref())
            .map(|meta| meta.page_index);
        let Some(page_index) = page_index else { return };
        let Some(key) = self.pdf_search_source.get(&buffer_id).cloned() else { return };
        self.pdf_jump_session_to_page(&key, page_index);
    }

    /// Encodes `keypress` and writes it to the live terminal session, if
    /// any (a no-op if the session's since exited or never started --
    /// shouldn't happen while `terminal_focused`, but no reason to panic
    /// if it does). Errors (the shell's pipe closed, e.g. it just
    /// exited) are swallowed -- the next `SPC o t` respawns.
    fn write_terminal_input(&mut self, keypress: KeyPress) {
        let Some(bytes) = encode_terminal_key(keypress) else { return };
        let Some(state) = self.terminal.as_mut() else { return };
        let _ = state.session.write_input(&bytes);
    }

    /// Builds fuzzy-picker candidates for every file in `root` --
    /// relative path as the label (fuzzy-matched and displayed),
    /// absolute path as the payload (what actually gets opened).
    /// A path relative to `root`, written with forward slashes on
    /// every platform.
    ///
    /// Not cosmetic. Every other path Fenix shows comes from `git`,
    /// which always writes `/` regardless of platform -- so on Windows
    /// a native-separator label made the file picker the one place a
    /// path looked different (`src\\main.rs` in the picker,
    /// `src/main.rs` in the Git panel two keys away), and made the
    /// obvious fuzzy query for a nested file (`src/ma`) match nothing.
    fn relative_label(root: &Path, path: &Path) -> String {
        path.strip_prefix(root).unwrap_or(path).components().map(|c| c.as_os_str().to_string_lossy()).collect::<Vec<_>>().join("/")
    }

    fn find_file_candidates(root: &Path) -> Vec<fenix_picker::Candidate<PathBuf>> {
        fenix_project::list_project_files(root)
            .into_iter()
            .map(|path| {
                let label = Self::relative_label(root, &path);
                fenix_picker::Candidate::new(label, path)
            })
            .collect()
    }

    /// `SPC p f`: a fuzzy file picker scoped to the current project (or
    /// the process's cwd, if no project was detected -- still useful,
    /// just not project-scoped).
    pub(crate) fn picker_find_file(&mut self) {
        let root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let candidates = Self::find_file_candidates(&root);
        self.enter_picker(ActivePicker::FindFile(fenix_picker::PickerState::new(candidates)));
    }

    /// Same shape as `find_file_candidates`, backed by `fenix_project::
    /// list_project_files_including_ignored` instead -- every file
    /// `.gitignore` would otherwise hide (`.env`, a build artifact,
    /// anything else) is fuzzy-findable by name here.
    fn find_file_candidates_all(root: &Path) -> Vec<fenix_picker::Candidate<PathBuf>> {
        fenix_project::list_project_files_including_ignored(root)
            .into_iter()
            .map(|path| {
                let label = Self::relative_label(root, &path);
                fenix_picker::Candidate::new(label, path)
            })
            .collect()
    }

    /// `SPC f a`: `picker_find_file`'s gitignore-blind sibling. Reuses
    /// `ActivePicker::FindFile` as-is -- `picker_confirm`'s own arm only
    /// cares that the payload is a path, not how the candidate list was
    /// built.
    pub(crate) fn picker_find_file_all(&mut self) {
        let root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let candidates = Self::find_file_candidates_all(&root);
        self.enter_picker(ActivePicker::FindFile(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC f r`: a fuzzy picker over `recent_files` (already loaded,
    /// already backing the dashboard's own recent-file rows -- just
    /// never exposed as a standalone picker before). Labeled with the
    /// full path, not root-relative -- recent files can span multiple
    /// projects, so "relative to the current project" wouldn't always
    /// make sense. Reuses `ActivePicker::FindFile`, same reasoning as
    /// `picker_find_file_all`.
    pub(crate) fn picker_recent_files(&mut self) {
        let candidates = self
            .recent_files
            .paths()
            .iter()
            .map(|path| fenix_picker::Candidate::new(path.display().to_string(), path.clone()))
            .collect();
        self.enter_picker(ActivePicker::FindFile(fenix_picker::PickerState::new(candidates)));
    }

    /// Candidates for both the switch-project (`SPC p p`) and delete-
    /// project (`SPC p d`) pickers -- same list, same label, just a
    /// different picker variant so `picker_confirm` dispatches to a
    /// different action.
    fn known_project_candidates(&self) -> Vec<fenix_picker::Candidate<PathBuf>> {
        self.known_projects
            .roots()
            .iter()
            .map(|root| fenix_picker::Candidate::new(root.to_string_lossy().into_owned(), root.clone()))
            .collect()
    }

    /// `SPC p p`: a fuzzy picker over the persisted, MRU-ordered known-
    /// projects list.
    pub(crate) fn picker_switch_project(&mut self) {
        let candidates = self.known_project_candidates();
        self.enter_picker(ActivePicker::SwitchProject(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC p d`: same list as `SPC p p`, but confirming a selection
    /// removes it from `known_projects` instead of switching to it (see
    /// `ActivePicker::DeleteProject`/`picker_confirm`).
    pub(crate) fn picker_delete_project(&mut self) {
        let candidates = self.known_project_candidates();
        self.enter_picker(ActivePicker::DeleteProject(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC p a`: opens the full-buffer file explorer, in "pick a
    /// directory" mode, to browse to and register a project in
    /// `known_projects` -- the *only* way a project gets into the switch-
    /// project list now (see `refresh_project_root`'s own doc comment for
    /// why auto-registration-on-visit was dropped: it made "switch
    /// project" list every project you'd ever opened a file in, not a
    /// deliberately curated set worth switching between). Starts browsing
    /// at the current project root (or the process's cwd, if none
    /// detected); navigate with the explorer's usual `j`/`k`/`l`/`h`/
    /// `Enter`, then `S` to register whichever directory is currently
    /// being browsed. `q`/`Escape` cancels without registering anything,
    /// same as leaving the explorer any other time.
    pub(crate) fn picker_add_project_prompt(&mut self) {
        let start = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let explorer = match ExplorerState::opened(&start) {
            Ok(e) => e,
            Err(err) => {
                eprintln!("fenix: couldn't list {} ({err})", start.display());
                return;
            }
        };
        self.explorer = Some(explorer);
        self.explorer_purpose = ExplorerPurpose::PickProjectDir;
        self.main_view = MainView::Explorer;
        self.wake_caret();
    }

    /// `S` on the add-project explorer (`ExplorerAction::SelectCwd`):
    /// registers whatever directory is currently being browsed. Already
    /// an absolute, real filesystem path (it came from actually listing
    /// it), so this only needs to canonicalize away any `..`/symlink
    /// noise before persisting -- no typed-input parsing like the old
    /// free-text prompt needed.
    fn register_project_dir(&mut self, dir: &Path) {
        let root = std::fs::canonicalize(dir).unwrap_or_else(|_| dir.to_path_buf());
        self.known_projects.add(root);
        if let Err(err) = self.known_projects.save() {
            eprintln!("fenix: couldn't save project history: {err}");
        }
        self.main_view = MainView::Editor;
        self.explorer = None;
        self.explorer_purpose = ExplorerPurpose::Browse;
    }

    /// `SPC f e`: opens the full-buffer file explorer starting at the
    /// user's home directory, in `FindFrom` mode -- for the file that
    /// isn't in any project and isn't worth typing an absolute path for
    /// (e.g. something in `~/Downloads`). Falls back to the process's
    /// cwd if the home directory can't be determined. Navigate with the
    /// explorer's usual `j`/`k`/`l`/`h`; `Enter` on a file opens it
    /// straight away (same as ordinary browsing), or `S` fuzzy-searches
    /// recursively from wherever you've navigated to (see
    /// `start_find_from_here`). `q`/`Escape` cancels.
    pub(crate) fn start_explore_from_home(&mut self) {
        let start = dirs::home_dir().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let explorer = match ExplorerState::opened(&start) {
            Ok(e) => e,
            Err(err) => {
                eprintln!("fenix: couldn't list {} ({err})", start.display());
                return;
            }
        };
        self.explorer = Some(explorer);
        self.explorer_purpose = ExplorerPurpose::FindFrom;
        self.main_view = MainView::Explorer;
        self.wake_caret();
    }

    /// `S` on the `FindFrom` explorer (`ExplorerAction::SelectCwd`):
    /// leaves the explorer and opens a `FindFile` picker over every file
    /// under `dir`, recursively -- same candidate-building as `SPC p f`/
    /// `picker_find_file`, just rooted wherever the user navigated
    /// instead of the project root.
    fn start_find_from_here(&mut self, dir: &Path) {
        let candidates = Self::find_file_candidates(dir);
        self.explorer = None;
        self.explorer_purpose = ExplorerPurpose::Browse;
        self.enter_picker(ActivePicker::FindFile(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC p s`: unlike find-file/switch-project (which already have a
    /// full candidate list to fuzzy-filter locally), grep needs a search
    /// term *before* there's anything to show -- this starts a short
    /// modeline-level prompt for it (mirroring Vim's own `:` command
    /// line), not the full picker view yet. `run_grep` opens the actual
    /// picker once results come back.
    pub(crate) fn picker_grep_prompt(&mut self) {
        self.pending_grep_query = Some(String::new());
        self.wake_caret();
    }

    /// Routes one keypress to the in-progress grep search-term prompt --
    /// the same "next keystrokes are special" shape as `explorer_prompt_key`,
    /// scoped to this one always-plain-text case.
    fn grep_query_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(query), Some(text)) = (&mut self.pending_grep_query, pasted) {
                query.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some(query) = &mut self.pending_grep_query else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.pending_grep_query = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let query = self.pending_grep_query.take().unwrap_or_default();
                self.run_grep(&query);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                query.pop();
            }
            KeyCode::Char(c) => query.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    fn run_grep(&mut self, query: &str) {
        let root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        match fenix_project::grep_project(&root, query) {
            Ok(matches) => {
                // Kept around as `quickfix` after the picker itself
                // closes -- `SPC p n`/`SPC p N` keep sweeping through
                // this same result set without re-running the search or
                // reopening the picker. Replaced on every successful
                // search (even a zero-result one), left alone on a
                // failed one -- a transient `rg` failure shouldn't wipe
                // out the ability to keep navigating the previous sweep.
                self.quickfix = matches.iter().cloned().map(QuickfixEntry::Grep).collect();
                self.quickfix_index = None;
                let candidates = matches
                    .into_iter()
                    .map(|m| {
                        let rel = Self::relative_label(&root, &m.path);
                        let label = format!("{rel}:{}: {}", m.line, m.text.trim());
                        fenix_picker::Candidate::new(label, m)
                    })
                    .collect();
                self.enter_picker(ActivePicker::Grep(fenix_picker::PickerState::new(candidates)));
            }
            Err(err) => self.set_error(format!("search failed: {err}")),
        }
    }

    /// `SPC p n` -- jumps to the next match in `quickfix` (the most
    /// recent `SPC p s` results), without reopening the picker or
    /// re-running the search. Starts at the first match if nothing's
    /// been visited yet. Clamps at either end (a no-op past the last/
    /// before the first match) rather than wrapping -- same "stop
    /// rather than surprise" reasoning `jump_back`/`jump_forward` use
    /// for an exhausted stack. Also a no-op while a Docker/Git panel
    /// session is open (`jumplist_navigation_allowed`) -- this steps
    /// through `open_file_from_picker`/`jump_to_grep_match` exactly like
    /// confirming a Grep picker entry does, so it's exactly as unsafe to
    /// call from there.
    pub(crate) fn quickfix_next(&mut self) {
        self.quickfix_step(1);
    }

    /// `SPC p N` -- the mirror of `quickfix_next`, stepping backward.
    pub(crate) fn quickfix_prev(&mut self) {
        self.quickfix_step(-1);
    }

    fn quickfix_step(&mut self, delta: isize) {
        if self.quickfix.is_empty() || !self.jumplist_navigation_allowed() {
            return;
        }
        let target = match self.quickfix_index {
            None => 0,
            Some(i) => {
                let n = i as isize + delta;
                if n < 0 || n as usize >= self.quickfix.len() {
                    return;
                }
                n as usize
            }
        };
        let entry = self.quickfix[target].clone();
        let from = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
        match entry {
            QuickfixEntry::Grep(m) | QuickfixEntry::Task(m) => {
                self.open_file_from_picker(&m.path);
                self.jump_to_grep_match(&m);
            }
            QuickfixEntry::Lsp { path, position } => {
                self.open_file_from_picker(&path);
                self.goto_lsp_position(position);
            }
        }
        self.record_jump(from);
        self.quickfix_index = Some(target);
    }

    // -- SCOS-2000 MIB (`SPC m ...`) --------------------------------

    /// Lazily builds (and `refresh()`'s once) the MIB index the first
    /// time any `SPC m ...` command needs it -- same "expensive work
    /// only when it's actually needed" deferral `tcl_tags`'s own cache
    /// already uses for `ctags`, just gated on first-use instead of
    /// project-root-change (MIB roots don't change while Fenix is
    /// running). `None` (with a message) if no roots are configured at
    /// all -- there'd be nothing to index.
    fn mib_index(&mut self) -> Option<&mut fenix_mib::MibIndex> {
        if self.mib_roots.is_empty() {
            self.set_error("no MIB roots configured (see [mib] in config.ini)");
            return None;
        }
        if self.mib_index.is_none() {
            let mut index = fenix_mib::MibIndex::new(self.mib_roots.clone());
            index.refresh();
            self.mib_index = Some(index);
        }
        self.mib_index.as_mut()
    }

    /// `SPC m r` -- clears and reparses the MIB index from disk (picks
    /// up edits to the `.dat` files made outside Fenix since the last
    /// load/refresh).
    pub(crate) fn mib_refresh_index(&mut self) {
        if let Some(index) = self.mib_index() {
            index.refresh();
        }
    }

    /// Rebuilds `self.mib_roots` from `self.config.mib_roots` and drops
    /// the parsed index so the next `SPC m ...` command rebuilds it
    /// against the new root set (same lazy-rebuild the index already
    /// gets from `mib_refresh_index`) -- called after `SPC m a`/`SPC m
    /// d` mutate `config.mib_roots`, right before saving it, so a save
    /// failure still leaves in-memory state consistent with what's
    /// configured even if the file on disk didn't catch up.
    fn persist_mib_roots(&mut self) {
        if let Err(err) = self.config.save() {
            eprintln!("fenix: couldn't save config: {err}");
        }
        self.mib_roots =
            self.config.mib_roots.iter().map(|(label, path)| fenix_mib::MibRoot { label: label.clone(), path: path.clone() }).collect();
        self.mib_index = None;
    }

    /// `SPC m a`: opens the full-buffer file explorer, in "pick a
    /// directory" mode, to browse to and register a new MIB root --
    /// same flow as `picker_add_project_prompt`, just landing in `S` on
    /// `start_mib_root_label_prompt` instead of registering directly
    /// (a MIB root needs a label, a project root doesn't).
    pub(crate) fn picker_add_mib_root_prompt(&mut self) {
        let start = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let explorer = match ExplorerState::opened(&start) {
            Ok(e) => e,
            Err(err) => {
                eprintln!("fenix: couldn't list {} ({err})", start.display());
                return;
            }
        };
        self.explorer = Some(explorer);
        self.explorer_purpose = ExplorerPurpose::PickMibRootDir;
        self.main_view = MainView::Explorer;
        self.wake_caret();
    }

    /// `S` on the add-MIB-root explorer (`ExplorerAction::SelectCwd`):
    /// closes the explorer and starts `mib_root_prompt` for the browsed
    /// directory, mirroring `register_project_dir`'s own canonicalize-
    /// before-persisting step, but not registering anything until the
    /// label prompt resolves.
    fn start_mib_root_label_prompt(&mut self, dir: &Path) {
        let root = std::fs::canonicalize(dir).unwrap_or_else(|_| dir.to_path_buf());
        self.mib_root_prompt = Some((root, String::new()));
        self.main_view = MainView::Editor;
        self.explorer = None;
        self.explorer_purpose = ExplorerPurpose::Browse;
    }

    /// Routes one keypress to the in-progress `mib_root_prompt` -- same
    /// shape as `find_file_prompt_key`, including its `Ctrl-V` paste
    /// handling.
    fn mib_root_prompt_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some((_, label)), Some(text)) = (&mut self.mib_root_prompt, pasted) {
                label.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some((_, label)) = &mut self.mib_root_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.mib_root_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let (path, label) = self.mib_root_prompt.take().unwrap();
                let label = label.trim();
                if !label.is_empty() {
                    self.add_mib_root(path, label.to_string());
                }
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                label.pop();
            }
            KeyCode::Char(c) if key.mods == Mods::default() => label.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// What to show in place of the modeline while `mib_root_prompt` is
    /// active -- mirrors `find_file_prompt_text`.
    fn mib_root_prompt_text(&self) -> Option<String> {
        self.mib_root_prompt.as_ref().map(|(path, label)| format!("MIB label for {}: {label}", path.display()))
    }

    /// `Enter` on `mib_root_prompt` with a non-empty label: registers
    /// `(label, path)` as a new `[mib]` root, persists it, and rebuilds
    /// `mib_roots`/invalidates the parsed index (`persist_mib_roots`)
    /// so it's usable by `SPC m t`/etc. immediately, not just after the
    /// next restart.
    fn add_mib_root(&mut self, path: PathBuf, label: String) {
        self.config.mib_roots.push((label, path));
        self.persist_mib_roots();
    }

    /// Candidates for `SPC m d` -- one per configured `[mib]` root,
    /// keyed by the full `(label, path)` pair (not a list position, so
    /// a fuzzy-filtered/reordered selection still removes the right
    /// entry -- same reasoning `known_project_candidates`'/`DeleteProject`'s
    /// own `PathBuf` keying already uses).
    fn mib_root_candidates(&self) -> Vec<fenix_picker::Candidate<(String, PathBuf)>> {
        self.config
            .mib_roots
            .iter()
            .map(|(label, path)| fenix_picker::Candidate::new(format!("{label}  {}", path.display()), (label.clone(), path.clone())))
            .collect()
    }

    /// `SPC m d`: same candidate list as the roots currently configured,
    /// but confirming a selection removes it instead of doing anything
    /// else -- mirrors `picker_delete_project` exactly.
    pub(crate) fn picker_delete_mib_root(&mut self) {
        let candidates = self.mib_root_candidates();
        self.enter_picker(ActivePicker::DeleteMibRoot(fenix_picker::PickerState::new(candidates)));
    }

    fn mib_tc_candidates(&mut self) -> Option<Vec<fenix_picker::Candidate<fenix_mib::Row>>> {
        let index = self.mib_index()?;
        Some(index.rows("ccf").iter().map(|row| fenix_picker::Candidate::new(mib_tc_label(row), row.clone())).collect())
    }

    fn mib_tm_packet_candidates(&mut self) -> Option<Vec<fenix_picker::Candidate<fenix_mib::Row>>> {
        let index = self.mib_index()?;
        Some(index.rows("pid").iter().map(|row| fenix_picker::Candidate::new(mib_tm_packet_label(row), row.clone())).collect())
    }

    fn mib_tm_parameter_candidates(&mut self) -> Option<Vec<fenix_picker::Candidate<fenix_mib::Row>>> {
        let index = self.mib_index()?;
        Some(
            index.rows("pcf").iter().map(|row| fenix_picker::Candidate::new(mib_tm_parameter_label(row), row.clone())).collect(),
        )
    }

    /// `caf` (numeric curves), `paf` (status/enumeration), and `prf`
    /// (range checks) rows merged into one candidate list -- the three
    /// SCOS-2000 calibration "kinds," each keyed by its own `_NUMBR`.
    fn mib_calibration_candidates(&mut self) -> Option<Vec<fenix_picker::Candidate<fenix_mib::Row>>> {
        let index = self.mib_index()?;
        let mut candidates = Vec::new();
        for table in ["caf", "paf", "prf"] {
            for row in index.rows(table) {
                candidates.push(fenix_picker::Candidate::new(mib_calibration_label(row), row.clone()));
            }
        }
        Some(candidates)
    }

    /// `SPC m t` -- fuzzy-find a telecommand, confirming opens its detail view.
    pub(crate) fn mib_lookup_telecommand(&mut self) {
        if let Some(candidates) = self.mib_tc_candidates() {
            self.enter_picker(ActivePicker::MibTelecommandLookup(fenix_picker::PickerState::new(candidates)));
        }
    }

    /// `SPC m i` -- fuzzy-find a telecommand, confirming starts the
    /// insert wizard (`mib_start_insert`).
    pub(crate) fn mib_insert_telecommand(&mut self) {
        if let Some(candidates) = self.mib_tc_candidates() {
            self.enter_picker(ActivePicker::MibTelecommandInsert(fenix_picker::PickerState::new(candidates)));
        }
    }

    /// `SPC m k` -- fuzzy-find a TM packet, confirming opens its detail view.
    pub(crate) fn mib_lookup_tm_packet(&mut self) {
        if let Some(candidates) = self.mib_tm_packet_candidates() {
            self.enter_picker(ActivePicker::MibTmPacket(fenix_picker::PickerState::new(candidates)));
        }
    }

    /// `SPC m p` -- fuzzy-find a TM parameter, confirming opens its detail view.
    pub(crate) fn mib_lookup_tm_parameter(&mut self) {
        if let Some(candidates) = self.mib_tm_parameter_candidates() {
            self.enter_picker(ActivePicker::MibTmParameter(fenix_picker::PickerState::new(candidates)));
        }
    }

    /// `SPC m c` -- fuzzy-find a calibration definition, confirming opens
    /// its detail view. Not in the reference elisp implementation --
    /// added per the user's own explicit ask, alongside the ported
    /// telecommand/TM-packet/TM-parameter lookups.
    pub(crate) fn mib_lookup_calibration(&mut self) {
        if let Some(candidates) = self.mib_calibration_candidates() {
            self.enter_picker(ActivePicker::MibCalibration(fenix_picker::PickerState::new(candidates)));
        }
    }

    /// Renders `text` into a fresh read-only-ish scratch buffer and
    /// shows it in the focused pane -- `BufferList::open_text_view`,
    /// "viewing generated content needs nothing beyond what an ordinary
    /// buffer already gives for free," reused here for every MIB detail
    /// view exactly as it was built for.
    fn mib_open_detail(&mut self, text: &str) {
        let id = self.buffers.open_text_view(text);
        self.open_buffer_in_focused_pane(id);
        self.main_view = MainView::Editor;
        self.wake_caret();
    }

    /// `SPC m t` confirm -- a telecommand's summary, every `CDF`
    /// parameter (with its `CPC` definition and calibration/reference
    /// rows inlined), and its raw fields.
    fn mib_show_telecommand(&mut self, row: &fenix_mib::Row) {
        const SUMMARY: &[&str] =
            &["CCF_CNAME", "CCF_TYPE", "CCF_STYPE", "CCF_APID", "CCF_DESCR", "CCF_DESCR2", "CCF_NPARS", "CCF_PKTID", "CCF_SUBSYS"];
        let name = row.clean("CCF_CNAME").to_string();
        let mut text =
            format!("* Telecommand {name}\n\n* Source\n{}\n* Summary\n{}", mib_source_text(&row.source), mib_field_list_text(row, SUMMARY));
        let Some(index) = self.mib_index() else {
            self.mib_open_detail(&text);
            return;
        };
        let params = fenix_mib::telecommand::tc_parameters(index, row);
        text.push_str("\n* Parameters\n");
        if params.is_empty() {
            text.push_str("- No CDF parameters found\n");
        } else {
            for param in &params {
                text.push_str(&format!(
                    "- {}  {}  bit:{}  len:{}  value:{}\n",
                    param.name,
                    param.cdf.clean("CDF_DESCR"),
                    param.cdf.clean("CDF_BIT"),
                    param.cdf.clean("CDF_ELLEN"),
                    param.cdf.clean("CDF_VALUE"),
                ));
                if let Some(cpc) = &param.cpc {
                    text.push_str(&format!(
                        "  CPC: {}, PTC/PFC {}/{}, unit {}, default {}\n",
                        cpc.clean("CPC_DESCR"),
                        cpc.clean("CPC_PTC"),
                        cpc.clean("CPC_PFC"),
                        cpc.clean("CPC_UNIT"),
                        cpc.clean("CPC_DEFVAL"),
                    ));
                    let cal_rows = fenix_mib::telecommand::calibration_rows(index, cpc);
                    if !cal_rows.is_empty() {
                        text.push_str("  Calibration / references:\n");
                        for cal in &cal_rows {
                            text.push_str(&format!(
                                "  - {}:{}:{}  {}\n",
                                cal.source.root_label,
                                cal.table,
                                cal.source.line,
                                mib_row_fields_inline(cal)
                            ));
                        }
                    }
                }
            }
        }
        text.push_str(&mib_raw_fields_text(row, "Raw CCF Fields"));
        self.mib_open_detail(&text);
    }

    /// `SPC m k` confirm -- a TM packet's summary, every `PLF` occurrence
    /// (with its `PCF` definition inlined), and its raw fields.
    fn mib_show_tm_packet(&mut self, row: &fenix_mib::Row) {
        const SUMMARY: &[&str] = &["PID_SPID", "PID_TYPE", "PID_STYPE", "PID_APID", "PID_DESCR", "PID_UNIT", "PID_TPSD", "PID_DFHSIZE"];
        let spid = row.clean("PID_SPID").to_string();
        let mut text =
            format!("* TM Packet SPID {spid}\n\n* Source\n{}\n* Summary\n{}", mib_source_text(&row.source), mib_field_list_text(row, SUMMARY));
        let Some(index) = self.mib_index() else {
            self.mib_open_detail(&text);
            return;
        };
        let root = Some(row.source.root_index);
        let params = index.rows_by_field("plf", "PLF_SPID", &spid, root);
        text.push_str("\n* Parameters\n");
        if params.is_empty() {
            text.push_str("- No PLF parameters found\n");
        } else {
            for param in &params {
                let pname = param.clean("PLF_NAME");
                text.push_str(&format!(
                    "- {pname}  off:{}.{}  occ:{}\n",
                    param.clean("PLF_OFFBY"),
                    param.clean("PLF_OFFBI"),
                    param.clean("PLF_NBOCC")
                ));
                if let Some(pcf) = index.first_row_by_field("pcf", "PCF_NAME", pname, root) {
                    text.push_str(&format!(
                        "  PCF: {}, PTC/PFC {}/{}, unit {}, width {}\n",
                        pcf.clean("PCF_DESCR"),
                        pcf.clean("PCF_PTC"),
                        pcf.clean("PCF_PFC"),
                        pcf.clean("PCF_UNIT"),
                        pcf.clean("PCF_WIDTH")
                    ));
                }
            }
        }
        text.push_str(&mib_raw_fields_text(row, "Raw PID Fields"));
        self.mib_open_detail(&text);
    }

    /// `SPC m p` confirm -- a TM parameter's summary, every `PLF` packet
    /// occurrence it appears in, and its raw fields.
    fn mib_show_tm_parameter(&mut self, row: &fenix_mib::Row) {
        const SUMMARY: &[&str] =
            &["PCF_NAME", "PCF_DESCR", "PCF_PID", "PCF_UNIT", "PCF_PTC", "PCF_PFC", "PCF_WIDTH", "PCF_CATEG", "PCF_INTER", "PCF_VALPAR", "PCF_DESCR2"];
        let name = row.clean("PCF_NAME").to_string();
        let mut text =
            format!("* TM Parameter {name}\n\n* Source\n{}\n* Summary\n{}", mib_source_text(&row.source), mib_field_list_text(row, SUMMARY));
        let Some(index) = self.mib_index() else {
            self.mib_open_detail(&text);
            return;
        };
        let root = Some(row.source.root_index);
        let occurrences = index.rows_by_field("plf", "PLF_NAME", &name, root);
        text.push_str("\n* Packet Occurrences\n");
        if occurrences.is_empty() {
            text.push_str("- No PLF packet occurrences found\n");
        } else {
            for occ in &occurrences {
                let spid = occ.clean("PLF_SPID");
                let pid = index.first_row_by_field("pid", "PID_SPID", spid, root);
                let (ptype, pstype, descr) =
                    pid.map(|p| (p.clean("PID_TYPE"), p.clean("PID_STYPE"), p.clean("PID_DESCR"))).unwrap_or(("", "", ""));
                text.push_str(&format!(
                    "- SPID {spid}  type:{ptype}  stype:{pstype}  off:{}.{}  {descr}\n",
                    occ.clean("PLF_OFFBY"),
                    occ.clean("PLF_OFFBI")
                ));
            }
        }
        text.push_str(&mib_raw_fields_text(row, "Raw PCF Fields"));
        self.mib_open_detail(&text);
    }

    /// `SPC m c` confirm -- a calibration definition's summary plus its
    /// own points: `CAP` x/y pairs for a `caf` (numeric curve), `PAS`
    /// raw/text aliases for a `paf` (status), or `PRV` min/max pairs for
    /// a `prf` (range check).
    fn mib_show_calibration(&mut self, row: &fenix_mib::Row) {
        let numbr_field = format!("{}_NUMBR", row.table.to_uppercase());
        let descr_field = format!("{}_DESCR", row.table.to_uppercase());
        let number = row.clean(&numbr_field).to_string();
        let mut text = format!(
            "* Calibration {number} ({})\n\n* Source\n{}\n* Summary\n- {numbr_field}: {number}\n- {descr_field}: {}\n",
            row.table.to_uppercase(),
            mib_source_text(&row.source),
            row.clean(&descr_field)
        );
        let Some(index) = self.mib_index() else {
            self.mib_open_detail(&text);
            return;
        };
        let root = Some(row.source.root_index);
        text.push_str("\n* Points\n");
        match row.table.as_str() {
            "caf" => {
                let points = index.rows_by_field("cap", "CAP_NUMBR", &number, root);
                if points.is_empty() {
                    text.push_str("- No CAP curve points found\n");
                } else {
                    for p in &points {
                        text.push_str(&format!("- x={}  y={}\n", p.clean("CAP_XVALS"), p.clean("CAP_YVALS")));
                    }
                }
            }
            "paf" => {
                let aliases = index.rows_by_field("pas", "PAS_NUMBR", &number, root);
                if aliases.is_empty() {
                    text.push_str("- No PAS aliases found\n");
                } else {
                    for a in &aliases {
                        text.push_str(&format!("- raw={}  text={}\n", a.clean("PAS_ALVAL"), a.clean("PAS_ALTXT")));
                    }
                }
            }
            "prf" => {
                let ranges = index.rows_by_field("prv", "PRV_NUMBR", &number, root);
                if ranges.is_empty() {
                    text.push_str("- No PRV ranges found\n");
                } else {
                    for r in &ranges {
                        text.push_str(&format!("- min={}  max={}\n", r.clean("PRV_MINVAL"), r.clean("PRV_MAXVAL")));
                    }
                }
            }
            _ => {}
        }
        text.push_str(&mib_raw_fields_text(row, "Raw Fields"));
        self.mib_open_detail(&text);
    }

    /// `SPC m i` picker confirm -- starts the insert wizard for `ccf`:
    /// straight to `Confirm` if it has no variable parameters, else
    /// `ChooseArgumentMode`.
    fn mib_start_insert(&mut self, ccf: fenix_mib::Row) {
        let Some(index) = self.mib_index() else { return };
        let variable_params: Vec<_> = fenix_mib::telecommand::tc_parameters(index, &ccf).into_iter().filter(|p| !p.fixed).collect();
        let origin = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
        let has_variable_params = !variable_params.is_empty();
        self.mib_insert = Some(MibInsertState {
            ccf,
            origin,
            variable_params,
            cursor: 0,
            repeat_stack: Vec::new(),
            collected: Vec::new(),
            stage: MibInsertStage::ChooseArgumentMode,
            current_argument_context: String::new(),
        });
        self.main_view = MainView::Editor;
        if !has_variable_params {
            self.mib_enter_confirm_stage();
        }
        self.wake_caret();
    }

    /// Advances the wizard to whichever variable parameter comes next --
    /// a picker (`ActivePicker::MibArgumentAlias`) if it has `PAF`/`PAS`
    /// aliases, otherwise a free-text capture stage -- or to `Confirm`
    /// once every parameter's been collected.
    fn mib_prompt_next_argument(&mut self) {
        let Some(insert) = &self.mib_insert else { return };
        if insert.cursor >= insert.variable_params.len() {
            self.mib_enter_confirm_stage();
            return;
        }
        let param = insert.variable_params[insert.cursor].clone();
        let group_suffix = mib_group_suffix(&insert.repeat_stack);
        let Some(index) = self.mib_index() else { return };
        let domain = fenix_mib::telecommand::parameter_domain(index, &param);
        if let Some(insert) = &mut self.mib_insert {
            insert.current_argument_context = mib_argument_context(&param.name, &domain, &group_suffix);
        }
        if domain.aliases.is_empty() {
            let prompt = mib_argument_prompt(&param.name, &domain, &group_suffix);
            if let Some(insert) = &mut self.mib_insert {
                insert.stage = MibInsertStage::ArgumentText { input: String::new(), prompt };
            }
        } else {
            let candidates = domain.aliases.iter().map(|alias| fenix_picker::Candidate::new(alias.clone(), alias.clone())).collect();
            self.enter_picker(ActivePicker::MibArgumentAlias(fenix_picker::PickerState::new(candidates)));
        }
        self.wake_caret();
    }

    /// `ActivePicker::MibArgumentAlias` confirm -- records `alias` as the
    /// current parameter's value and advances to the next one. Resets
    /// `main_view` back to `Editor` (picking a candidate left it on
    /// `Picker`) the same way every other picker-confirm path already
    /// does, whether inline (`Theme`/`TableColumn`) or via whatever it
    /// hands off to (`mib_start_insert`/`mib_open_detail`) -- missing
    /// here left the wizard's remaining stages (and the eventual insert
    /// itself) rendering behind a stale, now-buffer-less picker view
    /// until the user manually backed out of it.
    fn mib_resume_insert(&mut self, alias: String) {
        self.main_view = MainView::Editor;
        let Some(insert) = &self.mib_insert else { return };
        let idx = insert.cursor;
        let Some(param) = insert.variable_params.get(idx) else { return };
        let name = param.name.clone();
        if let Some(insert) = &mut self.mib_insert {
            insert.collected.push((name, alias.clone()));
            let (cursor, stack) =
                next_argument_cursor(&insert.variable_params, idx, &alias, std::mem::take(&mut insert.repeat_stack));
            insert.cursor = cursor;
            insert.repeat_stack = stack;
        }
        self.mib_prompt_next_argument();
    }

    /// Every variable parameter's collected (or skipped) -- renders the
    /// final command and re-validates every collected argument against
    /// its own engineering domain (aliases/ranges), moving the wizard to
    /// `Confirm`.
    fn mib_enter_confirm_stage(&mut self) {
        let Some(insert) = self.mib_insert.take() else { return };
        let Some(index) = self.mib_index() else {
            self.mib_insert = Some(insert);
            return;
        };
        let mut warnings = Vec::new();
        for (name, value) in &insert.collected {
            if let Some(param) = insert.variable_params.iter().find(|p| &p.name == name) {
                let domain = fenix_mib::telecommand::parameter_domain(index, param);
                warnings.extend(fenix_mib::telecommand::validate_argument(param, value, &domain));
            }
        }
        let rendered = fenix_mib::telecommand::render_telecommand(
            self.config.mib_telecommand_template.as_deref().unwrap_or(fenix_mib::telecommand::DEFAULT_TEMPLATE),
            self.config.mib_telecommand_argument_template.as_deref().unwrap_or(fenix_mib::telecommand::DEFAULT_ARGUMENT_TEMPLATE),
            self.config.mib_telecommand_argument_separator.as_deref().unwrap_or(fenix_mib::telecommand::DEFAULT_ARGUMENT_SEPARATOR),
            &insert.ccf,
            &insert.ccf.source.root_label.clone(),
            &insert.collected,
        );
        let mut insert = insert;
        insert.stage = MibInsertStage::Confirm { rendered, warnings };
        self.mib_insert = Some(insert);
        self.wake_caret();
    }

    /// `y` on the `Confirm` stage -- inserts the rendered command at
    /// wherever the wizard started (`MibInsertState::origin`) and closes
    /// the wizard.
    fn mib_commit_insert(&mut self) {
        let Some(insert) = self.mib_insert.take() else { return };
        let MibInsertStage::Confirm { rendered, .. } = insert.stage else { return };
        let Some(ob) = self.buffers.get_mut(insert.origin.buffer) else { return };
        let mut cursor = Cursor { char_idx: insert.origin.char_idx, sticky_col: 0 };
        ob.buffer.insert_str(&mut cursor, &rendered);
        if insert.origin.buffer == self.focused_buffer_id() {
            let pane = self.focused_pane_id();
            if let Some(pane_state) = self.workspaces.active_pane_states_mut().get_mut(&pane) {
                pane_state.cursor = cursor;
            }
        }
        self.wake_caret();
    }

    /// Routes one keystroke to the active `SPC m i` wizard -- only ever
    /// called while `mib_insert` is `Some` and its stage isn't delegated
    /// to a picker (`ChooseArgumentMode`/`ArgumentText`/`Confirm`; see
    /// `MibInsertStage`'s own doc comment). Computes what to do first
    /// (borrowing `self.mib_insert` immutably) and only then applies it
    /// (mutating `self`) -- the two can't overlap, since deciding what a
    /// `ChooseArgumentMode`/`Confirm` keystroke means can itself call
    /// `&mut self` methods (`mib_prompt_next_argument`/`mib_enter_
    /// confirm_stage`/`mib_commit_insert`).
    fn mib_insert_key(&mut self, key: KeyPress) {
        enum Action {
            Cancel,
            PromptNext,
            EnterConfirm,
            PushArgument(String),
            Backspace,
            PushChar(char),
            PushString(String),
            Commit,
            Ignore,
        }
        // Fetched before borrowing `self.mib_insert` below -- `clipboard_
        // text` takes `&mut self`, so it can't run while that borrow is
        // still live (same reasoning `find_file_prompt_key`'s own paste
        // handling documents).
        let pasted = if key == KeyPress::char('v').with_ctrl() { self.clipboard_text() } else { None };
        let Some(insert) = &self.mib_insert else { return };
        let action = match &insert.stage {
            MibInsertStage::ChooseArgumentMode => match key.code {
                KeyCode::Named(FenixNamedKey::Escape) => Action::Cancel,
                KeyCode::Char(c) if c.eq_ignore_ascii_case(&'y') => Action::PromptNext,
                _ => Action::EnterConfirm,
            },
            MibInsertStage::ArgumentText { input, .. } => {
                if let Some(text) = pasted {
                    Action::PushString(text)
                } else {
                    match key.code {
                        KeyCode::Named(FenixNamedKey::Escape) => Action::Cancel,
                        KeyCode::Named(FenixNamedKey::Enter) => Action::PushArgument(input.clone()),
                        KeyCode::Named(FenixNamedKey::Backspace) => Action::Backspace,
                        KeyCode::Char(c) if key.mods == Mods::default() => Action::PushChar(c),
                        _ => Action::Ignore,
                    }
                }
            }
            MibInsertStage::Confirm { .. } => match key.code {
                KeyCode::Char(c) if c.eq_ignore_ascii_case(&'y') => Action::Commit,
                _ => Action::Cancel,
            },
        };
        match action {
            Action::Cancel => self.mib_insert = None,
            Action::PromptNext => self.mib_prompt_next_argument(),
            Action::EnterConfirm => self.mib_enter_confirm_stage(),
            Action::PushArgument(value) => {
                if let Some(insert) = &mut self.mib_insert {
                    let idx = insert.cursor;
                    if let Some(param) = insert.variable_params.get(idx) {
                        let name = param.name.clone();
                        insert.collected.push((name, value.clone()));
                        let (cursor, stack) =
                            next_argument_cursor(&insert.variable_params, idx, &value, std::mem::take(&mut insert.repeat_stack));
                        insert.cursor = cursor;
                        insert.repeat_stack = stack;
                    }
                }
                self.mib_prompt_next_argument();
            }
            Action::Backspace => {
                if let Some(MibInsertStage::ArgumentText { input, .. }) = self.mib_insert.as_mut().map(|i| &mut i.stage) {
                    input.pop();
                }
            }
            Action::PushChar(c) => {
                if let Some(MibInsertStage::ArgumentText { input, .. }) = self.mib_insert.as_mut().map(|i| &mut i.stage) {
                    input.push(c);
                }
            }
            Action::PushString(text) => {
                if let Some(MibInsertStage::ArgumentText { input, .. }) = self.mib_insert.as_mut().map(|i| &mut i.stage) {
                    input.push_str(&text);
                }
            }
            Action::Commit => self.mib_commit_insert(),
            Action::Ignore => {}
        }
        self.wake_caret();
    }

    /// What to show in place of the modeline while `mib_insert` is active
    /// -- mirrors `explorer_prompt_text`/`git_prompt_text`. Takes
    /// priority over `modeline_pieces`'s own picker-badge/count display
    /// (`mib_insert.is_some()` is one of that function's own early-
    /// return conditions), so while `ActivePicker::MibArgumentAlias` is
    /// open (`mib_prompt_next_argument`'s alias branch enters it without
    /// changing `insert.stage`, which just stays whatever the *previous*
    /// parameter left it as -- there's no dedicated stage for "a picker
    /// is choosing this one's value") this needs its own check first,
    /// or the modeline would show stale wizard-stage text instead of
    /// anything about the picker actually on screen.
    fn mib_insert_text(&self) -> Option<String> {
        let insert = self.mib_insert.as_ref()?;
        if matches!(self.active_picker, Some(ActivePicker::MibArgumentAlias(_))) {
            return Some(format!("{} -- choose a value", insert.current_argument_context));
        }
        Some(match &insert.stage {
            MibInsertStage::ChooseArgumentMode => {
                let n = insert.variable_params.len();
                format!("Build {n} variable argument{}? (y/n)", if n == 1 { "" } else { "s" })
            }
            MibInsertStage::ArgumentText { input, prompt } => format!("{prompt}{input}"),
            MibInsertStage::Confirm { rendered, warnings } => {
                if warnings.is_empty() {
                    format!("Insert `{rendered}`? (y/n)")
                } else {
                    format!("{} warning(s) ({}) -- insert `{rendered}` anyway? (y/n)", warnings.len(), warnings.join("; "))
                }
            }
        })
    }

    /// `SPC s r`: starts the buffer-local search & replace wizard.
    /// Scoped to the current Visual selection's lines if invoked from
    /// Visual mode (mirroring real Vim's own `:'<,'>s` convention for a
    /// selection-invoked `:`), exiting Visual mode the same way
    /// `format_selection` already does; otherwise scoped to the whole
    /// buffer.
    pub(crate) fn start_replace_buffer(&mut self) {
        let line_range = if self.vim.mode() == Mode::Visual {
            let cursor = self.cursor();
            let ob = self.open();
            let lines = self.vim.visual_selection_range(&ob.buffer, &cursor).map(|(r, _)| {
                let lo = ob.buffer.line_col(&Cursor { char_idx: r.start, sticky_col: 0 }).0;
                let hi_idx = r.end.saturating_sub(1).max(r.start);
                let hi = ob.buffer.line_col(&Cursor { char_idx: hi_idx, sticky_col: 0 }).0;
                (lo, hi)
            });
            self.vim.exit_visual_mode(&cursor);
            lines
        } else {
            None
        };
        self.replace_wizard = Some(ReplaceWizard {
            scope: ReplaceScope::Buffer { line_range },
            stage: ReplaceWizardStage::Pattern { input: String::new() },
        });
        self.wake_caret();
    }

    /// `SPC s p`: starts the project-wide search & replace wizard --
    /// same pattern/replacement text entry as `SPC s r`, but the
    /// Replacement stage's Enter hands off to a real search
    /// (`start_project_search_replace`) instead of an in-place Confirm.
    pub(crate) fn start_replace_project(&mut self) {
        self.replace_wizard =
            Some(ReplaceWizard { scope: ReplaceScope::Project, stage: ReplaceWizardStage::Pattern { input: String::new() } });
        self.wake_caret();
    }

    /// Routes one keypress to the in-progress `replace_wizard` -- same
    /// "compute an `Action` enum immutably, apply mutably" two-phase
    /// shape `mib_insert_key` already uses.
    fn replace_wizard_key(&mut self, key: KeyPress) {
        enum Action {
            Cancel,
            PushChar(char),
            PushString(String),
            Backspace,
            ConfirmPattern,
            ConfirmReplacement,
            Apply,
        }
        // Fetched before borrowing `self.replace_wizard` below -- same
        // reasoning as `mib_insert_key`'s own paste handling.
        let pasted = if key == KeyPress::char('v').with_ctrl() { self.clipboard_text() } else { None };
        let Some(wizard) = &self.replace_wizard else { return };
        let action = match &wizard.stage {
            ReplaceWizardStage::Pattern { .. } | ReplaceWizardStage::Replacement { .. } if pasted.is_some() => {
                Action::PushString(pasted.unwrap_or_default())
            }
            ReplaceWizardStage::Pattern { .. } => match key.code {
                KeyCode::Named(FenixNamedKey::Escape) => Action::Cancel,
                KeyCode::Named(FenixNamedKey::Enter) => Action::ConfirmPattern,
                KeyCode::Named(FenixNamedKey::Backspace) => Action::Backspace,
                KeyCode::Char(c) if key.mods == Mods::default() => Action::PushChar(c),
                _ => return,
            },
            ReplaceWizardStage::Replacement { .. } => match key.code {
                KeyCode::Named(FenixNamedKey::Escape) => Action::Cancel,
                KeyCode::Named(FenixNamedKey::Enter) => Action::ConfirmReplacement,
                KeyCode::Named(FenixNamedKey::Backspace) => Action::Backspace,
                KeyCode::Char(c) if key.mods == Mods::default() => Action::PushChar(c),
                _ => return,
            },
            ReplaceWizardStage::Confirm { .. } => match key.code {
                KeyCode::Char(c) if c.eq_ignore_ascii_case(&'y') => Action::Apply,
                _ => Action::Cancel,
            },
        };
        match action {
            Action::Cancel => self.replace_wizard = None,
            Action::PushChar(c) => match &mut self.replace_wizard {
                Some(ReplaceWizard { stage: ReplaceWizardStage::Pattern { input }, .. })
                | Some(ReplaceWizard { stage: ReplaceWizardStage::Replacement { input, .. }, .. }) => input.push(c),
                _ => {}
            },
            Action::PushString(text) => match &mut self.replace_wizard {
                Some(ReplaceWizard { stage: ReplaceWizardStage::Pattern { input }, .. })
                | Some(ReplaceWizard { stage: ReplaceWizardStage::Replacement { input, .. }, .. }) => input.push_str(&text),
                _ => {}
            },
            Action::Backspace => match &mut self.replace_wizard {
                Some(ReplaceWizard { stage: ReplaceWizardStage::Pattern { input }, .. })
                | Some(ReplaceWizard { stage: ReplaceWizardStage::Replacement { input, .. }, .. }) => {
                    input.pop();
                }
                _ => {}
            },
            Action::ConfirmPattern => {
                if let Some(wizard) = &mut self.replace_wizard {
                    if let ReplaceWizardStage::Pattern { input } = &wizard.stage {
                        if !input.is_empty() {
                            wizard.stage = ReplaceWizardStage::Replacement { pattern: input.clone(), input: String::new() };
                        }
                    }
                }
            }
            Action::ConfirmReplacement => self.replace_wizard_confirm_replacement(),
            Action::Apply => self.apply_replace_wizard_confirm(),
        }
        self.wake_caret();
    }

    /// The Replacement stage's Enter -- for `Buffer` scope, computes the
    /// replacement right away (in-memory, no cost to pay) and advances
    /// to `Confirm` showing the match count; for `Project` scope, runs a
    /// real search and hands off to `project_replace` instead.
    fn replace_wizard_confirm_replacement(&mut self) {
        let Some(wizard) = &self.replace_wizard else { return };
        let ReplaceWizardStage::Replacement { pattern, input } = &wizard.stage else { return };
        let (pattern, replacement) = (pattern.clone(), input.clone());
        match wizard.scope {
            ReplaceScope::Buffer { line_range } => {
                let ob = self.open();
                let (start, end) = match line_range {
                    Some((lo, hi)) => {
                        let start = ob.buffer.line_start_char(lo);
                        let end = ob.buffer.line_start_char(hi) + ob.buffer.line_len(hi);
                        (start, end)
                    }
                    None => (0, ob.buffer.len_chars()),
                };
                let text = ob.buffer.text_range(start, end);
                match fenix_vim::replace_in_text(&text, &pattern, &replacement, false, true) {
                    Ok((_, 0)) | Err(_) => self.replace_wizard = None,
                    Ok((_, count)) => {
                        self.replace_wizard =
                            Some(ReplaceWizard { scope: wizard.scope, stage: ReplaceWizardStage::Confirm { pattern, replacement, count } });
                    }
                }
            }
            ReplaceScope::Project => {
                self.replace_wizard = None;
                self.start_project_search_replace(pattern, replacement);
            }
        }
    }

    /// `y` on the Buffer-scope `Confirm` stage -- re-runs the same
    /// `replace_in_text` computation (cheap, in-memory) over whatever
    /// scope the wizard captured and applies it as one `Buffer::
    /// replace_range` call (one undo step).
    fn apply_replace_wizard_confirm(&mut self) {
        let Some(wizard) = self.replace_wizard.take() else { return };
        let ReplaceWizardStage::Confirm { pattern, replacement, .. } = &wizard.stage else { return };
        let ReplaceScope::Buffer { line_range } = wizard.scope else { return };
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let (start, end) = match line_range {
            Some((lo, hi)) => {
                let start = buffer.line_start_char(lo);
                let end = buffer.line_start_char(hi) + buffer.line_len(hi);
                (start, end)
            }
            None => (0, buffer.len_chars()),
        };
        let text = buffer.text_range(start, end);
        if let Ok((new_text, count)) = fenix_vim::replace_in_text(&text, pattern, replacement, false, true) {
            if count > 0 {
                buffer.replace_range(cursor, start, end, &new_text);
            }
        }
    }

    /// What to show in place of the modeline while `replace_wizard` is
    /// active -- mirrors `mib_insert_text`/`explorer_prompt_text`.
    fn replace_wizard_text(&self) -> Option<String> {
        let wizard = self.replace_wizard.as_ref()?;
        Some(match &wizard.stage {
            ReplaceWizardStage::Pattern { input } => format!("search: {input}"),
            ReplaceWizardStage::Replacement { pattern, input } => format!("replace \"{pattern}\" with: {input}"),
            ReplaceWizardStage::Confirm { pattern, replacement, count } => {
                format!("Replace {count} occurrence{} of \"{pattern}\" with \"{replacement}\"? (y/n)", if *count == 1 { "" } else { "s" })
            }
        })
    }

    /// What to show in place of the modeline while the review buffer's
    /// y/n apply gate is armed -- mirrors `docker_confirm_text`.
    fn project_replace_confirm_text(&self) -> Option<String> {
        let session = self.project_replace.as_ref()?;
        if !session.confirming {
            return None;
        }
        let included = session.entries.iter().filter(|e| e.included).count();
        let total_matches: usize = session.entries.iter().filter(|e| e.included).map(|e| e.match_count).sum();
        Some(format!("Apply replace across {included} file(s) ({total_matches} occurrence(s))? (y/n)"))
    }

    /// `SPC s p`'s search step: runs a real project search and, unless
    /// it found nothing, groups the results by file and opens the
    /// review buffer. A `rg` failure or an empty result set is a silent
    /// no-op -- same graceful posture `run_grep` already has, and there
    /// being no review to show either way.
    fn start_project_search_replace(&mut self, pattern: String, replacement: String) {
        let root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let matches = fenix_project::grep_project(&root, &pattern).unwrap_or_else(|err| {
            self.set_error(format!("project search failed: {err}"));
            Vec::new()
        });
        if matches.is_empty() {
            return;
        }
        let entries = group_matches_by_file(matches);
        self.open_project_replace(pattern, replacement, root, entries);
    }

    /// Opens (or, if one's somehow already active, replaces) the
    /// `BufferKind::SearchReplace` review buffer for `entries` in the
    /// focused pane.
    fn open_project_replace(&mut self, pattern: String, replacement: String, root: PathBuf, entries: Vec<ProjectReplaceEntry>) {
        let (text, lines) = render_project_replace(&pattern, &replacement, &root, &entries);
        let id = self.buffers.open_text_view(&text);
        if let Some(ob) = self.buffers.get_mut(id) {
            ob.kind = BufferKind::SearchReplace;
        }
        self.project_replace_lines.insert(id, lines);
        let pane = self.focused_pane_id();
        self.set_pane_content(pane, id);
        self.project_replace = Some(ProjectReplaceSession { pattern, replacement, root, entries, buffer_id: id, confirming: false });
        self.wake_caret();
    }

    /// Regenerates the review buffer's rope text from `project_replace`'s
    /// *current* `entries` -- called after every toggle, one atomic
    /// `Buffer::replace_range` over the whole content (same tool `:s`/
    /// `set_dired_state` already use), deliberately not resetting any
    /// pane's cursor/scroll the way `set_dired_state` does for a real
    /// directory change (a toggle doesn't change the row count or what
    /// row means what, so there's nothing to re-seed).
    fn refresh_project_replace_buffer(&mut self) {
        let Some(session) = &self.project_replace else { return };
        let id = session.buffer_id;
        let (text, lines) = render_project_replace(&session.pattern, &session.replacement, &session.root, &session.entries);
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &text);
        }
        self.project_replace_lines.insert(id, lines);
    }

    /// `Space`/`t` on the review buffer: toggles the file under the
    /// cursor in/out of the pending replace.
    fn project_replace_toggle_selected(&mut self) {
        let id = self.focused_buffer_id();
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let Some(Some(idx)) = self.project_replace_lines.get(&id).and_then(|l| l.get(line)).copied() else { return };
        if let Some(session) = &mut self.project_replace {
            if let Some(entry) = session.entries.get_mut(idx) {
                entry.included = !entry.included;
            }
        }
        self.refresh_project_replace_buffer();
        self.wake_caret();
    }

    /// `a`/`Enter` on the review buffer -- arms the y/n apply gate the
    /// first time, actually applies on `y` while already armed.
    fn project_replace_confirm_or_apply(&mut self) {
        let already_confirming = self.project_replace.as_ref().is_some_and(|s| s.confirming);
        if already_confirming {
            self.project_replace_apply();
        } else if let Some(session) = &mut self.project_replace {
            session.confirming = true;
        }
        self.wake_caret();
    }

    /// Anything other than `y` while the apply gate is armed -- backs
    /// out to plain review, no writes.
    fn project_replace_decline_confirm(&mut self) {
        if let Some(session) = &mut self.project_replace {
            session.confirming = false;
        }
        self.wake_caret();
    }

    /// `q`/`Esc` on the review buffer: closes it without writing
    /// anything, same "this pane's `q` means close" precedent the
    /// Explorer/Docker/Git panels already established.
    fn project_replace_cancel(&mut self) {
        let Some(session) = self.project_replace.take() else { return };
        self.project_replace_lines.remove(&session.buffer_id);
        self.kill_buffer_now();
    }

    /// Writes every `included` entry's replacement -- an already-open
    /// buffer's path is edited in memory (left dirty, never written to
    /// disk directly out from under it -- see `BufferList::id_for_path`'s
    /// own doc comment for the clobbering risk this avoids); anything
    /// else is read fresh from disk, replaced, and written back
    /// directly. A file that no longer matches (changed since the
    /// search that found it) is silently skipped, not an error. Closes
    /// the review buffer and refocuses whatever was open before `SPC s
    /// p`, matching `mib_commit_insert`'s own "return to where this
    /// started" behavior.
    fn project_replace_apply(&mut self) {
        let Some(session) = self.project_replace.take() else { return };
        self.project_replace_lines.remove(&session.buffer_id);

        let mut files_changed = 0usize;
        let mut total_replacements = 0usize;
        let mut left_dirty = 0usize;
        for entry in session.entries.iter().filter(|e| e.included) {
            let open_id = self.buffers.id_for_path(&entry.path);
            let current_text = match open_id.and_then(|id| self.buffers.get(id)) {
                Some(ob) => ob.buffer.text(),
                None => match std::fs::read_to_string(&entry.path) {
                    Ok(text) => text,
                    Err(err) => {
                        eprintln!("fenix: search/replace couldn't read {}: {err}", entry.path.display());
                        continue;
                    }
                },
            };
            let (new_text, count) =
                match fenix_vim::replace_in_text(&current_text, &session.pattern, &session.replacement, false, true) {
                    Ok(result) => result,
                    Err(err) => {
                        eprintln!("fenix: search/replace pattern failed on {}: {err}", entry.path.display());
                        continue;
                    }
                };
            if count == 0 {
                continue;
            }
            match open_id {
                Some(id) => {
                    if let Some(ob) = self.buffers.get_mut(id) {
                        let mut scratch_cursor = Cursor::at_start();
                        let end = ob.buffer.len_chars();
                        ob.buffer.replace_range(&mut scratch_cursor, 0, end, &new_text);
                    }
                    left_dirty += 1;
                }
                None => {
                    if let Err(err) = std::fs::write(&entry.path, &new_text) {
                        eprintln!("fenix: search/replace couldn't write {}: {err}", entry.path.display());
                        continue;
                    }
                }
            }
            files_changed += 1;
            total_replacements += count;
        }
        self.set_message(format!(
            "applied {total_replacements} replacement(s) across {files_changed} file(s) ({left_dirty} already open, not yet saved)"
        ));
        self.kill_buffer_now();
    }

    /// `SPC b b`: a fuzzy picker over every open buffer, MRU-ordered
    /// (most-recently-touched first, matching Doom's own buffer switcher),
    /// each labeled with its path (or `*scratch*` for an unnamed buffer)
    /// and a leading `+` marker for unsaved changes.
    pub(crate) fn picker_switch_buffer(&mut self) {
        let candidates = self
            .buffers
            .mru()
            .iter()
            .map(|&id| {
                let ob = self.buffers.get(id).expect("mru only lists open buffers");
                let name = ob.buffer.path().map(|p| p.display().to_string()).unwrap_or_else(|| "*scratch*".to_string());
                let marker = if ob.kind.tracks_unsaved_changes() && ob.buffer.is_dirty() { "+ " } else { "" };
                fenix_picker::Candidate::new(format!("{marker}{name}"), id)
            })
            .collect();
        self.enter_picker(ActivePicker::SwitchBuffer(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC s s`: a fuzzy picker over every line in the focused buffer --
    /// candidates are the line's own text (trimmed of surrounding
    /// whitespace, right-aligned line number prefix for context), payload
    /// its start char offset. Live-filtered "for free" by `PickerState`'s
    /// own already-built fuzzy matching, the same mechanism `FindFile`/
    /// `Symbol` already lean on -- no new filtering logic needed here.
    pub(crate) fn picker_search_buffer(&mut self) {
        let buffer = &self.open().buffer;
        let visual_lines = buffer.visual_line_count();
        let candidates = (0..visual_lines)
            .map(|line| {
                let start = buffer.line_start_char(line);
                let len = buffer.line_len(line);
                let text = buffer.text_range(start, start + len);
                let label = format!("{:>4}  {}", line + 1, text.trim());
                fenix_picker::Candidate::new(label, start)
            })
            .collect();
        self.enter_picker(ActivePicker::BufferSearch(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC c o`: a fuzzy picker over every ATX heading in the focused
    /// Markdown buffer -- same "one candidate per matching line, payload
    /// its start char offset" shape `picker_search_buffer` already
    /// established for `SPC s s`, filtered to headings and labeled by
    /// nesting depth (`markdown::heading_label`) instead of a line
    /// number.
    ///
    /// Gated to a detected Markdown buffer, unlike list continuation/
    /// checkbox toggling: `#` at the start of a line means "comment,"
    /// not "heading," in half the languages this editor highlights
    /// (Python, Bash, YAML, Dockerfile, ...), so scanning for it without
    /// actually knowing the buffer is Markdown would list every comment
    /// in one of those as a heading.
    ///
    /// An empty result (no headings at all) still opens the picker,
    /// same as `SPC s s` -- "nothing to show" is a legitimate answer
    /// here, not an error worth a special-cased message.
    pub(crate) fn picker_outline(&mut self) {
        if self.focused_language() != Some(fenix_syntax::LanguageId::Markdown) {
            self.set_error("SPC c o needs a Markdown buffer");
            return;
        }
        let buffer = &self.open().buffer;
        let visual_lines = buffer.visual_line_count();
        let candidates = (0..visual_lines)
            .filter_map(|line| {
                let start = buffer.line_start_char(line);
                let len = buffer.line_len(line);
                let text = buffer.text_range(start, start + len);
                let (level, title) = markdown::parse_heading(&text)?;
                Some(fenix_picker::Candidate::new(markdown::heading_label(level, &title), start))
            })
            .collect();
        self.enter_picker(ActivePicker::Outline(fenix_picker::PickerState::new(candidates)));
    }

    /// Points the focused pane at an already-open buffer -- `SPC b b`'s
    /// confirm action, and shared by nothing else (unlike `open_file_from_
    /// picker`, there's no path to resolve/read; the buffer already
    /// exists in the registry).
    fn switch_focused_to_buffer(&mut self, id: BufferId) {
        self.open_buffer_in_focused_pane(id);
        self.buffers.touch(id);
        self.refresh_project_root();
        self.main_view = MainView::Editor;
    }

    /// `SPC b n`/`SPC b p`: cycles the focused pane through every open
    /// buffer in a stable, path-sorted order (not MRU -- repeated `n`/`p`
    /// should walk a fixed list, not bounce between the two most recent).
    fn cycle_buffer(&mut self, delta: isize) {
        let ids = self.buffers.ids_sorted_by_path();
        if ids.len() <= 1 {
            return;
        }
        let current = self.focused_buffer_id();
        let pos = ids.iter().position(|&id| id == current).unwrap_or(0) as isize;
        let next = ids[(pos + delta).rem_euclid(ids.len() as isize) as usize];
        self.switch_focused_to_buffer(next);
        self.wake_caret();
    }

    pub(crate) fn next_buffer(&mut self) {
        self.cycle_buffer(1);
    }

    pub(crate) fn prev_buffer(&mut self) {
        self.cycle_buffer(-1);
    }

    /// The unconditional half of buffer-closing: closes the focused
    /// buffer no matter what state it's in. Any pane (in this window
    /// tree) currently showing it falls back to the MRU-next open buffer,
    /// or a fresh scratch buffer if none remain -- never leaves a pane
    /// pointing at a closed `BufferId`. Closing one of the Docker/Git/
    /// Jira sessions' buffers this way really means "close the whole
    /// session" (they share live background state, not just a buffer
    /// slot) -- routed to `docker_session_close`/`git_session_close`/
    /// `jira_session_close` instead of the ordinary single-buffer path
    /// below. Used directly (bypassing `kill_buffer`'s dirty guard) by
    /// callers that are cancelling a generated review buffer
    /// (`project_replace_cancel` and its apply-flow counterpart) or
    /// have just deleted the buffer's file on purpose
    /// (`apply_delete_file`) -- none of those are the user-facing
    /// "close" action the guard exists for.
    fn kill_buffer_now(&mut self) {
        let id = self.focused_buffer_id();
        if let Some(session) = &self.docker_session {
            if [
                session.containers_buffer,
                session.images_buffer,
                session.volumes_buffer,
                session.networks_buffer,
                session.status_buffer,
                session.logs_buffer,
            ]
            .contains(&id)
            {
                self.docker_session_close();
                return;
            }
        }
        if let Some(session) = &self.git_session {
            if [
                session.status_buffer,
                session.staged_buffer,
                session.unstaged_buffer,
                session.branches_buffer,
                session.commits_buffer,
                session.stash_buffer,
                session.main_buffer,
            ]
            .contains(&id)
            {
                self.git_session_close();
                return;
            }
        }
        if let Some(session) = &self.jira_session {
            if [session.projects_buffer, session.users_buffer, session.issues_buffer, session.detail_buffer].contains(&id) {
                self.jira_session_close();
                return;
            }
        }
        if let Some(key) = self.vnc_session_key_for_buffer(id) {
            self.vnc_session_close(&key);
            return;
        }
        if let Some(key) = self.pdf_session_key_for_buffer(id) {
            self.pdf_session_close(&key);
            return;
        }
        if self.buffers.get(id).is_some_and(|ob| ob.kind == BufferKind::PdfOutline) {
            if let Some(key) = self.pdf_outline_source.get(&id).cloned() {
                self.pdf_close_outline_pane(&key);
                return;
            }
        }
        if self.buffers.get(id).is_some_and(|ob| ob.kind == BufferKind::PdfSearchResults) {
            if let Some(key) = self.pdf_search_source.get(&id).cloned() {
                self.pdf_close_search_pane(&key);
                return;
            }
        }
        // A pane-resident terminal's shell dies with its buffer -- see
        // `close_terminal_buffer` for why this, and not navigating away
        // from the pane, is what ends it.
        self.close_terminal_buffer(id);
        self.buffers.close(id);
        self.table_views.remove(&id);
        self.project_replace_lines.remove(&id);
        if self.project_replace.as_ref().is_some_and(|s| s.buffer_id == id) {
            self.project_replace = None;
        }
        let fallback = self.buffers.mru().first().copied().unwrap_or_else(|| self.buffers.open_scratch());
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                self.set_pane_content(pane, fallback);
            }
        }
        self.buffers.touch(fallback);
        self.refresh_project_root();
        self.wake_caret();
    }

    /// The guarded half both `:q`/`SPC b k` (`force = false`) and `:q!`
    /// (`force = true`) share. Unlike the app-wide `quit_confirm` y/n
    /// prompt, there's no ambiguity about *which* buffer a bare `:q`
    /// means, so an unsaved tracked (`BufferKind::tracks_unsaved_
    /// changes`) buffer is a hard refusal naming it, not a prompt.
    /// `force = true` bypasses this entirely -- same "`!` means I know,
    /// do it anyway" convention as `:qa!`.
    /// Closing a buffer means its snapshot has no owner left. Dropped
    /// either way: a clean close has nothing to recover, and a forced
    /// one is the user saying they don't want it -- offering it back on
    /// the next start would be ignoring that.
    fn close_focused_buffer(&mut self, force: bool) {
        let id = self.focused_buffer_id();
        if !force && self.buffers.get(id).is_some_and(|ob| ob.kind.tracks_unsaved_changes() && ob.buffer.is_dirty()) {
            let name = self.buffer_display_name(id);
            self.set_error(format!("{name} has unsaved changes -- use :q! to discard or :wq to save"));
            return;
        }
        self.discard_recovery_for(id);
        self.kill_buffer_now();
    }

    /// `SPC b k`/`:q`: closes the focused buffer, refusing (with a
    /// named error) if it has unsaved changes -- never quits the
    /// application, even if it's the last buffer open (falls back to a
    /// fresh scratch buffer instead, per `kill_buffer_now`). See
    /// `App::request_quit`/`app.quit` (`:qa`/`SPC q q`) for quitting.
    pub(crate) fn kill_buffer(&mut self) {
        self.close_focused_buffer(false);
    }

    /// `:q!`: closes the focused buffer unconditionally, discarding any
    /// unsaved changes.
    pub(crate) fn force_kill_buffer(&mut self) {
        self.close_focused_buffer(true);
    }

    /// `:wq`/`:x`: saves the focused buffer first if it needs it, then
    /// closes it. Refuses (naming the buffer) if it's dirty but has no
    /// path to save to yet, rather than silently discarding it or
    /// silently succeeding without writing anything.
    pub(crate) fn save_and_close_buffer(&mut self) {
        let id = self.focused_buffer_id();
        let Some(ob) = self.buffers.get(id) else { return };
        if ob.kind.tracks_unsaved_changes() && ob.buffer.is_dirty() {
            if ob.buffer.path().is_none() {
                let name = self.buffer_display_name(id);
                self.set_error(format!("no file name for {name} -- use :w <path> to save before closing"));
                return;
            }
            self.save();
            if self.buffers.get(id).is_some_and(|ob| ob.buffer.is_dirty()) {
                return; // save() already reported the failure; refuse to close
            }
        }
        self.kill_buffer_now();
    }

    /// `SPC b X`: opens a fresh, empty, unnamed buffer in the focused pane.
    pub(crate) fn new_scratch_buffer(&mut self) {
        let id = self.buffers.open_scratch();
        self.open_buffer_in_focused_pane(id);
        self.refresh_project_root();
        self.wake_caret();
    }

    /// `SPC d d`: (re-)opens the dashboard in the focused pane, freshly
    /// generated from the current `known_projects`/`recent_files` --
    /// always a *new* buffer, same "no dedup" precedent as `SPC b X`
    /// above (repeated presses just make more buffers; see this
    /// feature's own plan for why that's an intentional, not a new,
    /// simplification).
    pub(crate) fn open_dashboard(&mut self) {
        let dashboard = dashboard::render(self.known_projects.roots(), self.recent_files.paths());
        let id = self.buffers.open_dashboard(&dashboard.text);
        self.dashboard_lines.insert(id, dashboard.lines);
        self.open_buffer_in_focused_pane(id);
        self.refresh_project_root();
        self.wake_caret();
    }

    /// `SPC d d`: opens (or, if one's already open, refocuses/refreshes)
    /// the Lazydocker-style multi-pane session -- Containers/Images/
    /// Volumes stacked on the left, Status (small) and Logs stacked on
    /// the right, each with its own title bar (`pane_titles`).
    /// Deliberately breaks from the "always a new buffer/pane, no
    /// dedup" precedent `open_dashboard`/this feature's own earlier
    /// single-buffer form used: a session now owns live background
    /// threads/processes, and a second, orphaned one would leak them.
    /// Gets its own workspace (`SPC TAB`) so it doesn't disturb whatever
    /// splits/buffers were already open.
    pub(crate) fn open_docker_panel(&mut self) {
        if let Some(session) = &self.docker_session {
            let (workspace_index, containers_pane) = (session.workspace_index, session.containers_pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(containers_pane);
            self.docker_refresh_session();
            self.wake_caret();
            return;
        }

        let containers = fenix_docker::list_containers();
        let images = fenix_docker::list_images();
        let volumes = fenix_docker::list_volumes();
        let networks = fenix_docker::list_networks();

        let containers_panel = docker_panel::render_containers(&containers);
        let images_panel = docker_panel::render_images(&images);
        let volumes_panel = docker_panel::render_volumes(&volumes);
        let networks_panel = docker_panel::render_networks(&networks);
        let status_panel = docker_panel::render_details(None, None);

        let containers_buffer = self.buffers.open_docker(&containers_panel.text);
        let images_buffer = self.buffers.open_docker(&images_panel.text);
        let volumes_buffer = self.buffers.open_docker(&volumes_panel.text);
        let networks_buffer = self.buffers.open_docker(&networks_panel.text);
        let status_buffer = self.buffers.open_docker(&status_panel.text);
        let logs_buffer = self.buffers.open_docker("");
        self.docker_lines.insert(containers_buffer, containers_panel.lines);
        self.docker_lines.insert(images_buffer, images_panel.lines);
        self.docker_lines.insert(volumes_buffer, volumes_panel.lines);
        self.docker_lines.insert(networks_buffer, networks_panel.lines);
        self.docker_lines.insert(status_buffer, status_panel.lines);

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(containers_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let containers_pane = self.focused_pane_id();

        // Right column first, at the outer split -- default 0.5 ratio,
        // narrowed to ~35/65 next (left column is 3 stacked panes, so
        // it needs less width per pane than the right column's 2).
        let status_pane = self.windows_mut().split(SplitKind::Vertical, status_buffer);
        self.workspaces.active_pane_states_mut().insert(status_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-0.15);

        // Right column itself: Status (small, on top) / Logs (the rest)
        // -- shrink Status down from the default 50/50 split.
        let logs_pane = self.windows_mut().split(SplitKind::Horizontal, logs_buffer);
        self.workspaces.active_pane_states_mut().insert(logs_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-0.2);

        // Left column: Containers/Images/Volumes/Networks stacked.
        // Containers keeps its deliberate 50% (see the layout test's own
        // name); Images/Volumes/Networks split the other 50% into equal
        // thirds (1/6 of the column each). Three plain 0.5/0.5 splits
        // would only produce that for *three* panes (50/25/25) -- for
        // four, the Images split needs shrinking from 1/4 to 1/6 of the
        // column (1/3, not 1/2, of the remaining half) so the Volumes/
        // Networks split after it can still land on an even half each.
        self.windows_mut().focus(containers_pane);
        let images_pane = self.windows_mut().split(SplitKind::Horizontal, images_buffer);
        self.workspaces.active_pane_states_mut().insert(images_pane, PaneState::seeded_at(cursor));
        let volumes_pane = self.windows_mut().split(SplitKind::Horizontal, volumes_buffer);
        self.workspaces.active_pane_states_mut().insert(volumes_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-1.0 / 6.0);
        let networks_pane = self.windows_mut().split(SplitKind::Horizontal, networks_buffer);
        self.workspaces.active_pane_states_mut().insert(networks_pane, PaneState::seeded_at(cursor));
        self.windows_mut().focus(containers_pane);

        self.pane_titles.insert(containers_pane, "1. Containers".to_string());
        self.pane_titles.insert(images_pane, "2. Images".to_string());
        self.pane_titles.insert(volumes_pane, "3. Volumes".to_string());
        self.pane_titles.insert(networks_pane, "4. Networks".to_string());
        self.pane_titles.insert(status_pane, "5. Status".to_string());
        self.pane_titles.insert(logs_pane, "6. Logs".to_string());

        // Only spawned for a real, `main.rs`-launched `App` -- every
        // test's `event_proxy` stays `None` (see `App::new`'s own doc
        // comment), so a session opened in a test just never ticks,
        // which is fine (nothing there needs a working `docker` either).
        let stats_poller = self
            .event_proxy
            .clone()
            .map(|proxy| DockerStatsPoller::spawn(move |event| proxy.send_event(event).is_ok()));

        self.docker_session = Some(DockerSession {
            workspace_index,
            containers_pane,
            images_pane,
            volumes_pane,
            networks_pane,
            status_pane,
            logs_pane,
            containers_buffer,
            images_buffer,
            volumes_buffer,
            networks_buffer,
            status_buffer,
            logs_buffer,
            containers,
            images,
            volumes,
            networks,
            last_stats: Vec::new(),
            logs_container: None,
            stats_poller,
            log_follower: None,
        });

        self.refresh_project_root();
        self.wake_caret();
    }

    /// Rewrites `id`'s buffer text from a freshly-rendered `DockerPanel`,
    /// resetting every pane currently showing it back to the top -- same
    /// "rewrite the whole affected span as one step" tool (`Buffer::
    /// replace_range`) `set_dired_state` already uses for the dired
    /// buffer, and same "a refreshed listing can reorder/add/remove
    /// rows, so an old cursor position is meaningless against it"
    /// reasoning. Used by the manual `u` refresh and by switching
    /// Details between info/log content -- deliberately *not* used by
    /// the automatic stats-tick refresh (Phase 5), which needs to
    /// preserve the user's cursor instead of resetting it every ~2s.
    fn set_docker_buffer(&mut self, id: BufferId, panel: docker_panel::DockerPanel) {
        self.docker_lines.insert(id, panel.lines);
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &panel.text);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    /// `FenixUserEvent::StatsReady` handling: caches the fresh `docker
    /// stats` snapshot and re-syncs Status so a container's live CPU/MEM
    /// updates in place if one is currently selected -- Containers rows
    /// no longer show stats inline (see `docker_panel::render_
    /// containers`'s own doc comment for why), so there's no Containers-
    /// buffer rewrite here at all anymore, and Status is small/read-only
    /// enough that resetting it to the top on every tick (`docker_sync_
    /// details`'s own `set_docker_buffer` reset-to-top behavior) is
    /// harmless. A no-op if no session is open (the stats poller is
    /// always torn down with its session, but a stray already-in-flight
    /// event landing right at teardown is a cheap no-op to discard).
    fn apply_docker_stats(&mut self, stats: Vec<fenix_docker::ContainerStat>) {
        let Some(session) = self.docker_session.as_mut() else { return };
        session.last_stats = stats;
        self.docker_sync_details();
    }

    /// `u` (on any of the four left panes, Status, or Logs): re-lists
    /// containers/images/volumes/networks from `docker` and re-renders
    /// all four, then re-syncs Status from whatever's now under the
    /// cursor.
    fn docker_refresh_session(&mut self) {
        let Some(session) = self.docker_session.as_ref() else { return };
        let (containers_buffer, images_buffer, volumes_buffer, networks_buffer) =
            (session.containers_buffer, session.images_buffer, session.volumes_buffer, session.networks_buffer);

        let containers = fenix_docker::list_containers();
        let images = fenix_docker::list_images();
        let volumes = fenix_docker::list_volumes();
        let networks = fenix_docker::list_networks();
        let containers_panel = docker_panel::render_containers(&containers);
        let images_panel = docker_panel::render_images(&images);
        let volumes_panel = docker_panel::render_volumes(&volumes);
        let networks_panel = docker_panel::render_networks(&networks);

        if let Some(session) = self.docker_session.as_mut() {
            session.containers = containers;
            session.images = images;
            session.volumes = volumes;
            session.networks = networks;
        }
        self.set_docker_buffer(containers_buffer, containers_panel);
        self.set_docker_buffer(images_buffer, images_panel);
        self.set_docker_buffer(volumes_buffer, volumes_panel);
        self.set_docker_buffer(networks_buffer, networks_panel);
        self.docker_sync_details();
    }

    /// Which of the current `docker_session`'s six panes (if any) is
    /// focused right now -- `None` when there's no session, the active
    /// *workspace* isn't even the session's own one, or the focused
    /// pane belongs to something else entirely. The workspace check
    /// matters because `WindowId`s are only unique *within* one
    /// `WindowTree` (each workspace's tree keeps its own id counter
    /// starting from 0) -- comparing pane ids without first confirming
    /// the session's workspace is the active one could false-positive
    /// against a numerically-identical pane id in a completely
    /// different, unrelated workspace.
    fn docker_focused_role(&self) -> Option<DockerPaneRole> {
        let session = self.docker_session.as_ref()?;
        if self.workspaces.active_index() != session.workspace_index {
            return None;
        }
        let focused = self.focused_pane_id();
        if focused == session.containers_pane {
            Some(DockerPaneRole::Containers)
        } else if focused == session.images_pane {
            Some(DockerPaneRole::Images)
        } else if focused == session.volumes_pane {
            Some(DockerPaneRole::Volumes)
        } else if focused == session.networks_pane {
            Some(DockerPaneRole::Networks)
        } else if focused == session.status_pane {
            Some(DockerPaneRole::Status)
        } else if focused == session.logs_pane {
            Some(DockerPaneRole::Logs)
        } else {
            None
        }
    }

    /// The pane whose title bar is numbered `n` (`1. Containers` etc.,
    /// see `open_docker_panel`'s own title strings) -- backs the digit-
    /// key jump-to-pane shortcut. `None` outside a session or for a
    /// number with no matching pane.
    fn docker_pane_by_number(&self, n: u32) -> Option<fenix_window::WindowId> {
        let session = self.docker_session.as_ref()?;
        match n {
            1 => Some(session.containers_pane),
            2 => Some(session.images_pane),
            3 => Some(session.volumes_pane),
            4 => Some(session.networks_pane),
            5 => Some(session.status_pane),
            6 => Some(session.logs_pane),
            _ => None,
        }
    }

    /// What the cursor's current line on a Docker buffer targets -- a
    /// no-op (`None`) for a header/footer/blank line, mirroring
    /// `dashboard_activate_selected`'s own lookup shape. Reads whichever
    /// buffer is *focused*, which is always the right one here since
    /// every call site is only reached after routing has already
    /// confirmed the focused pane is a specific session role.
    fn docker_entry_at_cursor(&self) -> Option<docker_panel::DockerEntry> {
        let cursor = self.cursor();
        let line = self.open().buffer.line_col(&cursor).0;
        self.docker_lines
            .get(&self.focused_buffer_id())
            .and_then(|lines| lines.get(line))
            .and_then(|meta| meta.as_ref())
            .and_then(|meta| meta.entry.clone())
    }

    /// Re-renders the Status pane from whichever row is now under the
    /// cursor in the focused left pane, looked up in the session's own
    /// cached `containers`/`images`/`volumes` (plus `last_stats`, for a
    /// container's live CPU/MEM) -- pure formatting, no `docker` call.
    /// A no-op if nothing's selected or there's no session at all.
    /// Unconditional now that Status and Logs are separate buffers (see
    /// `DockerSession`'s own doc comment) -- moving the cursor around
    /// while logs are streaming no longer needs to skip this the way
    /// the single shared "Details" pane once did.
    fn docker_sync_details(&mut self) {
        let Some(entry) = self.docker_entry_at_cursor() else { return };
        let Some(session) = self.docker_session.as_ref() else { return };
        let (detail, stat) = match entry {
            docker_panel::DockerEntry::Container(id) => {
                let stat = docker_panel::find_stat(&session.last_stats, &id).cloned();
                (session.containers.iter().find(|c| c.id == id).cloned().map(docker_panel::DockerDetail::Container), stat)
            }
            docker_panel::DockerEntry::Image(id) => {
                (session.images.iter().find(|i| i.id == id).cloned().map(docker_panel::DockerDetail::Image), None)
            }
            docker_panel::DockerEntry::Volume(name) => {
                (session.volumes.iter().find(|v| v.name == name).cloned().map(docker_panel::DockerDetail::Volume), None)
            }
            docker_panel::DockerEntry::Network(id) => {
                (session.networks.iter().find(|n| n.id == id).cloned().map(docker_panel::DockerDetail::Network), None)
            }
        };
        let status_buffer = session.status_buffer;
        self.set_docker_buffer(status_buffer, docker_panel::render_details(detail.as_ref(), stat.as_ref()));
    }

    /// `s` on the Containers pane: starts the container under the cursor.
    fn docker_start_selected(&mut self) {
        if let Some(docker_panel::DockerEntry::Container(id)) = self.docker_entry_at_cursor() {
            if let Err(err) = fenix_docker::start_container(&id) {
                self.set_error(format!("docker start failed: {err}"));
            }
            self.docker_refresh_session();
        }
    }

    /// `S` on the Containers pane: stops the container under the cursor.
    fn docker_stop_selected(&mut self) {
        if let Some(docker_panel::DockerEntry::Container(id)) = self.docker_entry_at_cursor() {
            if let Err(err) = fenix_docker::stop_container(&id) {
                self.set_error(format!("docker stop failed: {err}"));
            }
            self.docker_refresh_session();
        }
    }

    /// `R` on the Containers pane: restarts the container under the
    /// cursor.
    fn docker_restart_selected(&mut self) {
        if let Some(docker_panel::DockerEntry::Container(id)) = self.docker_entry_at_cursor() {
            if let Err(err) = fenix_docker::restart_container(&id) {
                self.set_error(format!("docker restart failed: {err}"));
            }
            self.docker_refresh_session();
        }
    }

    /// `r` on the Images pane: creates and starts a detached container
    /// from the image under the cursor.
    fn docker_run_selected(&mut self) {
        if let Some(docker_panel::DockerEntry::Image(id)) = self.docker_entry_at_cursor() {
            if let Err(err) = fenix_docker::run_image(&id) {
                self.set_error(format!("docker run failed: {err}"));
            }
            self.docker_refresh_session();
        }
    }

    /// `l` on the Containers pane: switches the Logs pane into live
    /// log-follow mode for the container under the cursor -- spawns
    /// `docker logs -f`, replacing any previous follower first (so
    /// there's never more than one live child per session; see
    /// `DockerLogFollower`'s own doc comment), then forwards each new
    /// line into Logs as it arrives via `FenixUserEvent::LogLine` (see
    /// `append_docker_log_line`). Doesn't move focus -- Containers
    /// stays focused, Logs just starts streaming in place.
    ///
    /// Without a real `event_proxy` (every test, and any launch that
    /// somehow reaches this before the event loop exists) there's
    /// nothing that could ever deliver a `LogLine` event, so this falls
    /// back to `container_logs`' one-shot snapshot instead -- the
    /// feature still does something sensible rather than silently
    /// showing nothing.
    fn docker_view_logs_selected(&mut self) {
        let Some(docker_panel::DockerEntry::Container(id)) = self.docker_entry_at_cursor() else { return };
        let Some(session) = self.docker_session.as_mut() else { return };
        let logs_buffer = session.logs_buffer;
        session.log_follower = None; // tear down any previous follower first

        let Some(proxy) = self.event_proxy.clone() else {
            let text = match fenix_docker::container_logs(&id, DOCKER_LOG_TAIL_LINES) {
                Ok(text) if text.is_empty() => "(no log output)\n".to_string(),
                Ok(text) => text,
                Err(err) => format!("fenix: couldn't fetch logs for {id}: {err}\n"),
            };
            self.set_docker_buffer(logs_buffer, docker_panel::DockerPanel { text, lines: Vec::new() });
            return;
        };

        let Some(child) = fenix_docker::spawn_log_follower(&id, DOCKER_LOG_TAIL_LINES) else {
            let text = format!("fenix: couldn't start `docker logs -f` for {id}\n");
            self.set_docker_buffer(logs_buffer, docker_panel::DockerPanel { text, lines: Vec::new() });
            return;
        };

        let follower = DockerLogFollower::spawn(child, logs_buffer, move |event| proxy.send_event(event).is_ok());
        if let Some(session) = self.docker_session.as_mut() {
            session.log_follower = Some(follower);
            session.logs_container = Some(id.clone());
        }
        let text = format!("-- following logs for {id} --\n");
        self.set_docker_buffer(logs_buffer, docker_panel::DockerPanel { text, lines: Vec::new() });
    }

    /// `FenixUserEvent::LogLine` handling: appends one new line to the
    /// Details buffer. Discards a stray event for a buffer that isn't
    /// (or isn't anymore) the current session's Details buffer -- a
    /// cheap no-op, not worth racing to prevent at teardown.
    ///
    /// Auto-follow: for every pane currently showing this buffer, if
    /// its cursor was already on the last line *before* this line
    /// arrived, it's moved to the new last line after appending too, so
    /// the view stays pinned to the bottom -- the disclosed "simple
    /// heuristic" from the plan. A pane whose cursor was anywhere else
    /// (the user scrolled up to read earlier output) is left alone;
    /// navigating back to the end (real Vim `G`) re-arms auto-follow
    /// for it on the next line, since the same "already at the end"
    /// check will then be true again.
    fn append_docker_log_line(&mut self, buffer_id: BufferId, line: String) {
        if self.docker_session.as_ref().map(|s| s.logs_buffer) != Some(buffer_id) {
            return;
        }
        let panes_at_end: Vec<fenix_window::WindowId> = self
            .windows()
            .windows()
            .into_iter()
            .filter(|&pane| self.windows().content(pane) == Some(&buffer_id))
            .filter(|&pane| {
                let Some(ob) = self.buffers.get(buffer_id) else { return false };
                let (row, _) = ob.buffer.line_col(&self.pane_state(pane).cursor);
                row + 1 >= ob.buffer.visual_line_count()
            })
            .collect();

        let Some(ob) = self.buffers.get_mut(buffer_id) else { return };
        let mut append_cursor = Cursor { char_idx: ob.buffer.len_chars(), sticky_col: 0 };
        ob.buffer.insert_str(&mut append_cursor, &format!("{line}\n"));

        if let Some(ob) = self.buffers.get(buffer_id) {
            let last_line = ob.buffer.visual_line_count().saturating_sub(1);
            let end_char = ob.buffer.line_start_char(last_line);
            for pane in panes_at_end {
                self.pane_state_mut(pane).cursor = Cursor { char_idx: end_char, sticky_col: 0 };
            }
        }
    }

    /// `FenixUserEvent::LogEnded` handling: appends a marker line and
    /// drops the session's `log_follower` (the child already exited on
    /// its own in this path -- `Drop` still runs for consistency, but
    /// `kill()`/`wait()` on an already-gone process are harmless no-ops).
    fn finish_docker_log_stream(&mut self, buffer_id: BufferId) {
        if self.docker_session.as_ref().map(|s| s.logs_buffer) != Some(buffer_id) {
            return;
        }
        if let Some(ob) = self.buffers.get_mut(buffer_id) {
            let mut append_cursor = Cursor { char_idx: ob.buffer.len_chars(), sticky_col: 0 };
            ob.buffer.insert_str(&mut append_cursor, "-- log stream ended --\n");
        }
        if let Some(session) = self.docker_session.as_mut() {
            session.log_follower = None;
        }
    }

    /// `SPC t t` -- fuzzy-picks a discovered task
    /// (`fenix_tasks::discover_tasks`) to run. A no-op (with a message)
    /// with no known project root, or with a project root that has no
    /// discoverable tasks at all (no recognized marker file, and no
    /// `.fenix/project.ini` `[tasks]` overrides) -- there's genuinely
    /// nothing to offer the picker in either case.
    pub(crate) fn picker_tasks(&mut self) {
        let Some(root) = self.project_root.clone() else {
            self.set_error("no project root detected for the focused buffer".to_string());
            return;
        };
        let tasks = fenix_tasks::discover_tasks(&root);
        if tasks.is_empty() {
            self.set_error(format!("no known tasks for {}", root.display()));
            return;
        }
        let candidates = tasks.into_iter().map(|t| fenix_picker::Candidate::new(t.name.clone(), t)).collect();
        self.enter_picker(ActivePicker::Task(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC t r` -- reruns `last_task` without going back through the
    /// picker. A no-op (with a message) if nothing has been run yet this
    /// session.
    pub(crate) fn rerun_last_task(&mut self) {
        let Some((task, root)) = self.last_task.clone() else {
            self.set_error("no task has been run yet".to_string());
            return;
        };
        self.run_task(task, root);
    }

    /// `SPC t k` -- ends whatever task is currently running. A no-op
    /// (with a message) if no task is running right now -- either no
    /// panel is open at all, or one is but its last run already finished
    /// (`finish_task_run` already cleared `runner`).
    pub(crate) fn kill_running_task(&mut self) {
        let Some(session) = &self.task_session else {
            self.set_error("no task is running".to_string());
            return;
        };
        let Some(runner) = &session.runner else {
            self.set_error("no task is running".to_string());
            return;
        };
        runner.kill();
        let buffer = session.buffer;
        self.append_task_output_text(buffer, "-- task killed --");
        if let Some(session) = self.task_session.as_mut() {
            session.runner = None;
        }
    }

    /// Runs `task` from `root`, opening the single-pane Task Output
    /// panel if this is the first task run this session, or reusing
    /// (and clearing) the existing one otherwise -- replacing any
    /// previous run's live `runner` first, so there's never two tasks
    /// running from this app at once (same "one at a time" posture
    /// `docker_view_logs_selected` already established for the Docker
    /// log follower). Also records `last_task` for `SPC t r`, and clears
    /// the quickfix list before anything about this run's own output has
    /// arrived -- a stale previous run's diagnostics have no business
    /// surviving into a fresh one.
    fn run_task(&mut self, task: fenix_tasks::TaskDef, root: PathBuf) {
        self.last_task = Some((task.clone(), root.clone()));
        self.quickfix.clear();
        self.quickfix_index = None;
        let header = format!("$ {} {}\n", task.command, task.args.join(" "));

        let buffer = if let Some(session) = &self.task_session {
            let (workspace_index, pane, buffer) = (session.workspace_index, session.pane, session.buffer);
            self.task_session.as_mut().expect("just matched Some above").runner = None; // tear down any previous runner first
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(pane);
            self.reset_task_output_buffer(buffer, &header);
            buffer
        } else {
            let buffer = self.buffers.open_task_output(&header);
            let cursor = Cursor::at_start();
            self.workspaces.new_workspace(buffer, cursor);
            let workspace_index = self.workspaces.active_index();
            let pane = self.focused_pane_id();
            self.pane_titles.insert(pane, "Task Output".to_string());
            self.task_session = Some(TaskSession { workspace_index, pane, buffer, root: root.clone(), runner: None });
            buffer
        };

        self.start_task_process(task, root, buffer);
        self.wake_caret();
    }

    /// Overwrites the Task Output buffer's whole content with `header`
    /// (a fresh run's own `$ command args` line) and resets every pane
    /// currently showing it back to the top -- same shape as `set_
    /// docker_buffer`, just without that one's per-line metadata (there
    /// is none for task output; see `content_highlights_for_visible_
    /// range`'s own `BufferKind::TaskOutput` handling, which is exactly
    /// "none" -- plain foreground text throughout).
    fn reset_task_output_buffer(&mut self, id: BufferId, header: &str) {
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, header);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    /// Actually spawns `task`'s process and starts streaming its output
    /// into `buffer`. Without a real `event_proxy` (every test; see
    /// `App::new`'s own doc comment) there's nothing that could ever
    /// deliver a `TaskOutputLine`/`TaskFinished` event, so this falls
    /// back to running the task to completion synchronously and
    /// appending its whole combined output at once -- same posture
    /// `docker_view_logs_selected` already established for the same gap.
    fn start_task_process(&mut self, task: fenix_tasks::TaskDef, root: PathBuf, buffer: BufferId) {
        let Some(proxy) = self.event_proxy.clone() else {
            match std::process::Command::new(&task.command).args(&task.args).current_dir(&root).output() {
                Ok(out) => {
                    let mut combined = String::from_utf8_lossy(&out.stdout).into_owned();
                    combined.push_str(&String::from_utf8_lossy(&out.stderr));
                    for line in combined.lines() {
                        self.append_task_output_line(buffer, line.to_string());
                    }
                    self.finish_task_run(buffer, Some(out.status.success()));
                }
                Err(err) => self.append_task_output_text(buffer, &format!("fenix: couldn't start `{}`: {err}", task.command)),
            }
            return;
        };

        let Some(child) = fenix_tasks::spawn(&task, &root) else {
            self.append_task_output_text(buffer, &format!("fenix: couldn't start `{}`", task.command));
            return;
        };
        let runner = TaskRunner::spawn(child, buffer, move |event| proxy.send_event(event).is_ok());
        if let Some(session) = self.task_session.as_mut() {
            session.runner = Some(runner);
        }
    }

    /// `FenixUserEvent::TaskOutputLine` handling: parses the line
    /// (`fenix_tasks::parse_line` -- see its own doc comment for why a
    /// cargo `--message-format=json` line decodes into a human-readable
    /// multi-line block plus a recovered location, a recognized-but-
    /// uninteresting cargo JSON line -- `compiler-artifact`, one per
    /// crate compiled -- into nothing at all, and a plain `gcc`/`clang`/
    /// `pytest`/`ctest`-style line is tried against the generic
    /// `file:line:col:` convention instead), appends the display text
    /// (skipped entirely when empty, rather than leaving a blank line
    /// behind for every suppressed cargo JSON message), and -- when a
    /// location was recovered -- feeds it into the generalized quickfix
    /// list (as a path resolved against this session's own `root`,
    /// matching `fenix_project::grep_project`'s own `root.join(...)`
    /// treatment of a tool's root-relative paths) so `SPC p n`/`SPC p N`
    /// can step through this run's diagnostics the same way a project
    /// grep or LSP references already do.
    fn append_task_output_line(&mut self, buffer_id: BufferId, line: String) {
        if self.task_session.as_ref().map(|s| s.buffer) != Some(buffer_id) {
            return;
        }
        let parsed = fenix_tasks::parse_line(&line);
        if !parsed.display.is_empty() {
            self.append_task_output_text(buffer_id, &parsed.display);
        }
        if let Some(loc) = parsed.location {
            let root = self.task_session.as_ref().map(|s| s.root.clone()).unwrap_or_default();
            let path = root.join(loc.path);
            self.quickfix.push(QuickfixEntry::Task(fenix_project::GrepMatch { path, line: loc.line, col: loc.col, text: loc.message }));
        }
    }

    /// Appends `text` (verbatim, split on any internal `\n` -- a decoded
    /// cargo compiler message's own `rendered` block is often several
    /// lines) to the Task Output buffer, auto-following the same way
    /// `append_docker_log_line` already does for Docker's own live logs:
    /// any pane currently showing this buffer whose cursor was already
    /// on the last line before this arrived gets moved to the new last
    /// line after, so watching a live build stays pinned to the bottom
    /// unless the user has scrolled up to read something earlier.
    fn append_task_output_text(&mut self, buffer_id: BufferId, text: &str) {
        let panes_at_end: Vec<fenix_window::WindowId> = self
            .windows()
            .windows()
            .into_iter()
            .filter(|&pane| self.windows().content(pane) == Some(&buffer_id))
            .filter(|&pane| {
                let Some(ob) = self.buffers.get(buffer_id) else { return false };
                let (row, _) = ob.buffer.line_col(&self.pane_state(pane).cursor);
                row + 1 >= ob.buffer.visual_line_count()
            })
            .collect();

        let Some(ob) = self.buffers.get_mut(buffer_id) else { return };
        let mut append_cursor = Cursor { char_idx: ob.buffer.len_chars(), sticky_col: 0 };
        ob.buffer.insert_str(&mut append_cursor, &format!("{text}\n"));

        if let Some(ob) = self.buffers.get(buffer_id) {
            let last_line = ob.buffer.visual_line_count().saturating_sub(1);
            let end_char = ob.buffer.line_start_char(last_line);
            for pane in panes_at_end {
                self.pane_state_mut(pane).cursor = Cursor { char_idx: end_char, sticky_col: 0 };
            }
        }
    }

    /// `FenixUserEvent::TaskFinished` handling: appends a final
    /// succeeded/failed/unknown-status marker and drops the session's
    /// live `runner` -- same "the child already exited on its own here;
    /// `Drop` still runs for consistency, but its `kill()`/`wait()` on an
    /// already-gone process are harmless no-ops" shape `finish_docker_
    /// log_stream` already established.
    fn finish_task_run(&mut self, buffer_id: BufferId, success: Option<bool>) {
        if self.task_session.as_ref().map(|s| s.buffer) != Some(buffer_id) {
            return;
        }
        let marker = match success {
            Some(true) => "-- task succeeded --",
            Some(false) => "-- task failed --",
            None => "-- task ended (unknown status) --",
        };
        self.append_task_output_text(buffer_id, marker);
        if let Some(session) = self.task_session.as_mut() {
            session.runner = None;
        }
    }

    /// `SPC u u` -- starts a debug session for the focused buffer's
    /// language if none is running yet; sends `continue` if one is
    /// already stopped at a breakpoint/step; a no-op (with a message)
    /// if one is running but not currently stopped (nothing useful to
    /// do -- it's already going).
    pub(crate) fn debug_start_or_continue(&mut self) {
        if let Some(session) = &self.debug_session {
            let Some(thread_id) = session.stopped_thread else {
                // Already running -- nothing to continue, but still
                // worth taking the user back to the panel if they'd
                // navigated away from it (the same "reopen refocuses
                // the existing session" courtesy `open_docker_panel`
                // already gives Docker's own panel).
                let (workspace_index, pane) = (session.workspace_index, session.call_stack_pane);
                self.workspaces.switch_to_index(workspace_index);
                self.windows_mut().focus(pane);
                self.set_error("debug session is already running".to_string());
                return;
            };
            self.send_debug_step(fenix_dap::requests::Request::Continue(fenix_dap::requests::ContinueRequestArguments::builder().thread_id(thread_id).build()));
            return;
        }

        let Some(language) = self.focused_language() else {
            self.set_error("no recognized language for the focused buffer".to_string());
            return;
        };
        let Some((command, adapter_args)) = crate::dap::default_adapter_command(language) else {
            self.set_error(format!("no known debug adapter for {language:?}"));
            return;
        };
        let root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let launch = fenix_dap::read_launch_config(&root);
        let program = match launch.program {
            Some(p) => p,
            None => match self.open().buffer.path() {
                Some(p) => p.to_path_buf(),
                None => {
                    self.set_error("no file to debug -- open one, or set [launch] program in .fenix/project.ini".to_string());
                    return;
                }
            },
        };

        let (client, rx) = match fenix_dap::DapClient::spawn(&command, &adapter_args, &root) {
            Ok(pair) => pair,
            Err(err) => {
                self.set_error(format!("couldn't start debug adapter `{command}`: {err}"));
                return;
            }
        };
        let reader = self.event_proxy.clone().map(|proxy| DapReader::spawn(rx, move |event| proxy.send_event(event).is_ok()));

        let header = format!("$ {command} {}\n(starting {language:?} debug session for {})\n", adapter_args.join(" "), program.display());
        let call_stack_buffer = self.buffers.open_debug(&header);
        let variables_buffer = self.buffers.open_debug("(no variables)\n");
        let watches_buffer = self.buffers.open_debug("(no watches -- SPC u w adds the word under the cursor)\n");
        let breakpoints_buffer = self.buffers.open_debug(&render_breakpoints_text(&self.breakpoints));

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(call_stack_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let call_stack_pane = self.focused_pane_id();

        let variables_pane = self.windows_mut().split(SplitKind::Vertical, variables_buffer);
        self.workspaces.active_pane_states_mut().insert(variables_pane, PaneState::seeded_at(cursor));

        self.windows_mut().focus(call_stack_pane);
        let watches_pane = self.windows_mut().split(SplitKind::Horizontal, watches_buffer);
        self.workspaces.active_pane_states_mut().insert(watches_pane, PaneState::seeded_at(cursor));

        self.windows_mut().focus(variables_pane);
        let breakpoints_pane = self.windows_mut().split(SplitKind::Horizontal, breakpoints_buffer);
        self.workspaces.active_pane_states_mut().insert(breakpoints_pane, PaneState::seeded_at(cursor));

        self.windows_mut().focus(call_stack_pane);
        self.pane_titles.insert(call_stack_pane, "1. Call Stack".to_string());
        self.pane_titles.insert(variables_pane, "2. Variables".to_string());
        self.pane_titles.insert(watches_pane, "3. Watches".to_string());
        self.pane_titles.insert(breakpoints_pane, "4. Breakpoints".to_string());

        let mut session = DebugSession {
            workspace_index,
            call_stack_pane,
            variables_pane,
            watches_pane,
            breakpoints_pane,
            call_stack_buffer,
            variables_buffer,
            watches_buffer,
            breakpoints_buffer,
            client,
            reader,
            pending: HashMap::new(),
            root,
            program,
            initialized: false,
            stopped_thread: None,
            current_frame_id: None,
            call_stack: Vec::new(),
            variables: Vec::new(),
            pending_scopes: 0,
            watches: Vec::new(),
            watch_values: HashMap::new(),
        };
        let init_args = fenix_dap::requests::InitializeRequestArguments::builder().adapter_id("fenix".to_string()).client_id(Some("fenix".to_string())).build();
        if let Ok(seq) = session.client.request(fenix_dap::requests::Request::Initialize(init_args)) {
            session.pending.insert(seq, PendingDapRequest::Initialize);
        }
        self.debug_session = Some(session);
    }

    /// Sends a stepping/continuation request (`continue`/`next`/
    /// `stepIn`/`stepOut`/`pause`) -- these don't get their own
    /// response tracked in `pending` (see `PendingDapRequest`'s own doc
    /// comment: the state change they cause arrives via a `stopped`/
    /// `continued` event instead), so this is a thin, un-tracked send
    /// shared by every one of them.
    fn send_debug_step(&mut self, req: fenix_dap::requests::Request) {
        let Some(session) = self.debug_session.as_ref() else { return };
        let _ = session.client.request(req);
    }

    /// `SPC u n`/`SPC u i`/`SPC u o`/`SPC u p` -- step over/into/out, or
    /// pause. A no-op (with a message) unless actually stopped (step)
    /// or running (pause would be redundant while already stopped).
    pub(crate) fn debug_step_over(&mut self) {
        self.debug_step_request(|thread_id| fenix_dap::requests::Request::Next(fenix_dap::requests::NextRequestArguments::builder().thread_id(thread_id).build()));
    }
    pub(crate) fn debug_step_into(&mut self) {
        self.debug_step_request(|thread_id| fenix_dap::requests::Request::StepIn(fenix_dap::requests::StepInRequestArguments::builder().thread_id(thread_id).build()));
    }
    pub(crate) fn debug_step_out(&mut self) {
        self.debug_step_request(|thread_id| fenix_dap::requests::Request::StepOut(fenix_dap::requests::StepOutRequestArguments::builder().thread_id(thread_id).build()));
    }

    fn debug_step_request(&mut self, build: impl FnOnce(i32) -> fenix_dap::requests::Request) {
        let Some(session) = &self.debug_session else {
            self.set_error("no debug session running".to_string());
            return;
        };
        let Some(thread_id) = session.stopped_thread else {
            self.set_error("debug session isn't stopped".to_string());
            return;
        };
        self.send_debug_step(build(thread_id));
    }

    /// `SPC u q` -- ends the debug session entirely: dropping
    /// `DebugSession` drops its `DapClient`, whose own `Drop` sends
    /// `disconnect` and tears down the adapter process (see `DapClient::
    /// drop`'s own doc comment). Doesn't close the panel's workspace --
    /// same "leave what's already open, just stop the live session
    /// behind it" posture `finish_task_run`/`finish_docker_log_stream`
    /// already have; the four panes just stop updating.
    pub(crate) fn debug_stop(&mut self) {
        if self.debug_session.is_none() {
            self.set_error("no debug session running".to_string());
            return;
        }
        self.debug_session = None;
    }

    /// `SPC u b` -- toggles a breakpoint on the focused buffer's current
    /// line. Re-renders the Breakpoints pane immediately; if a session
    /// is running and already past its `initialized` event, also
    /// resends `setBreakpoints` for this file right away so a
    /// breakpoint set/cleared mid-session takes effect without needing
    /// a restart -- exactly what a real debugger's own "toggle
    /// breakpoint while running" already does.
    pub(crate) fn debug_toggle_breakpoint(&mut self) {
        let Some(path) = self.open().buffer.path().map(Path::to_path_buf) else {
            self.set_error("buffer has no file to set a breakpoint in".to_string());
            return;
        };
        let (line, _) = self.open().buffer.line_col(&self.cursor());
        let line = line + 1; // DAP/this map's own 1-indexed convention
        // `fenix_lsp::normalize` strips Windows' `\\?\` verbatim prefix
        // (which `canonicalize` always adds there) -- confirmed live
        // that skipping this breaks DAP breakpoints exactly the way it
        // once broke LSP diagnostics: the adapter reports the
        // breakpoint as `verified` against the prefixed path, but never
        // actually matches it against the plain-form path a running
        // frame reports, so it's silently never hit. See `fenix_rpc::
        // normalize`'s own doc comment for both incidents.
        let canonical = fenix_lsp::normalize(std::fs::canonicalize(&path).unwrap_or(path));
        let lines = self.breakpoints.entry(canonical.clone()).or_default();
        if !lines.remove(&line) {
            lines.insert(line);
        }
        if let Some(session) = self.debug_session.as_ref() {
            if session.initialized {
                self.send_set_breakpoints_for(&canonical);
            }
        }
        self.refresh_debug_panes();
    }

    /// `SPC u w` -- adds the identifier immediately before the cursor
    /// as a watch (`completion::prefix_at_cursor`'s own "what would
    /// autocomplete right here" notion -- no separate prompt UI for
    /// v1: place the cursor right after the identifier to watch, the
    /// same "cursor just past what you mean" convention `ciw`/`*`
    /// already ask for elsewhere in this app). Re-evaluates immediately
    /// if currently stopped; otherwise the watch just shows `<not
    /// evaluated>` until the next stop.
    pub(crate) fn debug_add_watch(&mut self) {
        let cursor = self.cursor();
        let ob = self.open();
        let Some((_, word)) = completion::prefix_at_cursor(&ob.buffer, &cursor).filter(|(_, w)| !w.is_empty()) else {
            self.set_error("no identifier before the cursor to watch".to_string());
            return;
        };
        if self.debug_session.as_ref().is_some_and(|s| s.watches.contains(&word)) {
            return; // already watching this expression
        }
        let Some(session) = self.debug_session.as_mut() else {
            self.set_error("no debug session running".to_string());
            return;
        };
        session.watches.push(word.clone());
        if let Some(frame_id) = session.current_frame_id {
            let args = fenix_dap::requests::EvaluateRequestArguments::builder().expression(word.clone()).frame_id(Some(frame_id)).build();
            if let Ok(seq) = session.client.request(fenix_dap::requests::Request::Evaluate(args)) {
                session.pending.insert(seq, PendingDapRequest::Evaluate { expression: word });
            }
        }
        self.refresh_debug_panes();
    }

    /// Sends `setBreakpoints` for `path` from `self.breakpoints`'
    /// current state -- always the *whole* file's breakpoint list, per
    /// DAP spec (one call replaces every breakpoint the adapter knows
    /// about for that source, there's no incremental add/remove
    /// request).
    fn send_set_breakpoints_for(&mut self, path: &Path) {
        let Some(session) = self.debug_session.as_mut() else { return };
        let lines = self.breakpoints.get(path).cloned().unwrap_or_default();
        let source = fenix_dap::types::Source::builder().path(Some(path.to_string_lossy().into_owned())).build();
        let breakpoints = lines.into_iter().map(|line| fenix_dap::types::SourceBreakpoint::builder().line(line as i32).build()).collect();
        let args = fenix_dap::requests::SetBreakpointsRequestArguments::builder().source(source).breakpoints(breakpoints).build();
        if let Ok(seq) = session.client.request(fenix_dap::requests::Request::SetBreakpoints(args)) {
            session.pending.insert(seq, PendingDapRequest::SetBreakpoints);
        }
    }

    /// `FenixUserEvent::Dap` handling -- the single dispatch point every
    /// decoded adapter event passes through, same role `apply_lsp_
    /// event` plays for language servers.
    fn apply_dap_event(&mut self, event: fenix_dap::DapEvent) {
        match event {
            fenix_dap::DapEvent::Response { request_seq, result } => {
                let Some(session) = self.debug_session.as_mut() else { return };
                let Some(pending) = session.pending.remove(&request_seq) else { return };
                self.apply_dap_response(pending, result);
            }
            fenix_dap::DapEvent::Event(event) => self.apply_dap_notification(event),
            // No reverse request this app actually needs to answer yet
            // (e.g. `runInTerminal`, which neither `debugpy` nor a
            // future native adapter needs for the `internalConsole`/
            // piped-output launch shape this app always requests) --
            // still answered, per spec, rather than left hanging.
            fenix_dap::DapEvent::ReverseRequest { seq, .. } => {
                if let Some(session) = self.debug_session.as_ref() {
                    let err = fenix_dap::responses::ErrorResponse::builder()
                        .command("unknown".to_string())
                        .message("not implemented".to_string())
                        .body(fenix_dap::responses::ErrorResponseBody::new(None))
                        .build();
                    let _ = session.client.respond(seq, Err(err));
                }
            }
            // See `DapEvent::Unknown`'s own doc comment -- expected,
            // not an error; simply nothing to do with it.
            fenix_dap::DapEvent::Unknown(_) => {}
            fenix_dap::DapEvent::Disconnected(reason) => {
                if let Some(session) = self.debug_session.as_mut() {
                    session.stopped_thread = None;
                    session.call_stack = vec![("(adapter disconnected)".to_string(), PathBuf::new(), 0)];
                }
                self.refresh_debug_panes();
                self.set_error(format!("debug adapter disconnected: {reason}"));
            }
        }
    }

    fn apply_dap_response(&mut self, pending: PendingDapRequest, result: Result<fenix_dap::responses::SuccessResponse, fenix_dap::responses::ErrorResponse>) {
        use fenix_dap::responses::SuccessResponse;
        match pending {
            PendingDapRequest::Initialize => match result {
                Ok(_) => {
                    let Some(session) = self.debug_session.as_ref() else { return };
                    let language = fenix_syntax::detect_language_from_path(&session.program).unwrap_or(fenix_syntax::LanguageId::Python);
                    let additional_attributes = crate::dap::launch_arguments(language, &session.program);
                    let args = fenix_dap::requests::LaunchRequestArguments::builder().additional_attributes(additional_attributes).build();
                    let Some(session) = self.debug_session.as_mut() else { return };
                    if let Ok(seq) = session.client.request(fenix_dap::requests::Request::Launch(args)) {
                        session.pending.insert(seq, PendingDapRequest::Launch);
                    }
                }
                Err(err) => self.set_error(format!("debug adapter failed to initialize: {}", err.message)),
            },
            PendingDapRequest::Launch => {
                if let Err(err) = result {
                    self.set_error(format!("launch failed: {}", err.message));
                }
            }
            PendingDapRequest::SetBreakpoints => {
                // Nothing further to do -- the Breakpoints pane already
                // renders from `self.breakpoints` (the source of truth)
                // the moment it changes, not from this response; see
                // `DebugSession::breakpoints_buffer`'s own doc comment
                // for the disclosed gap this leaves (verified/rejected
                // status per breakpoint isn't tracked for v1).
            }
            PendingDapRequest::StackTrace => {
                if let Ok(SuccessResponse::StackTrace(body)) = result {
                    let Some(session) = self.debug_session.as_mut() else { return };
                    session.call_stack = body
                        .stack_frames
                        .iter()
                        .map(|f| (f.name.clone(), f.source.as_ref().and_then(|s| s.path.clone()).map(PathBuf::from).unwrap_or_default(), f.line.max(0) as usize))
                        .collect();
                    let top = body.stack_frames.first();
                    session.current_frame_id = top.map(|f| f.id);
                    let top_location = top.and_then(|f| f.source.as_ref().and_then(|s| s.path.clone())).map(|p| (PathBuf::from(p), top.unwrap().line.max(0) as usize));
                    let frame_id = session.current_frame_id;

                    if let Some((path, line)) = top_location {
                        self.goto_debug_location(&path, line);
                    }
                    self.refresh_debug_panes();

                    if let Some(frame_id) = frame_id {
                        let Some(session) = self.debug_session.as_mut() else { return };
                        let args = fenix_dap::requests::ScopesRequestArguments::builder().frame_id(frame_id).build();
                        if let Ok(seq) = session.client.request(fenix_dap::requests::Request::Scopes(args)) {
                            session.pending.insert(seq, PendingDapRequest::Scopes);
                        }
                        for expr in session.watches.clone() {
                            let args = fenix_dap::requests::EvaluateRequestArguments::builder().expression(expr.clone()).frame_id(Some(frame_id)).build();
                            if let Ok(seq) = session.client.request(fenix_dap::requests::Request::Evaluate(args)) {
                                session.pending.insert(seq, PendingDapRequest::Evaluate { expression: expr });
                            }
                        }
                    }
                }
            }
            PendingDapRequest::Scopes => {
                if let Ok(SuccessResponse::Scopes(body)) = result {
                    let Some(session) = self.debug_session.as_mut() else { return };
                    session.variables.clear();
                    session.pending_scopes = body.scopes.len();
                    if body.scopes.is_empty() {
                        self.refresh_debug_panes();
                    }
                    for scope in body.scopes {
                        let Some(session) = self.debug_session.as_mut() else { return };
                        let args = fenix_dap::requests::VariablesRequestArguments::builder().variables_reference(scope.variables_reference).build();
                        if let Ok(seq) = session.client.request(fenix_dap::requests::Request::Variables(args)) {
                            session.pending.insert(seq, PendingDapRequest::Variables { scope_name: scope.name });
                        } else {
                            session.pending_scopes = session.pending_scopes.saturating_sub(1);
                        }
                    }
                }
            }
            PendingDapRequest::Variables { scope_name } => {
                let Some(session) = self.debug_session.as_mut() else { return };
                if let Ok(SuccessResponse::Variables(body)) = result {
                    let vars = body.variables.into_iter().map(|v| (v.name, v.value)).collect();
                    session.variables.push((scope_name, vars));
                }
                session.pending_scopes = session.pending_scopes.saturating_sub(1);
                if session.pending_scopes == 0 {
                    self.refresh_debug_panes();
                }
            }
            PendingDapRequest::Evaluate { expression } => {
                let Some(session) = self.debug_session.as_mut() else { return };
                let value = match result {
                    Ok(SuccessResponse::Evaluate(body)) => body.result,
                    _ => "<error>".to_string(),
                };
                session.watch_values.insert(expression, value);
                self.refresh_debug_panes();
            }
        }
    }

    /// One decoded `event` message (`initialized`/`stopped`/
    /// `continued`/`terminated`/`exited`/... -- everything not routed
    /// through `apply_dap_response`, since these arrive unsolicited
    /// rather than as an answer to a specific request).
    fn apply_dap_notification(&mut self, event: fenix_dap::events::Event) {
        use fenix_dap::events::Event;
        match event {
            Event::Initialized => {
                let Some(session) = self.debug_session.as_mut() else { return };
                session.initialized = true;
                let paths: Vec<PathBuf> = self.breakpoints.iter().filter(|(_, lines)| !lines.is_empty()).map(|(p, _)| p.clone()).collect();
                for path in paths {
                    self.send_set_breakpoints_for(&path);
                }
                let Some(session) = self.debug_session.as_mut() else { return };
                let _ = session.client.request(fenix_dap::requests::Request::ConfigurationDone);
            }
            Event::Stopped(body) => {
                let Some(session) = self.debug_session.as_mut() else { return };
                let thread_id = body.thread_id.unwrap_or(0);
                session.stopped_thread = Some(thread_id);
                let args = fenix_dap::requests::StackTraceRequestArguments::builder().thread_id(thread_id).build();
                if let Ok(seq) = session.client.request(fenix_dap::requests::Request::StackTrace(args)) {
                    session.pending.insert(seq, PendingDapRequest::StackTrace);
                }
            }
            Event::Continued(_) => {
                let Some(session) = self.debug_session.as_mut() else { return };
                session.stopped_thread = None;
                session.current_frame_id = None;
                session.call_stack.clear();
                session.variables.clear();
                self.refresh_debug_panes();
            }
            Event::Terminated(_) | Event::Exited(_) => {
                let Some(session) = self.debug_session.as_mut() else { return };
                session.stopped_thread = None;
                session.call_stack = vec![("(program ended)".to_string(), PathBuf::new(), 0)];
                self.refresh_debug_panes();
            }
            _ => {} // output/module/thread/process/... -- no dedicated pane for these in v1
        }
    }

    /// Moves the cursor to `line` (1-indexed) in whichever pane(s)
    /// already show `path`'s buffer, without stealing focus from
    /// wherever it currently is; if `path` isn't open in any pane yet,
    /// opens and focuses it (`open_file_from_picker`), same "visit a
    /// file" semantics a quickfix jump already has. What conveys "this
    /// is the current line while stopped" -- see `DebugSession`'s own
    /// doc comment on why this app relies on the caret's own visibility
    /// rather than a separate persistent highlight for v1.
    fn goto_debug_location(&mut self, path: &Path, line: usize) {
        let Some(buffer_id) = self.buffers.id_for_path(path) else {
            self.open_file_from_picker(path);
            self.jump_to_grep_match(&fenix_project::GrepMatch { path: path.to_path_buf(), line, col: 1, text: String::new() });
            return;
        };
        let mut shown_somewhere = false;
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&buffer_id) {
                shown_somewhere = true;
                if let Some(ob) = self.buffers.get(buffer_id) {
                    let target_line = line.saturating_sub(1).min(ob.buffer.visual_line_count().saturating_sub(1));
                    let char_idx = ob.buffer.line_start_char(target_line);
                    let (_, sticky) = ob.buffer.line_col(&Cursor { char_idx, sticky_col: 0 });
                    let ps = self.pane_state_mut(pane);
                    ps.cursor = Cursor { char_idx, sticky_col: sticky };
                }
            }
        }
        if !shown_somewhere {
            self.open_file_from_picker(path);
            self.jump_to_grep_match(&fenix_project::GrepMatch { path: path.to_path_buf(), line, col: 1, text: String::new() });
        }
    }

    /// Re-renders all four Debug panel panes from `self.debug_session`/
    /// `self.breakpoints`' current state -- called after any state
    /// change rather than patching each pane individually; cheap enough
    /// (a handful of stack frames/variables/watches/breakpoints, not
    /// thousands) that rebuilding beats the bug surface of four
    /// separately-patched panes drifting out of sync with each other.
    fn refresh_debug_panes(&mut self) {
        let Some(session) = &self.debug_session else { return };
        let (call_stack_buffer, variables_buffer, watches_buffer, breakpoints_buffer) =
            (session.call_stack_buffer, session.variables_buffer, session.watches_buffer, session.breakpoints_buffer);
        let call_stack_text = render_call_stack_text(session);
        let variables_text = render_variables_text(session);
        let watches_text = render_watches_text(session);
        let breakpoints_text = render_breakpoints_text(&self.breakpoints);
        self.set_debug_buffer(call_stack_buffer, &call_stack_text);
        self.set_debug_buffer(variables_buffer, &variables_text);
        self.set_debug_buffer(watches_buffer, &watches_text);
        self.set_debug_buffer(breakpoints_buffer, &breakpoints_text);
    }

    /// Overwrites one Debug panel pane's whole content with freshly
    /// rendered `text`, resetting every pane showing it back to the top
    /// -- same shape as `set_docker_buffer`/`reset_task_output_buffer`.
    fn set_debug_buffer(&mut self, id: BufferId, text: &str) {
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, text);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    /// `SPC l m`: opens (or, if already open, refreshes and refocuses)
    /// the single-pane tool status listing -- every `LanguageId` this
    /// app has a built-in LSP default or DAP default for (plus any
    /// `[lsp]`-configured override), whether that command is found on
    /// `PATH`, whether a session for it is running right now, and an
    /// install hint for anything missing. See `tool_status`'s own doc
    /// comment for why this is a synchronous, no-subprocess `PATH` scan
    /// rather than a background poller like `DockerSession`'s.
    ///
    /// `dap_running` only ever checks Python: `dap::default_adapter_
    /// command` is the one DAP adapter this app knows about at all right
    /// now (see its own doc comment), and `DebugSession` doesn't track
    /// which language it was launched for since there's never been a
    /// second one to distinguish from -- revisit this the day a second
    /// DAP adapter actually exists.
    pub(crate) fn open_tool_status_panel(&mut self) {
        let configured = self.config.lsp_servers.clone();
        let lsp_sessions: std::collections::HashSet<fenix_syntax::LanguageId> = self.lsp_sessions.keys().copied().collect();
        let dap_running = self.debug_session.is_some();
        let entries = crate::tool_status::scan(
            |language| crate::lsp::resolve_server_command(language, &configured),
            crate::dap::default_adapter_command,
            |language| lsp_sessions.contains(&language),
            |language| dap_running && language == fenix_syntax::LanguageId::Python,
        );
        let text = crate::tool_status::render(&entries);

        if let Some(session) = &self.tool_status_session {
            let (workspace_index, pane, buffer) = (session.workspace_index, session.pane, session.buffer);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(pane);
            self.set_tool_status_buffer(buffer, &text);
        } else {
            let buffer = self.buffers.open_tool_status(&text);
            let cursor = Cursor::at_start();
            self.workspaces.new_workspace(buffer, cursor);
            let workspace_index = self.workspaces.active_index();
            let pane = self.focused_pane_id();
            self.pane_titles.insert(pane, "Tool Status".to_string());
            self.tool_status_session = Some(ToolStatusSession { workspace_index, pane, buffer });
        }
        self.wake_caret();
    }

    /// Same shape as `set_debug_buffer`/`set_docker_buffer`.
    fn set_tool_status_buffer(&mut self, id: BufferId, text: &str) {
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, text);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    /// `SPC d b`: builds an image from the current project root's
    /// `Dockerfile` (falling back to the process's cwd with no detected
    /// project) -- doesn't need a particular pane focused, unlike the
    /// per-row actions above, since a build targets the project, not a
    /// selected container/image. Refreshes an already-open session so a
    /// freshly built image shows up without a separate manual `u`.
    pub(crate) fn docker_build(&mut self) {
        let context_dir = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let tag = context_dir.file_name().map(|n| format!("{}:latest", n.to_string_lossy()));
        match fenix_docker::build_image(&context_dir, tag.as_deref()) {
            Ok(_) => self.set_message(format!("docker build succeeded for {}", context_dir.display())),
            Err(err) => self.set_error(format!("docker build failed: {err}")),
        }
        if self.docker_session.is_some() {
            self.docker_refresh_session();
        }
        self.wake_caret();
    }

    /// `SPC d q`, or `SPC b k` on any of the session's five buffers (see
    /// `kill_buffer`'s own hook): tears down the whole multi-pane
    /// session -- closes all six buffers, clears their `docker_lines`/
    /// `pane_titles` entries, and removes the session's own workspace
    /// (switched to first, so this is correct regardless of whichever
    /// workspace happens to be active when it's called -- always
    /// succeeds, since `open_docker_panel` only ever creates a *new*
    /// workspace for a session, never reuses the one that was active
    /// before it, so there's always at least one other workspace left).
    pub(crate) fn docker_session_close(&mut self) {
        let Some(session) = self.docker_session.take() else { return };
        for id in [
            session.containers_buffer,
            session.images_buffer,
            session.volumes_buffer,
            session.networks_buffer,
            session.status_buffer,
            session.logs_buffer,
        ] {
            self.buffers.close(id);
            self.docker_lines.remove(&id);
        }
        for pane in [
            session.containers_pane,
            session.images_pane,
            session.volumes_pane,
            session.networks_pane,
            session.status_pane,
            session.logs_pane,
        ] {
            self.pane_titles.remove(&pane);
        }
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    /// Modeline text while a Docker remove is armed (`x` was just
    /// pressed) -- same "override the modeline with raw prompt text"
    /// mechanism `Mode::Command`/`Mode::Search` already use.
    fn docker_confirm_text(&self) -> Option<String> {
        let entry = self.docker_confirm_remove.as_ref()?;
        let what = match entry {
            docker_panel::DockerEntry::Container(_) => "container",
            docker_panel::DockerEntry::Image(_) => "image",
            // Volumes are list-only for now (see the multi-pane plan's
            // Scope: no `fenix_docker` volume-remove function exists
            // yet) -- unreachable today since nothing arms `x` on a
            // Volume entry, kept only for match exhaustiveness.
            docker_panel::DockerEntry::Volume(_) => "volume",
            docker_panel::DockerEntry::Network(_) => "network",
        };
        Some(format!("Remove this {what}? (y/n)"))
    }

    /// Resolves an armed Docker remove: `y` confirms and removes,
    /// anything else cancels. Either way clears `docker_confirm_remove`
    /// and returns the modeline to normal.
    fn docker_confirm_key(&mut self, keypress: KeyPress) {
        let entry = self.docker_confirm_remove.take();
        if keypress.code == KeyCode::Char('y') {
            if let Some(entry) = entry {
                let result = match entry {
                    docker_panel::DockerEntry::Container(id) => fenix_docker::remove_container(&id),
                    docker_panel::DockerEntry::Image(id) => fenix_docker::remove_image(&id),
                    // Unreachable today -- see `docker_confirm_text`'s
                    // matching comment.
                    docker_panel::DockerEntry::Volume(_) => Ok(String::new()),
                    docker_panel::DockerEntry::Network(id) => fenix_docker::remove_network(&id),
                };
                if let Err(err) = result {
                    self.set_error(format!("docker remove failed: {err}"));
                }
                self.docker_refresh_session();
            }
        }
        self.wake_caret();
    }

    /// `SPC g g`: opens (or, if one's already open, refocuses/refreshes)
    /// the Lazygit-style multi-pane session -- Status/Files/Branches/
    /// Commits/Stash stacked on the left, Main (diff view) on the right,
    /// each with its own title bar. Mirrors `open_docker_panel` closely
    /// (session-reuse-on-reopen, its own workspace, a background
    /// poller) -- see `GitSession`'s own doc comment for the one real
    /// structural difference (every `fenix-git` call targets a specific
    /// repo root, not a daemon reachable regardless of cwd).
    pub(crate) fn open_git_panel(&mut self) {
        if let Some(session) = &self.git_session {
            let (workspace_index, staged_pane) = (session.workspace_index, session.staged_pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(staged_pane);
            self.git_refresh_session();
            self.wake_caret();
            return;
        }

        let repo_root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));

        let (status, files) = fenix_git::status_and_files(&repo_root);
        let in_progress = fenix_git::in_progress(&repo_root);
        let sides = fenix_git::conflict_sides(&repo_root);
        let branches = fenix_git::list_branches(&repo_root);
        let commits = fenix_git::list_commits(&repo_root, 50);
        let stashes = fenix_git::list_stashes(&repo_root);

        let (staged, unstaged, untracked) = file_counts(&files);
        let status_panel =
            git_panel::render_status(status.as_ref(), staged, unstaged, untracked, in_progress.as_ref(), conflict_count(&files), sides.as_ref());
        let staged_panel = git_panel::render_staged(&files, &HashSet::new());
        let unstaged_panel = git_panel::render_unstaged(&files, &HashSet::new());
        let branches_panel = git_panel::render_branches(&branches);
        let commits_panel = git_panel::render_commits(&commits);
        let stash_panel = git_panel::render_stash(&stashes);

        let status_buffer = self.buffers.open_git(&status_panel.text);
        let staged_buffer = self.buffers.open_git(&staged_panel.text);
        let unstaged_buffer = self.buffers.open_git(&unstaged_panel.text);
        let branches_buffer = self.buffers.open_git(&branches_panel.text);
        let commits_buffer = self.buffers.open_git(&commits_panel.text);
        let stash_buffer = self.buffers.open_git(&stash_panel.text);
        // The Main pane is a real `BufferKind::Diff` buffer, not another
        // Git one: it renders through `diff_view` (hunk-aware, with a
        // line-number gutter and per-row anchors) rather than as
        // prefix-colored text, which is what makes hunk staging and
        // "open the file at this line" possible at all.
        let main_view = diff_view::render(&[], &HashSet::new());
        let main_buffer = self.buffers.open_diff(&main_view.text);
        self.git_lines.insert(status_buffer, status_panel.lines);
        self.git_lines.insert(staged_buffer, staged_panel.lines);
        self.git_lines.insert(unstaged_buffer, unstaged_panel.lines);
        self.git_lines.insert(branches_buffer, branches_panel.lines);
        self.git_lines.insert(commits_buffer, commits_panel.lines);
        self.git_lines.insert(stash_buffer, stash_panel.lines);
        self.diff_lines.insert(main_buffer, main_view.lines);

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(status_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let status_pane = self.focused_pane_id();

        // Right column first, at the outer split -- same ~35/65 left/
        // right proportions `open_docker_panel` uses for its own Status/
        // Logs vs. Containers/Images/Volumes split, and for the same
        // reason: list rows don't need much width, a diff view does.
        let main_pane = self.windows_mut().split(SplitKind::Vertical, main_buffer);
        self.workspaces.active_pane_states_mut().insert(main_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-0.15);

        // Left column: Status/Staged/Unstaged/Branches/Commits/Stash
        // stacked. Status is shrunk well below the default 50/50 split
        // (it's a handful of fixed overview lines, not a list);
        // everything after that cascades naturally the same way
        // Containers/Images/Volumes already do for the Docker panel --
        // Staged (split off Status) keeps the biggest remaining share
        // "for free," and each further split below it takes half of
        // whatever's left, without needing its own explicit resize.
        self.windows_mut().focus(status_pane);
        let staged_pane = self.windows_mut().split(SplitKind::Horizontal, staged_buffer);
        self.workspaces.active_pane_states_mut().insert(staged_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-0.35);
        let unstaged_pane = self.windows_mut().split(SplitKind::Horizontal, unstaged_buffer);
        self.workspaces.active_pane_states_mut().insert(unstaged_pane, PaneState::seeded_at(cursor));
        let branches_pane = self.windows_mut().split(SplitKind::Horizontal, branches_buffer);
        self.workspaces.active_pane_states_mut().insert(branches_pane, PaneState::seeded_at(cursor));
        let commits_pane = self.windows_mut().split(SplitKind::Horizontal, commits_buffer);
        self.workspaces.active_pane_states_mut().insert(commits_pane, PaneState::seeded_at(cursor));
        let stash_pane = self.windows_mut().split(SplitKind::Horizontal, stash_buffer);
        self.workspaces.active_pane_states_mut().insert(stash_pane, PaneState::seeded_at(cursor));
        self.windows_mut().focus(staged_pane);

        self.pane_titles.insert(status_pane, "1. Status".to_string());
        self.pane_titles.insert(staged_pane, "2. Staged".to_string());
        self.pane_titles.insert(unstaged_pane, "3. Unstaged".to_string());
        self.pane_titles.insert(branches_pane, "4. Branches".to_string());
        self.pane_titles.insert(commits_pane, "5. Commits".to_string());
        self.pane_titles.insert(stash_pane, "6. Stash".to_string());
        self.pane_titles.insert(main_pane, "7. Main".to_string());

        // Same "only a real, main.rs-launched App spawns anything" posture
        // as `open_docker_panel`'s own stats poller.
        let status_poller = self
            .event_proxy
            .clone()
            .map(|proxy| GitStatusPoller::spawn(repo_root.clone(), move |event| proxy.send_event(event).is_ok()));

        self.git_session = Some(GitSession {
            workspace_index,
            status_pane,
            staged_pane,
            unstaged_pane,
            branches_pane,
            commits_pane,
            stash_pane,
            main_pane,
            status_buffer,
            staged_buffer,
            unstaged_buffer,
            branches_buffer,
            commits_buffer,
            stash_buffer,
            main_buffer,
            repo_root,
            files,
            branches,
            commits,
            stashes,
            status,
            in_progress,
            sides,
            status_poller,
            staged_expanded_dirs: HashSet::new(),
            unstaged_expanded_dirs: HashSet::new(),
            last_main_entry: None,
            last_main_fetch: MainFetch::Skip,
            main_request_id: 0,
            refresh_request_id: 0,
        });

        self.refresh_project_root();
        self.wake_caret();
    }

    /// Rewrites `id`'s buffer text from a freshly-rendered `GitPanel`,
    /// resetting every pane currently showing it back to the top --
    /// mirrors `set_docker_buffer` exactly.
    /// Parses `diff` and renders it into `id` (a `BufferKind::Diff`
    /// buffer), caching both the per-line metadata and the parsed model
    /// so hunk actions can resolve the cursor's row back to a real hunk
    /// without re-shelling `git`. `None`/empty renders the view's own
    /// "(no changes)" placeholder rather than leaving stale content
    /// behind.
    ///
    /// Any fold state for files still present is carried across, so a
    /// refresh (or a hunk being staged out from under the view) doesn't
    /// silently unfold everything the user had collapsed -- same
    /// reasoning as `GitSession::staged_expanded_dirs` persisting across
    /// `git_refresh_session`.
    fn set_diff_buffer(&mut self, id: BufferId, diff: Option<&str>, source: DiffSource, repo_root: &Path) {
        self.set_diff_buffer_with_header(id, &[], diff, source, repo_root);
    }

    /// `set_diff_buffer`, with rows above the diff -- a commit's author,
    /// date and message, which `git show`'s own output carries but a
    /// diff parser has no reason to keep (see `diff_view::
    /// render_with_header`).
    fn set_diff_buffer_with_header(
        &mut self,
        id: BufferId,
        header: &[(String, diff_view::DiffStyle)],
        diff: Option<&str>,
        source: DiffSource,
        repo_root: &Path,
    ) {
        let files = diff.map(fenix_diff::parse).unwrap_or_default();
        // A read-only diff -- a commit, a stash, a comparison -- opens
        // with its files folded, so a change touching a dozen files
        // reads as a scannable list of what it touched rather than a
        // wall of hunks; `Tab` opens the one under the cursor. A
        // single-file diff has no list worth showing, so it stays open.
        // A working-tree diff also stays open: there you're staging
        // hunks, not surveying.
        let collapsed = if source == DiffSource::ReadOnly && files.len() > 1 {
            files.iter().map(|f| f.display_path().to_string()).collect()
        } else {
            self.diff_models.get(&id).map(|m| m.collapsed.clone()).unwrap_or_default()
        };
        let threads = self.diff_models.get(&id).map(|m| m.threads.clone()).unwrap_or_default();
        let view = diff_view::render_with_threads(header, &files, &collapsed, &threads);
        self.diff_lines.insert(id, view.lines);
        self.diff_models.insert(
            id,
            DiffModel {
                repo_root: repo_root.to_path_buf(), files, collapsed, source, header: header.to_vec(), threads },
        );
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &view.text);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    /// Fills a diff buffer with a message instead of a diff -- what a
    /// failed comparison shows. Deliberately *not* `set_diff_buffer`
    /// with an empty diff: that renders "(no changes)", which claims
    /// the two sides are identical rather than admitting the question
    /// couldn't be answered.
    ///
    /// The model is left empty, so every hunk action correctly declines
    /// on these rows.
    fn set_diff_buffer_message(&mut self, id: BufferId, rows: &[(String, diff_view::DiffStyle)], repo_root: &Path) {
        let mut text = String::new();
        let mut lines = Vec::new();
        for (row, style) in rows {
            text.push_str(row);
            text.push('\n');
            lines.push(Some(diff_view::DiffViewLine { style: *style, content_from: 0, anchor: None, thread: None }));
        }
        self.diff_lines.insert(id, lines);
        self.diff_models.insert(
            id,
            DiffModel {
                repo_root: repo_root.to_path_buf(),
                files: Vec::new(),
                collapsed: HashSet::new(),
                source: DiffSource::ReadOnly,
                header: Vec::new(),
                threads: Vec::new(),
            },
        );
        self.replace_buffer_text(id, &text);
    }

    /// Re-renders a diff buffer from its already-parsed model, keeping
    /// every pane's cursor on the same line index -- for fold toggles,
    /// where the content above the cursor is unchanged and resetting to
    /// the top would lose the user's place. Mirrors `set_git_buffer_
    /// preserving_line`'s own reasoning for the Files tree.
    fn rerender_diff_buffer(&mut self, id: BufferId) {
        let Some(model) = self.diff_models.get(&id) else { return };
        let view = diff_view::render_with_threads(&model.header, &model.files, &model.collapsed, &model.threads);
        self.diff_lines.insert(id, view.lines);

        let mut old_lines: Vec<(fenix_window::WindowId, usize)> = Vec::new();
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state(pane);
                if let Some(ob) = self.buffers.get(id) {
                    old_lines.push((pane, ob.buffer.line_col(&ps.cursor).0));
                }
            }
        }
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &view.text);
        }
        let line_count = self.buffers.get(id).map(|ob| ob.buffer.visual_line_count()).unwrap_or(1);
        for (pane, old_line) in old_lines {
            let line = old_line.min(line_count.saturating_sub(1));
            let Some(ob) = self.buffers.get(id) else { continue };
            let char_idx = ob.buffer.line_start_char(line);
            self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
        }
    }

    /// The diff buffer the focused pane is showing, if it is one.
    fn focused_diff_buffer(&self) -> Option<BufferId> {
        let id = self.focused_buffer_id();
        self.diff_models.contains_key(&id).then_some(id)
    }

    /// What the cursor's current row in a diff buffer points at -- the
    /// one lookup every hunk-level action goes through. `None` when the
    /// focused pane isn't a diff, or the row carries no anchor (a
    /// placeholder row).
    fn diff_anchor_at_cursor(&self) -> Option<(BufferId, diff_view::DiffAnchor)> {
        let id = self.focused_diff_buffer()?;
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let anchor = self.diff_lines.get(&id)?.get(line)?.as_ref()?.anchor?;
        Some((id, anchor))
    }

    /// The patch for the one hunk `anchor` names, rebuilt from the same
    /// cached parse the user is looking at. `None` if the anchor points
    /// at a file header rather than a hunk, or if the buffer/file/hunk
    /// is gone because a refresh landed in between -- both of which mean
    /// "don't apply anything," never "apply something else."
    fn hunk_patch_for(&self, buffer: BufferId, anchor: diff_view::DiffAnchor) -> Option<String> {
        let model = self.diff_models.get(&buffer)?;
        let file = model.files.get(anchor.file)?;
        let hunk = file.hunks.get(anchor.hunk?)?;
        Some(fenix_diff::hunk_patch(file, hunk))
    }

    /// `s`/`S`/`d` on a diff row: stages, unstages, or discards the hunk
    /// the cursor is inside. Rebuilds that hunk's patch from the same
    /// parse the user is looking at (`fenix_diff::hunk_patch`) and pipes
    /// it through `git apply` -- see `fenix_git::apply_patch`.
    ///
    /// `target` has to agree with which diff this is: an unstaged hunk
    /// can be staged or discarded, a staged one can only be unstaged.
    /// Asking for the wrong one is a message, not a no-op, since from
    /// the user's side "s did nothing" is indistinguishable from a bug.
    fn diff_apply_hunk(&mut self, target: fenix_git::ApplyTarget) {
        let Some((buffer, anchor)) = self.diff_anchor_at_cursor() else {
            self.set_error("no diff hunk under the cursor".to_string());
            return;
        };
        if anchor.hunk.is_none() {
            self.set_error("put the cursor inside a hunk, not on the file header".to_string());
            return;
        }
        let Some(model) = self.diff_models.get(&buffer) else { return };
        // A conflicted file's diff is a *combined* one, comparing the
        // working tree against both sides at once. There's no combined
        // patch format to feed back to `git apply`, so a hunk from one
        // can't be staged at all -- resolving the conflict is what
        // stages it.
        if model.files.get(anchor.file).is_some_and(|f| f.is_combined) {
            self.set_error("this file is conflicted -- resolve it (SPC g o/t/b) rather than staging a hunk".to_string());
            return;
        }
        let allowed = match (model.source, target) {
            (DiffSource::Unstaged, fenix_git::ApplyTarget::Stage | fenix_git::ApplyTarget::Discard) => true,
            (DiffSource::Staged, fenix_git::ApplyTarget::Unstage) => true,
            _ => false,
        };
        if !allowed {
            let why = match model.source {
                DiffSource::Unstaged => "this hunk isn't staged yet -- `s` stages it, `d` discards it",
                DiffSource::Staged => "this hunk is staged -- `S` unstages it",
                DiffSource::ReadOnly => "this diff isn't editable (a commit, a stash, or a comparison)",
            };
            self.set_error(why.to_string());
            return;
        }
        let repo_root = model.repo_root.clone();
        let Some(patch) = self.hunk_patch_for(buffer, anchor) else {
            self.set_error("that hunk is no longer in the diff -- refresh with `u`".to_string());
            return;
        };

        match fenix_git::apply_patch(&repo_root, &patch, target) {
            Ok(_) => {
                let what = match target {
                    fenix_git::ApplyTarget::Stage => "staged",
                    fenix_git::ApplyTarget::Unstage => "unstaged",
                    fenix_git::ApplyTarget::Discard => "discarded",
                };
                self.set_message(format!("hunk {what}"));
                self.git_refresh_session();
            }
            // git's own "error: patch does not apply" is far more
            // useful than anything this could paraphrase.
            Err(err) => self.set_error(err.trim().to_string()),
        }
    }

    /// `d` on a diff row: asks to discard the hunk under the cursor.
    ///
    /// Discarding is gated behind the panel's confirm-then-act step, but
    /// only a working-tree diff can be discarded at all -- a commit or a
    /// comparison says so rather than arming a confirmation that would
    /// then decline, which would make `y` look broken.
    fn diff_discard_request(&mut self) {
        if self.focused_diff_is_read_only() {
            self.set_error("this diff isn't editable (a commit, a stash, or a comparison)".to_string());
        } else {
            self.git_arm_confirm();
        }
    }

    /// `Tab` on a diff row: folds the file the cursor is in down to its
    /// header row, or unfolds it again.
    fn diff_toggle_fold(&mut self) {
        let Some((buffer, anchor)) = self.diff_anchor_at_cursor() else { return };
        let Some(model) = self.diff_models.get_mut(&buffer) else { return };
        let Some(path) = model.files.get(anchor.file).map(|f| f.display_path().to_string()) else { return };
        if !model.collapsed.remove(&path) {
            model.collapsed.insert(path);
        }
        self.rerender_diff_buffer(buffer);
        self.wake_caret();
    }

    /// `]c`/`[c` on a diff: moves the cursor to the next/previous hunk
    /// header, the same motion pair Vim's own diff mode uses for exactly
    /// this. Stops at the ends rather than wrapping -- a wrap would make
    /// "am I at the last change" impossible to feel.
    fn diff_jump_hunk(&mut self, forward: bool) {
        let Some(buffer) = self.focused_diff_buffer() else { return };
        let Some(lines) = self.diff_lines.get(&buffer) else { return };
        let current = self.open().buffer.line_col(&self.cursor()).0;
        let is_hunk = |i: usize| lines.get(i).and_then(|l| l.as_ref()).is_some_and(|l| l.style == diff_view::DiffStyle::HunkHeader);
        let target = if forward {
            (current + 1..lines.len()).find(|&i| is_hunk(i))
        } else {
            (0..current).rev().find(|&i| is_hunk(i))
        };
        let Some(target) = target else {
            self.set_message(if forward { "no next hunk" } else { "no previous hunk" });
            return;
        };
        let char_idx = self.open().buffer.line_start_char(target);
        let pane = self.focused_pane_id();
        self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
        self.wake_caret();
    }

    /// `Enter` on a diff row: opens the real file at the line under the
    /// cursor. Prefers the new-side line number (where the change landed
    /// in the file as it is now); a removed line has only an old-side
    /// number, which still lands in the right neighbourhood, which is
    /// what someone reading a diff actually wants.
    fn diff_open_file_at_cursor(&mut self) {
        let Some((buffer, anchor)) = self.diff_anchor_at_cursor() else { return };
        let Some(model) = self.diff_models.get(&buffer) else { return };
        let Some(file) = model.files.get(anchor.file) else { return };
        let path = model.repo_root.join(file.display_path());
        if !path.is_file() {
            self.set_error(format!("{} isn't a file on disk", file.display_path()));
            return;
        }
        let line = anchor.new_line.or(anchor.old_line).unwrap_or(1);
        self.open_file_from_picker(&path);
        self.jump_to_grep_match(&fenix_project::GrepMatch { path, line, col: 1, text: String::new() });
    }

    fn set_git_buffer(&mut self, id: BufferId, panel: git_panel::GitPanel) {
        self.git_lines.insert(id, panel.lines);
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &panel.text);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    /// Like `set_git_buffer` but keeps every pane's cursor on the same
    /// *line index* instead of resetting to the top. Right for `Tab`'s
    /// directory expand/collapse specifically: inserting or removing a
    /// directory's children only ever changes lines *below* the row the
    /// cursor is already sitting on (the toggled directory itself), so
    /// "same line index" lands back on that exact row every time. Not
    /// used for `git_refresh_session`'s own re-renders, which
    /// intentionally reset to the top like every other refresh in this
    /// session -- a real repo-status refresh can reorder or remove rows
    /// anywhere in the list, where this shortcut wouldn't hold.
    fn set_git_buffer_preserving_line(&mut self, id: BufferId, panel: git_panel::GitPanel) {
        self.git_lines.insert(id, panel.lines);
        let mut old_lines: Vec<(fenix_window::WindowId, usize)> = Vec::new();
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state(pane);
                if let Some(ob) = self.buffers.get(id) {
                    let (line, _) = ob.buffer.line_col(&ps.cursor);
                    old_lines.push((pane, line));
                }
            }
        }
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &panel.text);
        }
        let new_line_count = self.buffers.get(id).map(|ob| ob.buffer.visual_line_count()).unwrap_or(1);
        for (pane, old_line) in old_lines {
            let clamped = old_line.min(new_line_count.saturating_sub(1));
            let Some(ob) = self.buffers.get(id) else { continue };
            let char_idx = ob.buffer.line_start_char(clamped);
            self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
        }
    }

    /// `Tab` on Staged or Unstaged: toggles whether the directory under
    /// the cursor is expanded *in that pane's own tree*, then re-renders
    /// just that pane keeping the cursor on the same row (see `set_git_
    /// buffer_preserving_line`). A no-op on a file row, or anywhere but
    /// those two panes -- only directories are expandable, and each
    /// pane's expand state is independent (`GitSession::staged_expanded_
    /// dirs`'s own doc comment explains why).
    fn git_toggle_dir_expand(&mut self) {
        let Some(git_panel::GitEntry::Dir(path)) = self.git_entry_at_cursor() else { return };
        let Some(role) = self.git_focused_role() else { return };
        let Some(session) = self.git_session.as_mut() else { return };
        let (buffer, panel) = match role {
            GitPaneRole::Staged => {
                if !session.staged_expanded_dirs.remove(&path) {
                    session.staged_expanded_dirs.insert(path);
                }
                (session.staged_buffer, git_panel::render_staged(&session.files, &session.staged_expanded_dirs))
            }
            GitPaneRole::Unstaged => {
                if !session.unstaged_expanded_dirs.remove(&path) {
                    session.unstaged_expanded_dirs.insert(path);
                }
                (session.unstaged_buffer, git_panel::render_unstaged(&session.files, &session.unstaged_expanded_dirs))
            }
            _ => return,
        };
        self.set_git_buffer_preserving_line(buffer, panel);
    }

    /// `FenixUserEvent::GitStatusReady` handling: caches the fresh status
    /// and re-renders the Status pane -- mirrors `apply_docker_stats`,
    /// including its "reset to top is harmless, Status is a small read-
    /// only info pane" reasoning.
    fn apply_git_status(&mut self, status: Option<fenix_git::RepoStatus>) {
        let Some(session) = self.git_session.as_mut() else { return };
        session.status = status.clone();
        let (staged, unstaged, untracked) = file_counts(&session.files);
        let (status_buffer, conflicts) = (session.status_buffer, conflict_count(&session.files));
        let in_progress = session.in_progress.clone();
        let sides = session.sides.clone();
        self.set_git_buffer(
            status_buffer,
            git_panel::render_status(status.as_ref(), staged, unstaged, untracked, in_progress.as_ref(), conflicts, sides.as_ref()),
        );
    }

    /// `u` (on any pane), and after every mutating action (stage/unstage/
    /// commit/checkout/stash/...): re-lists files/branches/commits/
    /// stashes and the repo status. Same two-part async treatment as
    /// `git_sync_main` (its own doc comment explains the "why" in full):
    /// the four `git` calls this needs (`status_and_files`, `list_
    /// branches`, `list_commits`, `list_stashes`) used to run
    /// synchronously on the input thread, blocking the UI for every
    /// single one of those actions, not just `u`. Now they run on a
    /// background thread for a real app (`apply_git_refresh` applies the
    /// result when it lands, guarded by `refresh_request_id` against a
    /// slow request a faster later one already superseded), or inline
    /// when there's no `event_proxy` (every test) so existing tests
    /// asserting on pane content right after calling this keep working
    /// unchanged.
    fn git_refresh_session(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();

        let Some(session) = self.git_session.as_mut() else { return };
        session.refresh_request_id += 1;
        let request_id = session.refresh_request_id;

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let data = fetch_git_refresh_data(&repo_root);
                    let _ = proxy.send_event(FenixUserEvent::GitRefreshReady { request_id, data });
                });
            }
            None => {
                let data = fetch_git_refresh_data(&repo_root);
                self.apply_git_refresh(request_id, data);
            }
        }
    }

    /// `FenixUserEvent::GitRefreshReady` handling: applies a completed
    /// background session refresh (re-renders all six list/status panes,
    /// resets `last_main_entry` and re-syncs Main -- a manual refresh
    /// means the underlying content may have changed even when the
    /// selected path/hash/index hasn't, see `GitSession::last_main_
    /// entry`'s own doc comment), unless a newer refresh has since
    /// superseded it (`request_id` mismatch) or the session's since
    /// closed.
    fn apply_git_refresh(&mut self, request_id: u64, data: GitRefreshData) {
        let Some(session) = self.git_session.as_ref() else { return };
        if session.refresh_request_id != request_id {
            return;
        }
        let (status_buffer, staged_buffer, unstaged_buffer, branches_buffer, commits_buffer, stash_buffer) = (
            session.status_buffer,
            session.staged_buffer,
            session.unstaged_buffer,
            session.branches_buffer,
            session.commits_buffer,
            session.stash_buffer,
        );
        let (staged_expanded, unstaged_expanded) = (session.staged_expanded_dirs.clone(), session.unstaged_expanded_dirs.clone());

        let (staged, unstaged, untracked) = file_counts(&data.files);
        let status_panel = git_panel::render_status(
            data.status.as_ref(),
            staged,
            unstaged,
            untracked,
            data.in_progress.as_ref(),
            conflict_count(&data.files),
            data.sides.as_ref(),
        );
        let staged_panel = git_panel::render_staged(&data.files, &staged_expanded);
        let unstaged_panel = git_panel::render_unstaged(&data.files, &unstaged_expanded);
        let branches_panel = git_panel::render_branches(&data.branches);
        let commits_panel = git_panel::render_commits(&data.commits);
        let stash_panel = git_panel::render_stash(&data.stashes);

        let Some(session) = self.git_session.as_mut() else { return };
        session.status = data.status;
        session.files = data.files;
        session.branches = data.branches;
        session.commits = data.commits;
        session.stashes = data.stashes;
        session.in_progress = data.in_progress;
        session.sides = data.sides;
        session.last_main_entry = None;

        self.set_git_buffer(status_buffer, status_panel);
        self.set_git_buffer(staged_buffer, staged_panel);
        self.set_git_buffer(unstaged_buffer, unstaged_panel);
        self.set_git_buffer(branches_buffer, branches_panel);
        self.set_git_buffer(commits_buffer, commits_panel);
        self.set_git_buffer(stash_buffer, stash_panel);
        self.git_sync_main();
    }

    /// Which of the current `git_session`'s seven panes (if any) is
    /// focused right now -- mirrors `docker_focused_role`, including the
    /// same active-workspace guard (see its own doc comment for why
    /// that's needed: `WindowId`s are only unique within one workspace).
    fn git_focused_role(&self) -> Option<GitPaneRole> {
        let session = self.git_session.as_ref()?;
        if self.workspaces.active_index() != session.workspace_index {
            return None;
        }
        let focused = self.focused_pane_id();
        if focused == session.status_pane {
            Some(GitPaneRole::Status)
        } else if focused == session.staged_pane {
            Some(GitPaneRole::Staged)
        } else if focused == session.unstaged_pane {
            Some(GitPaneRole::Unstaged)
        } else if focused == session.branches_pane {
            Some(GitPaneRole::Branches)
        } else if focused == session.commits_pane {
            Some(GitPaneRole::Commits)
        } else if focused == session.stash_pane {
            Some(GitPaneRole::Stash)
        } else if focused == session.main_pane {
            Some(GitPaneRole::Main)
        } else {
            None
        }
    }

    /// The pane whose title bar is numbered `n` (`1. Status` etc., see
    /// `open_git_panel`'s own title strings) -- mirrors `docker_pane_by_
    /// number`, backs the same digit-key jump-to-pane shortcut.
    fn git_pane_by_number(&self, n: u32) -> Option<fenix_window::WindowId> {
        let session = self.git_session.as_ref()?;
        match n {
            1 => Some(session.status_pane),
            2 => Some(session.staged_pane),
            3 => Some(session.unstaged_pane),
            4 => Some(session.branches_pane),
            5 => Some(session.commits_pane),
            6 => Some(session.stash_pane),
            7 => Some(session.main_pane),
            _ => None,
        }
    }

    /// What the cursor's current line on a Git buffer targets -- mirrors
    /// `docker_entry_at_cursor`.
    fn git_entry_at_cursor(&self) -> Option<git_panel::GitEntry> {
        let cursor = self.cursor();
        let line = self.open().buffer.line_col(&cursor).0;
        self.git_lines.get(&self.focused_buffer_id()).and_then(|lines| lines.get(line)).and_then(|meta| meta.as_ref()).and_then(|meta| meta.entry.clone())
    }

    /// The selected row's full `FileEntry` (not just its path), looked
    /// up in the session's own cached `files` -- needed by discard (to
    /// know whether it's untracked) and by `git_sync_main` (to know
    /// whether it's staged).
    fn git_selected_file(&self) -> Option<fenix_git::FileEntry> {
        let git_panel::GitEntry::File(path) = self.git_entry_at_cursor()? else { return None };
        self.git_session.as_ref()?.files.iter().find(|f| f.path == path).cloned()
    }

    /// Re-renders Main from whichever row is now under the cursor in
    /// Staged/Unstaged/Commits/Stash -- a no-op for Branches/Status/Main
    /// itself (see `git_panel::render_status`'s own doc comment for why
    /// Branches doesn't drive Main the way the others do: a branch has
    /// no single "diff" of its own to show; a directory row aggregates
    /// an unknown mix of files, same reasoning).
    ///
    /// Two performance properties, both load-bearing for why this no
    /// longer visibly stutters the UI on every keystroke (it used to
    /// shell a real `git diff`/`show` synchronously on the input thread
    /// after *every* key handled while focus was on one of those panes,
    /// not just navigation -- see `GitSession::last_main_entry`'s and
    /// `main_request_id`'s own doc comments for the two-part fix):
    /// - Returns immediately, no work at all, when the cursor's entry
    ///   hasn't actually changed since the last sync.
    /// - The real `git` shell-out (when one's actually needed) runs on a
    ///   background thread for a real app (`self.event_proxy.is_some()`)
    ///   -- `apply_git_main` applies the result when it lands. Falls
    ///   back to a synchronous fetch when there's no event proxy (every
    ///   test, per `App::new`'s own doc comment -- same "only a real app
    ///   spawns anything" posture `DockerStatsPoller`/`GitStatusPoller`
    ///   already have), so existing tests asserting on Main's content
    ///   directly keep working with no mocking needed.
    fn git_sync_main(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let entry = self.git_entry_at_cursor();
        if entry == session.last_main_entry {
            return;
        }

        let fetch = match &entry {
            Some(git_panel::GitEntry::File(path)) => match session.files.iter().find(|f| &f.path == path) {
                Some(f) if f.index_status == '?' && f.worktree_status == '?' => MainFetch::Untracked,
                Some(f) => MainFetch::File { path: path.clone(), staged: f.index_status != '.' && f.index_status != '?' },
                None => MainFetch::Skip,
            },
            Some(git_panel::GitEntry::Commit(hash)) => MainFetch::Commit(hash.clone()),
            Some(git_panel::GitEntry::Stash(index)) => MainFetch::Stash(*index),
            Some(git_panel::GitEntry::Branch(_)) | Some(git_panel::GitEntry::Dir(_)) | None => MainFetch::Skip,
        };
        let repo_root = session.repo_root.clone();
        let main_buffer = session.main_buffer;

        let Some(session) = self.git_session.as_mut() else { return };
        session.last_main_entry = entry;
        session.last_main_fetch = fetch.clone();

        if let MainFetch::Skip = fetch {
            return;
        }
        if let MainFetch::Untracked = fetch {
            self.set_diff_buffer(main_buffer, None, DiffSource::ReadOnly, &repo_root);
            return;
        }

        session.main_request_id += 1;
        let request_id = session.main_request_id;

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let diff = fetch_main_diff(&repo_root, &fetch);
                    let _ = proxy.send_event(FenixUserEvent::GitMainReady { request_id, buffer: main_buffer, diff });
                });
            }
            None => {
                let source = DiffSource::of(&fetch);
                let diff = fetch_main_diff(&repo_root, &fetch);
                self.set_diff_buffer(main_buffer, diff.as_deref(), source, &repo_root);
            }
        }
    }

    /// `FenixUserEvent::GitMainReady` handling: applies a completed
    /// background diff fetch, unless a newer request has since
    /// superseded it (`request_id` mismatch -- see `GitSession::main_
    /// request_id`'s own doc comment) or the session's since closed.
    fn apply_git_main(&mut self, request_id: u64, buffer: BufferId, diff: Option<String>) {
        let Some(session) = self.git_session.as_ref() else { return };
        if session.main_request_id != request_id {
            return;
        }
        let (source, repo_root) = (DiffSource::of(&session.last_main_fetch), session.repo_root.clone());
        self.set_diff_buffer(buffer, diff.as_deref(), source, &repo_root);
    }

    /// `s` on Files: stages the file under the cursor.
    fn git_stage_selected(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        // `git add`/`git restore` are directory-transparent -- staging
        // a `Dir` path stages every changed file underneath it in one
        // call, same primitive as a single `File`, no separate function
        // needed.
        let path = match self.git_entry_at_cursor() {
            Some(git_panel::GitEntry::File(path)) | Some(git_panel::GitEntry::Dir(path)) => path,
            _ => return,
        };
        if let Err(err) = fenix_git::stage_file(&repo_root, &path) {
            self.set_error(format!("git stage failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `S` on Files: unstages the file (or every file under the
    /// directory) under the cursor.
    fn git_unstage_selected(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        let path = match self.git_entry_at_cursor() {
            Some(git_panel::GitEntry::File(path)) | Some(git_panel::GitEntry::Dir(path)) => path,
            _ => return,
        };
        if let Err(err) = fenix_git::unstage_file(&repo_root, &path) {
            self.set_error(format!("git unstage failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `a` on Files: stages every changed file.
    fn git_stage_all(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Err(err) = fenix_git::stage_all(&repo_root) {
            self.set_error(format!("git stage all failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `A` on Files: unstages every staged file.
    fn git_unstage_all(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Err(err) = fenix_git::unstage_all(&repo_root) {
            self.set_error(format!("git unstage all failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `z` on Files: stashes every change (tracked + untracked staged/
    /// unstaged), git's own default `stash push` behavior.
    fn git_stash_all(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Err(err) = fenix_git::stash_push(&repo_root) {
            self.set_error(format!("git stash failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `P` on Files: pushes the current branch.
    fn git_push(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Err(err) = fenix_git::push(&repo_root) {
            self.set_error(format!("git push failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `p` on Files: pulls into the current branch.
    fn git_pull(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Err(err) = fenix_git::pull(&repo_root) {
            self.set_error(format!("git pull failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `c` on Branches: checks out the branch under the cursor.
    fn git_checkout_selected_branch(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Some(git_panel::GitEntry::Branch(name)) = self.git_entry_at_cursor() {
            if let Err(err) = fenix_git::checkout_branch(&repo_root, &name) {
                self.set_error(format!("git checkout failed: {err}"));
            }
            self.git_refresh_session();
        }
    }

    /// `a` on Stash: applies the entry under the cursor (keeps it in the
    /// stash list -- see `g` for apply-and-drop).
    fn git_stash_apply_selected(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Some(git_panel::GitEntry::Stash(index)) = self.git_entry_at_cursor() {
            if let Err(err) = fenix_git::stash_apply(&repo_root, index) {
                self.set_error(format!("git stash apply failed: {err}"));
            }
            self.git_refresh_session();
        }
    }

    /// `g` on Stash: applies the entry under the cursor and removes it
    /// from the stash list in one step.
    fn git_stash_pop_selected(&mut self) {
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        if let Some(git_panel::GitEntry::Stash(index)) = self.git_entry_at_cursor() {
            if let Err(err) = fenix_git::stash_pop(&repo_root, index) {
                self.set_error(format!("git stash pop failed: {err}"));
            }
            self.git_refresh_session();
        }
    }

    /// `c` on Files: opens a compose buffer for the commit message.
    ///
    /// A buffer rather than the single-line prompt every other Git
    /// action here uses, because a commit message is the one piece of
    /// text in this panel that is routinely more than one line -- a
    /// subject, a blank line and a body is the convention, and a prompt
    /// can express none of it.
    fn git_commit_prompt(&mut self) {
        let repo_root = self.git_action_repo_root();
        if fenix_git::list_files(&repo_root).iter().all(|f| f.index_status == '.' || f.index_status == '?') {
            // `git commit` would refuse anyway, but it refuses *after*
            // the message has been written, which is the wrong moment
            // to find out.
            self.set_error("nothing staged to commit".to_string());
            return;
        }
        self.open_compose(ComposePurpose::CommitMessage { repo_root });
    }

    /// `n` on Branches: arms the new-branch-name prompt.
    fn git_new_branch_prompt(&mut self) {
        self.git_prompt = Some(GitPrompt { kind: GitPromptKind::NewBranch, input: String::new() });
    }

    /// `d` on Files/Branches/Stash: arms the matching destructive-action
    /// confirmation for whatever's under the cursor.
    fn git_arm_confirm(&mut self) {
        // In the diff pane the cursor sits on a diff row, not a
        // `GitEntry` row -- `d` there means "discard this hunk".
        if let Some((buffer, anchor)) = self.diff_anchor_at_cursor() {
            if anchor.hunk.is_some() {
                self.git_confirm = Some(GitConfirmAction::DiscardHunk { buffer, anchor });
            } else {
                self.set_error("put the cursor inside a hunk to discard it".to_string());
            }
            return;
        }
        let Some(entry) = self.git_entry_at_cursor() else { return };
        let action = match entry {
            git_panel::GitEntry::File(path) => {
                let untracked = self.git_selected_file().is_some_and(|f| f.index_status == '?' && f.worktree_status == '?');
                GitConfirmAction::DiscardFile { path, untracked }
            }
            git_panel::GitEntry::Dir(path) => GitConfirmAction::DiscardDir { path },
            git_panel::GitEntry::Branch(name) => GitConfirmAction::DeleteBranch { name },
            git_panel::GitEntry::Stash(index) => GitConfirmAction::DropStash { index },
            git_panel::GitEntry::Commit(_) => return,
        };
        self.git_confirm = Some(action);
    }

    // -- Rebase, merge and the operations that suspend -----------------

    /// The repo any Git action should target: whichever Git-ish view is
    /// open, else the focused buffer's project.
    fn git_action_repo_root(&self) -> PathBuf {
        self.git_session
            .as_ref()
            .map(|s| s.repo_root.clone())
            .or_else(|| self.history_session.as_ref().map(|s| s.repo_root.clone()))
            .or_else(|| self.compare_session.as_ref().map(|s| s.repo_root.clone()))
            .or_else(|| self.project_root.clone())
            .unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")))
    }

    /// Runs one git operation and reports what happened.
    ///
    /// A conflict is *not* a failure to recover from: `rebase`/`merge`/
    /// `cherry-pick` all exit non-zero when they stop for one, having
    /// done exactly what they were asked. So a non-zero exit that leaves
    /// an operation in progress reads as "stopped, here's what to do",
    /// while one that doesn't is a real error.
    fn run_git_operation(&mut self, what: &str, result: Result<String, String>) {
        let repo_root = self.git_action_repo_root();
        match result {
            Ok(_) => self.set_message(format!("{what} finished")),
            Err(err) => match fenix_git::in_progress(&repo_root) {
                Some(op) => self.set_error(format!("{} -- resolve the conflicts, then SPC g R to continue", op.label())),
                None => self.set_error(format!("{what} failed: {}", err.trim().lines().next().unwrap_or("").trim())),
            },
        }
        self.git_refresh_all_views();
    }

    /// Re-reads every open file whose contents changed on disk.
    ///
    /// A rebase, merge, checkout or discard rewrites working-tree files
    /// underneath whatever is already open. Without this, a buffer keeps
    /// showing what the file said before the operation -- and during a
    /// conflicted rebase that's actively dangerous, because saving that
    /// stale buffer writes the *pre-rebase* content back over git's
    /// conflict markers and silently destroys the merge state.
    ///
    /// A buffer with unsaved edits is never touched: those changes are
    /// the user's, and reloading would throw them away. They're counted
    /// and reported instead, so a file that didn't refresh says so
    /// rather than quietly lying about what's on disk.
    fn reload_buffers_changed_on_disk(&mut self) -> DiskSweep {
        // Buffers close from a dozen places; pruning here rather than
        // hooking every one of them keeps the bookkeeping in the one
        // place that already walks the list, and is self-healing if a
        // new close path is added later.
        self.disk_state.retain(|id, _| self.buffers.get(*id).is_some());
        self.externally_changed.retain(|id| self.buffers.get(*id).is_some());

        let mut sweep = DiskSweep::default();
        for id in self.buffers.ids_sorted_by_path() {
            self.check_one_file(id, &mut sweep, true);
        }
        sweep
    }

    /// One buffer's file, checked and acted on. The whole sweep in
    /// miniature, split out so the save guard can re-check exactly one
    /// file without walking every open buffer.
    /// `trust_fingerprint` skips the read when mtime and length are
    /// unchanged. The periodic sweep sets it, because it runs on every
    /// open file every couple of seconds and a stat is far cheaper than
    /// a read. The save guard clears it, because the fingerprint can
    /// miss a same-length edit made inside the filesystem's timestamp
    /// granularity -- rare, but a write is the one moment where being
    /// approximately right means losing somebody's work.
    fn check_one_file(&mut self, id: BufferId, sweep: &mut DiskSweep, trust_fingerprint: bool) {
        let Some(ob) = self.buffers.get(id) else { return };
        // Generated panels (Git, Docker, diffs, the graph) have no file
        // behind them, and the host rewrites their contents constantly.
        if !ob.kind.tracks_unsaved_changes() {
            return;
        }
        let Some(path) = ob.buffer.path().map(Path::to_path_buf) else { return };
        let name = self.buffer_display_name(id);

        let fingerprint = DiskFingerprint::of(&path);
        let Some(fingerprint) = fingerprint else {
            // Gone, or no longer a regular file. Never reloaded to
            // empty: an editor that blanks your buffer because
            // something deleted the file for a moment -- which is
            // exactly what a "safe write" in another editor looks like
            // -- is worse than one that says nothing happened.
            if self.disk_state.remove(&id).is_some() {
                self.externally_changed.insert(id);
                sweep.vanished.push(name);
            }
            return;
        };
        // The fast path: nothing about the file has moved since we last
        // looked, so there is nothing to read.
        let previously_seen = self.disk_state.get(&id).copied();
        if trust_fingerprint && previously_seen == Some(fingerprint) {
            return;
        }

        let Ok(on_disk) = std::fs::read_to_string(&path) else {
            // Stat'd fine but unreadable (a permission change, or a
            // binary file that isn't UTF-8). Not a change we can act on.
            return;
        };
        let Some(ob) = self.buffers.get(id) else { return };
        if on_disk == ob.buffer.text() {
            // The file moved but its content didn't -- `touch`, or a
            // tool that rewrote it identically. Record the new
            // fingerprint so this doesn't re-read every two seconds,
            // and say nothing: nothing happened.
            self.disk_state.insert(id, fingerprint);
            return;
        }

        if ob.buffer.is_dirty() {
            if previously_seen.is_none() || previously_seen == Some(fingerprint) {
                // Either this file has never been looked at, or it
                // hasn't moved since it was -- so the difference is the
                // buffer's own unsaved edits, which is what "dirty"
                // means, and no evidence at all that anybody else
                // touched it. Recording the fingerprint is all that can
                // honestly be done; a real change from here on moves it.
                self.disk_state.insert(id, fingerprint);
                return;
            }
            // Both sides changed since the last look. Neither can be
            // thrown away without being asked, so the buffer is left
            // exactly as it is and the next save refuses -- see `save`.
            self.externally_changed.insert(id);
            sweep.conflicted.push(name);
            return;
        }

        self.replace_buffer_from_disk(id, &on_disk);
        self.disk_state.insert(id, fingerprint);
        self.externally_changed.remove(&id);
        sweep.reloaded.push(name);
    }

    /// Swaps a buffer's text for what's on disk, keeping every pane that
    /// shows it on the same line.
    fn replace_buffer_from_disk(&mut self, id: BufferId, on_disk: &str) {
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch, 0, end, on_disk);
            // A reload isn't user work: leaving it dirty would make
            // every touched file look unsaved and block `:qa`.
            ob.buffer.mark_saved();
        }
        // Every pane showing it keeps its line, clamped to the new
        // length -- the file changed, but where you were looking in it
        // is still the best guess at where you want to be.
        let line_count = self.buffers.get(id).map(|ob| ob.buffer.visual_line_count()).unwrap_or(1);
        for pane in self.windows().windows() {
            if self.windows().content(pane) != Some(&id) {
                continue;
            }
            let line = self
                .buffers
                .get(id)
                .map(|ob| ob.buffer.line_col(&self.pane_state(pane).cursor).0.min(line_count.saturating_sub(1)))
                .unwrap_or(0);
            let Some(ob) = self.buffers.get(id) else { continue };
            let char_idx = ob.buffer.line_start_char(line);
            self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
        }
    }

    /// Records a buffer's file as Fenix last left it -- called after
    /// every read and every write, so the sweep's fast path stays
    /// accurate and a save Fenix performed itself never looks like
    /// somebody else's change.
    fn note_disk_state(&mut self, id: BufferId) {
        let Some(path) = self.buffers.get(id).and_then(|ob| ob.buffer.path()).map(Path::to_path_buf) else { return };
        match DiskFingerprint::of(&path) {
            Some(fingerprint) => {
                self.disk_state.insert(id, fingerprint);
            }
            None => {
                self.disk_state.remove(&id);
            }
        }
        self.externally_changed.remove(&id);
    }

    /// The periodic sweep, plus whatever it found, reported once.
    ///
    /// Called from the event loop's own wait deadline and whenever the
    /// window regains focus. Both are needed: focus catches editing in
    /// another application, and the timer catches Fenix's own terminal
    /// panel, which never takes focus away from the window at all.
    pub(crate) fn poll_files_changed_on_disk(&mut self) {
        if !self.config.watch_files.unwrap_or(true) {
            return;
        }
        self.next_disk_check = Instant::now() + DISK_CHECK_INTERVAL;
        // Before the sweep, not after: a sweep that reloads a buffer
        // makes it clean, and snapshotting afterwards would then throw
        // away a snapshot that had never been written.
        self.snapshot_dirty_buffers();
        let sweep = self.reload_buffers_changed_on_disk();
        let Some(message) = sweep.message() else { return };
        if sweep.is_bad() {
            self.set_error(message);
        } else {
            self.set_message(message);
        }
        self.wake_caret();
    }

    /// Writes every dirty buffer that has changed since its last
    /// snapshot, and clears the snapshot of every buffer that no longer
    /// needs one.
    ///
    /// Runs on the same tick as the disk sweep -- so at most a couple of
    /// seconds of typing is ever at risk, and a buffer nobody is
    /// touching costs one integer comparison. Keyed on `edit_count`
    /// rather than on the text, because comparing whole buffers every
    /// two seconds to decide whether to write them would cost more than
    /// writing them.
    fn snapshot_dirty_buffers(&mut self) {
        let Some(dir) = self.recovery_dir.clone() else { return };
        for id in self.buffers.ids_sorted_by_path() {
            let Some(ob) = self.buffers.get(id) else { continue };
            if !ob.kind.tracks_unsaved_changes() {
                continue;
            }
            let Some(path) = ob.buffer.path().map(Path::to_path_buf) else {
                // A buffer with no path has nowhere to be recovered
                // *to*, so there is nothing useful to write: restoring
                // it would produce text with no home. `:w` on it names
                // a file, and from then on it snapshots like any other.
                continue;
            };
            if !ob.buffer.is_dirty() {
                // Saved or reverted since the last tick -- the snapshot
                // is now describing work that isn't lost, and leaving it
                // would offer to "recover" it on the next start.
                if self.snapshot_state.remove(&id).is_some() {
                    let _ = fenix_recovery::discard(&dir, &path);
                }
                continue;
            }
            let edits = ob.buffer.edit_count();
            if self.snapshot_state.get(&id) == Some(&edits) {
                continue;
            }
            let contents = ob.buffer.text();
            match fenix_recovery::write(&dir, &path, &contents) {
                Ok(_) => {
                    self.snapshot_state.insert(id, edits);
                }
                // Deliberately silent. This runs every couple of
                // seconds; a read-only config directory would otherwise
                // produce an error message the user can neither act on
                // nor dismiss, on top of whatever they were doing.
                Err(err) => eprintln!("fenix: couldn't write a recovery snapshot for {}: {err}", path.display()),
            }
        }
    }

    /// Drops the recovery snapshot for a buffer whose work is no longer
    /// at risk -- it was saved, or deliberately thrown away.
    fn discard_recovery_for(&mut self, id: BufferId) {
        self.snapshot_state.remove(&id);
        let Some(dir) = self.recovery_dir.clone() else { return };
        let Some(path) = self.buffers.get(id).and_then(|ob| ob.buffer.path()).map(Path::to_path_buf) else { return };
        let _ = fenix_recovery::discard(&dir, &path);
    }

    /// Says once, at startup, that a previous session left work behind.
    ///
    /// A message rather than a prompt: a modal "recover?" on launch is
    /// the thing everyone hates about swap files, and it fires on every
    /// start until it's answered. This says what's there and where the
    /// key is, and gets out of the way. Old snapshots are pruned first,
    /// so a crash from months ago isn't still being announced.
    fn announce_recoverable_work(&mut self) {
        let Some(dir) = self.recovery_dir.clone() else { return };
        fenix_recovery::prune(&dir, RECOVERY_MAX_AGE);
        let snapshots = fenix_recovery::list(&dir);
        if snapshots.is_empty() {
            return;
        }
        let names: Vec<String> =
            snapshots.iter().filter_map(|s| s.original.file_name()).map(|n| n.to_string_lossy().into_owned()).collect();
        self.set_message(format!("unsaved work from a previous session: {} -- SPC f v recovers it", join_names(&names)));
    }

    /// `SPC f v`: what a previous session left unsaved.
    pub(crate) fn picker_recovery(&mut self) {
        let Some(dir) = self.recovery_dir.clone() else {
            self.set_error("no config directory to keep recovery snapshots in".to_string());
            return;
        };
        let snapshots = fenix_recovery::list(&dir);
        if snapshots.is_empty() {
            self.set_message("nothing to recover -- no unsaved work was left behind");
            return;
        }
        let candidates = snapshots
            .into_iter()
            .map(|snapshot| {
                let label = format!("{}   ({})", snapshot.original.display(), describe_age(snapshot.age()));
                fenix_picker::Candidate::new(label, snapshot)
            })
            .collect();
        self.enter_picker(ActivePicker::Recovery(fenix_picker::PickerState::new(candidates)));
    }

    /// Puts a snapshot's text back, as an unsaved edit.
    ///
    /// Deliberately *not* written straight to the file. The recovered
    /// text is what you had, not necessarily what you want -- and the
    /// file may have moved on since the crash. Loading it as a dirty
    /// buffer means `:w` accepts it and `:e!` throws it away, which is
    /// the same pair of answers the file-watching work already
    /// established for two versions that disagree.
    fn recover_snapshot(&mut self, snapshot: &fenix_recovery::Snapshot) {
        self.main_view = MainView::Editor;
        let existed = snapshot.original.exists();
        self.open_file_from_picker(&snapshot.original);
        let id = self.focused_buffer_id();
        // Compared against what's on disk *now*: a snapshot identical to
        // the file is work that was saved after all (recovered by hand,
        // or saved by another session), and re-opening it as a dirty
        // buffer would invent a change nobody made.
        let unchanged = self.buffers.get(id).is_some_and(|ob| ob.buffer.text() == snapshot.contents);
        if unchanged {
            self.discard_recovery_for(id);
            self.set_message(format!("{} already matches what was recovered", snapshot.original.display()));
            self.wake_caret();
            return;
        }
        self.replace_buffer_from_disk(id, &snapshot.contents);
        // `replace_buffer_from_disk` marks the buffer saved, which is
        // right when the text came from the file and wrong here: this
        // text exists nowhere but the snapshot, and letting `:qa` past
        // it would lose it a second time.
        if let Some(ob) = self.buffers.get_mut(id) {
            ob.buffer.mark_unsaved();
        }
        let note = if existed { "" } else { " (the file itself is gone)" };
        self.set_message(format!("recovered {}{note} -- :w keeps it, :e! discards it", snapshot.original.display()));
        self.wake_caret();
    }

    /// `:e!`: throw away the buffer's own edits and read the file again.
    pub(crate) fn reload_focused_file(&mut self) {
        let id = self.focused_buffer_id();
        let Some(path) = self.buffers.get(id).and_then(|ob| ob.buffer.path()).map(Path::to_path_buf) else {
            self.set_error("this buffer has no file to reload from".to_string());
            return;
        };
        match std::fs::read_to_string(&path) {
            Ok(on_disk) => {
                self.replace_buffer_from_disk(id, &on_disk);
                self.note_disk_state(id);
                self.set_message(format!("reloaded {}", path.display()));
            }
            Err(err) => self.set_error(format!("couldn't reload {}: {err}", path.display())),
        }
        self.wake_caret();
    }

    /// Refreshes whichever Git views are open -- every operation here
    /// can change the working tree, the branch, and the graph at once.
    fn git_refresh_all_views(&mut self) {
        let sweep = self.reload_buffers_changed_on_disk();
        if let Some(message) = sweep.message() {
            if sweep.is_bad() {
                self.set_error(message);
            } else {
                self.set_message(message);
            }
        }
        if self.git_session.is_some() {
            self.git_refresh_session();
        }
        if self.history_session.is_some() {
            self.history_refresh();
        }
        if self.compare_session.is_some() {
            self.compare_refresh();
        }
        if self.merge_session.is_some() {
            self.merge_refresh();
        }
    }

    // -- Merge Requests view (`SPC g M`) -------------------------------

    /// A GitLab client for `repo_root`, or the reason there isn't one.
    ///
    /// Three things have to line up, and each failure says which:
    /// `[gitlab] base_url`/`token` in `config.ini`, and an `origin`
    /// remote whose URL names a project. Nothing is configured per
    /// repo -- the checkout already knows which project it came from.
    fn forge_client(&self, repo_root: &Path) -> Result<fenix_gitlab::GitLab, String> {
        let Some(base_url) = self.config.gitlab_base_url.clone().filter(|u| !u.trim().is_empty()) else {
            return Err("set [gitlab] base_url in config.ini first".to_string());
        };
        let Some(token) = self.config.gitlab_token.clone().filter(|t| !t.trim().is_empty()) else {
            return Err("set [gitlab] token in config.ini first (a personal access token with `api` scope)".to_string());
        };
        let Some(url) = fenix_git::remote_url(repo_root, "origin") else {
            return Err("this repo has no `origin` remote to work out the project from".to_string());
        };
        fenix_gitlab::GitLab::from_remote(base_url, token, &url)
            .ok_or_else(|| format!("couldn't read a GitLab project path out of origin's URL ({url})"))
    }

    /// `SPC g M`: opens (or refocuses and refreshes) the Merge Requests
    /// view.
    pub(crate) fn open_forge_view(&mut self) {
        if let Some(session) = &self.forge_session {
            let (workspace_index, list_pane) = (session.workspace_index, session.list_pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(list_pane);
            self.forge_refresh_list();
            self.wake_caret();
            return;
        }
        let repo_root = self.compare_repo_root();
        // Checked before a workspace is opened: a view that can only
        // ever show one error message isn't worth two panes.
        let project = match self.forge_client(&repo_root) {
            Ok(client) => fenix_forge::Forge::project(&client).to_string(),
            Err(err) => {
                self.set_error(err);
                return;
            }
        };

        let list_buffer = self.buffers.open_git("");
        let detail_buffer = self.buffers.open_git("");
        let empty = diff_view::render(&[], &HashSet::new());
        let review_buffer = self.buffers.open_diff(&empty.text);
        self.diff_lines.insert(review_buffer, empty.lines);

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(list_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let list_pane = self.focused_pane_id();
        let detail_pane = self.windows_mut().split(SplitKind::Vertical, detail_buffer);
        self.workspaces.active_pane_states_mut().insert(detail_pane, PaneState::seeded_at(cursor));
        // The right half stacks: what the request *is* on top, the diff
        // being reviewed below. The diff takes most of the height --
        // the description is read once, the changes are read for as
        // long as the review takes.
        let review_pane = self.windows_mut().split(SplitKind::Horizontal, review_buffer);
        self.workspaces.active_pane_states_mut().insert(review_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-0.15);
        // An even split. `resize_focused`'s delta grows the *first*
        // child, so the `0.3` this used to pass gave the list 80% and
        // squeezed the detail -- the pane with all the reading in it --
        // into 20%. Left at the default rather than corrected to a
        // negative delta, because 50/50 is what's wanted here.
        self.windows_mut().focus(list_pane);

        self.pane_titles.insert(list_pane, "1. Merge Requests".to_string());
        self.pane_titles.insert(detail_pane, "2. Detail".to_string());
        self.pane_titles.insert(review_pane, "3. Review".to_string());

        self.forge_session = Some(ForgeSession {
            workspace_index,
            list_pane,
            detail_pane,
            review_pane,
            list_buffer,
            detail_buffer,
            review_buffer,
            repo_root,
            project,
            filter: fenix_forge::MrFilter::AllOpen,
            requests: Vec::new(),
            selected: None,
            detail: None,
            list_error: None,
            list_request_id: 0,
            detail_request_id: 0,
            merge_armed: false,
        });
        self.forge_render();
        self.forge_refresh_list();
        self.wake_caret();
    }

    /// Re-renders both panes from what's already cached -- no network.
    fn forge_render(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        // Wrapped to the panes they're going into, not to a fixed
        // width: this view is an even split, so each pane is about half
        // as wide as the fixed default assumes.
        let (list_cols, detail_cols) = (self.pane_cols(session.list_pane), self.pane_cols(session.detail_pane));
        let Some(session) = self.forge_session.as_ref() else { return };
        let list = forge_panel::render_list(&session.project, session.filter, &session.requests, session.list_error.as_deref(), list_cols);
        let detail = match &session.detail {
            Some(detail) => forge_panel::render_detail(
                Some(&detail.request),
                detail.approvals.as_ref(),
                &detail.files,
                &detail.discussions,
                detail.error.as_deref(),
                detail_cols,
            ),
            None => forge_panel::render_detail(None, None, &[], &[], None, detail_cols),
        };
        let (list_buffer, detail_buffer) = (session.list_buffer, session.detail_buffer);
        self.set_git_buffer_preserving_line(list_buffer, list);
        self.set_git_buffer_preserving_line(detail_buffer, detail);
        self.forge_render_review();
    }

    /// Renders the selected merge request's whole diff into the review
    /// pane, with its threads drawn in under the lines they hang on.
    ///
    /// The diff is reassembled from the forge's per-file hunks (see
    /// `ChangedFile::unified_diff`) and handed to the same parser and
    /// the same viewer every other diff in Fenix goes through -- so
    /// folding, hunk navigation and "open the real file here" work
    /// without this view knowing anything about them.
    fn forge_render_review(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        let (review_buffer, repo_root) = (session.review_buffer, session.repo_root.clone());
        let Some(detail) = session.detail.as_ref() else {
            self.set_diff_buffer(review_buffer, None, DiffSource::ReadOnly, &repo_root);
            return;
        };
        let diff: String = detail.files.iter().map(|f| f.unified_diff()).collect();
        let threads = forge_thread_annotations(&detail.discussions);
        let header = vec![(
            format!("{} {}  --  r reply, R resolve, C comment on this line", detail.request.reference(), detail.request.title),
            diff_view::DiffStyle::Title,
        )];
        self.set_diff_buffer_with_header(review_buffer, &header, Some(&diff), DiffSource::ReadOnly, &repo_root);
        if let Some(model) = self.diff_models.get_mut(&review_buffer) {
            model.threads = threads;
        }
        self.rerender_diff_buffer(review_buffer);
    }

    /// The review thread under the cursor, if the cursor is on one.
    fn forge_thread_at_cursor(&self) -> Option<String> {
        let session = self.forge_session.as_ref()?;
        if self.focused_pane_id() != session.review_pane {
            return None;
        }
        let line = self.open().buffer.line_col(&self.cursor()).0;
        self.diff_lines.get(&session.review_buffer)?.get(line)?.as_ref()?.thread.clone()
    }

    /// `r` in the review pane: open a compose buffer to reply to the
    /// thread under the cursor.
    pub(crate) fn forge_reply_at_cursor(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        let Some(number) = session.selected else { return };
        let Some(discussion) = self.forge_thread_at_cursor() else {
            self.set_message("put the cursor on a review comment to reply to it");
            return;
        };
        self.open_compose(ComposePurpose::Reply { number, discussion });
    }

    /// `R` in the review pane: resolve the thread under the cursor, or
    /// reopen it if it's already resolved.
    pub(crate) fn forge_resolve_at_cursor(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        let Some(number) = session.selected else { return };
        let Some(discussion) = self.forge_thread_at_cursor() else {
            self.set_message("put the cursor on a review comment to resolve it");
            return;
        };
        let was_resolved = session
            .detail
            .as_ref()
            .and_then(|d| d.discussions.iter().find(|t| t.id == discussion))
            .map(|t| t.resolved)
            .unwrap_or(false);
        let repo_root = session.repo_root.clone();
        let client = match self.forge_client(&repo_root) {
            Ok(client) => client,
            Err(err) => {
                self.set_error(err);
                return;
            }
        };
        match fenix_forge::Forge::resolve(&client, number, &discussion, !was_resolved) {
            Ok(()) => {
                self.set_message(if was_resolved { "thread reopened" } else { "thread resolved" });
                self.forge_select(number);
            }
            Err(err) => self.set_error(format!("couldn't resolve that thread: {err}")),
        }
        self.wake_caret();
    }

    /// `C` in the review pane: start a new thread on the diff line
    /// under the cursor.
    pub(crate) fn forge_comment_at_cursor(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        if self.focused_pane_id() != session.review_pane {
            self.set_message("comment from the Review pane (3)");
            return;
        }
        let Some(number) = session.selected else { return };
        let Some(detail) = session.detail.as_ref() else { return };
        let refs = detail.request.diff_refs.clone();
        if refs.head_sha.is_empty() {
            // Without the three SHAs a comment either lands on the
            // wrong line or is rejected; saying so beats posting it and
            // finding out on the forge.
            self.set_error("this merge request has no diff version to anchor a comment to yet".to_string());
            return;
        }
        let Some((_, anchor)) = self.diff_anchor_at_cursor() else {
            self.set_message("put the cursor on a line of the diff".to_string());
            return;
        };
        let Some(model) = self.diff_models.get(&session.review_buffer) else { return };
        let Some(file) = model.files.get(anchor.file) else { return };
        let (old_path, new_path) = (file.old_path.clone(), file.new_path.clone());
        // All three cases, because the forge distinguishes them: an
        // added line exists only on the new side, a removed line only
        // on the old, and an unchanged line on both -- and a context
        // position that names only one side is rejected outright (see
        // `Position::on_context_line`). Most of a diff is context, so
        // collapsing this into "new side where there is one" made most
        // of the lines you'd want to comment on refuse the comment.
        let position = match (anchor.old_line, anchor.new_line) {
            (Some(old), Some(new)) => fenix_forge::Position::on_context_line(&refs, &old_path, &new_path, old, new),
            (None, Some(new)) => fenix_forge::Position::on_new_line(&refs, &old_path, &new_path, new),
            (Some(old), None) => fenix_forge::Position::on_old_line(&refs, &old_path, &new_path, old),
            (None, None) => {
                self.set_message("put the cursor on a line of the diff, not on a header");
                return;
            }
        };
        self.open_compose(ComposePurpose::NewComment { number, position: Box::new(position) });
    }

    /// `A`: approve the selected merge request, or withdraw an approval
    /// already given.
    pub(crate) fn forge_toggle_approval(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        let Some(number) = session.selected else {
            self.set_message("no merge request selected");
            return;
        };
        let (repo_root, detail) = (session.repo_root.clone(), session.detail.clone());
        let approved = detail.as_ref().and_then(|d| d.approvals.as_ref()).map(|a| a.approved).unwrap_or(false);
        let sha = detail.as_ref().map(|d| d.request.sha.clone()).filter(|s| !s.is_empty());
        let client = match self.forge_client(&repo_root) {
            Ok(client) => client,
            Err(err) => {
                self.set_error(err);
                return;
            }
        };
        let result = if approved {
            fenix_forge::Forge::unapprove(&client, number)
        } else {
            fenix_forge::Forge::approve(&client, number, sha.as_deref())
        };
        match result {
            Ok(()) => {
                self.set_message(if approved { format!("approval withdrawn from !{number}") } else { format!("approved !{number}") });
                self.forge_select(number);
            }
            Err(err) => self.set_error(format!("couldn't change the approval: {err}")),
        }
        self.wake_caret();
    }

    /// Backs out of an armed merge. Called from the key handler for
    /// every key in this view that isn't a second `m`, so an arm left
    /// hanging can't fire later on a keystroke meant for something
    /// else.
    fn forge_disarm_merge(&mut self) {
        if let Some(session) = self.forge_session.as_mut() {
            session.merge_armed = false;
        }
    }

    /// `m`: arm the merge; a second `m` performs it.
    ///
    /// The one action in this view that can't be taken back, so it
    /// doesn't happen on a single keystroke -- the same arm-then-confirm
    /// the Git panel's destructive actions already use.
    pub(crate) fn forge_merge_request(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        let Some(number) = session.selected else {
            self.set_message("no merge request selected");
            return;
        };
        if !session.merge_armed {
            if let Some(session) = self.forge_session.as_mut() {
                session.merge_armed = true;
            }
            self.set_message(format!("merge !{number}? press m again to confirm, any other key cancels"));
            self.wake_caret();
            return;
        }
        let (repo_root, detail) = (session.repo_root.clone(), session.detail.clone());
        if let Some(session) = self.forge_session.as_mut() {
            session.merge_armed = false;
        }
        let client = match self.forge_client(&repo_root) {
            Ok(client) => client,
            Err(err) => {
                self.set_error(err);
                return;
            }
        };
        let options = fenix_forge::MergeOptions {
            squash: false,
            remove_source_branch: false,
            // Sent so the forge refuses rather than merging something
            // that moved between reading the diff and pressing the key.
            sha: detail.as_ref().map(|d| d.request.sha.clone()).filter(|s| !s.is_empty()),
        };
        match fenix_forge::Forge::merge(&client, number, &options) {
            Ok(()) => {
                self.set_message(format!("merged !{number}"));
                self.forge_refresh_list();
            }
            // The forge's own words: "unresolved discussions", "pipeline
            // must succeed", "branch cannot be merged" are all far more
            // useful than anything this could say instead.
            Err(err) => self.set_error(format!("couldn't merge !{number}: {err}")),
        }
        self.wake_caret();
    }

    /// Fetches the merge request list for the current filter.
    fn forge_refresh_list(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        use fenix_forge::Forge;
        let (repo_root, filter) = (session.repo_root.clone(), session.filter);
        let client = match self.forge_client(&repo_root) {
            Ok(client) => client,
            Err(err) => {
                if let Some(session) = self.forge_session.as_mut() {
                    session.list_error = Some(err.clone());
                    session.requests.clear();
                }
                self.set_error(err);
                self.forge_render();
                return;
            }
        };
        let Some(session) = self.forge_session.as_mut() else { return };
        session.list_request_id += 1;
        let request_id = session.list_request_id;
        self.set_message(format!("loading merge requests ({})...", filter.label()));

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let result = client.list_merge_requests(filter);
                    let _ = proxy.send_event(FenixUserEvent::ForgeListReady { request_id, result });
                });
            }
            None => {
                let result = client.list_merge_requests(filter);
                self.apply_forge_list(request_id, result);
            }
        }
    }

    fn apply_forge_list(&mut self, request_id: u64, result: Result<Vec<fenix_forge::MergeRequest>, String>) {
        let Some(session) = self.forge_session.as_mut() else { return };
        // A slower earlier request answering after a newer one would
        // otherwise put the previous filter's list back on screen.
        if request_id != session.list_request_id {
            return;
        }
        match result {
            Ok(requests) => {
                let count = requests.len();
                let filter = session.filter;
                session.requests = requests;
                session.list_error = None;
                // Keep the current selection if it survived the new
                // filter; otherwise show the first, so the detail pane
                // is never left describing something the list no longer
                // contains.
                let keep = session.selected.filter(|n| session.requests.iter().any(|r| r.number == *n));
                let next = keep.or_else(|| session.requests.first().map(|r| r.number));
                self.set_message(format!("{count} merge request(s) ({})", filter.label()));
                self.forge_render();
                if let Some(number) = next {
                    self.forge_select(number);
                } else if let Some(session) = self.forge_session.as_mut() {
                    session.selected = None;
                    session.detail = None;
                    self.forge_render();
                }
            }
            Err(err) => {
                session.requests.clear();
                session.list_error = Some(err.clone());
                session.selected = None;
                session.detail = None;
                self.set_error(err);
                self.forge_render();
            }
        }
    }

    /// Loads one merge request's detail into the right pane.
    fn forge_select(&mut self, number: u64) {
        let Some(session) = self.forge_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        let client = match self.forge_client(&repo_root) {
            Ok(client) => client,
            Err(err) => {
                self.set_error(err);
                return;
            }
        };
        let Some(session) = self.forge_session.as_mut() else { return };
        session.selected = Some(number);
        session.detail_request_id += 1;
        let request_id = session.detail_request_id;

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let result = Box::new(fetch_forge_detail(&client, number));
                    let _ = proxy.send_event(FenixUserEvent::ForgeDetailReady { request_id, number, result });
                });
            }
            None => {
                let result = fetch_forge_detail(&client, number);
                self.apply_forge_detail(request_id, number, result);
            }
        }
    }

    fn apply_forge_detail(&mut self, request_id: u64, number: u64, result: Result<ForgeDetail, String>) {
        let Some(session) = self.forge_session.as_mut() else { return };
        if request_id != session.detail_request_id {
            return;
        }
        match result {
            Ok(detail) => session.detail = Some(detail),
            Err(err) => {
                session.detail = None;
                self.set_error(format!("couldn't load !{number}: {err}"));
            }
        }
        self.forge_render();
        self.wake_caret();
    }

    /// The merge request number under the cursor in the list pane.
    fn forge_number_at_cursor(&self) -> Option<u64> {
        let session = self.forge_session.as_ref()?;
        if self.focused_pane_id() != session.list_pane {
            return None;
        }
        match self.git_entry_at_cursor()? {
            git_panel::GitEntry::Commit(number) => number.parse().ok(),
            _ => None,
        }
    }

    /// `Enter` in the list pane: show that merge request.
    pub(crate) fn forge_open_at_cursor(&mut self) {
        let Some(number) = self.forge_number_at_cursor() else {
            self.set_message("put the cursor on a merge request");
            return;
        };
        self.forge_select(number);
        self.wake_caret();
    }

    /// `f`: cycle the list filter (all open / mine / assigned to me).
    pub(crate) fn forge_cycle_filter(&mut self) {
        let Some(session) = self.forge_session.as_mut() else { return };
        session.filter = session.filter.next();
        self.forge_render();
        self.forge_refresh_list();
        self.wake_caret();
    }

    /// `c`: fetch the selected merge request's head into a local branch
    /// and check it out.
    ///
    /// Fetched from the *project's* own published ref rather than from
    /// the source branch, so a request opened from a fork needs no
    /// extra remote -- and lands on `mr-42` rather than the source
    /// branch's name, which may not exist locally, may point somewhere
    /// else, or may collide with an unrelated branch.
    pub(crate) fn forge_checkout_selected(&mut self) {
        let Some(session) = self.forge_session.as_ref() else { return };
        let (repo_root, selected) = (session.repo_root.clone(), session.selected);
        let Some(number) = self.forge_number_at_cursor().or(selected) else {
            self.set_message("no merge request selected");
            return;
        };
        let client = match self.forge_client(&repo_root) {
            Ok(client) => client,
            Err(err) => {
                self.set_error(err);
                return;
            }
        };
        let branch = format!("mr-{number}");
        let refspec = fenix_forge::Forge::checkout_refspec(&client, number);
        if let Err(err) = fenix_git::fetch_refspec(&repo_root, "origin", &refspec) {
            self.set_error(format!("couldn't fetch !{number}: {err}"));
            return;
        }
        match fenix_git::checkout_branch(&repo_root, &branch) {
            Ok(_) => self.set_message(format!("checked out !{number} as {branch}")),
            Err(err) => self.set_error(format!("fetched !{number}, but couldn't check out {branch}: {err}")),
        }
        // The checkout rewrote the working tree, so every other Git
        // view -- and every open file -- has to catch up.
        self.git_refresh_all_views();
        self.wake_caret();
    }

    fn forge_pane_by_number(&self, n: u32) -> Option<fenix_window::WindowId> {
        let session = self.forge_session.as_ref()?;
        match n {
            1 => Some(session.list_pane),
            2 => Some(session.detail_pane),
            3 => Some(session.review_pane),
            _ => None,
        }
    }

    /// `SPC g Q`: closes the Merge Requests view.
    pub(crate) fn forge_close(&mut self) {
        let Some(session) = self.forge_session.take() else { return };
        for id in [session.list_buffer, session.detail_buffer, session.review_buffer] {
            self.buffers.close(id);
            self.git_lines.remove(&id);
            self.diff_lines.remove(&id);
            self.diff_models.remove(&id);
        }
        for pane in [session.list_pane, session.detail_pane, session.review_pane] {
            self.pane_titles.remove(&pane);
        }
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    // -- Compose buffer ----------------------------------------------

    /// Opens a compose buffer in a strip under the current pane.
    ///
    /// Replaces any compose buffer already open rather than stacking a
    /// second one: there's only ever one thing being written, and two
    /// would leave no way to tell which `Enter` submits.
    fn open_compose(&mut self, purpose: ComposePurpose) {
        self.close_compose();
        let returning_to = self.focused_pane_id();
        let buffer = self.buffers.open_scratch();
        let pane = self.windows_mut().split(SplitKind::Horizontal, buffer);
        self.workspaces.active_pane_states_mut().insert(pane, PaneState::seeded_at(Cursor::at_start()));
        // A comment is a few lines; the thing being commented on is
        // what needs the room, and is what you're looking at while you
        // write.
        self.windows_mut().resize_focused(0.25);
        self.pane_titles.insert(pane, purpose.title());
        self.windows_mut().focus(pane);
        self.compose = Some(ComposeSession { pane, buffer, purpose, returning_to });
        self.set_message("write your comment (i to insert), then Esc and Enter to send");
        self.wake_caret();
    }

    /// Tears the compose pane down and puts focus back where it was.
    fn close_compose(&mut self) {
        let Some(compose) = self.compose.take() else { return };
        self.pane_titles.remove(&compose.pane);
        self.windows_mut().focus(compose.pane);
        if self.windows_mut().close_focused() {
            self.workspaces.active_pane_states_mut().remove(&compose.pane);
            self.workspaces.active_scroll_anims_mut().remove(&compose.pane);
        }
        self.buffers.close(compose.buffer);
        if self.windows().windows().contains(&compose.returning_to) {
            self.windows_mut().focus(compose.returning_to);
        }
        self.wake_caret();
    }

    /// `q` in the compose pane: throw the draft away.
    pub(crate) fn compose_cancel(&mut self) {
        if self.compose.is_none() {
            return;
        }
        self.close_compose();
        self.set_message("comment discarded");
    }

    /// `Enter` in the compose pane (Normal mode): send what's written.
    pub(crate) fn compose_submit(&mut self) {
        let Some(compose) = self.compose.as_ref() else { return };
        let body = self.buffers.get(compose.buffer).map(|ob| ob.buffer.text()).unwrap_or_default();
        let body = body.trim().to_string();
        if body.is_empty() {
            // Posting an empty comment is never what was meant, and the
            // forge would either reject it or publish a blank note.
            self.set_error("nothing written yet -- q discards this instead".to_string());
            return;
        }
        let purpose = compose.purpose.clone();

        // A commit message goes to `git`, not to a forge -- so it needs
        // none of the client below, and works with no Merge Requests
        // view open at all.
        if let ComposePurpose::CommitMessage { repo_root } = &purpose {
            match fenix_git::commit(repo_root, &body) {
                Ok(_) => {
                    self.close_compose();
                    let summary = body.lines().next().unwrap_or_default().to_string();
                    self.set_message(format!("committed: {summary}"));
                    self.git_refresh_all_views();
                }
                // The draft stays put, same as a failed post: a hook
                // that rejected the message is something you fix in the
                // message.
                Err(err) => self.set_error(format!("commit failed: {err} -- the message is still here")),
            }
            self.wake_caret();
            return;
        }

        let repo_root = match self.forge_session.as_ref() {
            Some(session) => session.repo_root.clone(),
            None => {
                self.set_error("the Merge Requests view was closed -- nothing to send this to".to_string());
                return;
            }
        };
        let client = match self.forge_client(&repo_root) {
            Ok(client) => client,
            Err(err) => {
                self.set_error(err);
                return;
            }
        };
        let (number, result) = match &purpose {
            ComposePurpose::Reply { number, discussion } => (*number, fenix_forge::Forge::reply(&client, *number, discussion, &body)),
            ComposePurpose::NewComment { number, position } => {
                (*number, fenix_forge::Forge::comment_on_line(&client, *number, position, &body))
            }
            ComposePurpose::CommitMessage { .. } => unreachable!("handled above"),
        };
        match result {
            Ok(()) => {
                // Only torn down on success: a failed send leaves the
                // draft in the buffer, which is the difference between
                // retrying and retyping.
                self.close_compose();
                self.set_message(format!("posted to !{number}"));
                self.forge_select(number);
            }
            Err(err) => self.set_error(format!("couldn't post that: {err} -- the draft is still here")),
        }
        self.wake_caret();
    }

    // -- Merge view (`SPC g x`) --------------------------------------------

    /// `SPC g x`: opens (or refocuses and refreshes) the Merge view --
    /// every conflicted file on the left, the selected one shown as two
    /// aligned columns on the right.
    pub(crate) fn open_merge_view(&mut self) {
        if let Some(session) = &self.merge_session {
            let (workspace_index, files_pane) = (session.workspace_index, session.files_pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(files_pane);
            self.merge_refresh();
            self.wake_caret();
            return;
        }
        let repo_root = self.compare_repo_root();
        if fenix_git::status(&repo_root).is_none() {
            self.set_error(format!("{} isn't a git repository", repo_root.display()));
            return;
        }

        let files_buffer = self.buffers.open_git("");
        let merge_buffer = self.buffers.open_merge("");

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(files_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let files_pane = self.focused_pane_id();
        let merge_pane = self.windows_mut().split(SplitKind::Vertical, merge_buffer);
        self.workspaces.active_pane_states_mut().insert(merge_pane, PaneState::seeded_at(cursor));
        // The file list is a short index; the two columns need the
        // width, and they're what's actually being read. Negative,
        // because the delta grows the *first* child (the list).
        self.windows_mut().resize_focused(-0.25);
        self.windows_mut().focus(files_pane);

        self.pane_titles.insert(files_pane, "1. Conflicts".to_string());
        self.pane_titles.insert(merge_pane, "2. Merge".to_string());

        self.merge_session = Some(MergeSession {
            workspace_index,
            files_pane,
            merge_pane,
            files_buffer,
            merge_buffer,
            repo_root,
            files: Vec::new(),
            selected: None,
            labels: merge_view::SideLabels::unknown(),
        });
        self.merge_refresh();
        self.wake_caret();
    }

    /// Re-lists the conflicted files and re-renders both panes.
    fn merge_refresh(&mut self) {
        let Some(session) = self.merge_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        let (files_buffer, merge_buffer, merge_pane) = (session.files_buffer, session.merge_buffer, session.merge_pane);

        // `u` entries are exactly git's own unmerged paths -- the same
        // ones `git status` calls "Unmerged", and the same list
        // `git rebase --continue` refuses to move past.
        let files: Vec<String> =
            fenix_git::list_files(&repo_root).into_iter().filter(|f| f.index_status == 'U' || f.worktree_status == 'U').map(|f| f.path).collect();
        let labels = fenix_git::conflict_sides(&repo_root).as_ref().map(merge_view::SideLabels::from).unwrap_or_else(merge_view::SideLabels::unknown);

        // Keep showing whatever was selected as long as it's still a
        // real path -- a file that has just been resolved should show
        // "nothing left to resolve" rather than silently jumping to a
        // different file the user wasn't looking at.
        let selected = session.selected.clone().filter(|p| files.contains(p) || repo_root.join(p).exists()).or_else(|| files.first().cloned());

        if let Some(session) = self.merge_session.as_mut() {
            session.files = files.clone();
            session.labels = labels.clone();
            session.selected = selected.clone();
        }
        self.set_git_buffer_preserving_line(files_buffer, git_panel::render_conflicts(&files, &labels.ours, &labels.theirs, &labels.ours_role, &labels.theirs_role));

        // Sized to the pane, so the two columns fill it rather than
        // being cut to a fixed 160 in a wider one or overflowing a
        // narrower one.
        let cols = self.pane_cols_or(merge_pane, merge_view::DEFAULT_WIDTH);
        let view = match &selected {
            Some(path) => {
                let full = repo_root.join(path);
                match std::fs::read_to_string(&full) {
                    Ok(text) => {
                        let conflicts = fenix_git::find_conflicts(&text);
                        merge_view::render(path, &text, &conflicts, &labels, cols)
                    }
                    Err(err) => {
                        merge_view::render(path, &format!("couldn't read {}: {err}\n", full.display()), &[], &labels, cols)
                    }
                }
            }
            None => merge_view::render("", "", &[], &labels, cols),
        };
        self.set_merge_buffer(merge_buffer, view);
    }

    /// Swaps a Merge buffer's content, keeping every pane showing it on
    /// the same line index -- resolving one conflict re-renders the
    /// whole file, and snapping back to the top after each choice would
    /// make a file with several conflicts miserable to work through.
    fn set_merge_buffer(&mut self, id: BufferId, view: merge_view::MergeView) {
        self.merge_lines.insert(id, view.lines);
        let mut old_lines: Vec<(fenix_window::WindowId, usize)> = Vec::new();
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state(pane);
                if let Some(ob) = self.buffers.get(id) {
                    old_lines.push((pane, ob.buffer.line_col(&ps.cursor).0));
                }
            }
        }
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch, 0, end, &view.text);
        }
        let line_count = self.buffers.get(id).map(|ob| ob.buffer.visual_line_count()).unwrap_or(1);
        for (pane, old_line) in old_lines {
            let clamped = old_line.min(line_count.saturating_sub(1));
            let Some(ob) = self.buffers.get(id) else { continue };
            let char_idx = ob.buffer.line_start_char(clamped);
            self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
        }
    }

    /// `Enter` on the Conflicts pane: show that file in the right pane.
    pub(crate) fn merge_select_at_cursor(&mut self) {
        let Some(git_panel::GitEntry::File(path)) = self.git_entry_at_cursor() else {
            self.set_message("put the cursor on a conflicted file");
            return;
        };
        if let Some(session) = self.merge_session.as_mut() {
            session.selected = Some(path);
        }
        let merge_pane = self.merge_session.as_ref().map(|s| s.merge_pane);
        self.merge_refresh();
        if let Some(pane) = merge_pane {
            self.windows_mut().focus(pane);
        }
        self.wake_caret();
    }

    /// `o`/`t` on the Conflicts pane: resolve a whole file by taking one
    /// side, then stage it -- the "I already know which version wins"
    /// path.
    pub(crate) fn merge_take_whole_file(&mut self, side: fenix_git::Resolution) {
        let Some(session) = self.merge_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        let labels = session.labels.clone();
        let Some(git_panel::GitEntry::File(path)) = self.git_entry_at_cursor() else {
            self.set_message("put the cursor on a conflicted file");
            return;
        };
        let kept = match side {
            fenix_git::Resolution::Ours => labels.ours.clone(),
            fenix_git::Resolution::Theirs => labels.theirs.clone(),
            fenix_git::Resolution::Both => {
                self.set_error("keeping both is a per-conflict choice -- open the file with Enter".to_string());
                return;
            }
        };
        match fenix_git::checkout_side(&repo_root, &path, side) {
            // Named by branch, not by "ours"/"theirs": the point of
            // saying it back is to confirm the *right* version survived.
            Ok(_) => self.set_message(format!("{path}: kept {kept}'s version, staged")),
            Err(err) => self.set_error(format!("couldn't take that side: {err}")),
        }
        self.merge_refresh();
        self.reload_buffers_changed_on_disk();
        self.wake_caret();
    }

    /// `u`: puts the selected file back the way git first wrote it,
    /// markers and all -- the undo for a resolution that went the wrong
    /// way.
    pub(crate) fn merge_restore_conflict(&mut self) {
        let Some(session) = self.merge_session.as_ref() else { return };
        let (repo_root, selected) = (session.repo_root.clone(), session.selected.clone());
        let Some(path) = selected else {
            self.set_message("no file selected");
            return;
        };
        match fenix_git::restore_conflict(&repo_root, &path) {
            Ok(_) => self.set_message(format!("{path}: conflict restored")),
            Err(err) => self.set_error(err),
        }
        self.merge_refresh();
        self.reload_buffers_changed_on_disk();
        self.wake_caret();
    }

    /// `s`: stages the selected file as resolved. Refuses while markers
    /// are still in it -- staging a file with `<<<<<<<` in it is how
    /// conflict markers end up committed.
    pub(crate) fn merge_stage_resolved(&mut self) {
        let Some(session) = self.merge_session.as_ref() else {
            self.set_message("no Merge view open -- SPC g x opens it");
            return;
        };
        let (repo_root, selected) = (session.repo_root.clone(), session.selected.clone());
        let Some(path) = selected else {
            self.set_message("no file selected");
            return;
        };
        let full = repo_root.join(&path);
        if let Ok(text) = std::fs::read_to_string(&full) {
            let left = fenix_git::find_conflicts(&text).len();
            if left > 0 {
                self.set_error(format!("{path} still has {left} unresolved conflict(s)"));
                return;
            }
        }
        match fenix_git::stage_file(&repo_root, &path) {
            Ok(_) => self.set_message(format!("{path}: staged as resolved")),
            Err(err) => self.set_error(format!("couldn't stage {path}: {err}")),
        }
        self.merge_refresh();
        self.wake_caret();
    }

    /// The conflict the cursor is on in the Merge pane, if it's there.
    fn merge_conflict_at_cursor(&self) -> Option<usize> {
        let session = self.merge_session.as_ref()?;
        if self.focused_pane_id() != session.merge_pane {
            return None;
        }
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let lines = self.merge_lines.get(&session.merge_buffer)?;
        // A row between conflicts belongs to none, so fall forward to
        // the next one -- the same "act on the next one down" rule
        // `resolve_conflict_at_cursor` uses in a plain buffer.
        lines
            .get(line)
            .and_then(|l| l.as_ref())
            .and_then(|l| l.conflict)
            .or_else(|| lines.iter().skip(line).flatten().find_map(|l| l.conflict))
    }

    /// `SPC g o`/`t`/`b` inside the Merge view: resolve the conflict
    /// under the cursor, on disk, and re-render.
    ///
    /// Writes the file rather than a buffer because the Merge pane isn't
    /// the file -- it's a rendering of it. `u` restores the conflict if
    /// this was the wrong call.
    fn merge_resolve_at_cursor(&mut self, resolution: fenix_git::Resolution) -> bool {
        let Some(index) = self.merge_conflict_at_cursor() else { return false };
        let Some(session) = self.merge_session.as_ref() else { return false };
        let (repo_root, selected, labels) = (session.repo_root.clone(), session.selected.clone(), session.labels.clone());
        let Some(path) = selected else { return false };
        let full = repo_root.join(&path);
        let Ok(text) = std::fs::read_to_string(&full) else {
            self.set_error(format!("couldn't read {}", full.display()));
            return true;
        };
        let conflicts = fenix_git::find_conflicts(&text);
        let Some(conflict) = conflicts.get(index) else {
            self.set_error("that conflict is gone -- the file changed underneath this view".to_string());
            self.merge_refresh();
            return true;
        };
        let resolved = fenix_git::resolve_conflict(&text, conflict, resolution);
        if let Err(err) = std::fs::write(&full, &resolved) {
            self.set_error(format!("couldn't write {}: {err}", full.display()));
            return true;
        }
        let kept = match resolution {
            fenix_git::Resolution::Ours => labels.ours.clone(),
            fenix_git::Resolution::Theirs => labels.theirs.clone(),
            fenix_git::Resolution::Both => "both sides".to_string(),
        };
        let left = fenix_git::find_conflicts(&resolved).len();
        self.set_message(if left == 0 {
            format!("kept {kept} -- {path} is resolved, SPC g s stages it")
        } else {
            format!("kept {kept} -- {left} conflict(s) left in {path}")
        });
        self.merge_refresh();
        self.reload_buffers_changed_on_disk();
        self.wake_caret();
        true
    }

    /// `SPC g X`: closes the Merge view.
    pub(crate) fn merge_close(&mut self) {
        let Some(session) = self.merge_session.take() else { return };
        for id in [session.files_buffer, session.merge_buffer] {
            self.buffers.close(id);
            self.git_lines.remove(&id);
            self.merge_lines.remove(&id);
        }
        for pane in [session.files_pane, session.merge_pane] {
            self.pane_titles.remove(&pane);
        }
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    /// `SPC g r`: pick a ref to replay the current branch onto.
    pub(crate) fn start_rebase_picker(&mut self) {
        let repo_root = self.git_action_repo_root();
        let refs = self.compare_ref_candidates(&repo_root);
        if refs.len() <= 1 {
            self.set_error("no refs to rebase onto -- is this a git repository?".to_string());
            return;
        }
        let candidates = refs.into_iter().skip(1).map(|r| fenix_picker::Candidate::new(r.clone(), r)).collect();
        self.enter_picker(ActivePicker::RebaseOnto(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC g m`: pick a ref to merge into the current branch.
    pub(crate) fn start_merge_picker(&mut self) {
        let repo_root = self.git_action_repo_root();
        let refs = self.compare_ref_candidates(&repo_root);
        if refs.len() <= 1 {
            self.set_error("no refs to merge -- is this a git repository?".to_string());
            return;
        }
        let candidates = refs.into_iter().skip(1).map(|r| fenix_picker::Candidate::new(r.clone(), r)).collect();
        self.enter_picker(ActivePicker::MergeFrom(fenix_picker::PickerState::new(candidates)));
    }

    pub(crate) fn git_rebase_onto(&mut self, onto: &str) {
        let repo_root = self.git_action_repo_root();
        let result = fenix_git::rebase(&repo_root, onto);
        self.run_git_operation(&format!("rebase onto {onto}"), result);
    }

    pub(crate) fn git_merge_from(&mut self, branch: &str) {
        let repo_root = self.git_action_repo_root();
        let result = fenix_git::merge(&repo_root, branch);
        self.run_git_operation(&format!("merge {branch}"), result);
    }

    /// `SPC g R`: carries on whichever operation is suspended.
    ///
    /// One key for all of them because from the user's side it's one
    /// question -- "I've fixed it, keep going" -- and having to remember
    /// whether this was a rebase or a cherry-pick to pick the right key
    /// is exactly the friction the banner exists to remove.
    pub(crate) fn git_operation_continue(&mut self) {
        let repo_root = self.git_action_repo_root();
        let Some(op) = fenix_git::in_progress(&repo_root) else {
            self.set_error("nothing in progress to continue".to_string());
            return;
        };
        // Staging is the caller's job in git's model, and skipping it is
        // the single most common way `--continue` fails; say so rather
        // than surfacing git's own longer complaint.
        let unresolved = conflict_count(&fenix_git::list_files(&repo_root));
        if unresolved > 0 {
            self.set_error(format!("{unresolved} file(s) still conflicted -- resolve and stage them first"));
            return;
        }
        let result = match op {
            fenix_git::InProgress::Rebase { .. } => fenix_git::rebase_continue(&repo_root),
            fenix_git::InProgress::Merge => fenix_git::commit(&repo_root, "Merge"),
            fenix_git::InProgress::CherryPick | fenix_git::InProgress::Revert | fenix_git::InProgress::Bisect => {
                self.set_error(format!("{} can't be continued from here -- finish it with git", op.label()));
                return;
            }
        };
        self.run_git_operation("continue", result);
    }

    /// `SPC g A`: abandons whichever operation is suspended, putting the
    /// tree back where it started.
    pub(crate) fn git_operation_abort(&mut self) {
        let repo_root = self.git_action_repo_root();
        let Some(op) = fenix_git::in_progress(&repo_root) else {
            self.set_error("nothing in progress to abort".to_string());
            return;
        };
        let result = match op {
            fenix_git::InProgress::Rebase { .. } => fenix_git::rebase_abort(&repo_root),
            fenix_git::InProgress::Merge => fenix_git::merge_abort(&repo_root),
            fenix_git::InProgress::CherryPick | fenix_git::InProgress::Revert | fenix_git::InProgress::Bisect => {
                self.set_error(format!("{} can't be aborted from here -- finish it with git", op.label()));
                return;
            }
        };
        self.run_git_operation("abort", result);
    }

    /// `SPC g p`: pull, rebasing local commits on top rather than adding
    /// a merge commit for every sync.
    pub(crate) fn git_pull_rebase(&mut self) {
        let repo_root = self.git_action_repo_root();
        let result = fenix_git::pull_rebase(&repo_root);
        self.run_git_operation("pull --rebase", result);
    }

    /// `SPC g F`: push after a rebase rewrote history.
    ///
    /// Always `--force-with-lease`: it refuses if the remote moved since
    /// the last fetch, so it can't silently discard someone else's work.
    /// Confirmed first anyway, since it does rewrite a published branch.
    pub(crate) fn git_force_push(&mut self) {
        self.git_confirm = Some(GitConfirmAction::ForcePush);
    }

    // -- Conflict resolution in an ordinary file buffer -----------------

    /// The conflicts in the focused buffer, parsed fresh from its text.
    ///
    /// Recomputed on every use rather than cached: the buffer is a real,
    /// editable file that the user may have just hand-edited, and acting
    /// on stale line numbers would resolve the wrong region.
    fn focused_conflicts(&self) -> Vec<fenix_git::Conflict> {
        fenix_git::find_conflicts(&self.open().buffer.text())
    }

    /// `SPC g j`/`SPC g k`: move to the next/previous conflict in the
    /// focused file.
    pub(crate) fn goto_conflict(&mut self, forward: bool) {
        if self.merge_goto_conflict(forward) {
            return;
        }
        let conflicts = self.focused_conflicts();
        if conflicts.is_empty() {
            self.set_message("no conflict markers in this file");
            return;
        }
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let target = if forward {
            conflicts.iter().find(|c| c.start > line).or_else(|| conflicts.first())
        } else {
            conflicts.iter().rev().find(|c| c.end < line).or_else(|| conflicts.last())
        };
        let Some(target) = target else { return };
        let char_idx = self.open().buffer.line_start_char(target.start);
        let pane = self.focused_pane_id();
        self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
        self.wake_caret();
    }

    /// `SPC g j`/`SPC g k` inside the Merge view: jump to the next or
    /// previous conflict's separator row. Returns whether it applied,
    /// so the plain-buffer path can take over when it didn't.
    fn merge_goto_conflict(&mut self, forward: bool) -> bool {
        let Some(session) = self.merge_session.as_ref() else { return false };
        if self.focused_pane_id() != session.merge_pane {
            return false;
        }
        let Some(lines) = self.merge_lines.get(&session.merge_buffer) else { return true };
        // The separator row is the one to land on: it names the conflict
        // ("conflict 2 of 3") and sits directly above both columns.
        let starts: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.as_ref().is_some_and(|l| l.style == merge_view::MergeStyle::Separator))
            .map(|(i, _)| i)
            .collect();
        if starts.is_empty() {
            self.set_message("no conflicts left in this file");
            return true;
        }
        let line = self.open().buffer.line_col(&self.cursor()).0;
        // Wraps, like the plain-buffer path: there are only ever a
        // handful, and cycling beats being stuck at the last one.
        let target = if forward {
            starts.iter().find(|&&s| s > line).copied().unwrap_or(starts[0])
        } else {
            starts.iter().rev().find(|&&s| s < line).copied().unwrap_or(*starts.last().unwrap())
        };
        let char_idx = self.open().buffer.line_start_char(target);
        let pane = self.focused_pane_id();
        self.pane_state_mut(pane).cursor = Cursor { char_idx, sticky_col: 0 };
        self.wake_caret();
        true
    }

    /// `SPC g o`/`SPC g t`/`SPC g b`: resolve the conflict under the
    /// cursor by keeping ours, theirs, or both.
    ///
    /// Edits the buffer rather than the file on disk, so it lands in the
    /// undo history like any other edit and isn't written until the
    /// buffer is saved -- a mistaken choice is one `u` away.
    pub(crate) fn resolve_conflict_at_cursor(&mut self, resolution: fenix_git::Resolution) {
        // Same keys in the Merge view, where the "buffer" is a rendering
        // of the file rather than the file, so the edit goes to disk.
        // One pair of keys for one decision, wherever you happen to be
        // looking at the conflict from.
        if self.merge_resolve_at_cursor(resolution) {
            return;
        }
        let conflicts = self.focused_conflicts();
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let Some(conflict) = conflicts.iter().find(|c| c.contains(line)).or_else(|| conflicts.iter().find(|c| c.start > line)) else {
            self.set_error("no conflict under the cursor".to_string());
            return;
        };
        let text = self.open().buffer.text();
        let resolved = fenix_git::resolve_conflict(&text, conflict, resolution);
        let start_char = self.open().buffer.line_start_char(conflict.start);

        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let end = buffer.len_chars();
        let mut scratch = Cursor::at_start();
        buffer.replace_range(&mut scratch, 0, end, &resolved);
        // Land on where the conflict was, so the next one is a `SPC g j`
        // away rather than needing the file re-navigated.
        cursor.char_idx = start_char.min(buffer.len_chars());
        cursor.sticky_col = 0;

        let kept = match resolution {
            fenix_git::Resolution::Ours => "ours",
            fenix_git::Resolution::Theirs => "theirs",
            fenix_git::Resolution::Both => "both sides",
        };
        let left = fenix_git::find_conflicts(&self.open().buffer.text()).len();
        self.set_message(format!("kept {kept} -- {left} conflict(s) left in this file"));
        self.wake_caret();
    }

    // -- History view (`SPC g l`) ------------------------------------------

    /// `SPC g l`: opens (or refocuses and refreshes) the History view --
    /// the commit graph across *every* branch, a refs tree showing how
    /// each local branch stands against its upstream, and the selected
    /// commit's diff in the shared diff viewer.
    pub(crate) fn open_history_view(&mut self) {
        if let Some(session) = &self.history_session {
            let (workspace_index, graph_pane) = (session.workspace_index, session.graph_pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(graph_pane);
            self.history_refresh();
            self.wake_caret();
            return;
        }

        let repo_root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
        let graph_buffer = self.buffers.open_graph("");
        let refs_buffer = self.buffers.open_git("");
        let detail_view = diff_view::render(&[], &HashSet::new());
        let detail_buffer = self.buffers.open_diff(&detail_view.text);
        self.diff_lines.insert(detail_buffer, detail_view.lines);

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(graph_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let graph_pane = self.focused_pane_id();

        // Graph on the left, refs above the commit's diff on the right --
        // the graph is the thing being read, so it keeps the larger
        // share, same proportions the Docker panel's own list/detail
        // split already uses.
        let detail_pane = self.windows_mut().split(SplitKind::Vertical, detail_buffer);
        self.workspaces.active_pane_states_mut().insert(detail_pane, PaneState::seeded_at(cursor));
        // `resize_focused` adjusts the *first* child's share of the
        // nearest split whichever side is focused, so this gives the
        // graph 40% and the right-hand column 60%, where the diffs are.
        self.windows_mut().resize_focused(-0.1);
        let refs_pane = self.windows_mut().split(SplitKind::Horizontal, refs_buffer);
        self.workspaces.active_pane_states_mut().insert(refs_pane, PaneState::seeded_at(cursor));
        // Commit detail (the split's first child) takes three quarters:
        // it holds a whole diff, while the refs tree is a short list
        // that only ever needs a handful of rows.
        self.windows_mut().resize_focused(0.25);
        self.windows_mut().focus(graph_pane);

        self.pane_titles.insert(graph_pane, "1. Graph".to_string());
        self.pane_titles.insert(refs_pane, "2. Refs".to_string());
        self.pane_titles.insert(detail_pane, "3. Commit".to_string());

        self.history_session = Some(HistorySession {
            workspace_index,
            graph_pane,
            refs_pane,
            detail_pane,
            graph_buffer,
            refs_buffer,
            detail_buffer,
            repo_root,
            commits: Vec::new(),
            last_detail_commit: None,
            detail_request_id: 0,
        });
        self.history_refresh();
        self.wake_caret();
    }

    /// Re-reads the graph and the refs tree from disk. Synchronous: a
    /// `git log`/`for-each-ref` pair against a local repo is fast, and
    /// unlike a fetch it never touches the network -- the same reasoning
    /// `open_git_panel` already applies to its own listings.
    fn history_refresh(&mut self) {
        let Some(session) = self.history_session.as_ref() else { return };
        let (repo_root, graph_buffer, refs_buffer) = (session.repo_root.clone(), session.graph_buffer, session.refs_buffer);

        let commits = fenix_git::commit_graph(&repo_root, self.config.git_graph_limit.unwrap_or(200));
        let rows = fenix_git::assign_lanes(&commits);
        let style = graph_view::GraphStyle::from_config(self.config.git_graph_style.as_deref());
        let panel = graph_view::render_graph(&commits, &rows, style);
        self.graph_lines.insert(graph_buffer, panel.lines);
        self.replace_buffer_text(graph_buffer, &panel.text);

        let branches = fenix_git::list_branches(&repo_root);
        let remotes = fenix_git::list_remote_branches(&repo_root);
        let tags = fenix_git::list_tags(&repo_root);
        let age = fenix_git::seconds_since_fetch(&repo_root);
        self.set_git_buffer(refs_buffer, graph_view::render_refs(&branches, &remotes, &tags, age));

        if let Some(session) = self.history_session.as_mut() {
            session.commits = commits;
            session.last_detail_commit = None; // force the detail pane to re-fetch
        }
        self.history_sync_detail();
    }

    /// `1`/`2`/`3` in the History view, matching the pane titles -- the
    /// same jump-to-pane shortcut the Docker and Git panels already
    /// advertise in theirs.
    fn history_pane_by_number(&self, n: u32) -> Option<fenix_window::WindowId> {
        let session = self.history_session.as_ref()?;
        match n {
            1 => Some(session.graph_pane),
            2 => Some(session.refs_pane),
            3 => Some(session.detail_pane),
            _ => None,
        }
    }

    /// `1`/`2` in the Compare view.
    fn merge_pane_by_number(&self, n: u32) -> Option<fenix_window::WindowId> {
        let session = self.merge_session.as_ref()?;
        match n {
            1 => Some(session.files_pane),
            2 => Some(session.merge_pane),
            _ => None,
        }
    }

    fn compare_pane_by_number(&self, n: u32) -> Option<fenix_window::WindowId> {
        let session = self.compare_session.as_ref()?;
        match n {
            1 => Some(session.commits_pane),
            2 => Some(session.diff_pane),
            _ => None,
        }
    }

    /// Whether the focused diff is one with no index relationship to
    /// change -- a commit, a stash, or a ref comparison.
    fn focused_diff_is_read_only(&self) -> bool {
        self.focused_diff_buffer().and_then(|id| self.diff_models.get(&id)).is_some_and(|m| m.source == DiffSource::ReadOnly)
    }

    /// The commit the cursor is on in the Graph pane, if that's where it
    /// is.
    fn history_commit_at_cursor(&self) -> Option<String> {
        let session = self.history_session.as_ref()?;
        if self.focused_pane_id() != session.graph_pane {
            return None;
        }
        let line = self.open().buffer.line_col(&self.cursor()).0;
        self.graph_lines.get(&session.graph_buffer)?.get(line)?.as_ref()?.commit.clone()
    }

    /// Fetches the selected commit's diff into the detail pane, skipping
    /// the work when the cursor hasn't moved to a different commit --
    /// same shape as `git_sync_main`, including its synchronous fallback
    /// when there's no `event_proxy` (every test).
    fn history_sync_detail(&mut self) {
        let Some(session) = self.history_session.as_ref() else { return };
        let commit = match self.history_commit_at_cursor() {
            Some(hash) => Some(hash),
            // The graph's connector rows (`|\`, `|/`) draw no commit of
            // their own. Scrolling across one must not yank the detail
            // pane back to the newest commit -- keep showing whatever
            // was selected.
            None if session.last_detail_commit.is_some() => return,
            // Nothing selected yet (the view just opened): show the
            // newest commit rather than an empty pane.
            None => session.commits.first().map(|c| c.hash.clone()),
        };
        if commit == session.last_detail_commit {
            return;
        }
        let (repo_root, detail_buffer) = (session.repo_root.clone(), session.detail_buffer);
        let Some(session) = self.history_session.as_mut() else { return };
        session.last_detail_commit = commit.clone();
        session.detail_request_id += 1;
        let request_id = session.detail_request_id;

        let Some(hash) = commit else {
            self.set_diff_buffer(detail_buffer, None, DiffSource::ReadOnly, &repo_root);
            return;
        };

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let detail = commit_detail(&repo_root, &hash);
                    let _ = proxy.send_event(FenixUserEvent::GitHistoryDetailReady { request_id, buffer: detail_buffer, diff: detail });
                });
            }
            None => {
                let detail = commit_detail(&repo_root, &hash);
                self.apply_history_detail(request_id, detail_buffer, detail);
            }
        }
    }

    /// `FenixUserEvent::GitHistoryDetailReady` handling -- drops a result
    /// a newer request has superseded, exactly as `apply_git_main` does.
    fn apply_history_detail(&mut self, request_id: u64, buffer: BufferId, diff: Option<CommitDetail>) {
        let Some(session) = self.history_session.as_ref() else { return };
        if session.detail_request_id != request_id {
            return;
        }
        let repo_root = session.repo_root.clone();
        let (header, diff) = match diff {
            Some(detail) => (commit_header_rows(&detail.meta), Some(detail.diff)),
            None => (Vec::new(), None),
        };
        self.set_diff_buffer_with_header(buffer, &header, diff.as_deref(), DiffSource::ReadOnly, &repo_root);
    }

    /// `SPC g f`: `git fetch --all --prune`, off the input thread since
    /// it touches the network. Refreshes whichever Git views are open
    /// once it lands, so the sync badges reflect what was just fetched.
    pub(crate) fn git_fetch(&mut self) {
        let repo_root = self
            .history_session
            .as_ref()
            .map(|s| s.repo_root.clone())
            .or_else(|| self.git_session.as_ref().map(|s| s.repo_root.clone()))
            .or_else(|| self.project_root.clone())
            .unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));

        match self.event_proxy.clone() {
            Some(proxy) => {
                self.set_message("fetching...");
                std::thread::spawn(move || {
                    let result = fenix_git::fetch(&repo_root);
                    let _ = proxy.send_event(FenixUserEvent::GitFetched { result });
                });
            }
            None => {
                let result = fenix_git::fetch(&repo_root);
                self.apply_git_fetched(result);
            }
        }
    }

    fn apply_git_fetched(&mut self, result: Result<String, String>) {
        match result {
            Ok(_) => self.set_message("fetched"),
            Err(err) => self.set_error(format!("fetch failed: {}", err.trim())),
        }
        if self.history_session.is_some() {
            self.history_refresh();
        }
        if self.git_session.is_some() {
            self.git_refresh_session();
        }
    }

    // -- Compare view (`SPC g c`) ------------------------------------------

    /// Every ref that can be compared: local branches, remote-tracking
    /// branches, tags. `HEAD` leads the list, since "what does my
    /// working checkout add" is the overwhelmingly common question.
    fn compare_ref_candidates(&self, repo_root: &Path) -> Vec<String> {
        let mut refs = vec!["HEAD".to_string()];
        refs.extend(fenix_git::list_branches(repo_root).into_iter().map(|b| b.name));
        refs.extend(fenix_git::list_remote_branches(repo_root));
        refs.extend(fenix_git::list_tags(repo_root));
        refs
    }

    fn compare_repo_root(&self) -> PathBuf {
        self.compare_session
            .as_ref()
            .map(|s| s.repo_root.clone())
            .or_else(|| self.git_session.as_ref().map(|s| s.repo_root.clone()))
            .or_else(|| self.project_root.clone())
            .unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")))
    }

    /// `SPC g c`: pick the ref to compare against, then the ref to
    /// compare. Two pickers rather than one prompt so both halves get
    /// fuzzy matching over the repo's real refs.
    ///
    /// The base list is ordered with `[git] base_branch` (default
    /// `main`) first when it exists, since "how does this differ from
    /// the mainline" is the question being asked most of the time.
    pub(crate) fn start_compare_picker(&mut self) {
        let repo_root = self.compare_repo_root();
        let mut refs = self.compare_ref_candidates(&repo_root);
        if refs.len() <= 1 {
            self.set_error("no refs to compare -- is this a git repository?".to_string());
            return;
        }
        // Lead with a mainline that actually exists. `[git] base_branch`
        // first, then the two conventional names -- a repo on `master`
        // would otherwise fall through to `HEAD` leading the list, and
        // then Enter-Enter compares HEAD against HEAD and reports
        // nothing, which reads as the feature being broken rather than
        // as "you compared a ref with itself".
        let preferred: Vec<String> = self
            .config
            .git_base_branch
            .clone()
            .into_iter()
            .chain(["main".to_string(), "master".to_string()])
            .collect();
        if let Some(i) = preferred.iter().find_map(|p| refs.iter().position(|r| r == p)) {
            let base = refs.remove(i);
            refs.insert(0, base);
        }
        let candidates = refs.into_iter().map(|r| fenix_picker::Candidate::new(r.clone(), r)).collect();
        self.enter_picker(ActivePicker::CompareBase(fenix_picker::PickerState::new(candidates)));
    }

    /// `CompareBase`'s confirm: remembers the base and asks for the head.
    fn compare_pick_head(&mut self, base: String) {
        let repo_root = self.compare_repo_root();
        let candidates = self.compare_ref_candidates(&repo_root).into_iter().map(|r| fenix_picker::Candidate::new(r.clone(), r)).collect();
        self.enter_picker(ActivePicker::CompareHead { base, picker: fenix_picker::PickerState::new(candidates) });
    }

    /// Opens (or retargets) the Compare view for `base` vs `head`.
    pub(crate) fn open_compare_view(&mut self, base: String, head: String) {
        let repo_root = self.compare_repo_root();
        if let Some(session) = self.compare_session.as_mut() {
            session.base = base;
            session.head = head;
            let (workspace_index, commits_pane) = (session.workspace_index, session.commits_pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(commits_pane);
            self.compare_refresh();
            self.wake_caret();
            return;
        }

        let commits_buffer = self.buffers.open_git("");
        let empty = diff_view::render(&[], &HashSet::new());
        let diff_buffer = self.buffers.open_diff(&empty.text);
        self.diff_lines.insert(diff_buffer, empty.lines);

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(commits_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let commits_pane = self.focused_pane_id();
        let diff_pane = self.windows_mut().split(SplitKind::Vertical, diff_buffer);
        self.workspaces.active_pane_states_mut().insert(diff_pane, PaneState::seeded_at(cursor));
        // The commit list is narrow; the diff is what's being read.
        // Negative: the delta grows the split's *first* child, which is
        // the list.
        self.windows_mut().resize_focused(-0.35);
        self.windows_mut().focus(commits_pane);

        self.pane_titles.insert(commits_pane, "1. Commits".to_string());
        self.pane_titles.insert(diff_pane, "2. Changes".to_string());

        self.compare_session =
            Some(CompareSession { workspace_index, commits_pane, diff_pane, commits_buffer, diff_buffer, repo_root, base, head, three_dot: true });
        self.compare_refresh();
        self.wake_caret();
    }

    /// Re-runs the comparison and re-renders both panes.
    fn compare_refresh(&mut self) {
        let Some(session) = self.compare_session.as_ref() else { return };
        let (repo_root, base, head, three_dot) = (session.repo_root.clone(), session.base.clone(), session.head.clone(), session.three_dot);
        let (commits_buffer, diff_buffer) = (session.commits_buffer, session.diff_buffer);

        const COMMIT_LIMIT: usize = 200;
        let commits = fenix_git::commits_between(&repo_root, &base, &head, COMMIT_LIMIT);
        let dots = if three_dot { "..." } else { ".." };
        self.set_git_buffer(
            commits_buffer,
            git_panel::render_compare(&format!("{base}{dots}{head}"), &commits, commits.len() >= COMMIT_LIMIT),
        );

        // A comparison against a ref git doesn't know has to be loud.
        // Rendered into the pane, not just flashed in the modeline: an
        // empty diff pane beside an error that has already scrolled past
        // reads as "these refs are identical", which is a completely
        // different answer from "one of those isn't a ref".
        match fenix_git::diff_refs(&repo_root, &base, &head, three_dot) {
            Ok(diff) => self.set_diff_buffer(diff_buffer, Some(&diff), DiffSource::ReadOnly, &repo_root),
            Err(err) => {
                let mut rows = vec![(format!("couldn't compare {base}{dots}{head}"), diff_view::DiffStyle::Removed)];
                rows.extend(err.trim().lines().map(|l| (format!("  {l}"), diff_view::DiffStyle::Meta)));
                self.set_diff_buffer_message(diff_buffer, &rows, &repo_root);
                self.set_error(err.trim().to_string());
            }
        }
    }

    /// `t` in the Compare view: three-dot (what `head` added since it
    /// diverged) vs two-dot (every difference between the two trees).
    pub(crate) fn compare_toggle_dots(&mut self) {
        let Some(session) = self.compare_session.as_mut() else { return };
        session.three_dot = !session.three_dot;
        let now = if session.three_dot { "base...head (since diverging)" } else { "base..head (full difference)" };
        self.set_message(now);
        self.compare_refresh();
        self.wake_caret();
    }

    /// `SPC g C`: closes the Compare view.
    pub(crate) fn compare_close(&mut self) {
        let Some(session) = self.compare_session.take() else { return };
        for id in [session.commits_buffer, session.diff_buffer] {
            self.buffers.close(id);
            self.git_lines.remove(&id);
            self.diff_lines.remove(&id);
            self.diff_models.remove(&id);
        }
        for pane in [session.commits_pane, session.diff_pane] {
            self.pane_titles.remove(&pane);
        }
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    /// `SPC g L`: closes the History view.
    pub(crate) fn history_close(&mut self) {
        let Some(session) = self.history_session.take() else { return };
        for id in [session.graph_buffer, session.refs_buffer, session.detail_buffer] {
            self.buffers.close(id);
            self.git_lines.remove(&id);
            self.graph_lines.remove(&id);
            self.diff_lines.remove(&id);
            self.diff_models.remove(&id);
        }
        for pane in [session.graph_pane, session.refs_pane, session.detail_pane] {
            self.pane_titles.remove(&pane);
        }
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    /// Replaces a generated buffer's whole text, resetting every pane
    /// showing it to the top -- the shared half of `set_git_buffer`/
    /// `set_diff_buffer`, for buffers whose metadata was already stored
    /// by the caller.
    fn replace_buffer_text(&mut self, id: BufferId, text: &str) {
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, text);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    /// `SPC g q`: closes the whole Git session -- mirrors
    /// `docker_session_close` exactly.
    pub(crate) fn git_session_close(&mut self) {
        let Some(session) = self.git_session.take() else { return };
        for id in [
            session.status_buffer,
            session.staged_buffer,
            session.unstaged_buffer,
            session.branches_buffer,
            session.commits_buffer,
            session.stash_buffer,
            session.main_buffer,
        ] {
            self.buffers.close(id);
            self.git_lines.remove(&id);
            self.diff_lines.remove(&id);
            self.diff_models.remove(&id);
        }
        for pane in [
            session.status_pane,
            session.staged_pane,
            session.unstaged_pane,
            session.branches_pane,
            session.commits_pane,
            session.stash_pane,
            session.main_pane,
        ] {
            self.pane_titles.remove(&pane);
        }
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.refresh_project_root();
        self.wake_caret();
    }

    /// Modeline text while a Git destructive action is armed -- mirrors
    /// `docker_confirm_text`.
    fn git_confirm_text(&self) -> Option<String> {
        let action = self.git_confirm.as_ref()?;
        Some(match action {
            GitConfirmAction::DiscardFile { path, .. } => format!("Discard changes to {path}? (y/n)"),
            GitConfirmAction::DiscardDir { path } => format!("Discard all changes under {path}/? (y/n)"),
            GitConfirmAction::DeleteBranch { name } => format!("Delete branch {name}? (y/n)"),
            GitConfirmAction::DropStash { index } => format!("Drop stash@{{{index}}}? (y/n)"),
            GitConfirmAction::ForcePush => "Force-push (with lease), rewriting the remote branch? (y/n)".to_string(),
            GitConfirmAction::DiscardHunk { buffer, anchor } => {
                let path = self
                    .diff_models
                    .get(buffer)
                    .and_then(|m| m.files.get(anchor.file))
                    .map(|f| f.display_path().to_string())
                    .unwrap_or_else(|| "this file".to_string());
                format!("Discard this hunk of {path}? (y/n)")
            }
        })
    }

    /// Resolves an armed Git destructive action: `y` confirms and runs
    /// it, anything else cancels. Mirrors `docker_confirm_key`.
    fn git_confirm_key(&mut self, keypress: KeyPress) {
        let action = self.git_confirm.take();
        if keypress.code == KeyCode::Char('y') {
            if let (Some(action), Some(session)) = (action, self.git_session.as_ref()) {
                let repo_root = session.repo_root.clone();
                let result = match action {
                    GitConfirmAction::DiscardFile { path, untracked } => fenix_git::discard_file(&repo_root, &path, untracked),
                    GitConfirmAction::DiscardDir { path } => fenix_git::discard_dir(&repo_root, &path),
                    GitConfirmAction::DeleteBranch { name } => fenix_git::delete_branch(&repo_root, &name, false),
                    GitConfirmAction::DropStash { index } => fenix_git::stash_drop(&repo_root, index),
                    GitConfirmAction::ForcePush => fenix_git::push_force_with_lease(&repo_root),
                    GitConfirmAction::DiscardHunk { buffer, anchor } => self.hunk_patch_for(buffer, anchor).map_or_else(
                        || Err("that hunk is no longer in the diff".to_string()),
                        |patch| fenix_git::apply_patch(&repo_root, &patch, fenix_git::ApplyTarget::Discard),
                    ),
                };
                if let Err(err) = result {
                    self.set_error(format!("git action failed: {err}"));
                }
                self.git_refresh_session();
            }
        }
        self.wake_caret();
    }

    /// What to show in place of the modeline while `git_prompt` is
    /// active -- mirrors `explorer_prompt_text`.
    fn git_prompt_text(&self) -> Option<String> {
        let prompt = self.git_prompt.as_ref()?;
        Some(match prompt.kind {
            GitPromptKind::NewBranch => format!("New branch name: {}", prompt.input),
        })
    }

    /// Mirrors `explorer_prompt_key`'s text-accumulation shape exactly.
    fn git_prompt_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(prompt), Some(text)) = (&mut self.git_prompt, pasted) {
                prompt.input.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some(prompt) = &mut self.git_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.git_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let GitPrompt { kind, input } = self.git_prompt.take().unwrap();
                self.git_prompt_submit(kind, &input);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                prompt.input.pop();
            }
            KeyCode::Char(c) => prompt.input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    fn git_prompt_submit(&mut self, kind: GitPromptKind, input: &str) {
        if input.trim().is_empty() {
            return;
        }
        let Some(session) = self.git_session.as_ref() else { return };
        let repo_root = session.repo_root.clone();
        let result = match kind {
            GitPromptKind::NewBranch => fenix_git::create_branch(&repo_root, input),
        };
        if let Err(err) = result {
            self.set_error(format!("git operation failed: {err}"));
        }
        self.git_refresh_session();
    }

    /// `SPC j j`: opens (or refocuses) the Jira dashboard -- mirrors
    /// `open_git_panel`'s WindowTree-split recipe, just four panes
    /// instead of seven and no background poller (see `JiraSession`'s
    /// own doc comment for why). Left to right: Projects | Users |
    /// Issues | Detail -- Issues is the main/widest pane, same
    /// "narrowest/most-filtering to widest/most-detail" cascade `open_
    /// git_panel`'s own Files/Branches/Commits/Stash -> Main already
    /// uses. `tracked_projects`/`tracked_users` are seeded fresh from
    /// `Config` every time this runs (including on refocus), so an edit
    /// made to `config.ini` by hand between sessions shows up too.
    pub(crate) fn open_jira_panel(&mut self) {
        if let Some(session) = &self.jira_session {
            let (workspace_index, projects_pane) = (session.workspace_index, session.projects_pane);
            self.workspaces.switch_to_index(workspace_index);
            self.windows_mut().focus(projects_pane);
            self.wake_caret();
            return;
        }

        let tracked_projects = self.config.jira_projects.clone();
        let tracked_users = self.config.jira_users.clone();

        let projects_panel = jira_panel::render_projects(&tracked_projects);
        let users_panel = jira_panel::render_users(&tracked_users);
        let issues_panel = jira_panel::render_issues(&[]);
        let detail_panel = jira_panel::render_detail(None);

        let projects_buffer = self.buffers.open_jira(&projects_panel.text);
        let users_buffer = self.buffers.open_jira(&users_panel.text);
        let issues_buffer = self.buffers.open_jira(&issues_panel.text);
        let detail_buffer = self.buffers.open_jira(&detail_panel.text);
        self.jira_lines.insert(projects_buffer, projects_panel.lines);
        self.jira_lines.insert(users_buffer, users_panel.lines);
        self.jira_lines.insert(issues_buffer, issues_panel.lines);
        self.jira_lines.insert(detail_buffer, detail_panel.lines);

        let cursor = Cursor::at_start();
        self.workspaces.new_workspace(projects_buffer, cursor);
        let workspace_index = self.workspaces.active_index();
        let projects_pane = self.focused_pane_id();

        // Right column first, at the outer split -- Detail gets the
        // same ~15% narrower-than-half share `open_git_panel`'s own
        // Main pane carves out, for the same reason: list rows don't
        // need much width, a detail view does.
        let detail_pane = self.windows_mut().split(SplitKind::Vertical, detail_buffer);
        self.workspaces.active_pane_states_mut().insert(detail_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-0.15);

        // Left column: Projects/Users/Issues stacked. Projects is
        // shrunk below the default 50/50 split (it's a short hand-typed
        // list, not the main content); Users keeps the biggest
        // remaining share "for free," Issues takes half of what's left
        // -- same cascade `open_git_panel`'s own Status/Staged split
        // uses.
        self.windows_mut().focus(projects_pane);
        let users_pane = self.windows_mut().split(SplitKind::Horizontal, users_buffer);
        self.workspaces.active_pane_states_mut().insert(users_pane, PaneState::seeded_at(cursor));
        self.windows_mut().resize_focused(-0.35);
        let issues_pane = self.windows_mut().split(SplitKind::Horizontal, issues_buffer);
        self.workspaces.active_pane_states_mut().insert(issues_pane, PaneState::seeded_at(cursor));
        self.windows_mut().focus(projects_pane);

        self.pane_titles.insert(projects_pane, "1. Projects".to_string());
        self.pane_titles.insert(users_pane, "2. Users".to_string());
        self.pane_titles.insert(issues_pane, "3. Issues".to_string());
        self.pane_titles.insert(detail_pane, "4. Detail".to_string());

        self.jira_session = Some(JiraSession {
            workspace_index,
            projects_pane,
            users_pane,
            issues_pane,
            detail_pane,
            projects_buffer,
            users_buffer,
            issues_buffer,
            detail_buffer,
            tracked_projects,
            tracked_users,
            issues: Vec::new(),
            detail: None,
            last_selected_user: None,
            issues_request_id: 0,
            last_selected_issue: None,
            detail_request_id: 0,
            transitions_request_id: 0,
            priorities_request_id: 0,
            known_statuses: HashSet::new(),
            excluded_statuses: Vec::new(),
        });

        self.wake_caret();
    }

    /// `SPC j q`: closes the Jira dashboard session -- mirrors `git_
    /// session_close` exactly (no poller to stop, unlike Docker/Git).
    pub(crate) fn jira_session_close(&mut self) {
        let Some(session) = self.jira_session.take() else { return };
        // A mid-flight `c`/`e` edit holds a scratch buffer pointed at
        // from one of this session's own panes -- closing the whole
        // panel out from under it must not leave that buffer orphaned.
        // No pane restore needed here (the panes themselves are about to
        // go away with the workspace below), so this is just the buffer
        // cleanup half of `jira_edit_restore`. The status filter is a
        // picker now (`ActivePicker::JiraStatusFilter`), not a buffer --
        // no cleanup needed here for it.
        if let Some(edit) = self.jira_edit.take() {
            self.buffers.close(edit.edit_buffer);
        }
        for id in [session.projects_buffer, session.users_buffer, session.issues_buffer, session.detail_buffer] {
            self.buffers.close(id);
            self.jira_lines.remove(&id);
        }
        for pane in [session.projects_pane, session.users_pane, session.issues_pane, session.detail_pane] {
            self.pane_titles.remove(&pane);
        }
        self.workspaces.switch_to_index(session.workspace_index);
        self.workspaces.remove_active();
        self.wake_caret();
    }

    /// Rewrites `id`'s buffer text from a freshly-rendered `JiraPanel`,
    /// resetting every pane currently showing it back to the top --
    /// mirrors `set_git_buffer`.
    fn set_jira_buffer(&mut self, id: BufferId, panel: jira_panel::JiraPanel) {
        self.jira_lines.insert(id, panel.lines);
        if let Some(ob) = self.buffers.get_mut(id) {
            let end = ob.buffer.len_chars();
            let mut scratch_cursor = Cursor::at_start();
            ob.buffer.replace_range(&mut scratch_cursor, 0, end, &panel.text);
        }
        for pane in self.windows().windows() {
            if self.windows().content(pane) == Some(&id) {
                let ps = self.pane_state_mut(pane);
                *ps = PaneState::seeded_at(Cursor::at_start());
            }
        }
    }

    fn jira_focused_role(&self) -> Option<JiraPaneRole> {
        let session = self.jira_session.as_ref()?;
        if self.workspaces.active_index() != session.workspace_index {
            return None;
        }
        let focused = self.focused_pane_id();
        if focused == session.projects_pane {
            Some(JiraPaneRole::Projects)
        } else if focused == session.users_pane {
            Some(JiraPaneRole::Users)
        } else if focused == session.issues_pane {
            Some(JiraPaneRole::Issues)
        } else if focused == session.detail_pane {
            Some(JiraPaneRole::Detail)
        } else {
            None
        }
    }

    /// Whether `route_keypress`'s Jira pane-scoped action-key block
    /// (digit-jump, `t`/`T`/`c`/`e`/`l`/`f`) should fire for the current
    /// keypress -- a real Jira pane is focused *and* no `c`/`e` edit is
    /// in progress. Factored out (rather than inlined at the one
    /// `route_keypress` call site) so this load-bearing guard has its
    /// own direct unit-test coverage: `route_keypress` itself can't be
    /// exercised in tests (needs a live `&ActiveEventLoop`, which
    /// nothing in this harness can construct -- see `test_route_key`'s
    /// own doc comment), so this is what a test asserts against instead.
    fn jira_pane_action_keys_active(&self) -> bool {
        self.jira_focused_role().is_some() && self.jira_edit.is_none()
    }

    /// The pane whose title bar is numbered `n` (`1. Projects` etc.,
    /// see `open_jira_panel`'s own title strings) -- mirrors `git_pane_
    /// by_number`, backs the same digit-key jump-to-pane shortcut.
    fn jira_pane_by_number(&self, n: u32) -> Option<fenix_window::WindowId> {
        let session = self.jira_session.as_ref()?;
        match n {
            1 => Some(session.projects_pane),
            2 => Some(session.users_pane),
            3 => Some(session.issues_pane),
            4 => Some(session.detail_pane),
            _ => None,
        }
    }

    /// What the cursor's current line on a Jira buffer targets --
    /// mirrors `git_entry_at_cursor`.
    fn jira_entry_at_cursor(&self) -> Option<jira_panel::JiraEntry> {
        let cursor = self.cursor();
        let line = self.open().buffer.line_col(&cursor).0;
        self.jira_lines.get(&self.focused_buffer_id()).and_then(|lines| lines.get(line)).and_then(|meta| meta.as_ref()).and_then(|meta| meta.entry.clone())
    }

    /// A ready-to-use `fenix_jira::JiraClient` built from `Config`'s
    /// `[jira]` settings, or `None` (with a surfaced error) when either
    /// `base_url` or `token` isn't configured yet.
    fn jira_client(&mut self) -> Option<fenix_jira::JiraClient> {
        let base_url = self.config.jira_base_url.clone();
        let token = self.config.jira_token.clone();
        match (base_url, token) {
            (Some(base_url), Some(token)) => Some(fenix_jira::JiraClient::new(base_url, token)),
            _ => {
                self.set_error("Jira isn't configured yet: set base_url/token in the [jira] section of config.ini");
                None
            }
        }
    }

    /// Re-fetches Issues from whichever row is now under the cursor in
    /// Users -- a no-op when the cursor hasn't actually moved to a
    /// *different* user, **and** a no-op whenever the Users pane isn't
    /// what's actually focused right now (`jira_entry_at_cursor` reads
    /// the *focused* pane's cursor, so this is only ever meaningful from
    /// there). Purely a cursor-reading wrapper -- the real fetch is
    /// `jira_fetch_issues`, shared with `jira_force_fetch_issues` for
    /// contexts that need to refetch regardless of what's focused (`SPC
    /// j r`, the status filter being applied, a completed write action's
    /// own refresh -- none of which necessarily run with Users focused).
    fn jira_sync_issues(&mut self) {
        let selected_user = match self.jira_entry_at_cursor() {
            Some(jira_panel::JiraEntry::User(id)) => Some(id),
            _ => return,
        };
        let Some(session) = self.jira_session.as_ref() else { return };
        if selected_user == session.last_selected_user {
            return;
        }
        self.jira_fetch_issues(selected_user);
    }

    /// Force-refetches Issues for `session.last_selected_user` -- the
    /// user already tracked as selected, independent of which pane
    /// currently has focus (unlike `jira_sync_issues`, which only ever
    /// does anything while the Users pane itself is focused). What `SPC
    /// j r`, the status-filter picker's own apply, and every completed
    /// write action's refresh (`apply_jira_action_done`) actually need:
    /// those can all run while Issues or Detail has focus, where `jira_
    /// sync_issues` would silently no-op.
    fn jira_force_fetch_issues(&mut self) {
        let Some(session) = self.jira_session.as_ref() else { return };
        let user_id = session.last_selected_user.clone();
        self.jira_fetch_issues(user_id);
    }

    /// The actual fetch, independent of what's focused or of any
    /// "did the selection change" dedup -- always refetches `user_id`
    /// (mirrors `git_sync_main`'s own background-thread-for-a-real-app/
    /// synchronous-for-tests split via `self.event_proxy`). `None`
    /// bumps the request id (invalidating any older in-flight fetch)
    /// without starting a new one, leaving Issues showing whatever it
    /// last had -- same as before this was split out of `jira_sync_
    /// issues`.
    fn jira_fetch_issues(&mut self, user_id: Option<String>) {
        let Some(client) = self.jira_client() else { return };
        let Some(session) = self.jira_session.as_mut() else { return };
        session.last_selected_user = user_id.clone();
        session.issues_request_id += 1;
        let request_id = session.issues_request_id;
        let project_keys: Vec<String> = session.tracked_projects.iter().map(|(key, _)| key.clone()).collect();
        let excluded_statuses = session.excluded_statuses.clone();
        let Some(user_id) = user_id else { return };
        let jql = fenix_jira::build_jql(&user_id, &project_keys, &excluded_statuses);

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let issues = client.search_issues(&jql, 50);
                    let _ = proxy.send_event(FenixUserEvent::JiraIssuesReady { request_id, issues });
                });
            }
            None => {
                let issues = client.search_issues(&jql, 50);
                self.apply_jira_issues(request_id, issues);
            }
        }
    }

    /// `FenixUserEvent::JiraIssuesReady` handling: applies a completed
    /// background issue search, unless a newer request has since
    /// superseded it (mirrors `apply_git_main`'s own staleness guard).
    fn apply_jira_issues(&mut self, request_id: u64, issues: Result<Vec<fenix_jira::IssueSummary>, String>) {
        let Some(session) = self.jira_session.as_ref() else { return };
        if session.issues_request_id != request_id {
            return;
        }
        let issues_buffer = session.issues_buffer;
        match issues {
            Ok(issues) => {
                if let Some(session) = self.jira_session.as_mut() {
                    for issue in &issues {
                        session.known_statuses.insert(issue.status.clone());
                    }
                    session.issues = issues.clone();
                }
                self.set_jira_buffer(issues_buffer, jira_panel::render_issues(&issues));
            }
            Err(err) => self.set_error(format!("Jira search failed: {err}")),
        }
    }

    /// Same shape as `jira_sync_issues`, one pane deeper -- re-fetches
    /// the full issue detail from whichever row is now under the cursor
    /// in Issues, when it's actually a *different* issue than the one
    /// already showing. Purely a cursor-reading wrapper now -- the real
    /// fetch is `jira_fetch_detail`, shared with the `SPC j g` goto-issue
    /// prompt.
    fn jira_sync_detail(&mut self) {
        let Some(session) = self.jira_session.as_ref() else { return };
        let selected_issue = match self.jira_entry_at_cursor() {
            Some(jira_panel::JiraEntry::Issue(key)) => Some(key),
            _ => return,
        };
        if selected_issue == session.last_selected_issue {
            return;
        }
        let Some(issue_key) = selected_issue else { return };
        self.jira_fetch_detail(issue_key);
    }

    /// The shared fetch-on-cursor-move body, factored out of `jira_sync_
    /// detail` so the goto-issue prompt (`SPC j g`, explicit-key-driven
    /// rather than cursor-driven) can reuse the exact same request-id-
    /// guarded background fetch instead of duplicating it. Sets `last_
    /// selected_issue` as part of kicking the fetch off (mirrors `jira_
    /// sync_detail`'s own prior behavior: only once a real client exists
    /// to fetch with, so an unconfigured client doesn't silently mark an
    /// issue "already showing" when nothing was actually fetched) --
    /// this alone is what makes a later cursor move onto that same issue
    /// in Issues a correct no-op re-select, for either caller.
    fn jira_fetch_detail(&mut self, key: String) {
        let Some(client) = self.jira_client() else { return };
        let Some(session) = self.jira_session.as_mut() else { return };
        session.last_selected_issue = Some(key.clone());
        session.detail_request_id += 1;
        let request_id = session.detail_request_id;

        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let detail = client.get_issue(&key);
                    let _ = proxy.send_event(FenixUserEvent::JiraDetailReady { request_id, detail });
                });
            }
            None => {
                let detail = client.get_issue(&key);
                self.apply_jira_detail(request_id, detail);
            }
        }
    }

    /// `FenixUserEvent::JiraDetailReady` handling -- mirrors `apply_
    /// jira_issues`.
    fn apply_jira_detail(&mut self, request_id: u64, detail: Result<fenix_jira::IssueDetail, String>) {
        let Some(session) = self.jira_session.as_ref() else { return };
        if session.detail_request_id != request_id {
            return;
        }
        let detail_buffer = session.detail_buffer;
        match detail {
            Ok(detail) => {
                if let Some(session) = self.jira_session.as_mut() {
                    session.detail = Some(detail.clone());
                }
                self.set_jira_buffer(detail_buffer, jira_panel::render_detail(Some(&detail)));
            }
            Err(err) => self.set_error(format!("Jira issue fetch failed: {err}")),
        }
    }

    /// Force-refetches Detail for `session.last_selected_issue` -- same
    /// "independent of focus" reasoning as `jira_force_fetch_issues`,
    /// one pane deeper. `jira_fetch_detail` itself has no dedup guard
    /// (that lives in `jira_sync_detail`, the cursor-driven wrapper), so
    /// this just calls it directly whenever there's a current issue.
    fn jira_force_fetch_detail(&mut self) {
        let Some(session) = self.jira_session.as_ref() else { return };
        if let Some(key) = session.last_selected_issue.clone() {
            self.jira_fetch_detail(key);
        }
    }

    /// `SPC j r`: manual refresh -- also what a completed write action
    /// (`apply_jira_action_done`) and the status-filter picker's own
    /// apply use to pick up whatever changed, since neither necessarily
    /// runs with Users/Issues focused (`jira_force_fetch_*` refetches
    /// using the *tracked* selection, not the focused pane's cursor --
    /// see their own doc comments for why `jira_sync_issues`/`jira_sync_
    /// detail` alone used to silently no-op here). The closest thing to
    /// Docker/Git's own poller for this phase, deliberately manual
    /// rather than timer-driven (see `JiraSession`'s own doc comment).
    pub(crate) fn jira_refresh(&mut self) {
        self.jira_force_fetch_issues();
        self.jira_force_fetch_detail();
    }

    /// `SPC j p a`: starts the two-step "add a tracked project" prompt
    /// (key, then display name) -- mirrors `git_start_commit_prompt`'s
    /// "just arm the prompt" shape.
    pub(crate) fn jira_start_add_project_prompt(&mut self) {
        self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::ProjectKey, input: String::new() });
    }

    /// `SPC j u a`: same shape as `jira_start_add_project_prompt`, for a
    /// tracked user's id.
    pub(crate) fn jira_start_add_user_prompt(&mut self) {
        self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::UserId, input: String::new() });
    }

    /// What to show in place of the modeline while `jira_prompt` is
    /// active -- mirrors `git_prompt_text`.
    fn jira_prompt_text(&self) -> Option<String> {
        let prompt = self.jira_prompt.as_ref()?;
        Some(match &prompt.kind {
            JiraPromptKind::ProjectKey => format!("Project key: {}", prompt.input),
            JiraPromptKind::ProjectName { .. } => format!("Project name: {}", prompt.input),
            JiraPromptKind::UserId => format!("User id: {}", prompt.input),
            JiraPromptKind::UserName { .. } => format!("User display name: {}", prompt.input),
            JiraPromptKind::NewIssueType { .. } => format!("Issue type: {}", prompt.input),
            JiraPromptKind::NewIssueSummary { .. } => format!("Summary: {}", prompt.input),
            JiraPromptKind::EditTitle { .. } => format!("Title: {}", prompt.input),
            JiraPromptKind::LogTime { .. } => format!("Log time (e.g. \"2h 30m\"): {}", prompt.input),
            JiraPromptKind::GotoIssue => format!("Go to issue: {}", prompt.input),
        })
    }

    /// Mirrors `git_prompt_key`'s text-accumulation shape exactly.
    fn jira_prompt_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(prompt), Some(text)) = (&mut self.jira_prompt, pasted) {
                prompt.input.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some(prompt) = &mut self.jira_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.jira_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let JiraPrompt { kind, input } = self.jira_prompt.take().unwrap();
                self.jira_prompt_advance(kind, input);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                prompt.input.pop();
            }
            KeyCode::Char(c) => prompt.input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// `Enter` on `jira_prompt`: either advances to the second field
    /// (key/id captured, now prompting for its display name) or, on the
    /// second field, appends the completed `(id, name)` pair to the
    /// tracked list, persists it to `Config`, and re-renders the
    /// matching pane. An empty field at either step silently cancels
    /// the whole prompt (mirrors `git_prompt_submit`'s own "blank input
    /// does nothing" guard).
    fn jira_prompt_advance(&mut self, kind: JiraPromptKind, input: String) {
        let value = input.trim().to_string();
        if value.is_empty() {
            return;
        }
        match kind {
            JiraPromptKind::ProjectKey => {
                self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::ProjectName { key: value }, input: String::new() });
            }
            JiraPromptKind::ProjectName { key } => {
                self.config.jira_projects.push((key, value));
                if let Err(err) = self.config.save() {
                    self.set_error(format!("couldn't save config.ini: {err}"));
                }
                let projects = self.config.jira_projects.clone();
                if let Some(session) = self.jira_session.as_mut() {
                    session.tracked_projects = projects.clone();
                }
                if let Some(session) = self.jira_session.as_ref() {
                    let buffer = session.projects_buffer;
                    self.set_jira_buffer(buffer, jira_panel::render_projects(&projects));
                }
            }
            JiraPromptKind::UserId => {
                self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::UserName { id: value }, input: String::new() });
            }
            JiraPromptKind::UserName { id } => {
                self.config.jira_users.push((id, value));
                if let Err(err) = self.config.save() {
                    self.set_error(format!("couldn't save config.ini: {err}"));
                }
                let users = self.config.jira_users.clone();
                if let Some(session) = self.jira_session.as_mut() {
                    session.tracked_users = users.clone();
                }
                if let Some(session) = self.jira_session.as_ref() {
                    let buffer = session.users_buffer;
                    self.set_jira_buffer(buffer, jira_panel::render_users(&users));
                }
            }
            JiraPromptKind::NewIssueType { project_key } => {
                self.jira_prompt =
                    Some(JiraPrompt { kind: JiraPromptKind::NewIssueSummary { project_key, issue_type: value }, input: String::new() });
            }
            JiraPromptKind::NewIssueSummary { project_key, issue_type } => {
                self.spawn_jira_action(move |client| {
                    let key = client.create_issue(&project_key, &issue_type, &value)?;
                    Ok(format!("Created {key}"))
                });
            }
            JiraPromptKind::EditTitle { key } => {
                self.spawn_jira_action(move |client| {
                    client.update_summary(&key, &value)?;
                    Ok(format!("Updated title for {key}"))
                });
            }
            JiraPromptKind::LogTime { key } => {
                self.spawn_jira_action(move |client| {
                    client.add_worklog(&key, &value)?;
                    Ok(format!("Logged {value} on {key}"))
                });
            }
            JiraPromptKind::GotoIssue => {
                self.jira_fetch_detail(value);
                if let Some(session) = self.jira_session.as_ref() {
                    let detail_pane = session.detail_pane;
                    self.windows_mut().focus(detail_pane);
                }
            }
        }
    }

    /// `SPC j g`: starts the plain-text goto-issue prompt -- doesn't
    /// require the issue to already appear in the current Issues list
    /// (a teammate references `PROJ-456` in Slack; you weren't already
    /// browsing it).
    pub(crate) fn jira_start_goto_issue_prompt(&mut self) {
        if self.jira_session.is_none() {
            return;
        }
        self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::GotoIssue, input: String::new() });
    }

    /// Candidates for `SPC j p d` -- one per tracked project, keyed by
    /// the full `(key, name)` pair. Mirrors `mib_root_candidates`.
    fn jira_project_candidates(&self) -> Vec<fenix_picker::Candidate<(String, String)>> {
        self.config.jira_projects.iter().map(|(key, name)| fenix_picker::Candidate::new(format!("{key}  {name}"), (key.clone(), name.clone()))).collect()
    }

    /// Candidates for `SPC j u d` -- same shape as `jira_project_
    /// candidates`, for tracked users.
    fn jira_user_candidates(&self) -> Vec<fenix_picker::Candidate<(String, String)>> {
        self.config.jira_users.iter().map(|(id, name)| fenix_picker::Candidate::new(format!("{name}  ({id})"), (id.clone(), name.clone()))).collect()
    }

    /// `SPC j p d`: mirrors `picker_delete_mib_root` exactly.
    pub(crate) fn picker_delete_jira_project(&mut self) {
        let candidates = self.jira_project_candidates();
        self.enter_picker(ActivePicker::DeleteJiraProject(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC j u d`: mirrors `picker_delete_jira_project`, for tracked
    /// users.
    pub(crate) fn picker_delete_jira_user(&mut self) {
        let candidates = self.jira_user_candidates();
        self.enter_picker(ActivePicker::DeleteJiraUser(fenix_picker::PickerState::new(candidates)));
    }

    /// The shared shape every new Jira write action (create, comment,
    /// title, description, log time, transition) needs: build a
    /// `JiraClient` from `Config` (via `jira_client`, which already
    /// surfaces its own error and returns `None` when unconfigured -- so
    /// this is a safe no-op-without-credentials early return, same
    /// posture `jira_sync_issues` already has), run `action` on a
    /// background thread (or synchronously when `event_proxy` is `None`,
    /// for tests -- mirrors `jira_sync_issues`'s own `Some`/`None`
    /// branching exactly), and report the result via `FenixUserEvent::
    /// JiraActionDone`/`apply_jira_action_done`.
    fn spawn_jira_action<F>(&mut self, action: F)
    where
        F: FnOnce(&fenix_jira::JiraClient) -> Result<String, String> + Send + 'static,
    {
        let Some(client) = self.jira_client() else { return };
        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let result = action(&client);
                    let _ = proxy.send_event(FenixUserEvent::JiraActionDone(result));
                });
            }
            None => {
                let result = action(&client);
                self.apply_jira_action_done(result);
            }
        }
    }

    /// `FenixUserEvent::JiraActionDone` handling: on success, shows the
    /// action's own human-readable confirmation and refreshes the panel
    /// (`jira_refresh` -- picks up whatever changed, e.g. a new comment
    /// or an updated status); on failure, surfaces the error. No
    /// staleness guard, unlike `apply_jira_issues`/`apply_jira_detail` --
    /// a write action should never be silently discarded just because
    /// the user navigated elsewhere while it was in flight.
    fn apply_jira_action_done(&mut self, result: Result<String, String>) {
        match result {
            Ok(message) => {
                self.set_message(message);
                self.jira_refresh();
            }
            Err(err) => self.set_error(err),
        }
    }

    /// `SPC j i a`: starts the create-issue picker over tracked projects
    /// -- mirrors `picker_delete_jira_project` exactly, just a different
    /// picker variant so `picker_confirm` dispatches to the prompt chain
    /// instead of a removal.
    pub(crate) fn picker_create_jira_issue(&mut self) {
        let candidates = self.jira_project_candidates();
        self.enter_picker(ActivePicker::CreateJiraIssue(fenix_picker::PickerState::new(candidates)));
    }

    /// What the cursor's current issue is, from either Issues (list) or
    /// Detail (single-issue view) -- both keep `last_selected_issue` in
    /// sync today, so this works uniformly regardless of which of the
    /// two is focused. Backs every per-issue action trigger.
    fn jira_current_issue_key(&self) -> Option<String> {
        self.jira_session.as_ref()?.last_selected_issue.clone()
    }

    /// `y` on Issues/Detail: copies the current issue's real web URL to
    /// the clipboard -- pure local string construction (no REST call),
    /// `format!("{base}/browse/{key}")`. Reuses the same `arboard::
    /// Clipboard` `yank_file_path` already writes onto. A no-op (with a
    /// surfaced error) when either the current issue or `config.jira_
    /// base_url` is missing -- nothing sensible to build a URL from.
    pub(crate) fn jira_copy_issue_url(&mut self) {
        let Some(key) = self.jira_current_issue_key() else { return };
        let Some(base_url) = self.config.jira_base_url.clone() else {
            self.set_error("Jira isn't configured yet: set base_url in the [jira] section of config.ini");
            return;
        };
        let url = format!("{}/browse/{key}", base_url.trim_end_matches('/'));
        if let Some(clipboard) = &mut self.clipboard {
            let _ = clipboard.set_text(url.clone());
        }
        self.set_message(format!("Copied: {url}"));
        self.wake_caret();
    }

    /// `t` on Issues/Detail: fetches the current issue's available
    /// workflow transitions fresh (they're workflow-dependent, not a
    /// fixed list) and opens a picker over them once the fetch
    /// completes (`apply_jira_transitions_ready`). Mirrors `jira_sync_
    /// issues`'s own request-id-guarded read shape, not `spawn_jira_
    /// action`'s write shape -- this is a read before the actual write
    /// (`apply_transition`, called from `picker_confirm`'s own
    /// `JiraTransition` arm).
    fn jira_start_transition_picker(&mut self) {
        let Some(key) = self.jira_current_issue_key() else { return };
        let Some(client) = self.jira_client() else { return };
        let Some(session) = self.jira_session.as_mut() else { return };
        session.transitions_request_id += 1;
        let request_id = session.transitions_request_id;
        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let transitions = client.list_transitions(&key);
                    let _ = proxy.send_event(FenixUserEvent::JiraTransitionsReady { request_id, transitions });
                });
            }
            None => {
                let transitions = client.list_transitions(&key);
                self.apply_jira_transitions_ready(request_id, transitions);
            }
        }
    }

    /// `FenixUserEvent::JiraTransitionsReady` handling -- mirrors `apply_
    /// jira_issues`'s own staleness guard.
    fn apply_jira_transitions_ready(&mut self, request_id: u64, transitions: Result<Vec<fenix_jira::Transition>, String>) {
        let Some(session) = self.jira_session.as_ref() else { return };
        if session.transitions_request_id != request_id {
            return;
        }
        match transitions {
            Ok(transitions) => {
                let candidates = transitions.into_iter().map(|t| fenix_picker::Candidate::new(t.name.clone(), t)).collect();
                self.enter_picker(ActivePicker::JiraTransition(fenix_picker::PickerState::new(candidates)));
            }
            Err(err) => self.set_error(format!("Jira transitions fetch failed: {err}")),
        }
    }

    /// `A` on Issues/Detail: opens a picker over `session.tracked_users`
    /// (same candidate shape as `jira_user_candidates`/`DeleteJiraUser`)
    /// -- no fetch needed, unlike `jira_start_transition_picker`/`jira_
    /// start_priority_picker`, since tracked users are already local
    /// state. Confirming calls `update_assignee`.
    pub(crate) fn jira_start_assignee_picker(&mut self) {
        if self.jira_current_issue_key().is_none() {
            return;
        }
        let candidates = self.jira_user_candidates();
        self.enter_picker(ActivePicker::JiraAssignee(fenix_picker::PickerState::new(candidates)));
    }

    /// `P` on Issues/Detail: fetches the instance's real configured
    /// priorities fresh (avoids hardcoding a guessed default that might
    /// not match this instance's actual scheme) and opens a picker over
    /// them once the fetch completes (`apply_jira_priorities_ready`) --
    /// mirrors `jira_start_transition_picker` exactly.
    pub(crate) fn jira_start_priority_picker(&mut self) {
        if self.jira_current_issue_key().is_none() {
            return;
        }
        let Some(client) = self.jira_client() else { return };
        let Some(session) = self.jira_session.as_mut() else { return };
        session.priorities_request_id += 1;
        let request_id = session.priorities_request_id;
        match self.event_proxy.clone() {
            Some(proxy) => {
                std::thread::spawn(move || {
                    let priorities = client.list_priorities();
                    let _ = proxy.send_event(FenixUserEvent::JiraPrioritiesReady { request_id, priorities });
                });
            }
            None => {
                let priorities = client.list_priorities();
                self.apply_jira_priorities_ready(request_id, priorities);
            }
        }
    }

    /// `FenixUserEvent::JiraPrioritiesReady` handling -- mirrors `apply_
    /// jira_transitions_ready`'s own staleness guard.
    fn apply_jira_priorities_ready(&mut self, request_id: u64, priorities: Result<Vec<fenix_jira::Priority>, String>) {
        let Some(session) = self.jira_session.as_ref() else { return };
        if session.priorities_request_id != request_id {
            return;
        }
        match priorities {
            Ok(priorities) => {
                let candidates = priorities.into_iter().map(|p| fenix_picker::Candidate::new(p.name.clone(), p)).collect();
                self.enter_picker(ActivePicker::JiraPriority(fenix_picker::PickerState::new(candidates)));
            }
            Err(err) => self.set_error(format!("Jira priorities fetch failed: {err}")),
        }
    }

    /// `T` on Issues/Detail: starts the edit-title prompt, pre-filled
    /// from `session.detail.summary` when it's actually showing the
    /// current issue (empty otherwise, rather than blocking on a fetch
    /// just to pre-fill a field the user can type over anyway).
    pub(crate) fn jira_start_edit_title_prompt(&mut self) {
        let Some(key) = self.jira_current_issue_key() else { return };
        let prefill = self
            .jira_session
            .as_ref()
            .and_then(|s| s.detail.as_ref())
            .filter(|d| d.key == key)
            .map(|d| d.summary.clone())
            .unwrap_or_default();
        self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::EditTitle { key }, input: prefill });
    }

    /// `l` on Issues/Detail: starts the log-time prompt -- a plain
    /// duration string, Jira's own syntax, no client-side format
    /// validation (matches `add_worklog`'s own posture).
    pub(crate) fn jira_start_log_time_prompt(&mut self) {
        let Some(key) = self.jira_current_issue_key() else { return };
        self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::LogTime { key }, input: String::new() });
    }

    /// `c`/`e` on Issues/Detail: opens a real scratch buffer for
    /// unrestricted Vim editing (the user's own confirmed choice over a
    /// single-line prompt), seeded with `seed` (empty for a new comment,
    /// the current description for an edit) and pointed at from the
    /// Detail pane in place of its own rendered content. `jira_edit`
    /// tracks `pane`/`original_buffer` explicitly so `jira_submit_edit`/
    /// `jira_cancel_edit` can restore Detail's own real rendering
    /// directly, rather than through `kill_buffer`'s generic "falls back
    /// to the MRU-next open buffer" behavior -- that risks landing Detail
    /// on some unrelated recently-visited buffer instead.
    fn jira_start_edit(&mut self, kind: JiraEditKind, seed: String) {
        let Some(session) = self.jira_session.as_ref() else { return };
        let pane = session.detail_pane;
        let original_buffer = session.detail_buffer;
        let edit_buffer = self.buffers.open_text_view(&seed);
        self.set_pane_content(pane, edit_buffer);
        self.jira_edit = Some(JiraEditSession { kind, pane, edit_buffer, original_buffer });
        self.wake_caret();
    }

    /// `c` on Issues/Detail: starts a new, empty comment buffer.
    pub(crate) fn jira_start_comment(&mut self) {
        let Some(key) = self.jira_current_issue_key() else { return };
        self.jira_start_edit(JiraEditKind::Comment { key }, String::new());
    }

    /// `e` on Issues/Detail: starts a description-edit buffer, pre-filled
    /// from `session.detail.description` when it's showing the current
    /// issue (empty otherwise).
    pub(crate) fn jira_start_edit_description(&mut self) {
        let Some(key) = self.jira_current_issue_key() else { return };
        let seed = self
            .jira_session
            .as_ref()
            .and_then(|s| s.detail.as_ref())
            .filter(|d| d.key == key)
            .and_then(|d| d.description.clone())
            .unwrap_or_default();
        self.jira_start_edit(JiraEditKind::Description { key }, seed);
    }

    /// Restores Detail to its own real rendering and closes the scratch
    /// edit buffer -- the shared tail of `jira_submit_edit`/`jira_
    /// cancel_edit`. Deliberately `set_pane_content` + `self.buffers.
    /// close` directly, not `kill_buffer()` (see `jira_start_edit`'s own
    /// doc comment for why).
    fn jira_edit_restore(&mut self) -> Option<JiraEditSession> {
        let session = self.jira_edit.take()?;
        self.set_pane_content(session.pane, session.original_buffer);
        self.buffers.close(session.edit_buffer);
        Some(session)
    }

    /// `SPC j s`: reads the edit buffer's current text, restores Detail,
    /// closes the scratch buffer, then submits the right write action
    /// (`add_comment`/`update_description`) via `spawn_jira_action`. A
    /// leader binding, not a pane-scoped bare key -- see `jira_edit`'s
    /// own doc comment on `App` for why that's load-bearing here.
    pub(crate) fn jira_submit_edit(&mut self) {
        let Some(session) = &self.jira_edit else { return };
        let text = self.buffers.get(session.edit_buffer).map(|ob| ob.buffer.text()).unwrap_or_default();
        let Some(session) = self.jira_edit_restore() else { return };
        match session.kind {
            JiraEditKind::Comment { key } => {
                self.spawn_jira_action(move |client| {
                    client.add_comment(&key, &text)?;
                    Ok(format!("Comment added to {key}"))
                });
            }
            JiraEditKind::Description { key } => {
                self.spawn_jira_action(move |client| {
                    client.update_description(&key, &text)?;
                    Ok(format!("Description updated for {key}"))
                });
            }
        }
        self.wake_caret();
    }

    /// `SPC j x`: restores Detail and closes the scratch buffer without
    /// submitting anything.
    pub(crate) fn jira_cancel_edit(&mut self) {
        self.jira_edit_restore();
        self.wake_caret();
    }

    /// `f` on Issues: opens a multi-select picker over every status seen
    /// so far this session (`session.known_statuses`, sorted
    /// alphabetically for a stable display order), pre-marked to match
    /// the currently-excluded set (`new_with_marks`) -- replaces phase
    /// 2's full-pane toggle-buffer checklist. A no-op (just a `set_
    /// message`) if nothing's been fetched yet -- nothing to filter.
    pub(crate) fn jira_start_status_filter(&mut self) {
        let Some(session) = self.jira_session.as_ref() else { return };
        if session.known_statuses.is_empty() {
            self.set_message("Jira: no statuses seen yet");
            self.wake_caret();
            return;
        }
        let mut names: Vec<String> = session.known_statuses.iter().cloned().collect();
        names.sort();
        let excluded_set: HashSet<&String> = session.excluded_statuses.iter().collect();
        let marked_indices = names.iter().enumerate().filter(|(_, name)| excluded_set.contains(name)).map(|(i, _)| i);
        let candidates: Vec<fenix_picker::Candidate<String>> = names.iter().map(|name| fenix_picker::Candidate::new(name.clone(), name.clone())).collect();
        let picker = fenix_picker::PickerState::new_with_marks(candidates, marked_indices);
        self.enter_picker(ActivePicker::JiraStatusFilter(picker));
    }

    /// No stashing needed -- same reasoning as `explorer_jump`, now that
    /// buffers live in `self.buffers` rather than direct `App` fields.
    fn enter_picker(&mut self, picker: ActivePicker) {
        self.active_picker = Some(picker);
        self.picker_scroll = 0;
        self.main_view = MainView::Picker;
        self.wake_caret();
    }

    /// `Escape`: cancels the active picker -- no file/project opened, the
    /// focused pane's buffer was never touched, so returning to the
    /// editor just means switching `main_view` back.
    fn picker_cancel(&mut self) {
        self.active_picker = None;
        self.main_view = MainView::Editor;
    }

    /// `Enter`: confirms the selected candidate, dispatching differently
    /// per picker kind. A no-op (stays open) if the filtered list is
    /// currently empty -- nothing to confirm.
    fn picker_confirm(&mut self) {
        match &self.active_picker {
            Some(ActivePicker::FindFile(state)) => {
                let Some(path) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.open_file_from_picker(&path);
            }
            Some(ActivePicker::SwitchProject(state)) => {
                let Some(root) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.switch_to_project(root);
            }
            Some(ActivePicker::Grep(state)) => {
                let Some(m) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                let from = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
                self.open_file_from_picker(&m.path);
                self.jump_to_grep_match(&m);
                self.record_jump(from);
                // So `SPC p n`/`SPC p N` continue from wherever the
                // picker actually landed (which candidate got confirmed
                // may not be `quickfix[0]` -- the picker's own fuzzy
                // filter can reorder/narrow what's shown), not always
                // restart from the top of the list.
                self.quickfix_index = self.quickfix.iter().position(|entry| matches!(entry, QuickfixEntry::Grep(gm) if gm == &m));
            }
            Some(ActivePicker::SwitchBuffer(state)) => {
                let Some(id) = state.selected().map(|c| c.payload) else { return };
                self.active_picker = None;
                self.switch_focused_to_buffer(id);
            }
            Some(ActivePicker::Recovery(state)) => {
                let Some(snapshot) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.recover_snapshot(&snapshot);
            }
            Some(ActivePicker::DeleteProject(state)) => {
                let Some(root) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.known_projects.remove(&root);
                if let Err(err) = self.known_projects.save() {
                    eprintln!("fenix: couldn't save project history: {err}");
                }
            }
            Some(ActivePicker::DeleteMibRoot(state)) => {
                let Some(target) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.config.mib_roots.retain(|entry| entry != &target);
                self.persist_mib_roots();
            }
            Some(ActivePicker::DeleteJiraProject(state)) => {
                let Some(target) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.config.jira_projects.retain(|entry| entry != &target);
                if let Err(err) = self.config.save() {
                    self.set_error(format!("couldn't save config.ini: {err}"));
                }
                let projects = self.config.jira_projects.clone();
                if let Some(session) = self.jira_session.as_mut() {
                    session.tracked_projects = projects.clone();
                }
                if let Some(session) = self.jira_session.as_ref() {
                    let buffer = session.projects_buffer;
                    self.set_jira_buffer(buffer, jira_panel::render_projects(&projects));
                }
            }
            Some(ActivePicker::DeleteJiraUser(state)) => {
                let Some(target) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.config.jira_users.retain(|entry| entry != &target);
                if let Err(err) = self.config.save() {
                    self.set_error(format!("couldn't save config.ini: {err}"));
                }
                let users = self.config.jira_users.clone();
                if let Some(session) = self.jira_session.as_mut() {
                    session.tracked_users = users.clone();
                }
                if let Some(session) = self.jira_session.as_ref() {
                    let buffer = session.users_buffer;
                    self.set_jira_buffer(buffer, jira_panel::render_users(&users));
                }
            }
            Some(ActivePicker::CreateJiraIssue(state)) => {
                let Some((project_key, _name)) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.jira_prompt = Some(JiraPrompt { kind: JiraPromptKind::NewIssueType { project_key }, input: String::new() });
            }
            Some(ActivePicker::JiraTransition(state)) => {
                let Some(transition) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                let Some(key) = self.jira_current_issue_key() else { return };
                self.spawn_jira_action(move |client| {
                    client.apply_transition(&key, &transition.id)?;
                    Ok(format!("Transitioned {key} to {}", transition.name))
                });
            }
            Some(ActivePicker::JiraStatusFilter(state)) => {
                // An empty marked set is a completely valid, meaningful
                // result -- "show every status," the normal way to clear
                // the filter, not a fallback edge case -- so this arm,
                // unlike every other one here, doesn't early-return on
                // "nothing selected."
                let excluded: Vec<String> = state.marked().cloned().collect();
                self.active_picker = None;
                self.main_view = MainView::Editor;
                if let Some(session) = self.jira_session.as_mut() {
                    session.excluded_statuses = excluded.clone();
                }
                // Not `jira_sync_issues` -- `f` is pressed with Issues
                // focused, not Users, so the cursor-driven wrapper would
                // silently no-op here (see its own doc comment). This
                // force-refetches the already-tracked selected user
                // regardless of what's focused.
                self.jira_force_fetch_issues();
                if excluded.is_empty() {
                    self.set_message("Jira: showing all statuses");
                } else {
                    self.set_message(format!("Jira: excluding {}", excluded.join(", ")));
                }
            }
            Some(ActivePicker::JiraAssignee(state)) => {
                let Some((user_id, _name)) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                let Some(key) = self.jira_current_issue_key() else { return };
                self.spawn_jira_action(move |client| {
                    client.update_assignee(&key, &user_id)?;
                    Ok(format!("Reassigned {key}"))
                });
            }
            Some(ActivePicker::JiraPriority(state)) => {
                let Some(priority) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                let Some(key) = self.jira_current_issue_key() else { return };
                self.spawn_jira_action(move |client| {
                    client.update_priority(&key, &priority.name)?;
                    Ok(format!("Set priority of {key} to {}", priority.name))
                });
            }
            Some(ActivePicker::Theme(state)) => {
                let Some(theme) = state.selected().map(|c| c.payload) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.apply_theme(theme);
            }
            Some(ActivePicker::Symbol(state)) => {
                let Some(tag) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                let from = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
                self.open_file_from_picker(&tag.file);
                self.jump_to_tag(&tag);
                self.record_jump(from);
            }
            Some(ActivePicker::Task(state)) => {
                let Some(task) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                let root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
                self.run_task(task, root);
            }
            Some(ActivePicker::CompareBase(state)) => {
                let Some(base) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                // Straight into picking the other side -- `enter_picker`
                // keeps `main_view` on the picker, so this reads as one
                // two-step interaction rather than two separate ones.
                self.compare_pick_head(base);
            }
            Some(ActivePicker::CompareHead { base, picker }) => {
                let Some(head) = picker.selected().map(|c| c.payload.clone()) else { return };
                let base = base.clone();
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.open_compare_view(base, head);
            }
            Some(ActivePicker::RebaseOnto(state)) => {
                let Some(onto) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.git_rebase_onto(&onto);
            }
            Some(ActivePicker::MergeFrom(state)) => {
                let Some(branch) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.git_merge_from(&branch);
            }
            Some(ActivePicker::MibTelecommandLookup(state)) => {
                let Some(row) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.mib_show_telecommand(&row);
            }
            Some(ActivePicker::MibTelecommandInsert(state)) => {
                let Some(row) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.mib_start_insert(row);
            }
            Some(ActivePicker::MibTmPacket(state)) => {
                let Some(row) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.mib_show_tm_packet(&row);
            }
            Some(ActivePicker::MibTmParameter(state)) => {
                let Some(row) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.mib_show_tm_parameter(&row);
            }
            Some(ActivePicker::MibCalibration(state)) => {
                let Some(row) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.mib_show_calibration(&row);
            }
            Some(ActivePicker::MibArgumentAlias(state)) => {
                let Some(alias) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.mib_resume_insert(alias);
            }
            Some(ActivePicker::VncHost(state)) => {
                let Some(name) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.open_vnc_session(&name);
            }
            Some(ActivePicker::Document(state)) => {
                let Some(path) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.open_document(&path);
            }
            Some(ActivePicker::TableColumn(state)) => {
                let Some(column) = state.selected().map(|c| c.payload) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                let line = self.open().buffer.line_col(&self.cursor()).0;
                let idx = self.table_column_start(line, column);
                let pane = self.focused_pane_id();
                let cursor = &mut self.pane_state_mut(pane).cursor;
                cursor.char_idx = idx;
                cursor.sticky_col = 0;
            }
            Some(ActivePicker::BufferSearch(state)) => {
                let Some(offset) = state.selected().map(|c| c.payload) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
                cursor.char_idx = offset.min(buffer.len_chars());
                let (_, col) = buffer.line_col(cursor);
                cursor.sticky_col = col;
            }
            Some(ActivePicker::SwitchWorkspace(state)) => {
                let Some(idx) = state.selected().map(|c| c.payload) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.workspaces.switch_to_index(idx);
            }
            Some(ActivePicker::WorkspaceLauncher(state)) => {
                let Some(name) = state.selected().map(|c| c.payload.clone()) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                self.open_configured_workspace(&name);
            }
            Some(ActivePicker::Outline(state)) => {
                let Some(offset) = state.selected().map(|c| c.payload) else { return };
                self.active_picker = None;
                self.main_view = MainView::Editor;
                let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
                cursor.char_idx = offset.min(buffer.len_chars());
                let (_, col) = buffer.line_col(cursor);
                cursor.sticky_col = col;
            }
            None => {}
        }
        self.wake_caret();
    }

    /// Points the focused pane at `path` (opening it in the registry --
    /// reusing an already-open buffer for the same path, per
    /// `BufferList::open_path`), exactly like opening a file from the
    /// explorer. A picker always fully took over `main_view` to get
    /// here, so confirming always means "this is current now, back to
    /// the editor."
    fn open_file_from_picker(&mut self, path: &Path) {
        if Self::looks_like_pdf(path) {
            self.open_pdf_path(path);
            return;
        }
        let id = self.buffers.open_path(path);
        self.note_disk_state(id);
        self.open_buffer_in_focused_pane(id);
        self.refresh_project_root();
        self.record_recent_file(path);
        self.main_view = MainView::Editor;
    }

    /// Opens every file argument this launch was given beyond the
    /// first -- `App::new`/`with_file` already seeded the initial
    /// buffer from `args[0]` itself, but Explorer's "Open With" can
    /// hand a launch multiple selected files at once. Reuses `open_
    /// file_from_picker`'s exact "point the focused pane at it"
    /// behavior; called once per extra path, right after startup, from
    /// `main.rs`.
    pub(crate) fn open_startup_file(&mut self, path: &Path) {
        self.open_file_from_picker(path);
    }

    /// `FenixUserEvent::OpenFiles`: a *later* `fenix` launch handed its
    /// file arguments off to this (the already-running) instance via
    /// the single-instance IPC server (see `crate::ipc`) instead of
    /// opening its own window. Opens each path the same way `open_
    /// startup_file` does, then pulls this window to the front -- the
    /// whole point of the hand-off is that the user just double-
    /// clicked a file expecting *something* to respond, not a window
    /// left sitting behind others.
    fn apply_open_files(&mut self, paths: Vec<String>) {
        for path in &paths {
            self.open_file_from_picker(Path::new(path));
        }
        if let Some(window) = &self.window {
            window.focus_window();
            window.request_redraw();
        }
        self.wake_caret();
    }

    /// `SPC f f`: starts the type-a-path find-file prompt.
    pub(crate) fn start_find_file_prompt(&mut self) {
        self.find_file_prompt = Some(String::new());
        self.wake_caret();
    }

    /// Routes one keypress to the in-progress `find_file_prompt` -- same
    /// "next keystrokes are special" shape as `grep_query_key`.
    fn find_file_prompt_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(input), Some(text)) = (&mut self.find_file_prompt, pasted) {
                input.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some(input) = &mut self.find_file_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.find_file_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let input = self.find_file_prompt.take().unwrap_or_default();
                self.open_typed_path(&input);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                input.pop();
            }
            KeyCode::Char(c) if key.mods == Mods::default() => input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// Resolves `typed` (a `~`-expandable, possibly-relative path -- an
    /// absolute one is used as-is) and opens it via `open_file_from_
    /// picker`, which already handles buffer reuse, `recent_files`
    /// tracking, and switching back to `MainView::Editor`. Unlike every
    /// fuzzy picker, this never enumerates anything -- a `.gitignore`'d
    /// (or simply not-yet-existing -- `open_path` already degrades to
    /// an empty, to-be-created buffer, real Emacs `find-file` semantics)
    /// path opens exactly the same as any other.
    fn open_typed_path(&mut self, typed: &str) {
        let typed = typed.trim();
        if typed.is_empty() {
            return;
        }
        let expanded = match typed.strip_prefix('~') {
            Some(rest) => dirs::home_dir()
                .map(|home| home.join(rest.trim_start_matches(['/', '\\'])))
                .unwrap_or_else(|| PathBuf::from(typed)),
            None => PathBuf::from(typed),
        };
        let resolved = if expanded.is_absolute() {
            expanded
        } else {
            let root = self.project_root.clone().unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
            root.join(expanded)
        };
        self.open_file_from_picker(&resolved);
    }

    /// What to show in place of the modeline while `find_file_prompt` is
    /// active -- mirrors `explorer_prompt_text`.
    fn find_file_prompt_text(&self) -> Option<String> {
        self.find_file_prompt.as_ref().map(|input| format!("find file: {input}"))
    }

    /// `SPC f y`: copies the focused buffer's file path to the OS
    /// clipboard -- a no-op (clipboard untouched) for an unsaved/
    /// unnamed buffer. Reuses the same `arboard::Clipboard` `y`/`p`
    /// already mirror onto.
    pub(crate) fn yank_file_path(&mut self) {
        let Some(path) = self.open().buffer.path() else { return };
        let text = path.display().to_string();
        if let Some(clipboard) = &mut self.clipboard {
            let _ = clipboard.set_text(text);
        }
        self.wake_caret();
    }

    /// `SPC f R`: starts the rename prompt, pre-seeded with the current
    /// filename -- a no-op for an unsaved/unnamed buffer (there's no
    /// file on disk yet to rename; `:w path` already covers "save this
    /// somewhere new").
    pub(crate) fn start_rename_file_prompt(&mut self) {
        let Some(path) = self.open().buffer.path() else { return };
        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or_default().to_string();
        self.rename_file_prompt = Some(name);
        self.wake_caret();
    }

    /// Routes one keypress to the in-progress `rename_file_prompt` --
    /// same shape as `find_file_prompt_key`.
    fn rename_file_prompt_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(input), Some(text)) = (&mut self.rename_file_prompt, pasted) {
                input.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some(input) = &mut self.rename_file_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.rename_file_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let input = self.rename_file_prompt.take().unwrap_or_default();
                self.apply_rename_file(&input);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                input.pop();
            }
            KeyCode::Char(c) if key.mods == Mods::default() => input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// Renames the focused buffer's file to `new_name` (resolved
    /// against its current parent directory -- a `new_name` containing
    /// its own `/`s lands in a sub/parent path relative to there, same
    /// as typing one into `Path::join` normally would). Writes the
    /// buffer's *current* content to the new path (`Buffer::save_as`,
    /// which also updates the buffer's own `path()`), so unsaved edits
    /// are captured too, not just what was last saved -- then removes
    /// the old file (create-then-remove rather than `std::fs::rename`,
    /// so this can't fail with `EXDEV` across filesystem boundaries) and
    /// tells the registry the path moved (`BufferList::path_changed`,
    /// keeping `open_path`/`id_for_path` correct afterward).
    fn apply_rename_file(&mut self, new_name: &str) {
        let new_name = new_name.trim();
        if new_name.is_empty() {
            return;
        }
        let Some(old_path) = self.open().buffer.path().map(Path::to_path_buf) else { return };
        let new_path = match old_path.parent() {
            Some(parent) => parent.join(new_name),
            None => PathBuf::from(new_name),
        };
        let id = self.focused_buffer_id();
        if let Err(err) = self.open_mut().buffer.save_as(&new_path) {
            self.set_error(format!("rename failed: {err}"));
            return;
        }
        self.buffers.path_changed(id, Some(&old_path));
        if let Err(err) = std::fs::remove_file(&old_path) {
            self.set_error(format!("rename couldn't remove the old file {}: {err}", old_path.display()));
        }
    }

    /// What to show in place of the modeline while `rename_file_prompt`
    /// is active.
    fn rename_file_prompt_text(&self) -> Option<String> {
        self.rename_file_prompt.as_ref().map(|input| format!("rename to: {input}"))
    }

    /// `SPC f D`: arms the delete-current-file confirmation -- a no-op
    /// for an unsaved/unnamed buffer.
    pub(crate) fn start_delete_file_confirm(&mut self) {
        if self.open().buffer.path().is_none() {
            return;
        }
        self.delete_file_confirm = true;
        self.wake_caret();
    }

    /// Routes one keypress to the armed delete confirmation -- same y/n
    /// shape as `docker_confirm_key`.
    fn delete_file_confirm_key(&mut self, key: KeyPress) {
        self.delete_file_confirm = false;
        if key.code == KeyCode::Char('y') {
            self.apply_delete_file();
        }
        self.wake_caret();
    }

    /// Deletes the focused buffer's file from disk and closes the
    /// buffer -- `kill_buffer` already falls back to the MRU-next
    /// buffer (or a fresh scratch one) and removes the stale path from
    /// the registry's own index.
    fn apply_delete_file(&mut self) {
        let Some(path) = self.open().buffer.path().map(Path::to_path_buf) else { return };
        if let Err(err) = std::fs::remove_file(&path) {
            self.set_error(format!("couldn't delete {}: {err}", path.display()));
            return;
        }
        self.kill_buffer_now();
    }

    /// What to show in place of the modeline while the delete
    /// confirmation is armed -- mirrors `docker_confirm_text`.
    fn delete_file_confirm_text(&self) -> Option<String> {
        if !self.delete_file_confirm {
            return None;
        }
        let name = self.open().buffer.path().map(|p| p.display().to_string()).unwrap_or_default();
        Some(format!("Delete {name}? (y/n)"))
    }

    fn jump_to_grep_match(&mut self, m: &fenix_project::GrepMatch) {
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let target_line = m.line.saturating_sub(1).min(buffer.visual_line_count().saturating_sub(1));
        let start = buffer.line_start_char(target_line);
        let col = m.col.saturating_sub(1).min(buffer.line_len(target_line));
        cursor.char_idx = start + col;
        let (_, sticky) = buffer.line_col(cursor);
        cursor.sticky_col = sticky;
    }

    /// Same shape as `jump_to_grep_match`, for a `ctags`-sourced
    /// definition -- `ctags` only ever gives a line, not a column, so
    /// this always lands at the start of it rather than on a specific
    /// character within.
    fn jump_to_tag(&mut self, tag: &fenix_completion::ctags::TagEntry) {
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let target_line = tag.line.saturating_sub(1).min(buffer.visual_line_count().saturating_sub(1));
        cursor.char_idx = buffer.line_start_char(target_line);
        let (_, sticky) = buffer.line_col(cursor);
        cursor.sticky_col = sticky;
    }

    /// Pushes `from` onto the `Ctrl-O` back stack and clears the
    /// `Ctrl-I` forward stack -- see `jump_back_stack`'s own doc comment
    /// for why a new jump invalidates old forward history rather than
    /// preserving it the way real Vim's jumplist does.
    fn record_jump(&mut self, from: JumpEntry) {
        self.jump_back_stack.push(from);
        self.jump_forward_stack.clear();
    }

    /// `Ctrl-O`: jumps to the most recently recorded position, pushing
    /// wherever the cursor currently is onto the forward stack so
    /// `Ctrl-I` can return here. Silently drops (without stopping) any
    /// entry whose buffer was since closed -- see `JumpEntry`'s own doc
    /// comment. A no-op with nothing left to go back to, or while a
    /// Docker/Git panel session is open (see `jumplist_navigation_
    /// allowed`'s own doc comment).
    pub(crate) fn jump_back(&mut self) {
        if !self.jumplist_navigation_allowed() {
            return;
        }
        let current = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
        while let Some(entry) = self.jump_back_stack.pop() {
            if self.buffers.get(entry.buffer).is_some() {
                self.jump_forward_stack.push(current);
                self.goto_jump_entry(entry, false);
                return;
            }
        }
    }

    /// `Ctrl-I`: the mirror of `jump_back`, popping the forward stack
    /// instead.
    pub(crate) fn jump_forward(&mut self) {
        if !self.jumplist_navigation_allowed() {
            return;
        }
        let current = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
        while let Some(entry) = self.jump_forward_stack.pop() {
            if self.buffers.get(entry.buffer).is_some() {
                self.jump_back_stack.push(current);
                self.goto_jump_entry(entry, false);
                return;
            }
        }
    }

    /// `` `{name} ``/`'{name}` -- looks up `name` in `marks` and jumps
    /// there, recording the position jumped *from* onto the jumplist
    /// first (same as a symbol/grep jump, and real Vim's own mark-jump
    /// behavior) so `Ctrl-O` returns here afterward. A no-op if that
    /// mark was never set, if its buffer's since closed (the stale entry
    /// is dropped from `marks` too, same graceful-degrade posture
    /// `jump_back`/`jump_forward` already have for the jumplist itself),
    /// or while a Docker/Git panel session is open (see `jumplist_
    /// navigation_allowed`'s own doc comment -- `goto_jump_entry` is
    /// exactly as unsafe to call from there for a mark as for a jump).
    fn jump_to_mark(&mut self, name: char, linewise: bool) {
        let Some(&entry) = self.marks.get(&name) else { return };
        if self.buffers.get(entry.buffer).is_none() {
            self.marks.remove(&name);
            return;
        }
        if !self.jumplist_navigation_allowed() {
            return;
        }
        let from = JumpEntry { buffer: self.focused_buffer_id(), char_idx: self.cursor().char_idx };
        self.goto_jump_entry(entry, linewise);
        self.record_jump(from);
    }

    /// `goto_jump_entry` repoints the *focused pane's* content outright
    /// (`set_pane_content`), which would silently desync a Docker/Git
    /// panel session's own pane-role bookkeeping (`pane_titles`, `docker_
    /// focused_role`/`git_focused_role`) if it fired on one of that
    /// session's panes -- those track *which pane holds which role* by
    /// pane id, not by buffer, and have no way to notice their pane's
    /// buffer just got swapped out from under them by something outside
    /// the session. Simplest safe rule: no jumplist navigation at all
    /// while either panel is open, rather than trying to reconcile
    /// session state case by case.
    fn jumplist_navigation_allowed(&self) -> bool {
        self.docker_session.is_none() && self.git_session.is_none()
    }

    /// Points the focused pane at `entry.buffer` (already open -- every
    /// `JumpEntry` was recorded from a buffer that existed at the time,
    /// see `JumpEntry`'s own doc comment) and lands the cursor at its
    /// char index (clamped in case the buffer's shrunk since) or, if
    /// `linewise`, the first non-blank of that char index's line --
    /// `'{mark}`'s own landing spot, real Vim's own `` ` ``/`'` split
    /// (`jump_back`/`jump_forward` always pass `false`; only `jump_to_
    /// mark` ever passes `true`). Doesn't touch `project_root`/recent-
    /// files the way `open_file_from_picker` does -- this is "return to
    /// where you were," not "visit a file," so those side effects don't
    /// apply.
    fn goto_jump_entry(&mut self, entry: JumpEntry, linewise: bool) {
        if entry.buffer != self.focused_buffer_id() {
            self.open_buffer_in_focused_pane(entry.buffer);
        }
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        let target = entry.char_idx.min(buffer.len_chars());
        cursor.char_idx = if linewise {
            let (line, _) = buffer.line_col(&Cursor { char_idx: target, sticky_col: 0 });
            line_first_non_blank_char(buffer, line)
        } else {
            target
        };
        let (_, col) = buffer.line_col(cursor);
        cursor.sticky_col = col;
    }

    /// Registers `root` as the current project and immediately chains
    /// into a find-file picker scoped to it -- matches Projectile's own
    /// default "switch project" action rather than leaving you with
    /// nothing to do next. Sets `main_view = Picker` explicitly: a no-op
    /// for the original caller (`picker_confirm`, already mid-picker so
    /// this was already true), but necessary for the dashboard's own
    /// call site (`dashboard_activate_selected`), which isn't already
    /// mid-picker when it calls this.
    fn switch_to_project(&mut self, root: PathBuf) {
        self.project_root = Some(root.clone());
        self.known_projects.add(root.clone());
        if let Err(err) = self.known_projects.save() {
            eprintln!("fenix: couldn't save project history: {err}");
        }
        let candidates = Self::find_file_candidates(&root);
        self.active_picker = Some(ActivePicker::FindFile(fenix_picker::PickerState::new(candidates)));
        self.picker_scroll = 0;
        self.main_view = MainView::Picker;
    }

    /// `Enter` on a dashboard buffer (see `handle_key`'s `BufferKind::
    /// Dashboard` check, right before the Vim fallthrough): looks up
    /// what the cursor's current line means via `dashboard_lines`, a
    /// no-op for any line that isn't a `Project`/`RecentFile` entry
    /// (banner/header/blank/footer). A project entry reuses `switch_to_
    /// project` (registers, then chains into a find-file picker, exactly
    /// what confirming it from the `SPC p p` picker already does); a
    /// recent-file entry reuses `open_file_from_picker` (opens it,
    /// records it, and focuses the editor) -- opening a file is opening
    /// a file, however the path was found.
    fn dashboard_activate_selected(&mut self) {
        let cursor = self.cursor();
        let line = self.open().buffer.line_col(&cursor).0;
        let entry = self
            .dashboard_lines
            .get(&self.focused_buffer_id())
            .and_then(|lines| lines.get(line))
            .and_then(|meta| meta.as_ref())
            .and_then(|meta| meta.entry.clone());
        let Some(entry) = entry else { return };
        match entry {
            dashboard::DashboardEntry::Project(root) => self.switch_to_project(root),
            dashboard::DashboardEntry::RecentFile(path) => self.open_file_from_picker(&path),
        }
    }

    /// Routes one keypress to the active picker: plain characters edit
    /// the query and re-filter, Up/Down or Ctrl-N/Ctrl-P move the
    /// selection, Enter confirms, Escape cancels -- everything else is
    /// ignored (the picker is a text-input mode, not an action trie like
    /// the explorer's, so unrecognized keys just don't do anything
    /// rather than falling through to something else).
    fn picker_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(picker), Some(text)) = (&mut self.active_picker, pasted) {
                // One `push_char` per pasted char, same as fast typing --
                // each fuzzy-picker's own `push_char` re-filters as it
                // goes, so this keeps the candidate list correct at every
                // step, not just at the end.
                for c in text.chars() {
                    picker_push_char(picker, c);
                }
            }
            self.wake_caret();
            return;
        }
        let Some(picker) = &mut self.active_picker else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.picker_cancel(),
            KeyCode::Named(FenixNamedKey::Enter) => self.picker_confirm(),
            KeyCode::Named(FenixNamedKey::Backspace) => picker_backspace(picker),
            KeyCode::Named(FenixNamedKey::Down) => picker_move_selection(picker, 1),
            KeyCode::Named(FenixNamedKey::Up) => picker_move_selection(picker, -1),
            KeyCode::Char('n') if key.mods.ctrl => picker_move_selection(picker, 1),
            KeyCode::Char('p') if key.mods.ctrl => picker_move_selection(picker, -1),
            // Toggles-and-does-not-close, unlike `Enter` -- a no-op for
            // every single-select picker (nothing ever reads their
            // marks). Chosen over `Space` since status names routinely
            // contain spaces (`"In Progress"`), which would make it
            // impossible to type a query that filters a long status list.
            KeyCode::Named(FenixNamedKey::Tab) => picker_toggle_mark(picker),
            KeyCode::Char(c) if !key.mods.ctrl => picker_push_char(picker, c),
            _ => {}
        }
        self.wake_caret();
    }

    /// The explorer currently receiving input: the full-buffer listing
    /// when `main_view == Explorer`, else the sidebar's when it's
    /// focused, else `None` (keys go to Vim instead).
    fn active_explorer(&self) -> Option<&ExplorerState> {
        if self.main_view == MainView::Explorer {
            self.explorer.as_ref()
        } else if self.sidebar_focused {
            self.sidebar.as_ref()
        } else {
            // The buffer-backed listing, which until now could not
            // reach any of this -- marks, delete, rename, create, copy
            // and move all existed and were simply unreachable from the
            // one form of the explorer that composes with splits.
            self.dired_states.get(&self.focused_dired_buffer()?)
        }
    }

    fn active_explorer_mut(&mut self) -> Option<&mut ExplorerState> {
        if self.main_view == MainView::Explorer {
            self.explorer.as_mut()
        } else if self.sidebar_focused {
            self.sidebar.as_mut()
        } else {
            let buffer = self.focused_dired_buffer()?;
            self.dired_states.get_mut(&buffer)
        }
    }

    /// The explorer buffer the focused pane is showing, if it is showing
    /// one.
    fn focused_dired_buffer(&self) -> Option<BufferId> {
        let id = *self.windows().content(self.focused_pane_id())?;
        (self.buffers.get(id).is_some_and(|ob| ob.kind == BufferKind::Explorer) && self.dired_states.contains_key(&id)).then_some(id)
    }

    /// Points the active listing's own `selected` at whatever the Vim
    /// cursor is on, for a buffer-backed listing.
    ///
    /// The two have to be reconciled somewhere. `ExplorerState` tracks a
    /// selection because the sidebar has no cursor; a buffer has a real
    /// one, and it is the real one the user is looking at. Doing this
    /// once, immediately before an action runs, is what stops `D` from
    /// deleting a row other than the one under the cursor.
    fn sync_dired_selection_from_cursor(&mut self) {
        let Some(buffer) = self.focused_dired_buffer() else { return };
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let entry = self.dired_lines.get(&buffer).and_then(|lines| lines.get(line)).copied().flatten();
        if let (Some(row), Some(state)) = (entry, self.dired_states.get_mut(&buffer)) {
            state.select_index(row.entry);
        }
    }

    /// Stores a freshly re-opened `ExplorerState` back into whichever
    /// slot is currently active -- used after navigating into a
    /// directory or up to a parent, which replace the whole listing.
    fn set_active_explorer(&mut self, state: ExplorerState) {
        if self.main_view == MainView::Explorer {
            self.explorer = Some(state);
        } else {
            self.sidebar = Some(state);
        }
    }

    /// Dispatches one explorer command against whichever listing is
    /// active. Re-fetches `active_explorer_mut()` fresh per arm rather
    /// than binding it once, since a few arms (`Open`, `ParentDir`,
    /// `Quit`) need to touch other `self` fields too (replacing the
    /// buffer, restoring the stash) and can't do that while still
    /// holding it borrowed.
    fn explorer_handle_action(&mut self, action: ExplorerAction) {
        if self.active_explorer().is_none() {
            return;
        }
        match action {
            ExplorerAction::Down => {
                self.active_explorer_mut().unwrap().move_selection(1);
            }
            ExplorerAction::Up => {
                self.active_explorer_mut().unwrap().move_selection(-1);
            }
            ExplorerAction::ToggleExpand => {
                if let Err(err) = self.active_explorer_mut().unwrap().toggle_expand() {
                    eprintln!("fenix: couldn't expand ({err})");
                }
            }
            ExplorerAction::ToggleMark => self.active_explorer_mut().unwrap().toggle_mark(),
            ExplorerAction::MarkAll => self.active_explorer_mut().unwrap().mark_all(),
            ExplorerAction::UnmarkAll => self.active_explorer_mut().unwrap().unmark_all(),
            ExplorerAction::ToggleAllMarks => self.active_explorer_mut().unwrap().toggle_all_marks(),
            ExplorerAction::ToggleHidden => {
                self.active_explorer_mut().unwrap().toggle_hidden();
                self.explorer_relist();
            }
            ExplorerAction::CycleSort => {
                let next = match self.active_explorer().unwrap().sort.key {
                    fenix_explorer::SortKey::Name => fenix_explorer::SortKey::Size,
                    fenix_explorer::SortKey::Size => fenix_explorer::SortKey::Modified,
                    fenix_explorer::SortKey::Modified => fenix_explorer::SortKey::Extension,
                    fenix_explorer::SortKey::Extension => fenix_explorer::SortKey::Name,
                };
                let sort = fenix_explorer::Sort { key: next, ..self.active_explorer().unwrap().sort };
                self.explorer_set_sort(sort);
            }
            ExplorerAction::ReverseSort => {
                let sort = self.active_explorer().unwrap().sort;
                self.explorer_set_sort(fenix_explorer::Sort { descending: !sort.descending, ..sort });
            }
            ExplorerAction::Refresh => self.explorer_relist(),
            ExplorerAction::ParentDir => {
                let parent = self.active_explorer().unwrap().cwd.parent().map(Path::to_path_buf);
                if let Some(parent) = parent {
                    self.explorer_go_to(&parent);
                }
            }
            ExplorerAction::Open => self.explorer_open_selected(),
            ExplorerAction::BeginDelete => {
                if !self.active_explorer().unwrap().targets().is_empty() {
                    self.explorer_prompt = Some(ExplorerPrompt { kind: PromptKind::ConfirmDelete, input: String::new() });
                }
            }
            ExplorerAction::BeginRename => {
                if let Some(name) = self.active_explorer().unwrap().selected_entry().map(|e| e.name.clone()) {
                    self.explorer_prompt = Some(ExplorerPrompt { kind: PromptKind::Rename, input: name });
                }
            }
            ExplorerAction::BeginCreateFile => {
                self.explorer_prompt = Some(ExplorerPrompt { kind: PromptKind::CreateFile, input: String::new() });
            }
            ExplorerAction::BeginCreateDir => {
                self.explorer_prompt = Some(ExplorerPrompt { kind: PromptKind::CreateDir, input: String::new() });
            }
            ExplorerAction::BeginCopy => {
                if !self.active_explorer().unwrap().targets().is_empty() {
                    self.explorer_prompt = Some(ExplorerPrompt { kind: PromptKind::CopyTo, input: String::new() });
                }
            }
            ExplorerAction::BeginMove => {
                if !self.active_explorer().unwrap().targets().is_empty() {
                    self.explorer_prompt = Some(ExplorerPrompt { kind: PromptKind::MoveTo, input: String::new() });
                }
            }
            ExplorerAction::Quit => self.explorer_quit(),
            ExplorerAction::SelectCwd => {
                if self.main_view == MainView::Explorer && self.explorer_purpose == ExplorerPurpose::PickProjectDir {
                    let cwd = self.active_explorer().unwrap().cwd.clone();
                    self.register_project_dir(&cwd);
                } else if self.main_view == MainView::Explorer && self.explorer_purpose == ExplorerPurpose::PickMibRootDir {
                    let cwd = self.active_explorer().unwrap().cwd.clone();
                    self.start_mib_root_label_prompt(&cwd);
                } else if self.main_view == MainView::Explorer && self.explorer_purpose == ExplorerPurpose::FindFrom {
                    let cwd = self.active_explorer().unwrap().cwd.clone();
                    self.start_find_from_here(&cwd);
                }
                // No-op during ordinary browsing (`SPC f j`/the sidebar) --
                // `S` only means something while picking a project/MIB dir,
                // or searching from a directory (`SPC f e`).
            }
        }
        self.wake_caret();
    }

    /// `Enter`/`l` on the entry at point: navigates into a directory
    /// (replacing the listing), or visits a file -- replacing the editor
    /// buffer and, depending on how the explorer got here, either
    /// returning to the editor (full-buffer mode, dropping the stash --
    /// the new file is now current) or just handing focus back to it
    /// (sidebar mode, which stays open). While picking a project
    /// directory (`SPC p a`), opening a file does nothing -- there's
    /// nothing sensible to do with a file when what's being picked is a
    /// directory; use `S` to register the directory currently being
    /// browsed instead.
    fn explorer_open_selected(&mut self) {
        let Some(explorer) = self.active_explorer() else { return };
        let Some(entry) = explorer.selected_entry() else { return };
        let path = entry.path.clone();
        let is_dir = entry.is_dir();

        if !is_dir
            && self.main_view == MainView::Explorer
            && matches!(self.explorer_purpose, ExplorerPurpose::PickProjectDir | ExplorerPurpose::PickMibRootDir)
        {
            return;
        }

        if is_dir {
            match ExplorerState::opened(&path) {
                Ok(new_state) => self.set_active_explorer(new_state),
                Err(err) => eprintln!("fenix: couldn't list {} ({err})", path.display()),
            }
            return;
        }

        if Self::looks_like_pdf(&path) {
            let was_full_buffer = self.main_view == MainView::Explorer;
            self.open_pdf_path(&path);
            if was_full_buffer {
                self.explorer = None;
            } else {
                self.sidebar_focused = false;
            }
            return;
        }

        let id = self.buffers.open_path(&path);
        self.note_disk_state(id);
        self.open_buffer_in_focused_pane(id);
        self.refresh_project_root();
        self.record_recent_file(&path);

        if self.main_view == MainView::Explorer {
            self.main_view = MainView::Editor;
            self.explorer = None;
        } else {
            self.sidebar_focused = false;
        }
    }

    /// `q`/`Escape`: in full-buffer mode, leaves the explorer entirely --
    /// the focused pane's buffer was never touched by entering it, so
    /// there's nothing to restore, just switch `main_view` back; in the
    /// sidebar, just hands focus back to the editor without closing it.
    fn explorer_quit(&mut self) {
        if self.main_view == MainView::Explorer {
            self.main_view = MainView::Editor;
            self.explorer = None;
            self.explorer_purpose = ExplorerPurpose::Browse;
        } else if self.sidebar_focused {
            self.sidebar_focused = false;
        }
    }

    /// Routes one keypress to whichever explorer prompt is active: a
    /// bare y/n for delete confirmation, or free-text input (with
    /// Backspace/Enter/Escape) for rename/create/copy/move.
    fn explorer_prompt_key(&mut self, key: KeyPress) {
        // A pending collision owns the keyboard until it is answered:
        // the operation is half-specified until then, and letting other
        // keys through would leave it in that state indefinitely.
        if self.explorer_conflict.is_some() {
            self.explorer_conflict_key(key);
            return;
        }

        let Some(prompt) = &mut self.explorer_prompt else { return };

        if prompt.kind == PromptKind::ConfirmDelete {
            if key.code == KeyCode::Char('y') || key.code == KeyCode::Char('Y') {
                self.explorer_prompt = None;
                self.explorer_delete_targets();
            } else {
                self.explorer_prompt = None;
            }
            self.wake_caret();
            return;
        }

        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(prompt), Some(text)) = (&mut self.explorer_prompt, pasted) {
                prompt.input.push_str(&text);
            }
            self.wake_caret();
            return;
        }

        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.explorer_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let ExplorerPrompt { kind, input } = self.explorer_prompt.take().unwrap();
                self.explorer_prompt_submit(kind, &input);
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                prompt.input.pop();
            }
            KeyCode::Char(c) => prompt.input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// One keystroke's answer to "something is already there".
    ///
    /// Four single keys rather than a typed word: this appears in the
    /// middle of an operation the user already asked for, and the whole
    /// point of asking is that it costs almost nothing.
    fn explorer_conflict_key(&mut self, key: KeyPress) {
        let on_conflict = match key.code {
            KeyCode::Char('o') | KeyCode::Char('O') => fenix_fs::OnConflict::Overwrite,
            KeyCode::Char('s') | KeyCode::Char('S') => fenix_fs::OnConflict::Skip,
            KeyCode::Char('b') | KeyCode::Char('B') => fenix_fs::OnConflict::KeepBoth,
            // Anything else -- Escape, `c`, a stray keystroke -- cancels.
            // Nothing has been written yet, so cancelling really does
            // leave both sides exactly as they were, and defaulting an
            // unrecognised key to "do nothing" is the only safe reading
            // of it.
            _ => {
                self.explorer_conflict = None;
                self.set_message("cancelled");
                self.wake_caret();
                return;
            }
        };
        let Some(ExplorerConflict { kind, targets, dest, .. }) = self.explorer_conflict.take() else { return };
        let outcomes = self.explorer_transfer(kind, &targets, &dest, on_conflict);
        self.report_explorer_outcomes(kind.past_tense(), outcomes);
        self.explorer_relist();
        self.wake_caret();
    }

    /// What to show in place of the modeline while `explorer_prompt` is
    /// active -- previously nothing rendered it at all, so typing a
    /// rename/create/copy/move was invisible (the state was captured
    /// correctly, there was just no on-screen feedback that a prompt was
    /// even open). Mirrors `:`/`/`'s own "the modeline becomes the
    /// prompt" convention.
    fn explorer_prompt_text(&self) -> Option<String> {
        if let Some(conflict) = &self.explorer_conflict {
            // Names the first collision and counts the rest: "some files
            // already exist" is not enough to decide on.
            let first = conflict.conflicts.first().map(|p| p.file_name().unwrap_or(p.as_os_str()).to_string_lossy().into_owned());
            let what = match (first, conflict.conflicts.len()) {
                (Some(name), 1) => format!("{name} already exists"),
                (Some(name), n) => format!("{name} and {} more already exist", n - 1),
                (None, n) => format!("{n} already exist"),
            };
            return Some(format!("{what}: [o]verwrite  [s]kip  keep [b]oth  Esc to cancel"));
        }
        let prompt = self.explorer_prompt.as_ref()?;
        Some(match prompt.kind {
            PromptKind::ConfirmDelete => {
                let n = self.active_explorer().map(|e| e.targets().len()).unwrap_or(0);
                let items = format!("{n} item{}", if n == 1 { "" } else { "s" });
                // The two deletes are not the same act and must never
                // read the same: one is undoable from the Recycle Bin,
                // the other is not.
                if self.explorer_delete_permanently {
                    format!("PERMANENTLY delete {items}? This cannot be undone. (y/n)")
                } else {
                    format!("Move {items} to the Recycle Bin? (y/n)")
                }
            }
            PromptKind::Rename => format!("Rename to: {}", prompt.input),
            PromptKind::CreateFile => format!("Create file: {}", prompt.input),
            PromptKind::CreateDir => format!("Create directory: {}", prompt.input),
            PromptKind::CopyTo => format!("Copy to: {}", prompt.input),
            PromptKind::MoveTo => format!("Move to: {}", prompt.input),
        })
    }

    fn explorer_prompt_submit(&mut self, kind: PromptKind, input: &str) {
        let Some(explorer) = self.active_explorer() else { return };
        let outcomes = match kind {
            PromptKind::Rename => vec![explorer.rename_selected(input).map(|_| ()).map_err(|e| e.to_string())],
            PromptKind::CreateFile => vec![explorer.create_file(input).map(|_| ()).map_err(|e| e.to_string())],
            PromptKind::CreateDir => vec![explorer.create_dir(input).map(|_| ()).map_err(|e| e.to_string())],
            // Copy and move ask about collisions *before* touching
            // anything -- the explorer this replaces overwrote silently.
            PromptKind::CopyTo | PromptKind::MoveTo => {
                let targets = explorer.target_paths();
                let dest = PathBuf::from(input);
                let conflicts = fenix_fs::conflicts_in(&targets, &dest);
                if !conflicts.is_empty() {
                    self.explorer_conflict = Some(ExplorerConflict { kind, targets, dest, conflicts });
                    self.wake_caret();
                    return;
                }
                self.explorer_transfer(kind, &targets, &dest, fenix_fs::OnConflict::KeepBoth)
            }
            PromptKind::ConfirmDelete => return, // handled in explorer_prompt_key via y/n, not Enter
        };
        self.report_explorer_outcomes(kind.past_tense(), outcomes);
        self.explorer_relist();
    }

    /// Runs a copy or a move now that its collisions have been settled,
    /// reporting each path's fate rather than only the first failure --
    /// a batch where two of ten files failed should say so.
    fn explorer_transfer(&mut self, kind: PromptKind, targets: &[PathBuf], dest: &Path, on_conflict: fenix_fs::OnConflict) -> Vec<Result<(), String>> {
        let outcomes = match kind {
            PromptKind::MoveTo => fenix_fs::move_into(targets, dest, on_conflict),
            _ => fenix_fs::copy_into(targets, dest, on_conflict),
        };
        outcomes.into_iter().map(|o| o.error.map_or(Ok(()), Err)).collect()
    }

    /// Moves the marked set (or the entry at point) to the Recycle Bin,
    /// so a mistake is recoverable through Windows' own restore rather
    /// than being final. `permanent` is the explicit `!` variant.
    fn explorer_delete_targets(&mut self) {
        let Some(explorer) = self.active_explorer() else { return };
        let targets = explorer.target_paths();
        let permanent = self.explorer_delete_permanently;
        let outcomes = if permanent { fenix_fs::permanently(&targets) } else { fenix_fs::to_recycle_bin(&targets) };
        let verb = if permanent { "deleted" } else { "moved to the Recycle Bin" };
        let outcomes: Vec<Result<(), String>> = outcomes.into_iter().map(|o| o.error.map_or(Ok(()), Err)).collect();
        self.report_explorer_outcomes(verb, outcomes);
        self.explorer_relist();
    }

    /// One status line for a whole batch: how many worked, and what went
    /// wrong with the first that did not. Silent failure is what the
    /// explorer this replaces did (an `eprintln!` nobody sees).
    fn report_explorer_outcomes(&mut self, verb: &str, outcomes: Vec<Result<(), String>>) {
        let total = outcomes.len();
        let failures: Vec<String> = outcomes.into_iter().filter_map(|o| o.err()).collect();
        match failures.first() {
            None if total == 1 => self.set_message(format!("1 item {verb}")),
            None => self.set_message(format!("{total} items {verb}")),
            Some(first) if failures.len() == total => self.set_error(first.clone()),
            Some(first) => self.set_error(format!("{} of {total} failed -- {first}", failures.len())),
        }
    }

    /// Re-reads whichever listing is active.
    ///
    /// A buffer-backed listing goes through the off-thread path, because
    /// that is the one that might be pointed at a share. The sidebar and
    /// the directory-picking overlay still read inline: both are
    /// deliberately rooted in local project directories, and giving them
    /// the same treatment is the last step of this milestone rather than
    /// something to half-do here.
    fn explorer_relist(&mut self) {
        if let Some(buffer) = self.focused_dired_buffer() {
            let Some(cwd) = self.dired_states.get(&buffer).map(|s| s.cwd.clone()) else { return };
            self.explorer_navigate(buffer, &cwd);
            return;
        }
        if let Some(explorer) = self.active_explorer_mut() {
            if let Err(err) = explorer.refresh() {
                let cwd = explorer.cwd.clone();
                self.set_error(format!("couldn't list {}: {err}", cwd.display()));
            }
        }
    }

    /// Points the active listing at `path`, whichever form it is.
    fn explorer_go_to(&mut self, path: &Path) {
        if let Some(buffer) = self.focused_dired_buffer() {
            self.explorer_navigate(buffer, path);
            return;
        }
        match ExplorerState::opened(path) {
            Ok(new_state) => self.set_active_explorer(new_state),
            Err(err) => self.set_error(format!("couldn't list {}: {err}", path.display())),
        }
    }

    /// Reorders the active listing. No re-read: rows are already in
    /// hand, and re-listing to change the order would be a needless
    /// round trip to a disk that might be slow.
    fn explorer_set_sort(&mut self, sort: fenix_explorer::Sort) {
        let Some(explorer) = self.active_explorer_mut() else { return };
        explorer.set_sort(sort);
        let label = explorer.sort.label();
        self.set_message(format!("sorted by {label}"));
        if let Some(buffer) = self.focused_dired_buffer() {
            self.render_dired(buffer, false);
        }
    }

    /// `SPC w v`/`SPC w s`: splits the focused window vertically (side by
    /// side) or horizontally (stacked), Doom's own `splitright`/
    /// `splitbelow` default -- the new pane shows the *same* buffer as the
    /// one it split from (matching Vim's own `:vsplit`/`:split`), not a
    /// blank scratch buffer, so it starts as a second view of what you
    /// were already looking at.
    fn split_window(&mut self, kind: SplitKind) {
        let id = self.focused_buffer_id();
        // The new pane starts as a second, independent view of the same
        // buffer -- same cursor/scroll as the pane it split from (real
        // Vim's own `:split` behavior), not the buffer's stale remembered
        // position. Cloned *before* `split` reassigns focus to the new
        // pane, from the source pane's own `PaneState` (see `PaneState`'s
        // own doc comment for why cursor/scroll are per-pane now).
        let source_state = *self.pane_state(self.focused_pane_id());
        let new_pane = self.windows_mut().split(kind, id);
        self.workspaces.active_pane_states_mut().insert(new_pane, source_state);
        self.wake_caret();
    }

    pub(crate) fn split_vertical(&mut self) {
        self.split_window(SplitKind::Vertical);
    }

    pub(crate) fn split_horizontal(&mut self) {
        self.split_window(SplitKind::Horizontal);
    }

    /// `SPC w hjkl`: moves focus to the nearest pane in that direction
    /// by real layout geometry, not tree adjacency -- and *across OS
    /// windows*, not just within one. Walking off the left edge of the
    /// window on one monitor continues into the window on the monitor
    /// beside it, landing on whichever of its panes is actually nearest
    /// (its rightmost, coming from the left edge -- not its first).
    ///
    /// One list of rectangles in desktop coordinates, one rule
    /// (`fenix_window::pick`). Panes in the current window are
    /// simply nearer than panes in the next window over, so ordinary
    /// same-window navigation behaves exactly as it always has without
    /// being a special case, and neither is the sidebar (see
    /// `NavTarget::Sidebar`).
    ///
    /// A no-op at the outermost edge of the outermost window.
    pub(crate) fn navigate_window(&mut self, dir: NavDirection) {
        let from = if self.sidebar_focused {
            NavTarget::Sidebar { frame: self.active_frame }
        } else {
            NavTarget::Pane { frame: self.active_frame, pane: self.focused_pane_id() }
        };
        let targets = self.nav_targets();
        let Some(target) = fenix_window::pick(&targets, from, dir) else { return };

        let frame = match target {
            NavTarget::Pane { frame, .. } | NavTarget::Sidebar { frame } => frame,
        };
        if frame != self.active_frame {
            self.focus_frame(frame);
            self.focus_active_frame_window();
        }
        match target {
            NavTarget::Pane { pane, .. } => {
                self.windows_mut().focus(pane);
                // Mirrors `handle_click_at`'s own rule: focusing a pane
                // always clears both panel-focus overrides, since they
                // sit outside the tree and nothing else would.
                self.sidebar_focused = false;
                self.terminal_focused = false;
            }
            NavTarget::Sidebar { .. } => {
                self.sidebar_focused = true;
                self.terminal_focused = false;
            }
        }
        self.wake_caret();
    }

    /// Every pane (and sidebar) of every open frame, as rectangles in
    /// one desktop coordinate space -- each frame's own layout offset by
    /// where its client area sits on the desktop.
    ///
    /// Computed by briefly activating each frame in turn, so the
    /// existing `frame_metrics`/`frame_geometry` pair -- which read the
    /// live sidebar and terminal state, and are what `redraw` and mouse
    /// hit-testing already agree with -- can be reused verbatim rather
    /// than reimplemented against a parked frame. Whichever frame was
    /// active is active again on return.
    fn nav_targets(&mut self) -> Vec<(NavTarget, fenix_window::Rect)> {
        let previous = self.active_frame;
        let mut targets = Vec::new();
        for frame in 0..self.frames.len() {
            self.activate_frame(frame);
            targets.extend(self.active_frame_nav_targets(frame));
        }
        self.activate_frame(previous);
        targets
    }

    /// The active frame's own navigation targets, in desktop
    /// coordinates. `frame` is passed in rather than read from
    /// `active_frame` only so the caller's loop index is what ends up
    /// in the keys.
    fn active_frame_nav_targets(&self, frame: usize) -> Vec<(NavTarget, fenix_window::Rect)> {
        let (width, height) = self
            .gpu
            .as_ref()
            .map(|gpu| (gpu.size.width as f32, gpu.size.height as f32))
            .unwrap_or(NAV_REFERENCE_SIZE);
        let (sidebar_px, terminal_h, modeline_top) = self.frame_metrics(height);
        let geometry = self.frame_geometry(width, sidebar_px, terminal_h, modeline_top);

        let (origin_x, origin_y) = (self.frame_origin.0 as f32, self.frame_origin.1 as f32);
        let to_desktop = |rect: fenix_window::Rect| fenix_window::Rect {
            x: rect.x + origin_x,
            y: rect.y + origin_y,
            w: rect.w,
            h: rect.h,
        };

        let mut targets: Vec<(NavTarget, fenix_window::Rect)> =
            geometry.panes.iter().map(|&(pane, rect)| (NavTarget::Pane { frame, pane }, to_desktop(rect))).collect();
        if let Some(rect) = geometry.sidebar_rect {
            targets.push((NavTarget::Sidebar { frame }, to_desktop(rect)));
        }
        targets
    }

    /// `SPC w w`: cycles focus to the next window in a stable pre-order
    /// traversal, wrapping around.
    pub(crate) fn cycle_window(&mut self) {
        self.windows_mut().cycle_next();
        self.wake_caret();
    }

    /// `SPC w q`: closes the focused window. Refuses (no-op) on the last
    /// window rather than quitting the editor -- silently losing your
    /// only view on a stray keypress is a real data-loss risk this
    /// project has consistently avoided elsewhere, a disclosed deviation
    /// from Doom's own "closes Emacs" behavior. The buffer itself is
    /// never closed here, only the pane showing it -- other panes may
    /// still reference the same `BufferId`.
    pub(crate) fn close_window(&mut self) {
        let closed_pane = self.focused_pane_id();
        if self.windows_mut().close_focused() {
            self.workspaces.active_pane_states_mut().remove(&closed_pane);
            self.workspaces.active_scroll_anims_mut().remove(&closed_pane);
        }
        self.wake_caret();
    }

    /// `SPC w o`: closes every window except the focused one. A permanent
    /// `only`, not Doom's reversible temporary "enlarge" -- restoring the
    /// closed panes would need layout history this tree doesn't keep yet
    /// (a disclosed cut, see `WindowTree::only`'s own doc comment).
    pub(crate) fn only_window(&mut self) {
        self.windows_mut().only();
        self.wake_caret();
    }

    /// `SPC w =`: resets every split's ratio back to an even 0.5.
    pub(crate) fn balance_windows(&mut self) {
        self.windows_mut().balance();
        self.wake_caret();
    }

    /// `SPC TAB n`: a new workspace, seeded with the focused pane's
    /// current buffer (so it starts on something, not a blank scratch
    /// buffer) -- becomes active immediately.
    pub(crate) fn new_workspace(&mut self) {
        let id = self.focused_buffer_id();
        let cursor = self.buffers.get(id).map(|ob| ob.cursor).unwrap_or(Cursor::at_start());
        self.workspaces.new_workspace(id, cursor);
        self.wake_caret();
    }

    /// `SPC TAB ]`/`SPC TAB [`: cycles the active workspace, wrapping.
    pub(crate) fn next_workspace(&mut self) {
        self.workspaces.next();
        self.wake_caret();
    }

    pub(crate) fn prev_workspace(&mut self) {
        self.workspaces.prev();
        self.wake_caret();
    }

    /// `SPC TAB d`: removes the active workspace. Refuses (no-op) on the
    /// last one -- same safety posture as `close_window` refusing the
    /// last window.
    pub(crate) fn remove_workspace(&mut self) {
        self.workspaces.remove_active();
        self.wake_caret();
    }

    /// `SPC TAB TAB`: a fuzzy picker over every currently open
    /// workspace, by name -- picking one directly rather than the
    /// relative `]`/`[` cycling `next_workspace`/`prev_workspace`
    /// already cover. The active workspace is marked with a leading
    /// `*` so re-opening the picker shows at a glance which one you're
    /// already on.
    pub(crate) fn picker_switch_workspace(&mut self) {
        let active = self.workspaces.active_index();
        let candidates = self
            .workspaces
            .summaries()
            .into_iter()
            .map(|(idx, name)| {
                let marker = if idx == active { "* " } else { "  " };
                fenix_picker::Candidate::new(format!("{marker}{name}"), idx)
            })
            .collect();
        self.enter_picker(ActivePicker::SwitchWorkspace(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC TAB r`: starts the rename prompt, pre-seeded with the
    /// active workspace's current name.
    pub(crate) fn start_rename_workspace_prompt(&mut self) {
        self.workspace_rename_prompt = Some(self.workspaces.active_name().to_string());
        self.wake_caret();
    }

    /// Routes one keypress to the in-progress `workspace_rename_prompt`
    /// -- same shape as `rename_file_prompt_key`.
    fn workspace_rename_prompt_key(&mut self, key: KeyPress) {
        if key == KeyPress::char('v').with_ctrl() {
            let pasted = self.clipboard_text();
            if let (Some(input), Some(text)) = (&mut self.workspace_rename_prompt, pasted) {
                input.push_str(&text);
            }
            self.wake_caret();
            return;
        }
        let Some(input) = &mut self.workspace_rename_prompt else { return };
        match key.code {
            KeyCode::Named(FenixNamedKey::Escape) => self.workspace_rename_prompt = None,
            KeyCode::Named(FenixNamedKey::Enter) => {
                let input = self.workspace_rename_prompt.take().unwrap_or_default();
                let trimmed = input.trim();
                if !trimmed.is_empty() {
                    self.workspaces.rename_active(trimmed.to_string());
                }
            }
            KeyCode::Named(FenixNamedKey::Backspace) => {
                input.pop();
            }
            KeyCode::Char(c) if key.mods == Mods::default() => input.push(c),
            _ => {}
        }
        self.wake_caret();
    }

    /// What to show in place of the modeline while `workspace_rename_
    /// prompt` is active.
    fn workspace_rename_prompt_text(&self) -> Option<String> {
        self.workspace_rename_prompt.as_ref().map(|input| format!("rename workspace to: {input}"))
    }

    /// `SPC TAB f`: a fuzzy picker over `config.ini`'s `[workspaces]`
    /// launcher list -- same "hand-configured shelf, one candidate
    /// list" shape `start_document_picker`/`start_vnc_picker` already
    /// established.
    ///
    /// An empty index says so rather than opening a picker over
    /// nothing, same reasoning as `start_document_picker`'s own check:
    /// this list can only be populated by hand-editing `config.ini`, so
    /// "no matches" would otherwise be indistinguishable from "you
    /// haven't set this up yet".
    pub(crate) fn start_workspace_launcher_picker(&mut self) {
        if self.config.workspaces.is_empty() {
            self.set_error(
                "no workspaces configured -- add a [workspaces] section to config.ini (ws1 = Name|action)".to_string(),
            );
            return;
        }
        let candidates =
            self.config.workspaces.iter().map(|(name, _)| fenix_picker::Candidate::new(name.clone(), name.clone())).collect();
        self.enter_picker(ActivePicker::WorkspaceLauncher(fenix_picker::PickerState::new(candidates)));
    }

    /// Switches to the currently-open workspace named `name`, or else
    /// runs its configured `[workspaces]` action to create one --
    /// `picker_confirm`'s `WorkspaceLauncher` arm.
    ///
    /// Every action already knows how to avoid duplicating itself:
    /// `open_git_panel`/`open_jira_panel`/`open_docker_panel` refocus
    /// their existing session instead of opening a second one, and
    /// `open_vnc_session` does the same by host name -- all independent
    /// of what the *workspace* happens to be named. Only the plain
    /// "no live session" action has nothing else to check against, so
    /// `open_named_workspace` does that matching itself.
    ///
    /// Whichever action ran, the workspace it leaves active gets
    /// renamed to `name` if it isn't already -- a freshly created
    /// session's workspace starts out "workspace-N," and without this
    /// it would show as that instead of the name you picked, both in
    /// `SPC TAB TAB`'s list and the modeline's own indicator.
    fn open_configured_workspace(&mut self, name: &str) {
        let Some((_, action)) = self.config.workspaces.iter().find(|(n, _)| n == name) else { return };
        // `Vnc`'s fresh-connect path is asynchronous: `open_vnc_session`
        // starts a background dial and returns immediately, having
        // touched no workspace at all (the real one is only created
        // later, from `apply_vnc_connected`, once the connection
        // actually succeeds) -- same for an outright connect failure
        // (an unconfigured host), which also leaves the active
        // workspace untouched. Comparing the active *index* before and
        // after, rather than assuming the dispatch always lands
        // somewhere new, is what keeps either of those from renaming
        // whatever workspace merely happened to be active at the time.
        let before = self.workspaces.active_index();
        match parse_workspace_action(action) {
            WorkspaceAction::Git => self.open_git_panel(),
            WorkspaceAction::Jira => self.open_jira_panel(),
            WorkspaceAction::Docker => self.open_docker_panel(),
            WorkspaceAction::Vnc(host) => self.open_vnc_session(&host),
            WorkspaceAction::Project(root) => self.open_project_workspace(name, root),
            WorkspaceAction::Plain => self.open_named_workspace(name),
        }
        if self.workspaces.active_index() != before && self.workspaces.active_name() != name {
            self.workspaces.rename_active(name.to_string());
        }
        self.wake_caret();
    }

    /// Switches to an already-open plain workspace named `name`, or
    /// else creates one (seeded with the focused buffer, via the same
    /// `new_workspace` `SPC TAB n` itself uses). The "no live session
    /// to check instead" counterpart of `open_vnc_session`/`open_
    /// docker_panel`'s own idempotence -- see `open_configured_
    /// workspace`'s own doc comment.
    fn open_named_workspace(&mut self, name: &str) {
        if let Some(idx) = self.workspaces.index_of_name(name) {
            self.workspaces.switch_to_index(idx);
            return;
        }
        self.new_workspace();
    }

    /// Switches to the already-open workspace named `name`, or else
    /// creates one and opens `root` in it via `switch_to_project` --
    /// the same "register, then chain into a find-file picker" behavior
    /// `SPC p p`/the dashboard's own project entries already use, so a
    /// `project:` launcher lands you exactly where picking that project
    /// any other way would. Same idempotence shape as `open_named_
    /// workspace`: identity is the launcher's configured *name*, not the
    /// root, so re-running this while that workspace is still open just
    /// switches to it rather than re-registering/re-picking every time.
    fn open_project_workspace(&mut self, name: &str, root: PathBuf) {
        if let Some(idx) = self.workspaces.index_of_name(name) {
            self.workspaces.switch_to_index(idx);
            return;
        }
        self.new_workspace();
        self.switch_to_project(root);
    }

    pub(crate) fn undo(&mut self) {
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        buffer.undo(cursor);
        self.wake_caret();
    }

    pub(crate) fn redo(&mut self) {
        let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
        buffer.redo(cursor);
        self.wake_caret();
    }

    /// Off -> Absolute -> Relative -> Off. Stands in for a config-file
    /// setting that doesn't exist yet (see `LineNumberMode`) -- a keybound
    /// cycle is how you'd want to flip this at runtime anyway, so it's not
    /// wasted work once config loading lands.
    pub(crate) fn cycle_line_number_mode(&mut self) {
        self.line_number_mode = match self.line_number_mode {
            LineNumberMode::Off => LineNumberMode::Absolute,
            LineNumberMode::Absolute => LineNumberMode::Relative,
            LineNumberMode::Relative => LineNumberMode::Off,
        };
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    /// Shared by the theme picker's confirm (`SPC t p`):
    /// sets the active theme, persists the choice, and requests a
    /// redraw. Save failure is non-fatal, same posture as `refresh_
    /// project_root`'s `known_projects.save()`.
    fn apply_theme(&mut self, theme: &'static Theme) {
        self.theme = theme;
        self.config.theme = Some(self.theme.name.to_string());
        if let Err(err) = self.config.save() {
            eprintln!("fenix: couldn't save theme choice: {err}");
        }
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    /// `SPC t f`: toggles borderless fullscreen. `winit::window::Window`
    /// is the source of truth (`window.fullscreen()`), not a mirrored
    /// `App`-owned flag -- nothing else in `App` duplicates window-owned
    /// state either, and this stays correct even if the window somehow
    /// left fullscreen by a means other than this toggle (e.g. the OS).
    pub(crate) fn toggle_fullscreen(&mut self) {
        let Some(window) = &self.window else { return };
        if window.fullscreen().is_some() {
            window.set_fullscreen(None);
        } else {
            window.set_fullscreen(Some(winit::window::Fullscreen::Borderless(None)));
        }
    }

    /// `SPC t p`: a fuzzy picker over every shipped theme (`theme::ALL`),
    /// for jumping straight to one by name rather than cycling through
    /// them one at a time.
    pub(crate) fn picker_pick_theme(&mut self) {
        let candidates =
            theme::ALL.iter().map(|t| fenix_picker::Candidate::new(t.name.to_string(), *t)).collect();
        self.enter_picker(ActivePicker::Theme(fenix_picker::PickerState::new(candidates)));
    }

    /// `SPC t =`/`Ctrl-=`/`SPC t -`/`Ctrl--`/`SPC t 0`/`Ctrl-0`: grows,
    /// shrinks, or resets the body text size at runtime and persists the
    /// choice, same posture as `apply_theme`. A no-op (nothing to resize,
    /// nothing to persist) before the GPU/`TextPipeline` exist yet --
    /// can't happen for a keybinding a running window is dispatching,
    /// but `App::new`/headless tests can call these before `resumed()`.
    fn adjust_font_size(&mut self, size: f32) {
        if self.text.is_none() {
            return;
        }
        // The *logical* size is what's persisted and what the steps
        // move: each frame's pipeline multiplies it by its own
        // monitor's scale factor (see `apply_font_size`), so storing
        // the already-scaled result would bake one monitor's DPI into
        // the config file.
        self.config.font_size = Some(size.clamp(text::MIN_FONT_SIZE, text::MAX_FONT_SIZE));
        self.apply_font_size();
        if let Err(err) = self.config.save() {
            eprintln!("fenix: couldn't save font size: {err}");
        }
        // `char_width` just changed, so how many columns fit the same
        // window width did too -- same reasoning as the window-resize
        // handler's own call.
        self.resync_terminal_cols();
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    /// Recomputes terminal columns for the current window width/font
    /// size and pushes it to the live session (if any) -- rows never
    /// change (`text::TERMINAL_ROWS` is fixed), so this is the one
    /// dimension that ever needs resyncing after a window resize or a
    /// font-size change.
    fn resync_terminal_cols(&mut self) {
        if self.terminal.is_none() {
            return;
        }
        let cols = self.terminal_cols();
        if let Some(state) = self.terminal.as_mut() {
            if let Err(err) = state.session.resize(text::TERMINAL_ROWS as u16, cols) {
                eprintln!("fenix: couldn't resize the terminal: {err}");
            }
        }
    }

    pub(crate) fn increase_font_size(&mut self) {
        if self.text.is_none() {
            return;
        }
        self.adjust_font_size(self.logical_font_size() + FONT_SIZE_STEP);
    }

    pub(crate) fn decrease_font_size(&mut self) {
        if self.text.is_none() {
            return;
        }
        self.adjust_font_size(self.logical_font_size() - FONT_SIZE_STEP);
    }

    pub(crate) fn reset_font_size(&mut self) {
        self.adjust_font_size(text::FONT_SIZE);
    }

    /// Whether caret-fade/scroll-ease/pulse animations should play at
    /// all -- `config.animations` unset defaults to on (today's look).
    /// A single flag consulted at every animation's own trigger site
    /// (`ensure_cursor_visible`'s scroll-anim insertion, the `Pulse`
    /// vim event, and `about_to_wait`'s blink-fade cadence check) rather
    /// than one central gate, since each animation is started from a
    /// different place and "just render it instantly instead" reads
    /// more clearly at the call site than a wrapped condition would.
    pub(crate) fn animations_enabled(&self) -> bool {
        self.config.animations.unwrap_or(true)
    }

    /// `SPC t a`: flips `config.animations` and persists it -- lets the
    /// user A/B a responsiveness complaint against animation cost
    /// without editing `config.ini` by hand.
    pub(crate) fn toggle_animations(&mut self) {
        let enabled = !self.animations_enabled();
        self.config.animations = Some(enabled);
        if let Err(err) = self.config.save() {
            self.set_error(format!("couldn't save config.ini: {err}"));
        } else {
            self.set_message(if enabled { "Animations on" } else { "Animations off" });
        }
    }

    /// Resets the caret blink timer so an edit or navigation always leaves
    /// the caret visible instead of possibly mid-blink.
    fn wake_caret(&mut self) {
        let now = Instant::now();
        self.blink_visible = true;
        // Already-elapsed transition: caret snaps to fully visible right
        // away. A fade-in here would read as input lag, not polish -- the
        // soft fade is for idle blinking, not for the moment right after
        // a keypress.
        self.blink_transition_start = now - BLINK_FADE;
        self.next_blink = now + BLINK_INTERVAL;
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    /// 0.0 (hidden) to 1.0 (fully visible), eased across `BLINK_FADE` from
    /// whichever state the caret last toggled into.
    fn caret_alpha(&self) -> f32 {
        if !self.animations_enabled() {
            return if self.blink_visible { 1.0 } else { 0.0 };
        }
        let elapsed = Instant::now().duration_since(self.blink_transition_start);
        let t = ease_out_cubic(elapsed.as_secs_f32() / BLINK_FADE.as_secs_f32());
        if self.blink_visible { t } else { 1.0 - t }
    }

    /// The actual `FenixUserEvent` handling logic, factored out of the
    /// `ApplicationHandler::user_event` trait method so it's directly
    /// callable from tests without needing a real `ActiveEventLoop`
    /// (which nothing outside winit's own running loop can construct)
    /// -- same reasoning `handle_key`/`test_vim_key` already established
    /// for keyboard input.
    fn handle_user_event(&mut self, event: FenixUserEvent) {
        match event {
            FenixUserEvent::Lsp { language, event } => self.apply_lsp_event(language, event),
            FenixUserEvent::StatsReady(stats) => self.apply_docker_stats(stats),
            FenixUserEvent::LogLine(buffer_id, line) => self.append_docker_log_line(buffer_id, line),
            FenixUserEvent::LogEnded(buffer_id) => self.finish_docker_log_stream(buffer_id),
            FenixUserEvent::TaskOutputLine(buffer_id, line) => self.append_task_output_line(buffer_id, line),
            FenixUserEvent::TaskFinished(buffer_id, success) => self.finish_task_run(buffer_id, success),
            FenixUserEvent::Dap(event) => self.apply_dap_event(event),
            FenixUserEvent::GitStatusReady(status) => self.apply_git_status(status),
            FenixUserEvent::GitMainReady { request_id, buffer, diff } => self.apply_git_main(request_id, buffer, diff),
            FenixUserEvent::ForgeListReady { request_id, result } => self.apply_forge_list(request_id, result),
            FenixUserEvent::ForgeDetailReady { request_id, number, result } => self.apply_forge_detail(request_id, number, *result),
            FenixUserEvent::GitHistoryDetailReady { request_id, buffer, diff } => {
                self.apply_history_detail(request_id, buffer, diff)
            }
            FenixUserEvent::GitFetched { result } => self.apply_git_fetched(result),
            FenixUserEvent::GitRefreshReady { request_id, data } => self.apply_git_refresh(request_id, data),
            FenixUserEvent::TerminalOutput(target, bytes) => self.apply_terminal_output(target, bytes),
            FenixUserEvent::ExplorerListed { buffer, request, result } => self.apply_explorer_listed(buffer, request, result),
            FenixUserEvent::ExplorerGitStatus { buffer, request, statuses } => self.apply_explorer_git_status(buffer, request, statuses),
            FenixUserEvent::TerminalSpawned(TerminalTarget::Panel, result) => self.apply_terminal_spawned(result.0),
            FenixUserEvent::TerminalSpawned(TerminalTarget::Buffer(id), result) => self.apply_terminal_buffer_spawned(id, result.0),
            FenixUserEvent::JiraIssuesReady { request_id, issues } => self.apply_jira_issues(request_id, issues),
            FenixUserEvent::JiraDetailReady { request_id, detail } => self.apply_jira_detail(request_id, detail),
            FenixUserEvent::JiraActionDone(result) => self.apply_jira_action_done(result),
            FenixUserEvent::JiraTransitionsReady { request_id, transitions } => self.apply_jira_transitions_ready(request_id, transitions),
            FenixUserEvent::JiraPrioritiesReady { request_id, priorities } => self.apply_jira_priorities_ready(request_id, priorities),
            FenixUserEvent::OpenFiles(paths) => self.apply_open_files(paths),
            // Deferred rather than handled here: opening a window needs
            // an `&ActiveEventLoop`, which `handle_user_event` doesn't
            // take (it's deliberately the `ActiveEventLoop`-free half of
            // `user_event`, so it stays directly testable). `about_to_
            // wait` runs moments later and does have one.
            FenixUserEvent::OpenFilesInNewFrame(paths) => self.pending_frames.push(paths),
            FenixUserEvent::VncConnected { name, host, port, result } => self.apply_vnc_connected(name, host, port, result.0),
            FenixUserEvent::VncFrame(key, frame) => self.apply_vnc_frame(key, frame),
            FenixUserEvent::PdfResponse(response) => self.apply_pdf_response(response),
        }
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    fn handle_key(&mut self, event: &KeyEvent, event_loop: &ActiveEventLoop) {
        // Caps Lock has no `fenix_keymap::NamedKey` counterpart -- it's
        // never a meaningful vim/leader keybinding, so `keymap::to_
        // keypress` filters it out before either branch below would ever
        // see it. Special-cased here instead, directly against the raw
        // winit key: forwarded as an ordinary press/release, but only
        // while a VNC session has input capture, so the guest's own OS
        // handles the actual lock toggle exactly as it would from a
        // directly-attached keyboard. Without this, physically toggling
        // Caps Lock only flips *this* OS's own lock state (which is all
        // that decides the case winit reports for the next letter typed)
        // -- the guest never finds out, so the two lock states silently
        // drift apart the moment they didn't already agree, with no key
        // that can resync them afterward.
        if event.logical_key == Key::Named(NamedKey::CapsLock) {
            if let Some(key) = self.vnc_focused.clone() {
                if let Some(session) = self.vnc_sessions.get(&key) {
                    session.client.send_key(fenix_vnc::keysym::CAPS_LOCK, event.state == ElementState::Pressed);
                }
            }
            return;
        }
        if event.state == ElementState::Released {
            // A focused VNC pane is the one place a real key-*up* matters
            // at all (RFB's `KeyEvent` genuinely distinguishes held keys
            // -- auto-repeat, drag-select, etc. -- from a synthetic
            // immediate down-then-up); nothing else in this app has ever
            // needed release events, so this is intentionally the only
            // path that looks at `ElementState::Released`, bypassing
            // `dispatch_keypress`/`route_keypress` entirely (macro
            // recording/dot-repeat have no meaningful notion of a key
            // release either).
            if let Some(key) = self.vnc_focused.clone() {
                if let Some(keypress) = keymap::to_keypress(event, self.modifiers) {
                    if keypress != KeyPress::char('\\').with_ctrl() {
                        self.send_vnc_key(&key, keypress, false);
                    }
                }
            }
            return;
        }
        if event.state != ElementState::Pressed {
            return;
        }

        let Some(keypress) = keymap::to_keypress(event, self.modifiers) else { return };
        self.dispatch_keypress(keypress, event_loop);
    }

    /// Every real keypress passes through here exactly once -- the tap
    /// that makes macro recording see everything, including keys a
    /// leader-triggered command or a prompt swallows before `VimState::
    /// handle_key` ever would (see `VimEvent::MacroRecordStart`'s own
    /// doc comment for why the tap has to live here, not in `fenix-
    /// vim`). `route_keypress` does the actual dispatch -- a macro
    /// replay (`VimEvent::MacroPlay`'s handling, inside `route_keypress`
    /// itself) calls `route_keypress` *directly*, deliberately skipping
    /// this tap: a nested `@b` call's own literal two keystrokes get
    /// captured here (as ordinary top-level input), but `b`'s *expanded*
    /// replay must not also be appended on top of that.
    ///
    /// Also where `.`'s own capture lives (`change_capture`), same
    /// always-tap reasoning: `VimState::is_idle()` marks the span
    /// boundary -- a fresh span starts (clearing `change_capture`/
    /// `change_capture_dirty`) whenever the state was idle *before* this
    /// key, and a completed span (idle again *after*) gets promoted to
    /// `last_change_keys` if it actually edited the buffer along the way
    /// (`change_capture_dirty`, set inside `route_keypress` at the one
    /// place `vim.handle_key` is called). `.` itself replays through
    /// `repeat_last_change` -> `route_keypress` directly, same as a
    /// macro, so its own replayed keys never re-enter this tap.
    fn dispatch_keypress(&mut self, keypress: KeyPress, event_loop: &ActiveEventLoop) {
        if self.vim.is_recording() {
            self.macro_capture.push(keypress);
        }
        if self.vim.is_idle() {
            self.change_capture.clear();
            self.change_capture_dirty = false;
        }
        self.change_capture.push(keypress);
        self.route_keypress(keypress, event_loop);
        if self.vim.is_idle() {
            if self.change_capture_dirty {
                self.last_change_keys = Some(std::mem::take(&mut self.change_capture));
            } else {
                self.change_capture.clear();
            }
        }
    }

    fn route_keypress(&mut self, keypress: KeyPress, event_loop: &ActiveEventLoop) {
        // A Docker which-key menu (`x` on a pane) is purely informational,
        // not a capturing prompt -- cleared unconditionally on *every*
        // keypress before that keypress is dispatched normally below, so
        // pressing any key both dismisses the popup and still does
        // whatever that key would otherwise do (real Lazydocker's own
        // "view command options" convention).
        self.docker_menu_open = false;
        // Same reasoning, for the Git panel's own `x` which-key menu.
        self.git_menu_open = false;
        // Same reasoning, for the Jira panel's own `x` which-key menu.
        self.jira_menu_open = false;
        // Same reasoning, for the LSP hover popup (`K`) -- purely
        // informational, dismissed by whatever key comes next rather
        // than needing its own dedicated close key.
        self.lsp_hover = None;

        // The terminal panel, when focused, owns *every* key -- checked
        // before even the capturing prompts/confirms below, since a
        // real shell needs Space/Escape/Ctrl-C/etc. to reach it
        // unmodified, not intercepted by something else first. `Ctrl-\`
        // is the one reserved chord that unfocuses (not closes) it
        // instead of forwarding, mirroring Neovim's own `:terminal`
        // convention -- see `App::terminal_focused`'s own doc comment.
        if self.terminal_focused {
            if keypress == KeyPress::char('\\').with_ctrl() {
                self.terminal_focused = false;
            } else {
                self.write_terminal_input(keypress);
            }
            self.wake_caret();
            return;
        }

        // A pane-resident terminal owns every key on exactly the same
        // terms as the panel above, and is checked in the same tier --
        // the two can never both hold the keyboard (`focus_terminal_
        // buffer` clears the other), so their order here is arbitrary.
        // `active_terminal_buffer`, rather than the field, is what makes
        // typing follow the pane you are actually looking at.
        if let Some(id) = self.active_terminal_buffer() {
            if keypress == KeyPress::char('\\').with_ctrl() {
                self.unfocus_terminal_buffer();
            } else {
                self.write_terminal_buffer_input(id, keypress);
            }
            self.wake_caret();
            return;
        }

        // A focused VNC pane owns every key the same way a focused
        // terminal does (same priority tier, same reserved `Ctrl-\`
        // release chord) -- see `App::vnc_focused`'s own doc comment.
        // Key *presses* are handled here; the corresponding key
        // *releases* are handled earlier, directly in `handle_key`,
        // since `route_keypress`/`dispatch_keypress` are never reached
        // for anything but a press (see `handle_key`'s own doc comment).
        if let Some(key) = self.vnc_focused.clone() {
            if keypress == KeyPress::char('\\').with_ctrl() {
                // Releases keyboard capture only -- the VNC pane stays
                // exactly as focused/visible as it was; a plain click
                // back into it (or reopening it via `SPC v v`) is what
                // re-engages capture, not anything automatic here. Not
                // `sync_vnc_focus()`: that derives `vnc_focused` from
                // which pane is *focused*, which this doesn't change, so
                // calling it here would just immediately re-capture.
                self.set_vnc_focused(None);
            } else {
                self.send_vnc_key(&key, keypress, true);
            }
            self.wake_caret();
            return;
        }

        // An armed quit confirmation (`:q`/`SPC q q`/the window's close
        // button with unsaved buffers) captures the very next key --
        // same "y confirms, anything else cancels" shape as `docker_
        // confirm_remove`/`git_confirm` below, checked first since it's
        // the one prompt that can be reached from *outside* Normal mode
        // too (the window close button).
        if self.quit_confirm {
            self.quit_confirm_key(keypress, event_loop);
            return;
        }

        // An active prompt (rename/create-name/confirm-delete), or an
        // unanswered "something is already there", captures every
        // keystroke until it resolves -- taking priority over everything
        // else, including global Ctrl-chords, so e.g. Ctrl-S can't
        // accidentally interrupt an in-progress rename, and a half-
        // specified copy can't be left pending while you go and edit
        // something.
        if self.explorer_prompt.is_some() || self.explorer_conflict.is_some() {
            self.explorer_prompt_key(keypress);
            return;
        }

        // An armed Docker remove confirmation (`x` on a container/image
        // row) captures the very next key the same way -- `y` confirms,
        // anything else cancels (see `docker_confirm_key`).
        if self.docker_confirm_remove.is_some() {
            self.docker_confirm_key(keypress);
            return;
        }

        // Same capturing shape for the Git panel's own destructive-action
        // confirm and its commit-message/new-branch-name prompt -- mirrors
        // `docker_confirm_remove`/`explorer_prompt` exactly.
        if self.git_confirm.is_some() {
            self.git_confirm_key(keypress);
            return;
        }
        if self.git_prompt.is_some() {
            self.git_prompt_key(keypress);
            return;
        }
        // Same capturing shape for the Jira dashboard's two-step add-
        // project/add-user prompt -- mirrors `git_prompt` exactly.
        if self.jira_prompt.is_some() {
            self.jira_prompt_key(keypress);
            return;
        }

        // `SPC f f`/`SPC f R`/`SPC f D` -- same capturing-prompt tier as
        // everything else here.
        if self.find_file_prompt.is_some() {
            self.find_file_prompt_key(keypress);
            return;
        }
        // `SPC r g` -- same capturing-prompt tier.
        if self.pdf_goto_page_prompt.is_some() {
            self.pdf_goto_page_prompt_key(keypress);
            return;
        }
        // `SPC r /` -- same capturing-prompt tier.
        if self.pdf_search_prompt.is_some() {
            self.pdf_search_prompt_key(keypress);
            return;
        }
        if self.rename_file_prompt.is_some() {
            self.rename_file_prompt_key(keypress);
            return;
        }
        // `SPC c r` -- same capturing-prompt tier.
        if self.lsp_rename_prompt.is_some() {
            self.lsp_rename_prompt_key(keypress);
            return;
        }
        // `SPC TAB r` -- same capturing-prompt tier.
        if self.workspace_rename_prompt.is_some() {
            self.workspace_rename_prompt_key(keypress);
            return;
        }
        // `SPC m a`'s label step -- same capturing-prompt tier.
        if self.mib_root_prompt.is_some() {
            self.mib_root_prompt_key(keypress);
            return;
        }
        if self.delete_file_confirm {
            self.delete_file_confirm_key(keypress);
            return;
        }

        // The grep search-term prompt and an open picker both capture
        // input the same way -- checked ahead of the explorer/sidebar-
        // focus check below since a picker can be opened while the
        // sidebar is focused (switch-project's find-file chain, for
        // instance). The add-project flow no longer has its own prompt
        // state to check here -- it's just the ordinary explorer
        // (`main_view == Explorer`), routed the same way `SPC f j` is.
        if self.pending_grep_query.is_some() {
            self.grep_query_key(keypress);
            return;
        }
        if self.active_picker.is_some() {
            self.picker_key(keypress);
            return;
        }
        // The `SPC m i` wizard's own text-entry/y-n stages -- checked
        // after `active_picker` so its `ArgumentAlias` sub-step (where
        // `mib_insert` is *also* still `Some`) is routed there instead;
        // this only ever fires for `ChooseArgumentMode`/`ArgumentText`/
        // `Confirm`, none of which go through a picker.
        if self.mib_insert.is_some() {
            self.mib_insert_key(keypress);
            return;
        }
        // `SPC s r`/`SPC s p`'s pattern/replacement text entry -- same
        // tier as the other capturing prompts above.
        if self.replace_wizard.is_some() {
            self.replace_wizard_key(keypress);
            return;
        }

        // The full-buffer explorer (dired-style, replacing the whole
        // editing view) owns all input unconditionally -- its own trie,
        // not Vim's, and not the global Ctrl-chords below (browsing is a
        // distinct modal UI, the same reasoning that already keeps
        // Insert/Command mode out of Normal's trie).
        if self.main_view == MainView::Explorer {
            if let Step::Matched(&action) = self.explorer_matcher.feed(keypress) {
                self.explorer_handle_action(action);
            }
            self.wake_caret();
            return;
        }

        // The sidebar is different: a persistent panel meant to coexist
        // with active editing, not a modal takeover, so SPC still reaches
        // the leader menu below (e.g. `SPC w l` to jump back to another
        // window) instead of being swallowed. Pressing it also hands focus
        // back to the editor, since leader commands act on the window/
        // buffer layer, not the sidebar.
        if self.sidebar_focused {
            if keypress == KeyPress::char(' ') && self.vim.mode() == Mode::Normal {
                self.sidebar_focused = false;
            } else {
                if let Step::Matched(&action) = self.explorer_matcher.feed(keypress) {
                    self.explorer_handle_action(action);
                }
                self.wake_caret();
                return;
            }
        }

        // `keypress.mods.ctrl`, not `self.modifiers.control_key()` --
        // the two always agree for a real hardware keypress (`keypress`
        // is derived from `self.modifiers` at conversion time), but only
        // `keypress` carries the *recorded* modifier state for a macro
        // replay, which has no live hardware modifiers of its own to
        // read. The Ctrl-Shift-Z-vs-Ctrl-Z distinction still reads the
        // live `self.modifiers.shift_key()` rather than the char's case
        // -- unlike Ctrl itself, this codebase has no evidence winit
        // reliably reports the *shifted* character through a Ctrl-chord
        // on every platform, so this one sub-branch keeps the original,
        // proven-correct check; a macro that recorded Ctrl-Shift-Z
        // specifically just won't replay that distinction faithfully, a
        // narrow, disclosed gap far preferable to risking a regression
        // in the everyday redo shortcut itself.
        if keypress.mods.ctrl {
            if let KeyCode::Char(c) = keypress.code {
                let id = if c.eq_ignore_ascii_case(&'s') {
                    Some("file.save")
                } else if c.eq_ignore_ascii_case(&'z') && self.modifiers.shift_key() {
                    Some("edit.redo")
                } else if c.eq_ignore_ascii_case(&'z') {
                    Some("edit.undo")
                } else if c.eq_ignore_ascii_case(&'y') {
                    Some("edit.redo")
                } else if c.eq_ignore_ascii_case(&'q') {
                    Some("app.quit")
                } else if c == '=' || c == '+' {
                    Some("view.increase_font_size")
                } else if c == '-' {
                    Some("view.decrease_font_size")
                } else if c == '0' {
                    Some("view.reset_font_size")
                } else if c.eq_ignore_ascii_case(&'o') {
                    Some("nav.jump_back")
                } else if c.eq_ignore_ascii_case(&'i') {
                    Some("nav.jump_forward")
                } else {
                    None
                };
                if let Some(id) = id {
                    // Built fresh per chord rather than stored on App: it's
                    // just a few fn-pointer entries, and this sidesteps
                    // borrowing `self` both as receiver and argument.
                    CommandRegistry::with_builtins().run(self, event_loop, id);
                    self.wake_caret();
                    return;
                }
            }
            // Not a recognized global chord (e.g. Ctrl-r is Vim's redo):
            // fall through instead of swallowing it.
        }

        // Window-size-aware paging is a GUI concern, handled the same way
        // regardless of Vim mode -- fenix-vim doesn't know about viewport size.
        if keypress == KeyPress::named(FenixNamedKey::PageUp)
            || keypress == KeyPress::named(FenixNamedKey::PageDown)
        {
            let page_size = match (&self.gpu, &self.text) {
                (Some(gpu), Some(text)) => {
                    text::visible_line_count(gpu.size.height as f32, text.modeline_height(), text.line_height())
                }
                (Some(gpu), None) => text::visible_line_count(gpu.size.height as f32, text::LINE_HEIGHT + 8.0, text::LINE_HEIGHT),
                (None, _) => 20,
            };
            let down = keypress == KeyPress::named(FenixNamedKey::PageDown);
            let (buffer, cursor) = self.focused_buffer_and_cursor_mut();
            buffer.move_page(cursor, page_size, down);
            self.wake_caret();
            return;
        }

        // Leader sequences span multiple keystrokes: stay routed here while
        // one is already in progress, or start one on SPC from Normal or
        // Visual mode (matching orbit-emacs, where SPC is evil-visual-
        // state's leader too -- in Insert mode it should just insert a
        // space). Fenix's own Visual keymap has no binding for a bare
        // space, so this doesn't take anything away from Visual mode --
        // it only makes `SPC c f` (format the active selection) and the
        // rest of the leader menu reachable without leaving the
        // selection first. The leader keys themselves (here, `c`/`f`)
        // never reach `self.vim`, so the selection's anchor/cursor stay
        // exactly as they were until whatever command they resolve to
        // (e.g. `format_selection`) reads them.
        if self.leader_matcher.is_pending()
            || (matches!(self.vim.mode(), Mode::Normal | Mode::Visual) && keypress == KeyPress::char(' '))
        {
            if let Step::Matched(&id) = self.leader_matcher.feed(keypress) {
                CommandRegistry::with_builtins().run(self, event_loop, id);
            }
            self.wake_caret();
            return;
        }

        if self.completion_key(keypress) {
            self.wake_caret();
            return;
        }

        // The dashboard is a real Vim-navigable buffer (see `BufferKind`'s
        // own doc comment) -- every other key still reaches Vim below
        // unchanged (movement, `/` search, `gg`/`G`...); only `Enter`
        // means something special on it.
        if self.open().kind == BufferKind::Dashboard && keypress.code == KeyCode::Named(FenixNamedKey::Enter) {
            self.dashboard_activate_selected();
            self.wake_caret();
            return;
        }

        // A dired buffer is real Vim-navigable text -- ordinary motions
        // (`hjkl`, `gg`/`G`, `/` search, ...) reach Vim below unchanged.
        // The *operations* are claimed here first, resolved through the
        // same `explorer_trie` the sidebar reads, so the two forms of
        // the explorer cannot disagree about what a key does. Only
        // navigation actions are left to Vim (see `ExplorerAction::
        // is_navigation`): `j`/`k` are the cursor here, and the cursor
        // is the selection.
        //
        // This is what closes the gap the buffer form shipped with --
        // marks, delete, rename, create, copy and move all existed and
        // were reachable only from the sidebar, which cannot be split.
        if self.open().kind == BufferKind::Explorer {
            // Escape stops waiting for a directory that is not
            // answering, and does nothing at all otherwise -- claiming
            // it unconditionally would take a key away from Vim for a
            // situation that is not happening (see `explorer_abandon_
            // listing` for why stopping the wait is all that is on
            // offer: the read itself cannot be cancelled).
            if keypress.code == KeyCode::Named(FenixNamedKey::Escape) {
                let id = self.focused_buffer_id();
                if self.explorer_abandon_listing(id) {
                    return;
                }
            }
            if let Some(action) = dired_action_for(keypress) {
                self.dired_handle_action(action);
                self.wake_caret();
                return;
            }
        }

        // A table view (`SPC f t`) is likewise real Vim-navigable text --
        // ordinary motions and edits reach Vim below unchanged (editing a
        // cell is just ordinary Vim text editing on the buffer's real
        // tab-separated content; nothing table-specific is needed for
        // that at all). Only `]`/`[` (next/prev column) and `j`/`k`
        // (reinterpreted: same *elastic column* on the adjacent row, not
        // plain char-based `sticky_col`, which stops tracking "same
        // column" once rows have different raw lengths up to it -- see
        // `table_move_row`'s own doc comment) and `c` (jump to a column
        // by name) are claimed here first.
        if self.open().kind == BufferKind::Table {
            match keypress.code {
                KeyCode::Char(']') if keypress.mods == Mods::default() => {
                    self.table_move_column(1);
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('[') if keypress.mods == Mods::default() => {
                    self.table_move_column(-1);
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('j') if keypress.mods == Mods::default() => {
                    self.table_move_row(1);
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('k') if keypress.mods == Mods::default() => {
                    self.table_move_row(-1);
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('c') if keypress.mods == Mods::default() => {
                    self.open_table_column_picker();
                    return;
                }
                _ => {}
            }
        }

        // A PDF pane's buffer is deliberately empty (see `BufferKind`'s
        // own doc comment on `Pdf`) -- there's no real text underneath
        // for any of these to move a cursor through, so a reader's worth
        // of bare keys is claimed here rather than falling through to Vim
        // as harmless no-ops on nothing.
        //
        // Everything a reader reaches for without thinking is bound
        // directly, because a three-key leader chord (`SPC r n`) per page
        // is not a page-turn gesture anyone will use to read a 50-page
        // document: `PageDown`/`PageUp` and `n`/`p` turn the page,
        // `j`/`k` and the arrow keys scroll continuously *through* page
        // boundaries (see `pdf_scroll`), `Home`/`End` jump to the first/
        // last page, `+`/`-`/`0` zoom, and `/` searches. The `SPC r ...`
        // leader bindings all still work and are what the which-key menu
        // discovers -- these are the same commands, reachable in one
        // keystroke while a PDF is actually focused. `SPC` itself never
        // reaches here (the leader block above claims it first), which is
        // why space isn't bound as a page-down.
        if self.open().kind == BufferKind::Pdf && keypress.mods == Mods::default() {
            match keypress.code {
                KeyCode::Char('h') | KeyCode::Named(FenixNamedKey::Left) => {
                    self.pdf_pan(-1, 0);
                    return;
                }
                KeyCode::Char('l') | KeyCode::Named(FenixNamedKey::Right) => {
                    self.pdf_pan(1, 0);
                    return;
                }
                KeyCode::Char('j') | KeyCode::Named(FenixNamedKey::Down) => {
                    self.pdf_scroll(PDF_PAN_STEP_PX as i32);
                    return;
                }
                KeyCode::Char('k') | KeyCode::Named(FenixNamedKey::Up) => {
                    self.pdf_scroll(-(PDF_PAN_STEP_PX as i32));
                    return;
                }
                KeyCode::Named(FenixNamedKey::PageDown) | KeyCode::Char('n') => {
                    self.pdf_next_page();
                    return;
                }
                KeyCode::Named(FenixNamedKey::PageUp) | KeyCode::Named(FenixNamedKey::Backspace) | KeyCode::Char('p') => {
                    self.pdf_prev_page();
                    return;
                }
                KeyCode::Named(FenixNamedKey::Home) | KeyCode::Char('g') => {
                    self.pdf_first_page();
                    return;
                }
                KeyCode::Named(FenixNamedKey::End) | KeyCode::Char('G') => {
                    self.pdf_last_page();
                    return;
                }
                KeyCode::Char('+') | KeyCode::Char('=') => {
                    self.pdf_zoom_in();
                    return;
                }
                KeyCode::Char('-') => {
                    self.pdf_zoom_out();
                    return;
                }
                KeyCode::Char('0') => {
                    self.pdf_zoom_fit_page();
                    return;
                }
                KeyCode::Char('w') => {
                    self.pdf_zoom_fit_width();
                    return;
                }
                KeyCode::Char('/') => {
                    self.start_pdf_search_prompt();
                    return;
                }
                _ => {}
            }
        }

        // A PDF outline pane is a real Vim-navigable buffer (see
        // `BufferKind`'s own doc comment on `PdfOutline`) -- every other
        // key still reaches Vim below unchanged (movement, `/` search,
        // `gg`/`G`...); only `Enter` means something special on it, same
        // shape as the Dashboard interception above.
        if self.open().kind == BufferKind::PdfOutline && keypress.code == KeyCode::Named(FenixNamedKey::Enter) {
            self.pdf_outline_activate_selected();
            self.wake_caret();
            return;
        }

        // A PDF search-results pane -- same shape as the outline
        // interception just above, just jumping to a match's page
        // instead of a bookmark's.
        if self.open().kind == BufferKind::PdfSearchResults && keypress.code == KeyCode::Named(FenixNamedKey::Enter) {
            self.pdf_search_activate_selected();
            self.wake_caret();
            return;
        }

        // The `SPC s p` project-replace review buffer -- ordinary
        // motions (`j k gg G / n N`) navigate it like any real buffer
        // (it's genuinely one), but its own action keys are claimed
        // here first, same "claim a few keys" shape as the dired/table
        // blocks above. `q`/`Esc` deliberately mean "close this pane"
        // here, not whatever they'd mean in ordinary editing (macro-
        // record `q`, in particular) -- same precedent the Explorer/
        // Docker/Git panels already established for their own `q`.
        if self.open().kind == BufferKind::SearchReplace {
            let confirming = self.project_replace.as_ref().is_some_and(|s| s.confirming);
            match keypress.code {
                KeyCode::Named(FenixNamedKey::Escape) | KeyCode::Char('q') if keypress.mods == Mods::default() => {
                    if confirming {
                        self.project_replace_decline_confirm();
                    } else {
                        self.project_replace_cancel();
                    }
                    return;
                }
                _ if confirming => {
                    // Any key other than Escape/`q` (already handled
                    // above) while the apply gate is armed: `y` applies,
                    // anything else declines back to plain review --
                    // same "only Escape/`q` or `y` mean anything, every
                    // other key is a plain decline" shape `docker_
                    // confirm_key`'s own y/n gate already has.
                    if let KeyCode::Char(c) = keypress.code {
                        if c.eq_ignore_ascii_case(&'y') {
                            self.project_replace_apply();
                            return;
                        }
                    }
                    self.project_replace_decline_confirm();
                    return;
                }
                KeyCode::Char(' ') | KeyCode::Char('t') if keypress.mods == Mods::default() => {
                    self.project_replace_toggle_selected();
                    return;
                }
                KeyCode::Char('a') if keypress.mods == Mods::default() => {
                    self.project_replace_confirm_or_apply();
                    return;
                }
                KeyCode::Named(FenixNamedKey::Enter) => {
                    self.project_replace_confirm_or_apply();
                    return;
                }
                _ => {}
            }
        }

        // Lazydocker-style multi-pane panel: ordinary motions (`hjkl`,
        // `gg`/`G`, `/` search) reach Vim below unchanged in every one of
        // the four panes -- only a small, pane-scoped action-key set is
        // claimed here first, same "claim a few keys, everything else
        // falls through" shape the dired buffer above already uses.
        // Routed by *which pane is focused*, not by buffer kind alone --
        // all four panes share `BufferKind::Docker` (see `DockerSession`'s
        // own doc comment for why role lives there, not in `BufferKind`).
        if let Some(role) = self.docker_focused_role() {
            use DockerPaneRole::*;
            match (role, keypress.code) {
                (Containers, KeyCode::Char('s')) if keypress.mods == Mods::default() => {
                    self.docker_start_selected();
                    self.wake_caret();
                    return;
                }
                (Containers, KeyCode::Char('S')) if keypress.mods == Mods::default() => {
                    self.docker_stop_selected();
                    self.wake_caret();
                    return;
                }
                (Containers, KeyCode::Char('R')) if keypress.mods == Mods::default() => {
                    self.docker_restart_selected();
                    self.wake_caret();
                    return;
                }
                (Containers, KeyCode::Char('l')) if keypress.mods == Mods::default() => {
                    self.docker_view_logs_selected();
                    self.wake_caret();
                    return;
                }
                (Images, KeyCode::Char('r')) if keypress.mods == Mods::default() => {
                    self.docker_run_selected();
                    self.wake_caret();
                    return;
                }
                (Containers, KeyCode::Char('d')) | (Images, KeyCode::Char('d')) | (Networks, KeyCode::Char('d'))
                    if keypress.mods == Mods::default() =>
                {
                    if let Some(entry) = self.docker_entry_at_cursor() {
                        self.docker_confirm_remove = Some(entry);
                    }
                    self.wake_caret();
                    return;
                }
                (_, KeyCode::Char('u')) if keypress.mods == Mods::default() => {
                    self.docker_refresh_session();
                    self.wake_caret();
                    return;
                }
                (Containers | Images | Volumes | Networks, KeyCode::Char('x')) if keypress.mods == Mods::default() => {
                    self.docker_menu_open = true;
                    self.wake_caret();
                    return;
                }
                // Jump straight to the pane numbered `n` in its title bar
                // (`1. Containers`, `2. Images`, ...) -- a plain digit
                // here would otherwise just start an unused Vim count on
                // a non-editable panel buffer, so claiming it costs
                // nothing real editing would use.
                (_, KeyCode::Char(c)) if keypress.mods == Mods::default() && c.is_ascii_digit() => {
                    if let Some(pane) = self.docker_pane_by_number(c.to_digit(10).unwrap_or(0)) {
                        self.windows_mut().focus(pane);
                        if matches!(
                            self.docker_focused_role(),
                            Some(DockerPaneRole::Containers | DockerPaneRole::Images | DockerPaneRole::Volumes | DockerPaneRole::Networks)
                        ) && self.docker_session.as_ref().is_some_and(|s| s.logs_container.is_none())
                        {
                            self.docker_sync_details();
                        }
                        self.wake_caret();
                    }
                    return;
                }
                _ => {}
            }
        }

        // Diff-viewer keys, claimed wherever a rendered diff is focused
        // rather than per-panel: the working tree's Main pane, a
        // commit's detail in the History view and a comparison's changes
        // are all the same viewer, so `Tab` folding a file and `]`/`[`
        // stepping between hunks have to mean the same thing in all
        // three. Everything else falls through to the per-view blocks
        // below, and from there to Vim.
        // The compose pane's own two keys, checked before anything else
        // claims them. Only in Normal mode: in Insert, `Enter` is a
        // newline and `q` is a letter, which is the whole point of
        // writing a comment in a real buffer.
        if self.compose.as_ref().is_some_and(|c| c.pane == self.focused_pane_id())
            && self.vim.mode() == Mode::Normal
            && keypress.mods == Mods::default()
        {
            match keypress.code {
                KeyCode::Named(FenixNamedKey::Enter) => {
                    self.compose_submit();
                    return;
                }
                KeyCode::Char('q') => {
                    self.compose_cancel();
                    return;
                }
                _ => {}
            }
        }

        if self.focused_diff_buffer().is_some() && keypress.mods == Mods::default() {
            match keypress.code {
                KeyCode::Char('s') => {
                    self.diff_apply_hunk(fenix_git::ApplyTarget::Stage);
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('S') => {
                    self.diff_apply_hunk(fenix_git::ApplyTarget::Unstage);
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('d') => {
                    self.diff_discard_request();
                    self.wake_caret();
                    return;
                }
                KeyCode::Char(']') => {
                    self.diff_jump_hunk(true);
                    return;
                }
                KeyCode::Char('[') => {
                    self.diff_jump_hunk(false);
                    return;
                }
                KeyCode::Named(FenixNamedKey::Tab) => {
                    self.diff_toggle_fold();
                    return;
                }
                KeyCode::Named(FenixNamedKey::Enter) => {
                    self.diff_open_file_at_cursor();
                    return;
                }
                _ => {}
            }
        }

        // The History and Compare views claim their own small key sets
        // the same way, ahead of the working-tree panel's block below --
        // they're separate workspaces, so there's no ambiguity about
        // which one a keypress is meant for.
        if self.history_session.as_ref().is_some_and(|s| {
            let focused = self.focused_pane_id();
            focused == s.graph_pane || focused == s.refs_pane || focused == s.detail_pane
        }) && keypress.mods == Mods::default()
        {
            match keypress.code {
                KeyCode::Char('u') => {
                    self.history_refresh();
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('f') => {
                    self.git_fetch();
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('x') => {
                    self.git_menu_open = true;
                    self.wake_caret();
                    return;
                }
                // Jump straight to a numbered pane, the same shortcut
                // the Docker and Git panels' own titles advertise.
                KeyCode::Char(c) if c.is_ascii_digit() => {
                    if let Some(pane) = self.history_pane_by_number(c.to_digit(10).unwrap_or(0)) {
                        self.windows_mut().focus(pane);
                        // Landing on the graph re-syncs the detail pane
                        // to whatever row the cursor was left on there.
                        self.history_sync_detail();
                        self.wake_caret();
                    }
                    return;
                }
                _ => {}
            }
        }
        if self.compare_session.as_ref().is_some_and(|s| {
            let focused = self.focused_pane_id();
            focused == s.commits_pane || focused == s.diff_pane
        }) && keypress.mods == Mods::default()
        {
            match keypress.code {
                KeyCode::Char('t') => {
                    self.compare_toggle_dots();
                    return;
                }
                KeyCode::Char('u') => {
                    self.compare_refresh();
                    self.wake_caret();
                    return;
                }
                KeyCode::Char('r') => {
                    // Re-target without closing: the same two-step ref
                    // picker `SPC g c` opens, reusing this workspace.
                    self.start_compare_picker();
                    return;
                }
                KeyCode::Char('x') => {
                    self.git_menu_open = true;
                    self.wake_caret();
                    return;
                }
                KeyCode::Char(c) if c.is_ascii_digit() => {
                    if let Some(pane) = self.compare_pane_by_number(c.to_digit(10).unwrap_or(0)) {
                        self.windows_mut().focus(pane);
                        self.wake_caret();
                    }
                    return;
                }
                _ => {}
            }
        }

        // The Merge Requests view's own keys.
        if let Some((on_list, on_detail, on_review)) = self.forge_session.as_ref().map(|s| {
            let focused = self.focused_pane_id();
            (focused == s.list_pane, focused == s.detail_pane, focused == s.review_pane)
        }) {
            if (on_list || on_detail || on_review) && keypress.mods == Mods::default() {
                // Any key that isn't a second `m` cancels an armed
                // merge -- the same "arm, then anything else backs out"
                // the Git panel's destructive actions already use.
                if keypress.code != KeyCode::Char('m') {
                    self.forge_disarm_merge();
                }
                match keypress.code {
                    KeyCode::Char('r') if on_review => {
                        self.forge_reply_at_cursor();
                        return;
                    }
                    KeyCode::Char('R') if on_review => {
                        self.forge_resolve_at_cursor();
                        return;
                    }
                    KeyCode::Char('C') if on_review => {
                        self.forge_comment_at_cursor();
                        return;
                    }
                    KeyCode::Char('A') => {
                        self.forge_toggle_approval();
                        return;
                    }
                    KeyCode::Char('m') => {
                        self.forge_merge_request();
                        return;
                    }
                    KeyCode::Named(fenix_keymap::NamedKey::Enter) if on_list => {
                        self.forge_open_at_cursor();
                        return;
                    }
                    KeyCode::Char('f') => {
                        self.forge_cycle_filter();
                        return;
                    }
                    KeyCode::Char('c') => {
                        self.forge_checkout_selected();
                        return;
                    }
                    KeyCode::Char('u') => {
                        self.forge_refresh_list();
                        return;
                    }
                    KeyCode::Char('x') => {
                        self.git_menu_open = true;
                        self.wake_caret();
                        return;
                    }
                    KeyCode::Char(c) if c.is_ascii_digit() => {
                        if let Some(pane) = self.forge_pane_by_number(c.to_digit(10).unwrap_or(0)) {
                            self.windows_mut().focus(pane);
                            self.wake_caret();
                        }
                        return;
                    }
                    _ => {}
                }
            }
        }

        // The Merge view's own keys. `o`/`t` mean the same thing in both
        // its panes -- keep the left side, keep the right side -- and
        // differ only in scope: on the file list it's the whole file, in
        // the columns it's the conflict under the cursor. That's the one
        // thing worth learning here, so it's the one thing that's
        // consistent.
        if let Some((on_files, on_merge)) = self.merge_session.as_ref().map(|s| {
            let focused = self.focused_pane_id();
            (focused == s.files_pane, focused == s.merge_pane)
        }) {
            if (on_files || on_merge) && keypress.mods == Mods::default() {
                match keypress.code {
                    KeyCode::Char('o') if on_files => {
                        self.merge_take_whole_file(fenix_git::Resolution::Ours);
                        return;
                    }
                    KeyCode::Char('t') if on_files => {
                        self.merge_take_whole_file(fenix_git::Resolution::Theirs);
                        return;
                    }
                    KeyCode::Char('o') if on_merge => {
                        self.resolve_conflict_at_cursor(fenix_git::Resolution::Ours);
                        return;
                    }
                    KeyCode::Char('t') if on_merge => {
                        self.resolve_conflict_at_cursor(fenix_git::Resolution::Theirs);
                        return;
                    }
                    KeyCode::Char('b') if on_merge => {
                        self.resolve_conflict_at_cursor(fenix_git::Resolution::Both);
                        return;
                    }
                    KeyCode::Char('n') if on_merge => {
                        self.goto_conflict(true);
                        return;
                    }
                    KeyCode::Char('p') if on_merge => {
                        self.goto_conflict(false);
                        return;
                    }
                    KeyCode::Named(fenix_keymap::NamedKey::Enter) if on_files => {
                        self.merge_select_at_cursor();
                        return;
                    }
                    KeyCode::Char('s') => {
                        self.merge_stage_resolved();
                        return;
                    }
                    KeyCode::Char('u') => {
                        self.merge_restore_conflict();
                        return;
                    }
                    KeyCode::Char('r') => {
                        self.merge_refresh();
                        self.wake_caret();
                        return;
                    }
                    KeyCode::Char('x') => {
                        self.git_menu_open = true;
                        self.wake_caret();
                        return;
                    }
                    KeyCode::Char(c) if c.is_ascii_digit() => {
                        if let Some(pane) = self.merge_pane_by_number(c.to_digit(10).unwrap_or(0)) {
                            self.windows_mut().focus(pane);
                            self.wake_caret();
                        }
                        return;
                    }
                    _ => {}
                }
            }
        }

        // Lazygit-style multi-pane panel -- same "claim a small, pane-
        // scoped action-key set, everything else falls through to Vim"
        // shape as the Docker block above. Real lazygit's own `<space>`
        // stage-toggle isn't reachable here: `SPC` is already the global
        // leader-key trigger in Normal mode, checked earlier than this
        // block ever runs (see `git_menu_popup`'s own doc comment) -- so
        // Files uses separate `s`/`S` stage/unstage keys instead, matching
        // Docker's own `s`/`S`/`R` precedent of distinct keys per action
        // rather than a single toggle.
        if let Some(role) = self.git_focused_role() {
            use GitPaneRole::*;
            match (role, keypress.code) {
                (Staged | Unstaged, KeyCode::Char('s')) if keypress.mods == Mods::default() => {
                    self.git_stage_selected();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Char('S')) if keypress.mods == Mods::default() => {
                    self.git_unstage_selected();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Char('a')) if keypress.mods == Mods::default() => {
                    self.git_stage_all();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Char('A')) if keypress.mods == Mods::default() => {
                    self.git_unstage_all();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Char('z')) if keypress.mods == Mods::default() => {
                    self.git_stash_all();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Char('P')) if keypress.mods == Mods::default() => {
                    self.git_push();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Char('p')) if keypress.mods == Mods::default() => {
                    self.git_pull();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Char('c')) if keypress.mods == Mods::default() => {
                    self.git_commit_prompt();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged, KeyCode::Named(FenixNamedKey::Tab)) if keypress.mods == Mods::default() => {
                    self.git_toggle_dir_expand();
                    self.wake_caret();
                    return;
                }
                (Branches, KeyCode::Char('c')) if keypress.mods == Mods::default() => {
                    self.git_checkout_selected_branch();
                    self.wake_caret();
                    return;
                }
                (Branches, KeyCode::Char('n')) if keypress.mods == Mods::default() => {
                    self.git_new_branch_prompt();
                    self.wake_caret();
                    return;
                }
                (Stash, KeyCode::Char('a')) if keypress.mods == Mods::default() => {
                    self.git_stash_apply_selected();
                    self.wake_caret();
                    return;
                }
                (Stash, KeyCode::Char('g')) if keypress.mods == Mods::default() => {
                    self.git_stash_pop_selected();
                    self.wake_caret();
                    return;
                }
                // Discard is Unstaged-only -- discarding a *staged*
                // change means unstaging it first (`S`), matching git's
                // own semantics (`checkout`/`clean` act on the worktree,
                // not the index).
                (Unstaged | Branches | Stash, KeyCode::Char('d')) if keypress.mods == Mods::default() => {
                    self.git_arm_confirm();
                    self.wake_caret();
                    return;
                }
                // The Main pane's own diff keys (`s`/`S`/`d`, `]`/`[`,
                // Tab, Enter) are handled by the shared diff-viewer
                // block above, which covers every pane showing a
                // rendered diff rather than just this one.
                (_, KeyCode::Char('u')) if keypress.mods == Mods::default() => {
                    self.git_refresh_session();
                    self.wake_caret();
                    return;
                }
                (Staged | Unstaged | Branches | Commits | Stash | Main, KeyCode::Char('x')) if keypress.mods == Mods::default() => {
                    self.git_menu_open = true;
                    self.wake_caret();
                    return;
                }
                // Same digit-key jump-to-pane shortcut as the Docker
                // block above (`1. Status`, `2. Staged`, ...).
                (_, KeyCode::Char(c)) if keypress.mods == Mods::default() && c.is_ascii_digit() => {
                    if let Some(pane) = self.git_pane_by_number(c.to_digit(10).unwrap_or(0)) {
                        self.windows_mut().focus(pane);
                        if matches!(self.git_focused_role(), Some(GitPaneRole::Staged | GitPaneRole::Unstaged | GitPaneRole::Commits | GitPaneRole::Stash)) {
                            self.git_sync_main();
                        }
                        self.wake_caret();
                    }
                    return;
                }
                _ => {}
            }
        }

        // Jira dashboard -- the digit-key jump-to-pane shortcut the
        // Docker/Git blocks above already have (`1. Projects`, `2.
        // Users`, ...), plus the per-issue action keys on Issues/Detail
        // (`t` transition, `T` edit title, `c` add comment, `e` edit
        // description, `l` log time) and the status filter's own trigger
        // (`f`, Issues only). Gated on `jira_edit.is_none()` in addition
        // to a Jira pane being focused -- load-bearing, not decorative:
        // while a comment/description edit is in progress, none of these
        // letters may fire, regardless of Vim mode, or they'd hijack
        // ordinary typing/editing of that real prose the moment it
        // contained one of them (see `App::jira_edit`'s own doc comment).
        if self.jira_pane_action_keys_active() {
            if let KeyCode::Char(c) = keypress.code {
                if keypress.mods == Mods::default() && c.is_ascii_digit() {
                    if let Some(pane) = self.jira_pane_by_number(c.to_digit(10).unwrap_or(0)) {
                        self.windows_mut().focus(pane);
                        match self.jira_focused_role() {
                            Some(JiraPaneRole::Users) => self.jira_sync_issues(),
                            Some(JiraPaneRole::Issues) => self.jira_sync_detail(),
                            _ => {}
                        }
                        self.wake_caret();
                    }
                    return;
                }
            }
            match (self.jira_focused_role(), keypress.code) {
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('t')) if keypress.mods == Mods::default() => {
                    self.jira_start_transition_picker();
                    self.wake_caret();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('T')) if keypress.mods == Mods::default() => {
                    self.jira_start_edit_title_prompt();
                    self.wake_caret();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('c')) if keypress.mods == Mods::default() => {
                    self.jira_start_comment();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('e')) if keypress.mods == Mods::default() => {
                    self.jira_start_edit_description();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('l')) if keypress.mods == Mods::default() => {
                    self.jira_start_log_time_prompt();
                    self.wake_caret();
                    return;
                }
                (Some(JiraPaneRole::Issues), KeyCode::Char('f')) if keypress.mods == Mods::default() => {
                    self.jira_start_status_filter();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('A')) if keypress.mods == Mods::default() => {
                    self.jira_start_assignee_picker();
                    self.wake_caret();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('P')) if keypress.mods == Mods::default() => {
                    self.jira_start_priority_picker();
                    self.wake_caret();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('y')) if keypress.mods == Mods::default() => {
                    self.jira_copy_issue_url();
                    self.wake_caret();
                    return;
                }
                (Some(JiraPaneRole::Issues | JiraPaneRole::Detail), KeyCode::Char('x')) if keypress.mods == Mods::default() => {
                    self.jira_menu_open = true;
                    self.wake_caret();
                    return;
                }
                _ => {}
            }
        }

        self.pull_clipboard_before_paste(keypress);
        let id = self.focused_buffer_id();
        let pane = self.focused_pane_id();
        let vim_event = {
            let Some(ob) = self.buffers.get_mut(id) else { return };
            let Some(pane_state) = self.workspaces.active_pane_states_mut().get_mut(&pane) else { return };
            let mode_before = self.vim.mode();
            let edit_count_before = ob.buffer.edit_count();
            let event = self.vim.handle_key(&mut ob.buffer, &mut pane_state.cursor, keypress);
            // See `dispatch_keypress`'s own doc comment for `change_
            // capture`/`replaying_change` -- suppressed only while `.`
            // itself is replaying, so its own outer span doesn't get
            // polluted by the edits its replayed keys make.
            if ob.buffer.edit_count() != edit_count_before {
                if !self.replaying_change {
                    self.change_capture_dirty = true;
                }
                // Automatic `` `. `` mark (real Vim's own "position of
                // the last change") -- `resolve_mark`/`jump_to_mark`
                // already accept any char as a mark name, so writing
                // this entry is the only piece that's missing; `` `. ``
                // itself works for free the moment it exists.
                self.marks.insert('.', JumpEntry { buffer: id, char_idx: pane_state.cursor.char_idx });
                // Docker/Git/Jira panel buffers are read-only -- an edit
                // slipped through Vim's own dispatch anyway (there's no
                // clean "is this an edit" answer available *before* the
                // fact), so it's immediately reverted here instead. Safe
                // specifically because these buffers get wholesale-
                // regenerated on every refresh anyway -- a locally-
                // corrupted undo stack has no real consequence. See `is_
                // readonly_buffer_kind`'s own doc comment.
                if is_readonly_buffer_kind(ob.kind) {
                    ob.buffer.undo(&mut pane_state.cursor);
                }
            }
            // Automatic `` `^ `` mark (real Vim's own "position when
            // Insert mode was last exited") -- same reasoning, on the
            // Insert -> non-Insert transition instead of an edit.
            if mode_before == Mode::Insert && self.vim.mode() != Mode::Insert {
                self.marks.insert('^', JumpEntry { buffer: id, char_idx: pane_state.cursor.char_idx });
            }
            event
        };
        self.push_clipboard_after_edit();
        self.sync_completion();
        // Ordinary movement in one of the three left panes re-syncs the
        // Details pane to whatever's now under the cursor -- pure
        // formatting, no `docker` call, cheap enough every keystroke
        // (mirrors `sync_completion`'s own "derive fresh from whatever's
        // current" posture). Skipped while Details is showing live logs
        // (`logs_container.is_some()`) -- moving the cursor in Containers
        // shouldn't yank a different container's log view back to plain
        // info text.
        if matches!(self.docker_focused_role(), Some(DockerPaneRole::Containers | DockerPaneRole::Images | DockerPaneRole::Volumes | DockerPaneRole::Networks))
            && self.docker_session.as_ref().is_some_and(|s| s.logs_container.is_none())
        {
            self.docker_sync_details();
        }
        // Same "cheap, derive fresh from whatever's under the cursor now"
        // re-sync for the Git panel's Main pane, after ordinary Vim
        // movement in Files/Commits/Stash (Branches has no diff of its
        // own to show -- see `git_sync_main`'s own doc comment).
        if matches!(self.git_focused_role(), Some(GitPaneRole::Staged | GitPaneRole::Unstaged | GitPaneRole::Commits | GitPaneRole::Stash)) {
            self.git_sync_main();
        }
        // Same again for the History view: moving down the graph shows
        // whichever commit the cursor lands on.
        if self.history_session.as_ref().is_some_and(|s| s.graph_pane == self.focused_pane_id()) {
            self.history_sync_detail();
        }
        // Same re-sync for the Jira dashboard: ordinary movement in
        // Users re-fetches Issues, ordinary movement in Issues re-
        // fetches Detail (see `jira_sync_issues`/`jira_sync_detail`'s
        // own doc comments).
        match self.jira_focused_role() {
            Some(JiraPaneRole::Users) => self.jira_sync_issues(),
            Some(JiraPaneRole::Issues) => self.jira_sync_detail(),
            _ => {}
        }
        match vim_event {
            VimEvent::RequestSave => {
                CommandRegistry::with_builtins().run(self, event_loop, "file.save");
            }
            VimEvent::RequestForceSave => {
                CommandRegistry::with_builtins().run(self, event_loop, "file.save_force");
            }
            VimEvent::RequestReloadFile => {
                CommandRegistry::with_builtins().run(self, event_loop, "file.reload");
            }
            VimEvent::RequestCloseBuffer => {
                CommandRegistry::with_builtins().run(self, event_loop, "buffer.kill");
            }
            VimEvent::RequestForceCloseBuffer => {
                CommandRegistry::with_builtins().run(self, event_loop, "buffer.kill_force");
            }
            VimEvent::RequestSaveAndCloseBuffer => {
                CommandRegistry::with_builtins().run(self, event_loop, "buffer.save_and_kill");
            }
            VimEvent::RequestQuitAll => {
                CommandRegistry::with_builtins().run(self, event_loop, "app.quit");
            }
            VimEvent::RequestForceQuitAll => {
                CommandRegistry::with_builtins().run(self, event_loop, "app.quit_force");
            }
            VimEvent::RequestSaveAllAndQuit => {
                CommandRegistry::with_builtins().run(self, event_loop, "app.save_all_and_quit");
            }
            VimEvent::Error(msg) => self.set_error(msg),
            VimEvent::ScrollWindow(target) => self.scroll_window(target),
            VimEvent::RepeatLastChange => self.repeat_last_change(event_loop),
            VimEvent::ToggleComment { start_line, end_line } => self.toggle_comment_lines(start_line, end_line),
            VimEvent::Pulse(range) => {
                if self.animations_enabled() {
                    self.pulse = Some(Pulse { range, started: Instant::now() });
                }
            }
            VimEvent::IndentWidthChanged(width) => {
                self.config.indent_width = Some(width);
                if let Err(err) = self.config.save() {
                    eprintln!("fenix: couldn't save indent width ({err})");
                }
            }
            VimEvent::JumpRecorded(from) => {
                let buffer = self.focused_buffer_id();
                self.record_jump(JumpEntry { buffer, char_idx: from });
            }
            VimEvent::MarkSet(name, char_idx) => {
                let buffer = self.focused_buffer_id();
                self.marks.insert(name, JumpEntry { buffer, char_idx });
            }
            VimEvent::JumpToMark { name, linewise } => {
                self.jump_to_mark(name, linewise);
            }
            VimEvent::MacroRecordStart(register) => {
                // The register-select keystrokes (`q`, then the register
                // name) were already tapped into `macro_capture` by
                // `dispatch_keypress` before `VimState` ever resolved
                // them into this event -- real Vim doesn't record either
                // of those two keys, only what happens *after* recording
                // starts, so it's cleared here rather than left to
                // accumulate from this point on.
                self.macro_capture.clear();
                self.macro_recording_append = register.is_ascii_uppercase();
            }
            VimEvent::MacroRecordStop(register) => {
                // The closing `q` itself was also just tapped (recording
                // was still active when `dispatch_keypress` saw it) --
                // trimmed the same way, rather than included as part of
                // the macro's own content.
                self.macro_capture.pop();
                let keys = std::mem::take(&mut self.macro_capture);
                self.vim.finish_recording(register, &keys, self.macro_recording_append);
            }
            VimEvent::MacroPlay { register, count } => {
                self.play_macro(register, count, event_loop);
            }
            VimEvent::RequestLsp(kind) => match kind {
                fenix_vim::LspRequestKind::GoToDefinition => self.request_goto_definition(),
                fenix_vim::LspRequestKind::References => self.request_references(),
                fenix_vim::LspRequestKind::Hover => self.request_hover(),
            },
            VimEvent::None => {}
        }
        self.wake_caret();
    }

    /// `@{register}` (or `@@`, `register` literally `'@'` -- resolved to
    /// `last_played_macro` here, real Vim's own "repeat whichever
    /// register was last played" convention; a `None` `last_played_
    /// macro` is a silent no-op, matching real Vim's "no previously used
    /// register"). Decodes the register's content (`VimState::decode_
    /// register` -- works the same whether it got there by recording,
    /// yanking, or hand-editing) and replays each key via `route_
    /// keypress` directly, *not* `dispatch_keypress` -- see `dispatch_
    /// keypress`'s own doc comment for why a nested `@b` call must not
    /// double-record its own expansion. `replay_budget` is a defensive
    /// cap (not real Vim's own behavior, which really would hang on a
    /// self-referential macro like `qaa@aq` too) shared across nested
    /// replay calls via a single counter on `self`, so a runaway macro
    /// bails out with a modeline-visible message instead of freezing
    /// the app.
    fn play_macro(&mut self, register: char, count: u32, event_loop: &ActiveEventLoop) {
        let register = if register == '@' { self.last_played_macro } else { Some(register) };
        let Some(register) = register else { return };
        if self.replay_depth >= MAX_MACRO_REPLAY_DEPTH {
            self.set_error("macro replay stopped -- nested too deep (possible infinite recursion)");
            return;
        }
        let Some(keys) = self.vim.decode_register(register) else { return };
        self.last_played_macro = Some(register);
        // The budget is one shared pool across every nested `@` call
        // this replay makes (only reset at true top-level, tracked via
        // `replay_depth`), not per-level -- a self-referential macro
        // recursing through many levels should still hit the same
        // overall cap, not get `MACRO_REPLAY_BUDGET` keys *per level*.
        if self.replay_depth == 0 {
            self.replay_budget = MACRO_REPLAY_BUDGET;
        }
        self.replay_depth += 1;
        'replay: for _ in 0..count.max(1) {
            for key in &keys {
                if self.replay_budget == 0 {
                    self.set_error("macro replay stopped -- too many keys played (possible infinite recursion)");
                    break 'replay;
                }
                self.replay_budget -= 1;
                self.route_keypress(*key, event_loop);
            }
        }
        self.replay_depth -= 1;
    }

    /// `.` -- replays `last_change_keys` (the most recently completed
    /// change-producing key span, captured by `dispatch_keypress`) the
    /// same way `play_macro` replays a register's decoded content:
    /// through `route_keypress` directly, not `dispatch_keypress`, so
    /// the replay's own keys don't get re-tapped into `change_capture`.
    /// `replaying_change` additionally suppresses `change_capture_
    /// dirty`'s bookkeeping for the duration (see its own doc comment)
    /// -- without it, the replayed edits would make the *outer* `.`
    /// keypress's own span look dirty too, and `last_change_keys` would
    /// get overwritten with just `['.']` on every repeat. A silent no-op
    /// if nothing's been recorded yet.
    fn repeat_last_change(&mut self, event_loop: &ActiveEventLoop) {
        let Some(keys) = self.last_change_keys.clone() else { return };
        self.replaying_change = true;
        for key in &keys {
            self.route_keypress(*key, event_loop);
        }
        self.replaying_change = false;
    }

    /// Right before dispatching a bare `p`/`P` in Normal mode (the only
    /// place those keys mean "paste" -- see `fenix_vim::keymaps::normal_
    /// trie`), pulls whatever's currently on the OS clipboard into Vim's
    /// unnamed register, so the paste sees anything copied outside Fenix
    /// since the last sync, not just Fenix's own last yank/delete.
    /// Gated on `!is_pending()` so a count prefix (`3p`) still resolves
    /// through here (counts aren't tracked via the pending-sequence
    /// matcher) while a `g`-prefixed or operator-pending sequence never
    /// misreads its own continuation key as a paste.
    fn pull_clipboard_before_paste(&mut self, keypress: KeyPress) {
        if self.vim.mode() != Mode::Normal || self.vim.is_pending() || keypress.mods != Mods::default() {
            return;
        }
        if !matches!(keypress.code, KeyCode::Char('p') | KeyCode::Char('P')) {
            return;
        }
        let Some(clipboard) = self.clipboard.as_mut() else { return };
        let Ok(text) = clipboard.get_text() else { return };
        // No per-entry regtype metadata on a plain OS clipboard -- a
        // trailing newline is the same linewise signal Neovim's own
        // clipboard provider uses to infer "this was a whole line" from
        // plain text.
        let linewise = text.ends_with('\n');
        self.clipboard_mirror = text.clone();
        self.vim.set_register(text, linewise);
    }

    /// After every dispatched key, mirrors Vim's unnamed register onto
    /// the OS clipboard if this keystroke just changed it (yank, delete,
    /// change -- anything `fenix_vim::VimState` writes it from). Compared
    /// against `clipboard_mirror` rather than gated on `VimEvent::Pulse`,
    /// since delete deliberately doesn't raise a pulse (see `VimEvent::
    /// Pulse`'s own doc comment) but still needs to reach the clipboard --
    /// otherwise `dd` then `p` in Fenix would silently diverge from
    /// whatever's pasted elsewhere.
    fn push_clipboard_after_edit(&mut self) {
        let (text, _linewise) = self.vim.register();
        if text == self.clipboard_mirror {
            return;
        }
        let text = text.to_string();
        let Some(clipboard) = self.clipboard.as_mut() else { return };
        if clipboard.set_text(text.clone()).is_ok() {
            self.clipboard_mirror = text;
        }
    }

    /// The OS clipboard's current text, if any -- `None` if there's no
    /// clipboard (headless tests), it's empty, or it doesn't hold text.
    /// `Ctrl-V` in every modeline-style prompt (`find_file_prompt_key`
    /// and its siblings) pastes this in; Vim's own `p`/`P` paste has its
    /// own separate path (`pull_clipboard_before_paste`) since it also
    /// needs the linewise/charwise distinction these plain-text prompts
    /// don't have.
    fn clipboard_text(&mut self) -> Option<String> {
        self.clipboard.as_mut()?.get_text().ok()
    }

    /// Keeps the cursor's line within the *focused pane's* visible
    /// window, scrolling as needed. Must be called with the same
    /// `visible_lines` used to render. Every pane owns its own scroll
    /// independently (see `PaneState`'s own doc comment) -- only the
    /// focused one auto-follows the cursor like this; others just render
    /// wherever they were last left.
    fn ensure_cursor_visible(&mut self, visible_lines: usize) {
        let buffer_id = self.focused_buffer_id();
        let pane = self.focused_pane_id();
        let (line, scroll_line) = {
            let ob = self.buffers.get(buffer_id).expect("focused window always has an open buffer");
            let cursor = self.pane_state(pane).cursor;
            (ob.buffer.line_col(&cursor).0, self.pane_state(pane).scroll_line)
        };
        let target = scroll_to_include(scroll_line, line, visible_lines);
        if target != scroll_line {
            let jump = target.abs_diff(scroll_line);
            // A jump bigger than a few screens (`G`, a search landing far
            // away) snaps instantly rather than blurring through an ease.
            // A target arriving while the *previous* ease for this pane
            // hasn't finished yet snaps too: that only happens when scroll
            // targets are coming in faster than SCROLL_DURATION can settle
            // (held-key repeat, e.g. holding `j`), and re-triggering a
            // fresh 150ms ease on every one of those keystrokes would
            // otherwise make `rendered_scroll` perpetually chase a few
            // lines behind the cursor instead of ever catching up -- the
            // opposite of the "never sits between a keypress and its
            // effect" goal this animation was built for.
            if !self.animations_enabled() || jump > visible_lines.saturating_mul(SCROLL_SNAP_SCREENS) || self.workspaces.active_scroll_anims().contains_key(&pane) {
                self.workspaces.active_scroll_anims_mut().remove(&pane);
                self.pane_state_mut(pane).rendered_scroll = target as f32;
            } else {
                let from = self.pane_state(pane).rendered_scroll;
                self.workspaces.active_scroll_anims_mut().insert(pane, ScrollAnim { from, to: target, started: Instant::now() });
            }
            self.pane_state_mut(pane).scroll_line = target;
        }
        self.update_rendered_scroll();
    }

    /// Horizontal analog of `ensure_cursor_visible` -- keeps the cursor's
    /// *visual* column within the focused pane's visible window, snapping
    /// `scroll_col` instantly (no `rendered_scroll`-style easing on this
    /// axis; see `PaneState.scroll_col`'s own doc comment for why).
    /// `visual_cols` needs the cursor's own line's tab-expanded column,
    /// not its raw character column -- `content_spans` slices the tab-
    /// *expanded* display text, where "1 char = 1 visual column" holds
    /// (the same invariant `remap_col`'s own doc comment relies on), so
    /// comparing a raw column against `scroll_col` would drift on any
    /// line with a tab before the cursor.
    fn ensure_cursor_visible_horizontally(&mut self, visible_cols: usize) {
        let pane = self.focused_pane_id();
        let buffer_id = self.focused_buffer_id();
        let cursor_col = {
            let ob = self.buffers.get(buffer_id).expect("focused window always has an open buffer");
            let cursor = self.pane_state(pane).cursor;
            let (line, col) = ob.buffer.line_col(&cursor);
            let start = ob.buffer.line_start_char(line);
            let len = ob.buffer.line_len(line);
            let line_text = ob.buffer.text_range(start, start + len);
            if line_text.contains('\t') {
                let tab_stops = self.tab_stops_for(buffer_id);
                let (_, col_map) = tabstops::expand_line(&line_text, &tab_stops);
                tabstops::visual_col(&col_map, col)
            } else {
                col
            }
        };
        let pane_state = self.pane_state_mut(pane);
        pane_state.scroll_col = scroll_to_include(pane_state.scroll_col, cursor_col, visible_cols);
    }

    /// Advances the focused pane's `rendered_scroll` toward its
    /// `scroll_line` if a transition is in flight, clearing it once
    /// settled.
    fn update_rendered_scroll(&mut self) {
        let pane = self.focused_pane_id();
        let scroll_line = self.pane_state(pane).scroll_line;
        let Some(anim) = self.workspaces.active_scroll_anims().get(&pane) else {
            self.pane_state_mut(pane).rendered_scroll = scroll_line as f32;
            return;
        };
        let (from, to, started) = (anim.from, anim.to, anim.started);
        let t = Instant::now().duration_since(started).as_secs_f32() / SCROLL_DURATION.as_secs_f32();
        if t >= 1.0 {
            self.pane_state_mut(pane).rendered_scroll = to as f32;
            self.workspaces.active_scroll_anims_mut().remove(&pane);
        } else {
            let to = to as f32;
            self.pane_state_mut(pane).rendered_scroll = from + (to - from) * ease_out_cubic(t);
        }
    }

    /// The focused pane's line rendering starts from -- `rendered_scroll`
    /// rounded down. Content, caret, hl-line, selection, and pulse all
    /// anchor their row math to this (not `scroll_line`, which is only
    /// the *target* `rendered_scroll` is easing toward).
    fn render_base_line(&self) -> usize {
        self.pane_state(self.focused_pane_id()).rendered_scroll.floor().max(0.0) as usize
    }

    /// The display name for `buffer_id` -- its filename if it has a
    /// path, else a kind-specific placeholder (`*dashboard*`, `*docker*`,
    /// a dired buffer's own directory, or `[No Name]`). Shared by the
    /// modeline (which only ever names the *focused* pane) and the
    /// per-pane title strips `redraw()` draws above every visible pane
    /// -- with a split open, two different files need their own labels
    /// to tell them apart at a glance, not just the one the modeline
    /// shows for whichever pane happens to be focused.
    fn buffer_display_name(&self, buffer_id: BufferId) -> String {
        let Some(ob) = self.buffers.get(buffer_id) else { return "[No Name]".to_string() };
        ob.buffer.path().and_then(|p| p.file_name()).map(|n| n.to_string_lossy().into_owned()).unwrap_or_else(|| {
            if ob.kind == BufferKind::Dashboard {
                "*dashboard*".to_string()
            } else if ob.kind == BufferKind::Explorer {
                self.dired_states.get(&buffer_id).map(|s| s.cwd.display().to_string()).unwrap_or_else(|| "*dired*".to_string())
            } else if ob.kind == BufferKind::Docker {
                "*docker*".to_string()
            } else if ob.kind == BufferKind::Git {
                "*git*".to_string()
            } else if ob.kind == BufferKind::Jira {
                "*jira*".to_string()
            } else if ob.kind == BufferKind::Vnc {
                // Named from the session that owns this buffer, so every
                // pane showing it is titled the same way -- including a
                // split's second pane, which a per-pane title (what this
                // used to be) never reached. `*vnc*` only for the window
                // between the buffer existing and its session being
                // registered.
                self.vnc_session_key_for_buffer(buffer_id).map(|name| format!("VNC: {name}")).unwrap_or_else(|| "*vnc*".to_string())
            } else if ob.kind == BufferKind::Pdf {
                self.pdf_display_names.get(&buffer_id).cloned().unwrap_or_else(|| "*pdf*".to_string())
            } else if ob.kind == BufferKind::PdfOutline {
                "*pdf outline*".to_string()
            } else if ob.kind == BufferKind::PdfSearchResults {
                "*pdf search*".to_string()
            } else if ob.kind == BufferKind::TaskOutput {
                "*task output*".to_string()
            } else if ob.kind == BufferKind::Debug {
                "*debug*".to_string()
            } else if ob.kind == BufferKind::ToolStatus {
                "*tool status*".to_string()
            } else if ob.kind == BufferKind::Diff {
                "*diff*".to_string()
            } else if ob.kind == BufferKind::Graph {
                "*graph*".to_string()
            } else if ob.kind == BufferKind::Merge {
                "*merge*".to_string()
            } else if ob.kind == BufferKind::Terminal {
                // Numbered on creation (`terminal_buffer_labels`) so
                // several open at once are tellable apart here and in
                // `SPC b b`; the bare fallback only covers the instant
                // between the buffer existing and being labelled.
                self.terminal_buffer_labels.get(&buffer_id).cloned().unwrap_or_else(|| "*terminal*".to_string())
            } else {
                "[No Name]".to_string()
            }
        })
    }

    /// Sets a plain (non-error) status message -- shown in the modeline
    /// for `MESSAGE_DURATION` (`modeline_pieces`). For routine
    /// confirmations ("saved", "tags refreshed"), not failures -- use
    /// `set_error` for those, which also tints the text.
    fn set_message(&mut self, text: impl Into<String>) {
        self.status_message = Some(StatusMessage { text: text.into(), is_error: false, set_at: Instant::now() });
    }

    /// Sets an error status message -- same display as `set_message`,
    /// tinted red (`git_conflicted`'s accent). This is the replacement
    /// for what used to be a silent `eprintln!` at most of this file's
    /// failure sites: invisible in a normally-launched GUI window, so
    /// the user had no way to know a search/save/format/etc. failed.
    fn set_error(&mut self, text: impl Into<String>) {
        self.status_message = Some(StatusMessage { text: text.into(), is_error: true, set_at: Instant::now() });
    }

    /// The modeline's mode badge: "VNC" while some session has input
    /// capture (`vnc_focused`), overriding the vim mode label the same
    /// way a captured VNC pane already overrides every keystroke (see
    /// `route_keypress`'s own VNC-focused branch) -- there's no Normal/
    /// Insert/Visual distinction worth showing while every key goes
    /// straight to the guest instead of vim's own dispatch.
    fn mode_badge_label(&self) -> &'static str {
        if self.vnc_focused.is_some() {
            return "VNC";
        }
        if self.vim.mode() == Mode::Visual { self.vim.visual_kind().label() } else { self.vim.mode().label() }
    }

    /// (mode label, rest-of-modeline suffix) -- always returns real
    /// content now, even while a capturing prompt (`:command`, `/`
    /// search, a git commit prompt, ...) is active: that text lives in
    /// its own floating popup now (`App::prompt_popup`), so the
    /// modeline itself just keeps showing its ordinary badge/filename/
    /// position underneath it, the same "additive, doesn't replace the
    /// real indicator" posture `recording_indicator`/`workspace_
    /// indicator` already have below.
    fn modeline_pieces(&self) -> (&'static str, String) {
        // A live status/error message pre-empts even the Explorer/Picker
        // badge -- it's telling the user something just happened,
        // regardless of what view they're in. Uses the plain mode badge
        // (Normal/Insert/...) rather than Explorer's/Picker's own,
        // matching the "additive, doesn't replace the real mode
        // indicator" posture `recording_indicator`/`workspace_indicator`
        // already have below.
        if let Some(msg) = &self.status_message {
            if msg.set_at.elapsed() < MESSAGE_DURATION {
                return (self.mode_badge_label(), format!("│ {} ", msg.text));
            }
        }
        if self.main_view == MainView::Explorer {
            let suffix = match &self.explorer {
                Some(explorer) => {
                    let marked =
                        if explorer.marks.is_empty() { String::new() } else { format!(" [{} marked]", explorer.marks.len()) };
                    match self.explorer_purpose {
                        ExplorerPurpose::Browse => {
                            format!("│ {}{marked}   {} items ", explorer.cwd.display(), explorer.entries.len())
                        }
                        ExplorerPurpose::PickProjectDir => {
                            format!("│ {}   S to add as a project, q to cancel ", explorer.cwd.display())
                        }
                        ExplorerPurpose::PickMibRootDir => {
                            format!("│ {}   S to add as a MIB root, q to cancel ", explorer.cwd.display())
                        }
                        ExplorerPurpose::FindFrom => {
                            format!("│ {}{marked}   Enter to open, S to search here, q to cancel ", explorer.cwd.display())
                        }
                    }
                }
                None => String::new(),
            };
            let badge = match self.explorer_purpose {
                ExplorerPurpose::Browse => "EXPLORE",
                ExplorerPurpose::PickProjectDir => "ADDPROJ",
                ExplorerPurpose::PickMibRootDir => "ADDMIB",
                ExplorerPurpose::FindFrom => "FINDFROM",
            };
            return (badge, suffix);
        }
        if self.main_view == MainView::Picker {
            let (label, count) = match &self.active_picker {
                Some(picker @ ActivePicker::FindFile(_)) => ("FINDFILE", picker_len(picker)),
                Some(picker @ ActivePicker::Grep(_)) => ("GREP", picker_len(picker)),
                Some(picker @ ActivePicker::SwitchProject(_)) => ("SWPROJ", picker_len(picker)),
                Some(picker @ ActivePicker::SwitchBuffer(_)) => ("SWBUF", picker_len(picker)),
                Some(picker @ ActivePicker::Recovery(_)) => ("RECOVER", picker_len(picker)),
                Some(picker @ ActivePicker::DeleteProject(_)) => ("DELPROJ", picker_len(picker)),
                Some(picker @ ActivePicker::DeleteMibRoot(_)) => ("DELMIB", picker_len(picker)),
                Some(picker @ ActivePicker::DeleteJiraProject(_)) => ("DELJIRAPROJ", picker_len(picker)),
                Some(picker @ ActivePicker::DeleteJiraUser(_)) => ("DELJIRAUSER", picker_len(picker)),
                Some(picker @ ActivePicker::CreateJiraIssue(_)) => ("NEWJIRAISSUE", picker_len(picker)),
                Some(picker @ ActivePicker::JiraTransition(_)) => ("JIRATRANSITION", picker_len(picker)),
                Some(picker @ ActivePicker::JiraStatusFilter(_)) => ("JIRASTATUSFILTER", picker_len(picker)),
                Some(picker @ ActivePicker::JiraAssignee(_)) => ("JIRAASSIGNEE", picker_len(picker)),
                Some(picker @ ActivePicker::JiraPriority(_)) => ("JIRAPRIORITY", picker_len(picker)),
                Some(picker @ ActivePicker::Theme(_)) => ("THEME", picker_len(picker)),
                Some(picker @ ActivePicker::Symbol(_)) => ("SYMBOL", picker_len(picker)),
                Some(picker @ ActivePicker::MibTelecommandLookup(_)) => ("MIB-TC", picker_len(picker)),
                Some(picker @ ActivePicker::MibTelecommandInsert(_)) => ("MIB-TC", picker_len(picker)),
                Some(picker @ ActivePicker::MibTmPacket(_)) => ("MIB-PKT", picker_len(picker)),
                Some(picker @ ActivePicker::MibTmParameter(_)) => ("MIB-PARAM", picker_len(picker)),
                Some(picker @ ActivePicker::MibCalibration(_)) => ("MIB-CAL", picker_len(picker)),
                Some(picker @ ActivePicker::MibArgumentAlias(_)) => ("MIB-ARG", picker_len(picker)),
                Some(picker @ ActivePicker::VncHost(_)) => ("VNC", picker_len(picker)),
                Some(picker @ ActivePicker::Document(_)) => ("DOCUMENT", picker_len(picker)),
                Some(picker @ ActivePicker::TableColumn(_)) => ("COLUMN", picker_len(picker)),
                Some(picker @ ActivePicker::BufferSearch(_)) => ("SEARCH", picker_len(picker)),
                Some(picker @ ActivePicker::SwitchWorkspace(_)) => ("SWWS", picker_len(picker)),
                Some(picker @ ActivePicker::WorkspaceLauncher(_)) => ("WORKSPACE", picker_len(picker)),
                Some(picker @ ActivePicker::Outline(_)) => ("OUTLINE", picker_len(picker)),
                Some(picker @ ActivePicker::Task(_)) => ("TASK", picker_len(picker)),
                Some(picker @ ActivePicker::CompareBase(_)) => ("COMPARE", picker_len(picker)),
                Some(picker @ ActivePicker::RebaseOnto(_)) => ("REBASE ONTO", picker_len(picker)),
                Some(picker @ ActivePicker::MergeFrom(_)) => ("MERGE", picker_len(picker)),
                Some(picker @ ActivePicker::CompareHead { .. }) => ("COMPARE", picker_len(picker)),
                None => ("PICKER", 0),
            };
            // Which half of a two-step comparison you're on, spelled
            // out. "base" and "head" alone don't say which direction the
            // result reads in, and picking them the wrong way round
            // silently answers the opposite question.
            let suffix = match &self.active_picker {
                Some(ActivePicker::CompareBase(_)) => {
                    format!("│ {count} refs   pick the ref to compare *against* (the base) ")
                }
                Some(ActivePicker::CompareHead { base, .. }) => {
                    format!("│ {count} refs   {base}...?   pick the ref whose changes you want to see ")
                }
                _ => format!("│ {count} matches "),
            };
            return (label, suffix);
        }
        let ob = self.open();
        let filename = self.buffer_display_name(self.focused_buffer_id());
        let modified = if ob.kind.tracks_unsaved_changes() && ob.buffer.is_dirty() { " [+]" } else { "" };
        // A file that moved under an unsaved buffer is worth seeing
        // without pressing anything: the message that announced it
        // scrolls away, and the next `:w` refusing out of nowhere is a
        // worse way to find out.
        let diverged = if self.externally_changed.contains(&self.focused_buffer_id()) { " [disk]" } else { "" };
        let (line, col) = ob.buffer.line_col(&self.cursor());
        let modified = format!("{modified}{diverged}");
        let mode_label = self.mode_badge_label();
        // Only shown once there's more than one workspace to distinguish --
        // stays out of the way for the common single-workspace case.
        let workspace_indicator = if self.workspaces.len() > 1 {
            format!("   [{}/{} {}]", self.workspaces.active_index() + 1, self.workspaces.len(), self.workspaces.active_name())
        } else {
            String::new()
        };
        // Additive, not a full modeline override like a capturing prompt
        // (`explorer_prompt_text`, ...) -- recording doesn't block
        // ordinary editing/redraws, so the rest of the modeline should
        // keep showing real information, same posture as `workspace_
        // indicator`.
        let recording_indicator =
            match self.vim.recording_register() {
                Some(reg) => format!("   recording @{reg}"),
                None => String::new(),
            };
        // A PDF pane has no text and no cursor, so "Ln 1, Col 1" is
        // both wrong and useless there -- it shows where in the
        // *document* the reader is instead, which is the one thing a
        // reader checks the status line for (and the only place the
        // current zoom is visible at all).
        if let Some(session) = self.pdf_session_key_for_pane(self.focused_pane_id()).and_then(|key| self.pdf_sessions.get(&key)) {
            let position = if session.page_count == 0 {
                "opening...".to_string()
            } else {
                format!("Page {}/{}   {}", session.current_page + 1, session.page_count, pdf_zoom_label(session))
            };
            return (mode_label, format!("│ {filename}{workspace_indicator}   {position} "));
        }
        // Error/warning counts for whatever the focused buffer's own
        // language server last published for its path, if any -- the
        // simplest possible "is anything actually wrong here" signal;
        // inline squiggle-equivalent markup and a real diagnostics list
        // (`SPC c d`) are a follow-up, this is deliberately the smallest
        // slice that's still genuinely useful on its own. Canonicalizes
        // the path on every call (matching how `apply_lsp_diagnostics`
        // keys the map) rather than caching -- a plain `stat`, not worth
        // the extra bookkeeping unless it actually shows up as slow.
        let diagnostics_indicator = ob
            .buffer
            .path()
            .map(|p| fenix_lsp::normalize(std::fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf())))
            .and_then(|p| self.diagnostics.get(&p))
            .filter(|diags| !diags.is_empty())
            .map(|diags| {
                let errors = diags.iter().filter(|d| d.severity == Some(lsp_types::DiagnosticSeverity::ERROR)).count();
                let warnings = diags.iter().filter(|d| d.severity == Some(lsp_types::DiagnosticSeverity::WARNING)).count();
                format!("   {errors}E {warnings}W")
            })
            .unwrap_or_default();
        let suffix = format!(
            "│ {filename}{modified}{workspace_indicator}{recording_indicator}{diagnostics_indicator}   Ln {}, Col {} ",
            line + 1,
            col + 1
        );
        (mode_label, suffix)
    }

    /// The text currently occupying the app's one shared "capturing
    /// prompt" slot -- whichever of Vim's own `:command`/`/`-`?`-search,
    /// the project-wide grep query, or one of this app's many single-
    /// line prompts/confirmations is active right now. `None` when
    /// nothing is capturing input, the common case. These are mutually
    /// exclusive states (`route_keypress`'s own capturing-prompt
    /// dispatch already treats them that way), so this priority order
    /// only matters for readability, not correctness. Feeds `prompt_
    /// popup` -- the only thing that changed here from this function's
    /// own predecessor (the old `modeline_command_text` local `redraw`
    /// used to compute inline) is *where* this text ends up shown, not
    /// what it is or how it's computed; every individual `*_text()`
    /// function this calls is untouched.
    fn active_prompt_text(&self) -> Option<String> {
        if let Some(query) = &self.pending_grep_query {
            return Some(format!("rg: {query}"));
        }
        if self.vim.mode() == Mode::Search {
            let prefix = if self.vim.search_forward() { "/" } else { "?" };
            return Some(format!("{prefix}{}", self.vim.search_query()));
        }
        if self.vim.mode() == Mode::Command {
            return Some(format!(":{}", self.vim.command_line()));
        }
        self.explorer_prompt_text()
            .or_else(|| self.docker_confirm_text())
            .or_else(|| self.git_confirm_text())
            .or_else(|| self.git_prompt_text())
            .or_else(|| self.jira_prompt_text())
            .or_else(|| self.mib_insert_text())
            .or_else(|| self.replace_wizard_text())
            .or_else(|| self.project_replace_confirm_text())
            .or_else(|| self.find_file_prompt_text())
            .or_else(|| self.pdf_goto_page_prompt_text())
            .or_else(|| self.pdf_search_prompt_text())
            .or_else(|| self.rename_file_prompt_text())
            .or_else(|| self.lsp_rename_prompt_text())
            .or_else(|| self.workspace_rename_prompt_text())
            .or_else(|| self.mib_root_prompt_text())
            .or_else(|| self.delete_file_confirm_text())
    }

    /// Test-only: the modeline as one plain string, for assertions --
    /// `redraw` renders it as separately-colored spans instead (see
    /// `modeline_pieces`/`mode_colors`), so nothing else needs this.
    /// Always the modeline's own ordinary badge/filename/position now --
    /// a capturing prompt's own text lives in `prompt_popup`/`active_
    /// prompt_text` instead, asserted on separately.
    #[cfg(test)]
    fn modeline_text(&self) -> String {
        let (mode_label, suffix) = self.modeline_pieces();
        format!(" {mode_label:^width$}{suffix}", width = text::MODE_BADGE_CHARS)
    }

    /// (badge background, badge text color) for the current mode. Visual's
    /// Whether the caret should render as a full-cell block (Normal,
    /// Visual, Replace, Command) rather than the thin Insert-mode bar --
    /// matches real Vim's own cursor-shape convention (block outside
    /// Insert, thin bar while actively typing).
    fn caret_is_block(&self) -> bool {
        self.vim.mode() != Mode::Insert
    }

    /// three kinds all share one accent (matching orbit-emacs's own
    /// evil-state table, which has a single "Visual" entry) -- only the
    /// badge's label text differs between them.
    fn mode_colors(&self) -> ([f32; 4], glyphon::Color) {
        let theme = self.theme;
        if self.main_view == MainView::Explorer {
            return (theme.mode_explorer, theme.mode_text_dark);
        }
        if self.main_view == MainView::Picker {
            return (theme.mode_picker, theme.mode_text_dark);
        }
        match self.vim.mode() {
            Mode::Normal => (theme.mode_normal, theme.mode_text_dark),
            Mode::Insert => (theme.mode_insert, theme.mode_text_dark),
            Mode::Visual => (theme.mode_visual, theme.mode_text_light),
            Mode::Replace => (theme.mode_replace, theme.mode_text_dark),
            Mode::Command => (theme.mode_command, theme.mode_text_dark),
            // Same "prompt-like input" family as `:` -- not a new theme
            // color, just reusing the command one.
            Mode::Search => (theme.mode_command, theme.mode_text_dark),
        }
    }

    /// `Custom` stops for a `BufferKind::Table` buffer, else the buffer-
    /// wide `Fixed` default from `config.tab_width` (real Vim's own
    /// `:set tabstop`, `DEFAULT_TAB_WIDTH` if unset).
    fn tab_stops_for(&self, id: BufferId) -> TabStops {
        match self.table_views.get(&id) {
            Some(view) => TabStops::Custom(view.stops.clone()),
            None => TabStops::Fixed(self.config.tab_width.unwrap_or(DEFAULT_TAB_WIDTH)),
        }
    }

    /// Recomputes `id`'s `TableView` from its *current* buffer text if
    /// it doesn't have one yet, or if `edit_count()` has moved since the
    /// last computation -- the auto-realign every edit gets for free,
    /// mirroring the `edit_count`-diff idiom `syntax_highlights_for_
    /// visible_range` already uses to decide "did anything change." A
    /// no-op for a buffer that isn't (or is no longer) `BufferKind::
    /// Table`. Column names are synthesized (`Column 1`, `Column 2`,
    /// ...) -- the source data's real tab-separated content has no
    /// header row `parse` could reliably distinguish from an ordinary
    /// data row.
    fn sync_table_view(&mut self, id: BufferId) {
        let Some(ob) = self.buffers.get(id) else { return };
        if ob.kind != BufferKind::Table {
            return;
        }
        let edit_count = ob.buffer.edit_count();
        if self.table_views.get(&id).is_some_and(|v| v.last_edit_count == edit_count) {
            return;
        }
        let rows = fenix_table::parse(&ob.buffer.text(), '\t');
        let column_count = rows.iter().map(Vec::len).max().unwrap_or(0);
        let columns: Vec<String> = (0..column_count).map(|i| format!("Column {}", i + 1)).collect();
        let widths = fenix_table::column_widths(&columns, &rows);
        let stops = fenix_table::tab_stops(&widths, TABLE_COLUMN_GAP);
        self.table_views.insert(id, TableView { columns, stops, last_edit_count: edit_count });
    }

    /// This pane's title-bar text for a `BufferKind::Table` buffer --
    /// column names, space-padded to line up with the same `stops` the
    /// renderer expands the content's real tabs to, so header and
    /// content land in identical pixel columns (both ultimately paid out
    /// in the same `char_width`). `None` for anything else, so the
    /// caller falls back to the ordinary `buffer_display_name`.
    fn table_view_header(&self, id: BufferId) -> Option<String> {
        let view = self.table_views.get(&id)?;
        let mut header = String::new();
        let mut col_start = 0usize;
        for (name, &stop) in view.columns.iter().zip(&view.stops) {
            header.push_str(name);
            let pad = stop.saturating_sub(col_start + name.chars().count());
            header.push_str(&" ".repeat(pad));
            col_start = stop;
        }
        Some(header)
    }

    /// `SPC f t`: toggles the focused buffer between `Text` and `Table`
    /// -- no synthetic buffer, no distinct copy: the *same* buffer, same
    /// path, same undo history, just retagged in place, since the file's
    /// real tab-separated content is already exactly what the elastic-
    /// column renderer needs to align it. A no-op on anything but
    /// `Text`/`Table` (Dashboard/Explorer/Docker/Git buffers have no
    /// meaningful table view).
    pub(crate) fn toggle_table_view(&mut self) {
        let id = self.focused_buffer_id();
        let Some(ob) = self.buffers.get_mut(id) else { return };
        match ob.kind {
            BufferKind::Table => {
                ob.kind = BufferKind::Text;
                self.table_views.remove(&id);
            }
            BufferKind::Text => {
                ob.kind = BufferKind::Table;
                self.sync_table_view(id);
            }
            _ => {}
        }
    }

    /// 0-indexed tab-occurrence column the cursor currently sits in on
    /// its own line, for a `BufferKind::Table` buffer's `]`/`[`/`j`/`k`
    /// key interception -- counts real `\t` characters before the
    /// cursor. A cursor past every tab on its line (the last column, or
    /// a short ragged row) reports one past the last tab, same convention
    /// `tab_index` uses in `tabstops::expand_line`.
    fn table_current_column(&self) -> usize {
        let buffer = &self.open().buffer;
        let cursor_idx = self.cursor().char_idx;
        let line = buffer.line_col(&self.cursor()).0;
        let line_start = buffer.line_start_char(line);
        buffer.text_range(line_start, cursor_idx).matches('\t').count()
    }

    /// The char index just after `line`'s `column`-th tab (0-indexed),
    /// or the line's own end if it has fewer than `column` tabs -- the
    /// landing spot for a table view's column navigation, both `]`/`[`
    /// (same row) and `j`/`k` (adjacent row, same column).
    fn table_column_start(&self, line: usize, column: usize) -> usize {
        let buffer = &self.open().buffer;
        let line_start = buffer.line_start_char(line);
        if column == 0 {
            return line_start; // field 0 starts at the line itself, no preceding tab
        }
        let len = buffer.line_len(line);
        let line_text = buffer.text_range(line_start, line_start + len);
        // Field `column` (>= 1) starts just after tab occurrence `column
        // - 1` (0-indexed): tab 0 separates field 0 from field 1, tab 1
        // separates field 1 from field 2, and so on.
        match line_text.match_indices('\t').nth(column - 1) {
            Some((byte_idx, _)) => line_start + line_text[..byte_idx].chars().count() + 1,
            None => line_start + len,
        }
    }

    /// `]`/`[` on a `BufferKind::Table` buffer: moves to the start of
    /// the next/previous column on the current row.
    fn table_move_column(&mut self, delta: isize) {
        let current = self.table_current_column() as isize;
        let target = (current + delta).max(0) as usize;
        let line = self.open().buffer.line_col(&self.cursor()).0;
        let idx = self.table_column_start(line, target);
        let pane = self.focused_pane_id();
        let cursor = &mut self.pane_state_mut(pane).cursor;
        cursor.char_idx = idx;
        cursor.sticky_col = 0;
    }

    /// `j`/`k` on a `BufferKind::Table` buffer: moves a row while
    /// staying in the *same elastic column* -- plain char-based `sticky_
    /// col` doesn't work here, since rows have different raw lengths up
    /// to the same visual column (that's the whole point of elastic
    /// alignment), so this counts tabs instead of chars to find "same
    /// column."
    fn table_move_row(&mut self, delta: isize) {
        let column = self.table_current_column();
        let line = self.open().buffer.line_col(&self.cursor()).0;
        // `visual_line_count`, not `line_count` -- a buffer ending in
        // `\n` (every table view's real file content, per convention)
        // would otherwise let this land on ropey's phantom trailing
        // empty line past the real last row.
        let line_count = self.open().buffer.visual_line_count();
        let Some(target_line) = line.checked_add_signed(delta).filter(|&l| l < line_count) else { return };
        let idx = self.table_column_start(target_line, column);
        let pane = self.focused_pane_id();
        let cursor = &mut self.pane_state_mut(pane).cursor;
        cursor.char_idx = idx;
        cursor.sticky_col = 0;
    }

    /// `c` on a `BufferKind::Table` buffer: a fuzzy picker over its
    /// synthesized column names -- confirming (`picker_confirm`'s own
    /// `TableColumn` arm) jumps to that column's start on the current
    /// row. A no-op if the buffer has no `TableView` yet (shouldn't
    /// happen in practice: `sync_table_view` runs every redraw a `Table`
    /// buffer is visible, but this guards the interception key itself
    /// firing before the first redraw ever ran).
    fn open_table_column_picker(&mut self) {
        let id = self.focused_buffer_id();
        let Some(view) = self.table_views.get(&id) else { return };
        let candidates =
            view.columns.iter().enumerate().map(|(i, name)| fenix_picker::Candidate::new(name.clone(), i)).collect();
        self.enter_picker(ActivePicker::TableColumn(fenix_picker::PickerState::new(candidates)));
    }

    /// Character width of the line-number gutter, including one trailing
    /// column of padding before the text starts; 0 when the gutter is off.
    /// Sized to the buffer's total line count regardless of Absolute vs.
    /// Relative, so the gutter doesn't resize if that mode is ever toggled
    /// at runtime -- matching how Vim shares one `numberwidth` between
    /// `number` and `relativenumber` instead of sizing them separately.
    /// `ob` is passed explicitly (rather than always reading the focused
    /// buffer) so a split's every visible pane gets a gutter sized to
    /// *its own* buffer's line count, not just the focused one's.
    fn gutter_chars(&self, ob: &OpenBuffer) -> usize {
        if self.line_number_mode == LineNumberMode::Off
            || ob.kind == BufferKind::Dashboard
            || ob.kind == BufferKind::Explorer
            || ob.kind == BufferKind::Docker
            || ob.kind == BufferKind::Git
            || ob.kind == BufferKind::Jira
            || ob.kind == BufferKind::Table
            || ob.kind == BufferKind::SearchReplace
            || ob.kind == BufferKind::Vnc
            || ob.kind == BufferKind::Pdf
            || ob.kind == BufferKind::PdfOutline
            || ob.kind == BufferKind::PdfSearchResults
            || ob.kind == BufferKind::TaskOutput
            || ob.kind == BufferKind::Debug
            || ob.kind == BufferKind::ToolStatus
            // The diff view draws its own old/new line-number columns
            // (see `diff_view::content_row`), which are the real line
            // numbers here -- a buffer-line gutter next to them would
            // be a third, meaningless column.
            || ob.kind == BufferKind::Diff
            || ob.kind == BufferKind::Graph
            // The merge view's own two columns are the layout; a line
            // gutter beside them would shift one column and not the
            // other, which is exactly the alignment it exists to keep.
            || ob.kind == BufferKind::Merge
            // A terminal's columns are the shell's own; a gutter would
            // shift every one of them out from under what the shell
            // thinks it drew.
            || ob.kind == BufferKind::Terminal
        {
            return 0;
        }
        ob.buffer.visual_line_count().max(1).to_string().len() + 1
    }

    /// Rich-text spans for one pane's content area covering `rows` screen
    /// rows starting at `render_base_line`: each row that maps to a real
    /// buffer line gets an optional gutter prefix (its line number, right-
    /// aligned, brighter on the cursor's own line) followed by that line's
    /// text; rows past the end of the buffer get a `~` marker instead,
    /// matching Vim's convention for "there's no line here" -- shown even
    /// with the gutter off, same as Vim shows it regardless of `number`.
    /// `syntax_highlights` (document-wide byte ranges, already resolved to
    /// colors) splits each line's text into colored sub-spans instead of
    /// one flat `theme.fg` span when non-empty. `ob` (rather than always
    /// the focused buffer) is what makes every visible pane -- not just
    /// the focused one -- show its own buffer's real content.
    ///
    /// `dashboard_pad`, when `Some`, replaces the real-gutter/tilde logic
    /// entirely: index `buffer_line` gives that specific row's own
    /// horizontal-centering pad (in characters, from `dashboard_center_
    /// offset` -- different rows can want different padding, e.g. the
    /// banner block and the content block below it center independently)
    /// written as literal leading blank characters, since `TextArea.left`
    /// has no geometric offset to hook a shift into.
    ///
    /// `cursor_line` is `ob`'s *pane's* own cursor row (relative-gutter
    /// numbering needs it) -- passed in rather than read off `ob.cursor`
    /// now that cursor is pane-owned, not buffer-owned (see `PaneState`'s
    /// own doc comment), so this stays correct for any pane, not just
    /// the focused one.
    ///
    /// `tab_stops` governs how a literal `\t` in the line's own text
    /// expands (see the `tabstops` module) -- a line with no tab at all
    /// never consults it and renders exactly as before. A line that
    /// *does* contain one still gets full `syntax_highlights` coloring,
    /// via `remap_highlights_for_display` translating the highlight
    /// ranges (byte offsets against the real buffer text) onto the
    /// tab-expanded display string's own offsets -- tab-indented C/
    /// Bash/Python files (all have a tree-sitter grammar registered in
    /// this project) keep working, not just delimited data files with
    /// no grammar in the first place.
    ///
    /// `scroll_col` (visual columns, post-tab-expansion -- see `remap_
    /// col`'s own doc comment for why) drops that many leading
    /// characters from each row's *code* text only, via `skip_chars` --
    /// the gutter prefix above is built and pushed before this runs, so
    /// it's never touched. A line shorter than `scroll_col` renders
    /// with no code text at all for that row, same as a real editor
    /// showing nothing once you've scrolled past a short line's end.
    #[allow(clippy::too_many_arguments)] // a plain data parameter list, not a design smell worth a struct for one private call site
    fn content_spans(
        &self,
        ob: &OpenBuffer,
        render_base_line: usize,
        rows: usize,
        gutter_chars: usize,
        dashboard_pad: Option<&[usize]>,
        syntax_highlights: &[(std::ops::Range<usize>, glyphon::Color)],
        cursor_line: usize,
        tab_stops: &TabStops,
        scroll_col: usize,
    ) -> Vec<(String, glyphon::Color)> {
        let theme = self.theme;
        let visual_lines = ob.buffer.visual_line_count();
        let mut spans = Vec::new();
        for r in 0..rows {
            let buffer_line = render_base_line + r;
            let has_line = buffer_line < visual_lines;
            if let Some(pad) = dashboard_pad {
                let n = pad.get(buffer_line).copied().unwrap_or(0);
                if n > 0 {
                    spans.push((" ".repeat(n), theme.fg));
                }
            } else if gutter_chars > 0 {
                let gutter = if has_line {
                    let n = match self.line_number_mode {
                        LineNumberMode::Relative => buffer_line.abs_diff(cursor_line),
                        _ => buffer_line + 1,
                    };
                    format!("{:>width$} ", n, width = gutter_chars - 1)
                } else {
                    format!("{:<width$}", "~", width = gutter_chars)
                };
                let color = if has_line && buffer_line == cursor_line { theme.fg } else { theme.gutter_fg };
                spans.push((gutter, color));
            } else if !has_line {
                spans.push(("~".to_string(), theme.gutter_fg));
            }
            if has_line {
                let start = ob.buffer.line_start_char(buffer_line);
                let len = ob.buffer.line_len(buffer_line);
                let line_text = ob.buffer.text_range(start, start + len);
                if line_text.contains('\t') {
                    let (display, col_map) = tabstops::expand_line(&line_text, tab_stops);
                    let (sliced, skipped_bytes) = skip_chars(&display, scroll_col);
                    if syntax_highlights.is_empty() {
                        spans.push((sliced.to_string(), theme.fg));
                    } else {
                        let line_byte_start = ob.buffer.char_to_byte(start);
                        let line_byte_end = ob.buffer.char_to_byte(start + len);
                        let remapped = remap_highlights_for_display(
                            &ob.buffer,
                            start,
                            &col_map,
                            &display,
                            line_byte_start,
                            line_byte_end,
                            syntax_highlights,
                        );
                        // `skipped_bytes`/`display.len()` here are local
                        // to `display` (0-based), matching `remapped`'s
                        // own coordinate space -- not the real buffer's
                        // byte offsets, unlike the plain branch below.
                        spans.extend(split_line_by_highlights(sliced, skipped_bytes, display.len(), &remapped, theme.fg));
                    }
                } else {
                    let (sliced, skipped_bytes) = skip_chars(&line_text, scroll_col);
                    if syntax_highlights.is_empty() {
                        spans.push((sliced.to_string(), theme.fg));
                    } else {
                        let line_byte_start = ob.buffer.char_to_byte(start) + skipped_bytes;
                        let line_byte_end = ob.buffer.char_to_byte(start + len);
                        spans.extend(split_line_by_highlights(
                            sliced,
                            line_byte_start,
                            line_byte_end,
                            syntax_highlights,
                            theme.fg,
                        ));
                    }
                }
            }
            if r + 1 < rows {
                spans.push(("\n".to_string(), theme.fg));
            }
        }
        spans
    }

    /// Drains buffer `id`'s edits since the last frame, feeds them through
    /// its active language's incremental parser (if any), and returns
    /// resolved syntax-highlight colors for the visible byte range only --
    /// same windowing discipline `Buffer::visible_text` already uses.
    /// Always drains, even with no active language, so the buffer's edit
    /// log doesn't grow unbounded for files nothing is consuming it for.
    /// Takes an explicit `id` (rather than always the focused buffer) so
    /// every visible pane's buffer gets reparsed, not just the focused
    /// one's -- `self.buffers.get_mut(id)` is a direct field projection,
    /// so this can still read `self.theme` first in the same call without
    /// the opaque-method-call borrow conflict `open_mut()` would risk.
    fn syntax_highlights_for_visible_range(
        &mut self,
        id: BufferId,
        render_base_line: usize,
        rows: usize,
    ) -> Vec<(std::ops::Range<usize>, glyphon::Color)> {
        let theme = self.theme;
        // Cloned out ahead of the `self.buffers.get_mut` borrow below --
        // `dashboard_lines` is a different field, but going through a
        // `&self` method call for it while `ob` (from `self.buffers`) is
        // still borrowed would look like a whole-`self` borrow to the
        // compiler. The cloned `Vec` is small (a few dozen entries at
        // most), so this is cheap.
        let dashboard_lines = self.dashboard_lines.get(&id).cloned();
        let docker_lines = self.docker_lines.get(&id).cloned();
        let git_lines = self.git_lines.get(&id).cloned();
        let jira_lines = self.jira_lines.get(&id).cloned();
        let diff_lines = self.diff_lines.get(&id).cloned();
        let graph_lines = self.graph_lines.get(&id).cloned();
        let merge_lines = self.merge_lines.get(&id).cloned();
        let dired_lines = self.dired_lines.get(&id).cloned();

        // Same reasoning, for Tcl: `tcl.scm`'s own `(command name: (_)
        // @function)` rule captures *every* word in command position,
        // since a tree-sitter query has no way to know whether it's a
        // real command -- only Fenix's own known-symbols set (built-in
        // keywords, ctags, the external symbols file: the exact same
        // three sources `tcl_candidates` already merges for completion)
        // can validate that. Built up here, before `self.buffers.get_mut`
        // below, since `tcl_candidates` is itself a `&mut self` call.
        let is_tcl = self.buffers.get(id).is_some_and(|ob| {
            ob.buffer.path().and_then(|p| p.extension()).and_then(|e| e.to_str()).and_then(fenix_syntax::detect_language)
                == Some(fenix_syntax::LanguageId::Tcl)
        });
        let known_tcl_commands: Option<std::collections::HashSet<String>> = if is_tcl {
            let root = self.project_root.clone();
            let mut known: std::collections::HashSet<String> =
                self.tcl_candidates(root.as_deref()).into_iter().map(|c| c.payload.label).collect();
            // Plus whatever this file itself defines. Without it, a call
            // to a proc defined twenty lines up renders as plain body
            // text whenever `ctags` has nothing to say -- which is every
            // single-file script (no project root, so `tcl_tags` never
            // runs) and every proc added since the last index.
            if let Some(ob) = self.buffers.get(id) {
                known.extend(fenix_completion::tcl::procs_defined_in(&ob.buffer.text()));
            }
            Some(known)
        } else {
            None
        };

        let Some(ob) = self.buffers.get_mut(id) else { return Vec::new() };
        let deltas = ob.buffer.drain_edits();

        if ob.kind == BufferKind::Dashboard {
            return dashboard_highlights_for_visible_range(ob, dashboard_lines.as_deref(), render_base_line, rows, theme);
        }
        if ob.kind == BufferKind::Docker {
            return docker_highlights_for_visible_range(ob, docker_lines.as_deref(), render_base_line, rows, theme);
        }
        if ob.kind == BufferKind::Git {
            return git_highlights_for_visible_range(ob, git_lines.as_deref(), render_base_line, rows, theme);
        }
        if ob.kind == BufferKind::Jira {
            return jira_highlights_for_visible_range(ob, jira_lines.as_deref(), render_base_line, rows, theme);
        }
        if ob.kind == BufferKind::Diff {
            return diff_highlights_for_visible_range(ob, diff_lines.as_deref(), render_base_line, rows, theme);
        }
        if ob.kind == BufferKind::Graph {
            return graph_highlights_for_visible_range(ob, graph_lines.as_deref(), render_base_line, rows, theme);
        }
        if ob.kind == BufferKind::Merge {
            return merge_highlights_for_visible_range(ob, merge_lines.as_deref(), render_base_line, rows, theme);
        }
        if ob.kind == BufferKind::Explorer {
            return explorer_highlights_for_visible_range(ob, dired_lines.as_deref(), render_base_line, rows, theme);
        }

        // Conflict markers, in an ordinary file. A conflicted file opens
        // as plain text -- the markers are just lines, and tree-sitter
        // sees them as broken syntax, so the three regions it matters
        // most to tell apart render identically to everything else.
        // Colored ahead of syntax rather than merged with it because the
        // two are answering different questions, and while a file has
        // `<<<<<<<` in it the conflict is the only one worth answering.
        let conflict_ranges = conflict_marker_highlights(ob, render_base_line, rows, theme);
        if !conflict_ranges.is_empty() {
            return conflict_ranges;
        }

        let Some(syntax) = &mut ob.syntax else { return Vec::new() };

        let edits: Vec<fenix_syntax::RawEdit> = deltas
            .into_iter()
            .map(|d| fenix_syntax::RawEdit { start_char: d.start_char, new_end_char: d.new_end_char, removed: d.removed })
            .collect();
        let source = ob.buffer.text();
        syntax.apply_edits(&source, &edits);

        let visual_lines = ob.buffer.visual_line_count();
        if render_base_line >= visual_lines {
            return Vec::new();
        }
        let last_line = (render_base_line + rows).min(visual_lines) - 1;
        let start_char = ob.buffer.line_start_char(render_base_line);
        let end_char = ob.buffer.line_start_char(last_line) + ob.buffer.line_len(last_line);
        let byte_range = ob.buffer.char_to_byte(start_char)..ob.buffer.char_to_byte(end_char);

        syntax
            .highlights_in_range(&source, byte_range)
            .into_iter()
            .filter(|(range, name)| {
                // Only the generic, unvalidated "function" capture (any
                // bare word in command position) needs cross-referencing
                // -- every other Tcl capture (specific builtins, "proc",
                // keywords, the switch/unset/variable special cases, ...)
                // is already validated by the query's own static
                // `#any-of?` lists, so it's left alone here.
                let Some(known) = &known_tcl_commands else { return true };
                if *name != "function" {
                    return true;
                }
                let text = &source[range.clone()];
                known.contains(text.strip_prefix("::").unwrap_or(text))
            })
            .map(|(range, name)| (range, theme.syntax_color(name)))
            .collect()
    }

    /// Per-visible-line (view_row, col_start, col_end) segments of the
    /// active Visual-mode selection, for highlighting. Empty outside Visual
    /// mode. Shape depends on `visual_kind()`: Char is a single charwise
    /// span, Line highlights whole lines regardless of column, Block is a
    /// column-range rectangle across lines (clamped per ragged line, like
    /// the Block operators themselves).
    fn visual_selection_segments(&self, visible_lines: usize) -> Segments {
        if self.vim.mode() != Mode::Visual {
            return Vec::new();
        }
        let anchor = self.vim.visual_anchor();
        let last_visible = (self.render_base_line() + visible_lines).min(self.open().buffer.line_count());
        let mut segments = Vec::new();

        match self.vim.visual_kind() {
            VisualKind::Char => {
                let cursor_idx = self.cursor().char_idx;
                let (lo, hi) =
                    if anchor <= cursor_idx { (anchor, cursor_idx + 1) } else { (cursor_idx, anchor + 1) };
                let hi = hi.min(self.open().buffer.len_chars());
                segments = self.range_to_segments(lo..hi, visible_lines);
            }
            VisualKind::Line => {
                let (line_lo, line_hi) = self.anchor_cursor_line_range(anchor);
                for line in self.render_base_line().max(line_lo)..last_visible.min(line_hi + 1) {
                    // at least 1 col wide so an empty line still shows a sliver
                    let width = self.open().buffer.line_len(line).max(1);
                    segments.push((line - self.render_base_line(), 0, width));
                }
            }
            VisualKind::Block => {
                let (line_lo, line_hi) = self.anchor_cursor_line_range(anchor);
                let anchor_cursor = Cursor { char_idx: anchor, sticky_col: 0 };
                let (_, anchor_col) = self.open().buffer.line_col(&anchor_cursor);
                let (_, cursor_col) = self.open().buffer.line_col(&self.cursor());
                let (col_lo, col_hi) = if anchor_col <= cursor_col {
                    (anchor_col, cursor_col + 1)
                } else {
                    (cursor_col, anchor_col + 1)
                };
                for line in self.render_base_line().max(line_lo)..last_visible.min(line_hi + 1) {
                    let len = self.open().buffer.line_len(line);
                    let seg_start = col_lo.min(len);
                    let seg_end = col_hi.min(len);
                    if seg_start < seg_end {
                        segments.push((line - self.render_base_line(), seg_start, seg_end));
                    }
                }
            }
        }
        segments
    }

    /// (min, max) line index spanned by the visual anchor and the cursor.
    fn anchor_cursor_line_range(&self, anchor: usize) -> (usize, usize) {
        let anchor_cursor = Cursor { char_idx: anchor, sticky_col: 0 };
        let (anchor_line, _) = self.open().buffer.line_col(&anchor_cursor);
        let (cursor_line, _) = self.open().buffer.line_col(&self.cursor());
        if anchor_line <= cursor_line { (anchor_line, cursor_line) } else { (cursor_line, anchor_line) }
    }

    /// Per-visible-line (view_row, col_start, col_end) segments a plain
    /// char range covers -- shared by Char-kind Visual selection and the
    /// yank/paste pulse, which are both "highlight this contiguous span"
    /// even though they come from different sources.
    fn range_to_segments(&self, range: std::ops::Range<usize>, visible_lines: usize) -> Segments {
        let last_visible = (self.render_base_line() + visible_lines).min(self.open().buffer.line_count());
        let mut segments = Vec::new();
        for line in self.render_base_line()..last_visible {
            let line_start = self.open().buffer.line_start_char(line);
            let line_end = line_start + self.open().buffer.line_len(line);
            let seg_start = range.start.max(line_start);
            let seg_end = range.end.min(line_end);
            if seg_start < seg_end {
                segments.push((line - self.render_base_line(), seg_start - line_start, seg_end - line_start));
            }
        }
        segments
    }

    /// Segments for the bracket under the cursor and its match, when the
    /// cursor sits exactly on one of `(){}[]` and a match exists --
    /// empty otherwise (unmatched brackets, or the cursor isn't on a
    /// bracket at all). Reuses `range_to_segments` for the "char range
    /// -> view segments" conversion, called once per bracket rather
    /// than over a combined range since the two are rarely adjacent.
    fn bracket_match_segments(&self, visible_lines: usize) -> Segments {
        let cursor_idx = self.cursor().char_idx;
        let Some(match_idx) = fenix_vim::find_matching_bracket(&self.open().buffer, cursor_idx) else {
            return Vec::new();
        };
        let mut segments = self.range_to_segments(cursor_idx..cursor_idx + 1, visible_lines);
        segments.extend(self.range_to_segments(match_idx..match_idx + 1, visible_lines));
        segments
    }

    /// `hlsearch`'s persistent match-highlight segments -- every
    /// occurrence of the last confirmed search pattern within the
    /// visible range, empty whenever `VimState::hlsearch_active` is
    /// false. Converts the visible line range to a byte range (`Buffer::
    /// char_to_byte` at each line boundary) for `VimState::hlsearch_
    /// matches`, then each match's byte range back to view segments via
    /// `range_to_segments`, the same "windowed, computed fresh each
    /// frame" discipline `bracket_match_segments`/`syntax_highlights_
    /// for_visible_range` already use.
    fn hlsearch_segments(&self, visible_lines: usize) -> Segments {
        let buffer = &self.open().buffer;
        let last_visible = (self.render_base_line() + visible_lines).min(buffer.line_count());
        let start_char = buffer.line_start_char(self.render_base_line());
        let end_char = if last_visible < buffer.line_count() {
            buffer.line_start_char(last_visible)
        } else {
            buffer.len_chars()
        };
        let byte_range = buffer.char_to_byte(start_char)..buffer.char_to_byte(end_char);

        let mut segments = Segments::new();
        for m in self.vim.hlsearch_matches(buffer, byte_range) {
            let start = buffer.byte_to_char(m.start);
            let end = buffer.byte_to_char(m.end);
            segments.extend(self.range_to_segments(start..end, visible_lines));
        }
        segments
    }

    /// The focused pane's caret position for this frame: normally
    /// `hl_row`/the real cursor's column, but during `Mode::Search`
    /// previews where the in-progress query would jump to instead
    /// (incsearch) -- the real `Cursor`/`last_search` are untouched
    /// until Enter confirms (see `VimState::preview_match`'s own doc
    /// comment). The preview is only shown when it falls inside the
    /// currently-fetched `[render_base_line, render_base_line +
    /// pane_visible_lines]` window; a match outside it shows no caret
    /// this frame rather than auto-scrolling to reveal it (a disclosed
    /// simplification -- real incsearch also pans the viewport).
    fn focused_caret(
        &self,
        hl_row: Option<usize>,
        col: usize,
        render_base_line: usize,
        pane_visible_lines: usize,
    ) -> Option<(usize, usize)> {
        if self.vim.mode() != Mode::Search {
            return hl_row.map(|row| (row, col));
        }
        self.vim.preview_match(&self.open().buffer, &self.cursor()).and_then(|idx| {
            let preview_cursor = Cursor { char_idx: idx, sticky_col: 0 };
            let (preview_line, preview_col) = self.open().buffer.line_col(&preview_cursor);
            preview_line
                .checked_sub(render_base_line)
                .filter(|&row| row <= pane_visible_lines)
                .map(|row| (row, preview_col))
        })
    }

    /// Key/label pairs for whichever pending sequence is currently active
    /// (the leader menu takes priority, since it's the outermost one --
    /// Vim can't be mid-sequence while a leader sequence is in progress).
    /// Empty when nothing is pending.
    fn pending_hints(&self) -> Vec<(KeyPress, &'static str)> {
        if self.leader_matcher.is_pending() {
            self.leader_matcher.pending_children()
        } else {
            self.vim.pending_children()
        }
    }

    /// Segments and current alpha for an active yank/paste pulse, or
    /// `None` when there isn't one. Fades quickly at first then lingers
    /// faintly, via the same ease-out curve as the caret (inverted: pulses
    /// start bright and fade, blink fades in toward its target instead).
    fn pulse_overlay(&self, visible_lines: usize) -> Option<(Segments, f32)> {
        let pulse = self.pulse.as_ref()?;
        let t = Instant::now().duration_since(pulse.started).as_secs_f32() / PULSE_DURATION.as_secs_f32();
        let alpha = PULSE_PEAK_ALPHA * (1.0 - ease_out_cubic(t));
        if alpha <= 0.0 {
            return None;
        }
        Some((self.range_to_segments(pulse.range.clone(), visible_lines), alpha))
    }

    /// Whichever prompt/confirmation `active_prompt_text` says is
    /// currently active, as a one-row floating popup just above the
    /// modeline -- `None` when nothing is. Shares the modeline's own
    /// background/text color (`bg_modeline`/`fg_modeline`), since this
    /// is exactly the text the modeline itself used to show inline
    /// before this popup existed. Unlike `which_key_popup`, not capped
    /// at `WHICH_KEY_MAX_WIDTH` (480px, tuned for short which-key
    /// labels) -- prompt text routinely needs to be longer (a file
    /// path, a commit message), so the only ceiling here is the same
    /// window-width-based one `which_key_popup` itself computes before
    /// *additionally* clamping to `WHICH_KEY_MAX_WIDTH`.
    fn prompt_popup(&self, window_width: f32, modeline_top: f32) -> Option<(fenix_window::Rect, RowSpans)> {
        let content = self.active_prompt_text()?;

        let (char_width, line_height) = match &self.text {
            Some(text) => (text.char_width(), text.line_height()),
            None => (text::CHAR_WIDTH, text::LINE_HEIGHT),
        };

        let content_chars = content.chars().count();
        let max_width = (window_width - 2.0 * text::WHICH_KEY_MARGIN).max(text::WHICH_KEY_MIN_WIDTH);
        let width = (content_chars as f32 * char_width + WHICH_KEY_PADDING).clamp(text::WHICH_KEY_MIN_WIDTH, max_width);
        let height = line_height + WHICH_KEY_PADDING;

        let theme = self.theme;
        let spans = vec![(content, theme.fg_modeline, false)];
        let rect = popup::resolve(popup::Anchor::BottomLeft { margin: text::WHICH_KEY_MARGIN }, width, height, window_width, modeline_top);
        Some((rect, spans))
    }

    /// The which-key popup's rich-text spans (key column in
    /// `theme.caret_text`, label/overflow-summary in the modeline's own
    /// text color, sorted alphabetically by label for scannability) and
    /// its resolved on-screen rect, or `None` when nothing is pending. The
    /// popup shares the modeline's background (`bg_modeline`), so both
    /// colors here are picked from that family, not the content one --
    /// `syntax_keyword` was tried for the key column originally, but it's
    /// calibrated for `bg` (the content background), and on TempleOS
    /// specifically its value is identical to `bg_modeline`, making the
    /// key column invisible. `caret_text` is guaranteed high-contrast
    /// against `bg_modeline` in every theme (`caret` already needs that
    /// against `bg` to work as a caret), which is what makes it a safe
    /// second accent color here too.
    /// Two other things could previously make the panel not actually fit
    /// its own content, both fixed here: its *width* is now sized to the
    /// longest visible label at the font's real measured `char_width`
    /// (clamped to `[WHICH_KEY_MIN_WIDTH, WHICH_KEY_MAX_WIDTH]` and to
    /// what the window can hold) instead of a fixed 260px that didn't
    /// scale with font size or label length -- a big font or a long
    /// label (real examples: "insert at line start", "WORD backward")
    /// used to just get cut off; and its *height* truncates to whatever
    /// `popup::max_rows` says actually fits above the modeline, with a
    /// trailing "+N more" summary row instead of letting the panel run
    /// under it.
    fn which_key_popup(&self, window_width: f32, modeline_top: f32) -> Option<(fenix_window::Rect, RowSpans)> {
        let mut hints = self.pending_hints();
        if hints.is_empty() {
            return None;
        }
        hints.sort_by(|a, b| a.1.cmp(b.1));

        let (char_width, line_height) = match &self.text {
            Some(text) => (text.char_width(), text.line_height()),
            None => (text::CHAR_WIDTH, text::LINE_HEIGHT),
        };

        let max_rows = popup::max_rows(modeline_top, text::WHICH_KEY_MARGIN, line_height, WHICH_KEY_PADDING);
        let shown_count = if hints.len() > max_rows { max_rows.saturating_sub(1).max(1) } else { hints.len() };
        let truncated = hints.len() - shown_count;

        const KEY_COLUMN_CHARS: usize = 6;
        let longest_label = hints[..shown_count].iter().map(|(_, label)| label.chars().count()).max().unwrap_or(0);
        let content_chars = KEY_COLUMN_CHARS + longest_label + 1;
        let max_width = (window_width - 2.0 * text::WHICH_KEY_MARGIN).max(text::WHICH_KEY_MIN_WIDTH);
        let width = (content_chars as f32 * char_width + WHICH_KEY_PADDING)
            .clamp(text::WHICH_KEY_MIN_WIDTH, text::WHICH_KEY_MAX_WIDTH.min(max_width));

        let theme = self.theme;
        let mut spans = Vec::new();
        for (i, (key, label)) in hints[..shown_count].iter().enumerate() {
            if i > 0 {
                spans.push(("\n".to_string(), theme.fg_modeline, false));
            }
            spans.push((format!("{:<KEY_COLUMN_CHARS$}", keymap::describe_keypress(key)), theme.caret_text, false));
            spans.push(((*label).to_string(), theme.fg_modeline, false));
        }
        if truncated > 0 {
            spans.push(("\n".to_string(), theme.fg_modeline, false));
            spans.push((format!("+{truncated} more"), theme.fg_modeline, false));
        }

        let row_count = shown_count + usize::from(truncated > 0);
        let height = row_count as f32 * line_height + WHICH_KEY_PADDING;
        let rect = popup::resolve(popup::Anchor::TopRight { margin: text::WHICH_KEY_MARGIN }, width, height, window_width, modeline_top);
        Some((rect, spans))
    }

    /// The Docker panel's contextual "view command options" popup (`x`
    /// on a Containers/Images/Volumes pane) -- mirrors `which_key_popup`'s
    /// shape, but its content is a small static per-`DockerPaneRole` list
    /// instead of `pending_hints()`. `None` whenever the popup isn't
    /// showing (`docker_menu_open` is false), the focused pane isn't part
    /// of a Docker session, or that pane has no bindings of its own
    /// (Status/Logs).
    fn docker_menu_popup(&self, window_width: f32, modeline_top: f32) -> Option<(fenix_window::Rect, RowSpans)> {
        if !self.docker_menu_open {
            return None;
        }
        let bindings: &[(&str, &str)] = match self.docker_focused_role()? {
            DockerPaneRole::Containers => {
                &[("s", "start"), ("S", "stop"), ("R", "restart"), ("l", "logs"), ("d", "remove"), ("u", "refresh")]
            }
            DockerPaneRole::Images => &[("r", "run"), ("d", "remove"), ("u", "refresh")],
            DockerPaneRole::Volumes => &[("u", "refresh")],
            DockerPaneRole::Networks => &[("d", "remove"), ("u", "refresh")],
            DockerPaneRole::Status | DockerPaneRole::Logs => return None,
        };

        let (char_width, line_height) = match &self.text {
            Some(text) => (text.char_width(), text.line_height()),
            None => (text::CHAR_WIDTH, text::LINE_HEIGHT),
        };

        let max_rows = popup::max_rows(modeline_top, text::WHICH_KEY_MARGIN, line_height, WHICH_KEY_PADDING).max(1);
        let shown_count = bindings.len().min(max_rows);

        const KEY_COLUMN_CHARS: usize = 6;
        let longest_label = bindings[..shown_count].iter().map(|(_, label)| label.chars().count()).max().unwrap_or(0);
        let content_chars = KEY_COLUMN_CHARS + longest_label + 1;
        let max_width = (window_width - 2.0 * text::WHICH_KEY_MARGIN).max(text::WHICH_KEY_MIN_WIDTH);
        let width = (content_chars as f32 * char_width + WHICH_KEY_PADDING)
            .clamp(text::WHICH_KEY_MIN_WIDTH, text::WHICH_KEY_MAX_WIDTH.min(max_width));

        let theme = self.theme;
        let mut spans = Vec::new();
        for (i, (key, label)) in bindings[..shown_count].iter().enumerate() {
            if i > 0 {
                spans.push(("\n".to_string(), theme.fg_modeline, false));
            }
            spans.push((format!("{key:<KEY_COLUMN_CHARS$}"), theme.caret_text, false));
            spans.push(((*label).to_string(), theme.fg_modeline, false));
        }

        let height = shown_count as f32 * line_height + WHICH_KEY_PADDING;
        let rect = popup::resolve(popup::Anchor::TopRight { margin: text::WHICH_KEY_MARGIN }, width, height, window_width, modeline_top);
        Some((rect, spans))
    }

    /// The Git panel's contextual "view command options" popup (`x` on a
    /// Files/Branches/Commits/Stash pane) -- mirrors `docker_menu_popup`
    /// exactly, including its own note on why literal Vim/lazygit
    /// `<space>`-based stage-toggle isn't used here: `SPC` is already
    /// globally claimed as Fenix's leader-key trigger (checked earlier
    /// than any pane-role routing in `handle_key`), so Files uses
    /// separate `s`/`S` stage/unstage keys instead, matching the
    /// existing Docker-panel precedent of separate keys over a single
    /// toggle (`s`/`S` start/stop, `R` restart) rather than inventing a
    /// new convention. `None` on Status/Main, which have no bindings of
    /// their own beyond the global `u` (mirrors Docker's Status/Logs).
    fn git_menu_popup(&self, window_width: f32, modeline_top: f32) -> Option<(fenix_window::Rect, RowSpans)> {
        if !self.git_menu_open {
            return None;
        }
        // The History and Compare views are separate workspaces with no
        // `GitPaneRole` of their own, but `x` means the same thing in
        // them -- "what can I press here" -- so they get their own key
        // lists rather than no menu at all.
        if let Some(session) = &self.history_session {
            let focused = self.focused_pane_id();
            let bindings: Option<&[(&str, &str)]> = if focused == session.graph_pane {
                Some(&[("1/2/3", "go to pane"), ("u", "refresh"), ("f", "fetch")])
            } else if focused == session.refs_pane {
                Some(&[("1/2/3", "go to pane"), ("u", "refresh"), ("f", "fetch")])
            } else if focused == session.detail_pane {
                Some(&[("Tab", "fold/unfold file"), ("]", "next hunk"), ("[", "prev hunk"), ("Enter", "open file here"), ("u", "refresh")])
            } else {
                None
            };
            if let Some(bindings) = bindings {
                return self.git_menu_popup_at(bindings, window_width, modeline_top);
            }
        }
        if let Some(session) = &self.compare_session {
            let focused = self.focused_pane_id();
            if focused == session.commits_pane || focused == session.diff_pane {
                let bindings: &[(&str, &str)] = &[
                    ("1/2", "go to pane"),
                    ("t", "three-dot/two-dot"),
                    ("r", "re-target refs"),
                    ("Tab", "fold/unfold file"),
                    ("]", "next hunk"),
                    ("[", "prev hunk"),
                    ("u", "refresh"),
                ];
                return self.git_menu_popup_at(bindings, window_width, modeline_top);
            }
        }
        if let Some(session) = &self.forge_session {
            let focused = self.focused_pane_id();
            if focused == session.list_pane || focused == session.detail_pane || focused == session.review_pane {
                let mut bindings: Vec<(&str, &str)> = vec![
                    ("1/2/3", "go to pane"),
                    ("Enter", "show this one"),
                    ("f", "cycle filter"),
                    ("c", "check it out locally"),
                    ("u", "refresh"),
                    ("A", "approve / withdraw"),
                    ("m", "merge (press twice)"),
                ];
                if focused == session.review_pane {
                    // Only offered where they mean something: these act
                    // on a diff line or a thread, and neither exists in
                    // the other two panes.
                    bindings.extend([
                        ("C", "comment on this line"),
                        ("r", "reply to this thread"),
                        ("R", "resolve / reopen"),
                        ("Tab", "fold this file"),
                        ("]/[", "next/prev hunk"),
                    ]);
                }
                return self.git_menu_popup_at(&bindings, window_width, modeline_top);
            }
        }
        if let Some(session) = &self.merge_session {
            let focused = self.focused_pane_id();
            // The labels name the branches rather than saying "ours" and
            // "theirs" -- the popup is for someone who isn't sure which
            // key does what, so it's the wrong place to make them
            // translate git's own vocabulary.
            let (ours, theirs) = (session.labels.ours.as_str(), session.labels.theirs.as_str());
            let keep_ours = format!("keep {ours}");
            let keep_theirs = format!("keep {theirs}");
            let bindings: Option<Vec<(&str, &str)>> = if focused == session.files_pane {
                Some(vec![
                    ("1/2", "go to pane"),
                    ("Enter", "resolve line by line"),
                    ("o", keep_ours.as_str()),
                    ("t", keep_theirs.as_str()),
                    ("s", "stage as resolved"),
                    ("u", "put the conflict back"),
                    ("r", "refresh"),
                ])
            } else if focused == session.merge_pane {
                Some(vec![
                    ("1/2", "go to pane"),
                    ("n/p", "next/prev conflict"),
                    ("o", keep_ours.as_str()),
                    ("t", keep_theirs.as_str()),
                    ("b", "keep both"),
                    ("s", "stage as resolved"),
                    ("u", "put the conflict back"),
                ])
            } else {
                None
            };
            if let Some(bindings) = bindings {
                return self.git_menu_popup_at(&bindings, window_width, modeline_top);
            }
        }
        let bindings: &[(&str, &str)] = match self.git_focused_role()? {
            GitPaneRole::Staged => &[
                ("Tab", "expand/collapse"),
                ("s", "stage"),
                ("S", "unstage"),
                ("a", "stage all"),
                ("A", "unstage all"),
                ("c", "commit"),
                ("z", "stash all"),
                ("P", "push"),
                ("p", "pull"),
                ("u", "refresh"),
            ],
            GitPaneRole::Unstaged => &[
                ("Tab", "expand/collapse"),
                ("s", "stage"),
                ("S", "unstage"),
                ("a", "stage all"),
                ("A", "unstage all"),
                ("c", "commit"),
                ("d", "discard"),
                ("z", "stash all"),
                ("P", "push"),
                ("p", "pull"),
                ("u", "refresh"),
            ],
            GitPaneRole::Branches => &[("c", "checkout"), ("n", "new branch"), ("d", "delete"), ("u", "refresh")],
            GitPaneRole::Commits => &[("u", "refresh")],
            GitPaneRole::Stash => &[("a", "apply"), ("g", "pop"), ("d", "drop"), ("u", "refresh")],
            GitPaneRole::Main => &[
                ("s", "stage hunk"),
                ("S", "unstage hunk"),
                ("d", "discard hunk"),
                ("]", "next hunk"),
                ("[", "prev hunk"),
                ("Tab", "fold file"),
                ("Enter", "open file here"),
                ("u", "refresh"),
            ],
            GitPaneRole::Status => return None,
        };
        self.git_menu_popup_at(bindings, window_width, modeline_top)
    }

    /// Lays out one key list as the contextual popup -- the shared half
    /// of `git_menu_popup`, so the History and Compare views' own key
    /// lists render identically to the Git panel's without duplicating
    /// the geometry.
    fn git_menu_popup_at(
        &self,
        bindings: &[(&str, &str)],
        window_width: f32,
        modeline_top: f32,
    ) -> Option<(fenix_window::Rect, RowSpans)> {
        let (char_width, line_height) = match &self.text {
            Some(text) => (text.char_width(), text.line_height()),
            None => (text::CHAR_WIDTH, text::LINE_HEIGHT),
        };

        let max_rows = popup::max_rows(modeline_top, text::WHICH_KEY_MARGIN, line_height, WHICH_KEY_PADDING).max(1);
        let shown_count = bindings.len().min(max_rows);

        const KEY_COLUMN_CHARS: usize = 6;
        let longest_label = bindings[..shown_count].iter().map(|(_, label)| label.chars().count()).max().unwrap_or(0);
        let content_chars = KEY_COLUMN_CHARS + longest_label + 1;
        let max_width = (window_width - 2.0 * text::WHICH_KEY_MARGIN).max(text::WHICH_KEY_MIN_WIDTH);
        let width = (content_chars as f32 * char_width + WHICH_KEY_PADDING)
            .clamp(text::WHICH_KEY_MIN_WIDTH, text::WHICH_KEY_MAX_WIDTH.min(max_width));

        let theme = self.theme;
        let mut spans = Vec::new();
        for (i, (key, label)) in bindings[..shown_count].iter().enumerate() {
            if i > 0 {
                spans.push(("\n".to_string(), theme.fg_modeline, false));
            }
            spans.push((format!("{key:<KEY_COLUMN_CHARS$}"), theme.caret_text, false));
            spans.push(((*label).to_string(), theme.fg_modeline, false));
        }

        let height = shown_count as f32 * line_height + WHICH_KEY_PADDING;
        let rect = popup::resolve(popup::Anchor::TopRight { margin: text::WHICH_KEY_MARGIN }, width, height, window_width, modeline_top);
        Some((rect, spans))
    }

    /// The Jira panel's own contextual "view command options" popup (`x`
    /// on an Issues/Detail pane) -- mirrors `docker_menu_popup`/`git_
    /// menu_popup` exactly. `None` on Projects/Users, which have no
    /// pane-scoped keys of their own (add/delete are leader-bound) --
